/* Generated by build/build_data.py from titterpig-dsl-tor2e/0.5 — do not edit by hand.
   Every string is verbatim from the DSL corpus; regenerate rather than patch. */
(function(){var d={"book": {"chapters": [{"cid": "tor2e-hands-introduction", "container": "EXTENSION", "dependsOn": [], "desc": null, "file": "tor2e-0.5-hands-introduction.ttrpg", "guidance": [], "kind": "ttrpg", "name": "Hands of the White Wizard - Introduction", "page": 5, "props": [], "roots": ["#tv6SJ9aoTwWOzFRiPUOW880", "#trhzOwG5SR561o83VFZVUKV", "#tz8ibzN9UkMTUNLV7TVtSOX", "#tISoGUNZz2VE9kykXX8Ohtc", "#tt3qThmdMDDeiOEa4SfoqQ1", "#t5mXLkdNrxFIXVCfT0kUbiu", "#tYTRDNCyEPe4yv1Uy7AZqe8"]}, {"cast": [], "cid": "tor2e-hands-the-beast-of-dunland", "container": "ARC", "dependsOn": ["tor2e"], "desc": "Long has there been bad blood between the folk of Rohan and those who dwell across the Isen in Dunland. A full accounting of their quarrels is too lengthy to go into here; the Dunlendings are an old people, having lived in these parts since before the Sea-kings of Númenor came from the west, and bear a list of grudges to match. They hate the Men of Gondor for giving the Rohirrim the province of Calenardhon, and hate the Rohirrim for driving the Dunlendings from the land. A dark and bitter folk are they, Middle Men under the Shadow.\n\nBut they can be brought into the light. In his wisdom and foresight, Saruman has treated the Dunlendings better than others have done, and he has fostered and taught the sons and daughters of their chieftains in Isengard. When the War comes, the Wild Men of Dunland may prove useful allies.\n\nNow, word comes to Isengard of a fearsome beast that troubles the Dunlending stronghold of Crow Hall. If Saruman sends aid to the Dunlendings, they will be indebted to the White Wizard…", "entries": [], "file": "tor2e-0.5-hands-the-beast-of-dunland.arc", "guidance": [{"concerns": [], "id": "#tSxJPC7J7jGNEm2b84BImkv", "name": "The Death of Sigulf", "text": "Sigulf’s farmstead was indeed attacked by raiders from Dunland — specifically, Toirlas, the son of the Dunlending chieftain Gorsad. He stole Sigulf’s flock of sheep — and kidnapped Sigulf’s daughter, Gleodwyn.\n\nThere was only one witness to the crime — an old shepherd named Scepa who served Sigulf. Scepa saw the smoke rising from the burning farmstead and watched as Toirlas dragged Gleodwyn away. He has followed the Dunlendings up into the hills. The large, heavy tracks that the Player-heroes can spot around the farmstead belong to Scepa himself, who is a very tall and broad man.", "topics": ["the beast of dunland"]}, {"concerns": [], "id": "#tbQnN9AAZCm1dzVUp0eb314", "name": "What’s in the Box?", "text": "The box can easily be opened if the Player-heroes are willing to break the seal; removing the seal without breaking it requires a CRAFT roll. It contains thirty silver coins — and a vial of black, viscous liquid that smells horribly bitter. The vial bears a label in Saruman’s copperplate handwriting: *dilute with one hundred parts water*. This is a medicine brewed up by Saruman to treat Gorsad’s gout, but it is meant to be diluted — one drop from the vial mixed with a pot of water. Undiluted, it’s a grievous poison.", "topics": ["the beast of dunland"]}, {"concerns": [], "id": "#twaiUI63UPcUNjnPFBnGS6I", "name": "Dunwalla’s Movements", "text": "Until Toirlas returns (see page 36), Dunwalla intends to placate the beast by bringing food to its secret lair at the Eordscrafa (see page 37). Watchful Player-heroes may notice Dunwalla leaving Crow Hall with a bag of food. Her crows watch over her, making it exceedingly difficult to follow her unnoticed — those who attempt to *lose (2d)* on their STEALTH roll. If she knows she’s being followed, Dunwalla leads her pursuers on a long and fruitless walk through the Forest of Eyes.", "topics": ["the beast of dunland"]}, {"concerns": [], "id": "#tvLt3S2hwFyBG3DvJgJtnGm", "name": "A Murder of Crows", "text": "Given the amount of trouble caused by crows in this adventure, some Player-heroes may turn violent. Killing a crow is relatively easy — an *Ill- favoured* ranged attack roll is needed (the crows have no Parry), and any successful hit kills one and scares the rest away for the rest of the scene. A successful AWE, BATTLE or HUNTING roll can also drive them away, for one round on a success, or for a whole scene with 1 or more [Success] icons. A Magical success on a SONG roll can command the crows for a scene, countering Dunwalla’s magic (see page 30).\n\nIf the Player-heroes kill a crow, they *lose (1d)* permanently in any social interactions with the Dunlendings of Crow Hall, and are blamed for all ill-luck in the rest of the scenario. (The crows, too, hate the murderer of their kin, and they have long memories…).", "topics": ["the beast of dunland"]}, {"concerns": [], "id": "#t2JYSsuy6I5oYfxHnIkjYgy", "name": "Halt!", "text": "If the Player-heroes set off for the Eordscrafa before Toirlas returns, then Dunwalla has to act quickly to salvage her scheme — she sends Dunrach off in haste to find Toirlas, and then has Dunrach bring Toirlas and his company on a route that crosses the trail to the Eordscrafa and intercepts the Player-heroes.\n\nDunrach argues that everyone should then return to Crow Hall — to welcome Toirlas home, and to carefully consider what is to be done next, instead of running off into the hills following a trail of blood.", "topics": ["the beast of dunland"]}, {"concerns": [], "id": "#tOBsKMsd51sEag50SPweBUn", "name": "Gleodwyn", "text": "The unfortunate woman has been a prisoner of the Dunlendings for days, and witnessed them slaughtering her family. She remains mute and terrified, although an ENHEARTEN roll from a friendly face can encourage her to speak. She begs to be rescued from the clutches of Toirlas.\n\nToirlas will not let her go freely; while his initial desire for her has been blunted by all the trouble of dragging her across Dunland, she’s still a valuable trophy in his eyes. He might ransom her or wager her in a game of\n\nchance or skill, but he will not relinquish her readily. The Player-heroes might: Fight Toirlas for her (but this risks turning the Dunlendings against the Player-heroes and Saruman) Help her escape by night (with a STEALTH roll, possibly penalised by the crows) Appeal to Gorsad (see *Part 6: The Judgements of Gorsad*, on page 39)\n\nFailing to rescue Gleodwyn, or at least ensure her safety, is a Misdeed worth 2 Shadow points.", "topics": ["the beast of dunland"]}, {"concerns": [], "id": "#t3y8QOTnv44TKQo6uzZKyoT", "name": "The Choices of Saruman, Part I", "text": "Raise Saruman’s Shadow by the fixed amount decided at the start of the campaign (1, 2, or 3; see *The Fall of Saruman*, on page 17).\n\nIf the Player-heroes committed Misdeeds\n\nover the course of the adventure collec-\n\ntively worth 4 Shadow points or more, raise Saruman’s Shadow by 1 point.\n\nIf Vila is not sent to Isengard, raise Saru-\n\nman’s Shadow by 1 point.\n\nIf Scepa is killed, raise Saruman’s Shadow\n\nby 1 point.\n\nIf Saruman loses influence over Crow Hall\n\n(because Toirlas takes credit for slaying the beast, or because he remains under the\n\ninfluence of Dunrach and Dunwalla), raise his Shadow by 2.", "topics": ["the beast of dunland"]}], "kind": "arc", "locations": [{"desc": "Mostly overgrown, it becomes clearer within a mile of Crow Hall. As travellers advance, they are constantly accompanied by the cawing of crows.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "LOCATION", "name": "1. Old Road", "props": [], "refs": [], "table": null, "type": null}, {"desc": "Towering pines with twisted branches crowd tightly around the settlement. Thousands of crows roost among their branches, their watchful eyes giving the forest its ominous name.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "LOCATION", "name": "2. Forest of Eyes", "props": [], "refs": [], "table": null, "type": null}, {"desc": "Built to protect the gates opening on the Outer Palisade at the end of the Old Road, this tower serves as the first line of observation.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "LOCATION", "name": "3. Watchpost", "props": [], "refs": [], "table": null, "type": null}, {"desc": "A rampart of sharpened stakes and wattle fencing fully encircles Crow Hall.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "LOCATION", "name": "4. Outer Palisade", "props": [], "refs": [], "table": null, "type": null}, {"desc": "Simple wooden enclosures hold the village’s livestock. Several pens are empty — it will be a hard winter for the clan.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "LOCATION", "name": "5. Animal Pens", "props": [], "refs": [], "table": null, "type": null}, {"desc": "Rough dwellings cluster within the palisade, built using parts salvaged from the stone houses of the ancient Númenorean stronghold.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "LOCATION", "name": "6. Dunlending Huts", "props": [], "refs": [], "table": null, "type": null}, {"desc": "The heart of Crow Hall, once a grand hall now diminished by time and conflict. Its roof sags, with bricked-up windows and cracked walls, yet it still serves as a gathering place.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "LOCATION", "name": "7. Feast-hall", "props": [], "refs": [], "table": null, "type": null}, {"desc": "The personal quarters of the chieftain and his advisers. Though modest, these chambers are well-defended from outside eyes — many crows roost on the eaves.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "LOCATION", "name": "8. Private Chambers", "props": [], "refs": [], "table": null, "type": null}, {"desc": "The door is low and narrow; scrapes and scratches on the stone lintels show that some large creature has crawled in and out recently. The Player-heroes must enter the tomb one at a time.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "LOCATION", "name": "1. Entrance", "props": [], "refs": [], "table": null, "type": null}, {"desc": null, "entities": [], "entries": [], "guidance": [], "id": null, "kw": "LOCATION", "name": "The Eordscrafa", "props": [], "refs": [], "table": null, "type": null}, {"desc": "A number of side chambers open along the low-ceilinged corridor. They once contained grave goods and other gifts to the dead, long since looted or turned to dust. Some offerings here are much more recent — animal bones from a carcass. Player-heroes observing them discover that the bones are slightly charred; the carcass was cooked. Now, some forms of Troll, like Stone-trolls, have the wit to cook their meals (roasted, minced fine and boiled, with a starter of burrahobbit pie), but the monster that attacked Crow Hall is not such a creature. Someone else provided this meal — and a search of the chamber (a **SCAN** roll) discovers the sticky residue of Dunwalla’s foul incense (see page 32). It stinks of pine, and breathing the fumes too deeply sickens the Player-hero.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "LOCATION", "name": "2. Outer Chambers", "props": [], "refs": [], "table": null, "type": null}, {"desc": "The Beast of Dunland sleeps here, amid the graves of kings. The chamber is so small that only one or two Player-heroes can fit in here if the monster is at home.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "LOCATION", "name": "3. Inner Chamber", "props": [], "refs": [], "table": null, "type": null}, {"desc": "The entrance to this chamber is concealed behind a heavy stone carved in the likeness of a decorated shield (**ATHLETICS** roll to move it); it contains a trove of ancient coins and treasures, a Lesser Hoard.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "LOCATION", "name": "4. Secret Chamber", "props": [], "refs": [], "table": null, "type": null}], "name": "The Beast of Dunland", "page": 21, "phases": [{"desc": "It is late summer. On their way to Isengard, the Player-heroes come upon a scene of horror. A small farmstead has been attacked, the inhabitants slaughtered.\n\nA Player-hero familiar with the region recognizes the place as belonging to a man named Sigulf. While suspicious of strangers, Sigulf was a good man who gave (albeit grudgingly) hospitality to travellers. The Loremaster may ask the player to describe Sigulf’s personality, his small household, and how they first met.\n\nThe attack on the farmstead clearly took place some weeks ago — the remains of Sigulf and his family lie exposed and unburied, and animals have partially consumed the bodies. There’s no sign that the defenders of the farmstead were able to slay any of the attackers. Of the farmstead and small barn, only ashes remain.\n\nThere’s no sign of any of Sigulf’s sheep, although a successful **HUNTING** or **SCAN** roll discovers some heavily trampled tracks, suggesting that at least some of the flock were driven up into the hills towards Dunland. One or more [Success] icons give a little more information:\n\nThis riddle, at least, looks easy to read. Raiders came down from Dunland and sacked the farmstead. Sigulf’s farm was isolated and only lightly defended, and hungry Men do evil things.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "PHASE", "name": "Part 1: Raiders from Dunland", "props": [{"items": [{"value": "If the Player-heroes are approaching Isengard from the west, via the Gap of Rohan, then Sigulf was of Dunlending blood; if they’re coming from the north or east, across the Mark, then he was of Rohan, but had quarrelled with the King’s men and had little contact with the other Rohirrim. Either way, Sigulf took no interest in the affairs of the wider world, preferring to tend to his sheep.", "vk": "scalar"}], "name": "Rules", "of": "STRING", "vk": "list"}, {"items": [{"value": "There were a dozen raiders, all on foot, and they took at least one prisoner — there are places where someone stumbled.", "vk": "scalar"}, {"value": "There are also other tracks, big and heavy and deep — a very large man, perhaps. All the tracks vanish on the stony ground of the uplands.", "vk": "scalar"}], "name": "Items", "of": "STRING", "vk": "list"}], "refs": [], "scenes": ["#ttVT6Ug0qGT9vEhex5SSkhj"], "table": null, "type": null}, {"desc": "Crow Hall lies about a hundred miles north-west of Isengard as the crow flies — but the crow has an easier journey. Travellers on foot must skirt the foothills of the Misty Mountains, and then traverse the desolate grey hills of Dunland. Even in summer, there’s something unwholesome about those brooding wooded hills under a leaden arch of sky. Saruman’s detailed maps of Dunland have marked the easiest route through the hills, but it’s still a hard road.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "PHASE", "name": "Part 2: Journey to Crow Hall", "props": [], "refs": [], "scenes": ["#tgOOQqh7FbfDWf7qEDK2cQF", "#tzvqghMY6MiDPhccYy6Woee", "#tPzBqMpcdRlq34vUFBdJXKN"], "table": null, "type": null}, {"desc": "A fire smoulders in the hearth at Crow Hall. Gorsad sits on a high seat beside it, staring into the ashes. There are only a handful of warriors in the hall, seated on long benches, and they look dour. They glare suspiciously at the Player-heroes as they arrive. Dunrach announces the Player-heroes to his lord, then sits with the warriors, muttering about the strangers from Isengard.\n\nGorsad rises to greet the Player-heroes. He winces as he stands, for his feet pain him terribly. If they introduce themselves as servants of Saruman, then he bows and greets them in the ancient tongue of the High Elves — *“Elen sila lumenn’ omentielvo”*. Otherwise, he merely invites them to sit and state their business.\n\nAs the Player-heroes sit, a big black one-eyed crow flies in through the window and perches on the rafter above one of them. The crow seems oddly attentive as it paces back and forth. This is the familiar of Dunwalla.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "PHASE", "name": "Part 3: The Lord of Crow Hall", "props": [], "refs": [], "scenes": ["#tcunOMGOJNKDMpN13cFk99o", "#tWZ8Rw09tCB8dSKmZ1qhFGM"], "table": null, "type": null}, {"desc": "According to their mission, the Player-heroes should endeavour to hunt the fearsome beast haunting the Dunlendings. To do so, they will likely search the area around Crow Hall. Dunrach offers to send three of his warriors with them as local guides — though these warriors provide no aid, they report back to the chieftain about the Player-heroes’ movements.\n\nSearching within the Outer Palisade of Crow Hall itself reveals many scratches on doors, fence-posts, and hut walls, suggesting the creature has huge, sharp claws — perhaps a Troll or a Warg, if the Wargs have indeed come west of the mountains.\n\nThe crows around the hall make a raucous noise whenever anyone moves — clever Player-heroes may deduce that for the monster to have slipped into the yard, it must have found a way to silence the watchful birds.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "PHASE", "name": "Part 4: The Search for the Beast", "props": [], "refs": [], "scenes": ["#t7UJ2V0rPSUHcxAYoN2hqsk", "#tqbNYri4uAaSRtEaBqX1vUN", "#tyKt6534d5a3JL28ql6vApH"], "table": null, "type": null}, {"desc": null, "entities": ["#toaZuep1a361JHq78g4BdMb", "#t6bKeB4hnomDGMtaFdLYgSW"], "entries": [], "guidance": [], "id": null, "kw": "PHASE", "name": "Part 5: The Eordscrafa", "props": [], "refs": [], "scenes": ["#tdLgXtoJqs9QTdHfcKxj5wp", "#trBaMo9d8qW6TOZXjAWu7J5", "#td30qyfHSPIU1fTmyxVaj7k", "#tGxzE9oVQ1VrZlCT0XNw6om"], "table": null, "type": null}, {"desc": "Several problems in this adventure may require arbitration by the chieftain of Crow Hall. While Gorsad is likely well disposed towards the visitors from Isengard, he must still weigh testimonies and appear unbiased.\n\nThe Loremaster should resolve this with another Council. The Resistance is based on the demands made by Player-heroes from those listed below. Making one or two of the demands is a Reasonable request (Resistance 3), three demands is a Bold request (Resistance 6), and making all four demands is an Outrageous request (Resistance 9).\n\nThe attitude toward the Player-heroes is Open if the initial Council when arriving at Crow Hall was successful, and Reluctant if it was not. However, if the Player-heroes slew the Beast and can offer some proof of it, the attitude is improved one step, to Friendly or Open, respectively.\n\nThe players should be informed of the above conditions ahead of the Council, so they can plan their approach accordingly. If the Player-heroes make demands not covered by the above suggestions, it is up to the Loremaster to set the final Resistance.\n\n**Updated Council Rules:** For this Council, and Councils in general, it is recommended using the updated rules in the third and later printings of **The One Ring** Second Edition core rules, where the time limit is equal to 4 plus 1 for each [Success] icon rolled in a successful introduction of the Council, and 3 if the introduction failed.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "PHASE", "name": "Part 6: The Judgements of Gorsad", "props": [{"items": [{"value": "**Sending Vila to Isengard:** While Gorsad would personally prefer for his daughter to be educated in Isengard, Dunwalla has spoken against it.", "vk": "scalar"}, {"value": "**Sparing Scepa’s Life:** The shepherd is suspected of being the monster who attacked Crow Hall.", "vk": "scalar"}, {"value": "**Freeing Gleodywn:** Toirlas captured her in a raid, which is permissible by Dunlending law.", "vk": "scalar"}, {"value": "**Accusing a Dunlending**, such as Dunwalla, Dunrach or Toirlas, of some misdeed, and convincing Gorsad of their guilt. However, unless some form of proof is presented, the Resistance rating for the Council will be 9, no matter what other demands are made.", "vk": "scalar"}], "name": "Items", "of": "STRING", "vk": "list"}], "refs": [], "scenes": ["#t6SNrvHVWkBuXCikjO02f8s", "#tqfZnZDBEzINO2gkSSBCGG0"], "table": null, "type": null}], "props": [{"name": "Epigraph", "type": "STRING", "value": "“... Saruman has long studied the arts of the Enemy himself, and thus we have often been able to forestall him. It was by the devices of Saruman that we drove him from Dol Guldur.”", "vk": "scalar"}], "roots": [], "scenes": [{"desc": "Saruman meets with the Player-heroes in the gardens of Isengard. It is a warm day, but a gentle breeze blows down off the mountains. Butterflies flit around the flowers in great profusion. The Wizard sits on a simple chair by a cloth laid out with a fine meal. The Player-heroes may eat and drink as they wish; Saruman only sips red wine. His white robes are glorious in the sunshine. His keen dark eyes study the Player-heroes.\n\n*“I have a task for you,”* he declares. *“Word has come to me that Crow Hall is troubled by a monster. Gorsad is chieftain there — a lord of the Dunlending people. He is known to me; when he was a young man, I fostered him here in Isengard. Go to him and give what aid you can — against this creature, or whatever else troubles his court.”*\n\nOne of Saruman’s servants — a Dunlending boy — hurries over with a rolled-up map at a signal from the Wizard. Saruman spreads the map out (and the wind instantly calms when he glares at the mountain) and points at the location of Crow Hall.\n\nLikely questions from the Player-heroes:\n\nIf the Player-heroes bring up the attack on Sigulf’s household, Saruman nods gravely. *“The work of Dunlendings. They are violent and cruel, for they long lived under the Shadow of the Enemy.”*\n\nSaruman also adds that it is high time Gorsad’s heir came to Isengard for a suitable education. Just as Gorsad was tutored in the virtues of rhetoric, philosophy and history, so should the next leader of Crow Hall. Little by little, generation by generation, they can be led into the light.", "entities": ["#trcydXQGQxmHOIdyRTB7UUX"], "entries": [], "guidance": [], "id": "#ttVT6Ug0qGT9vEhex5SSkhj", "kw": "SCENE", "name": "Counsel at Isengard", "props": [{"items": [{"value": "**What sort of monster? ***“It has not been seen directly — only the traces of its passage. It has slain some of Gorsad’s guards, and prowled outside the Hall at night. The Enemy has returned to Barad-dûr and his power grows daily; all across the land, evil things are stirring.”*", "vk": "scalar"}, {"value": "**What can you tell us about Crow Hall?*** “It is an ancient fort. Its walls were first raised by Men of Gondor, but it lay abandoned for centuries until the Dunlendings claimed it. It is named for the flocks of crows that nest nearby. My colleague Radagast says they are clever beasts. Some speak a few words of the Common tongue.”*", "vk": "scalar"}, {"value": "**Why help Gorsad?*** “He is one of the more… tractable of the Dunlending chieftains, more amiable to the guiding hand of Isengard. If strengthened, he may prove useful.”*", "vk": "scalar"}], "name": "Items", "of": "STRING", "vk": "list"}], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "The first journey event that the Player-heroes have is a chance-meeting with a wandering minstrel going by the name of **Caelur**. She claims to be a travelling singer and poet, roaming the lands in search of tales old and new. If the Player-heroes let her share their fire, and keep her safe on the journey, she’ll cook for them and sing them a song.\n\nA successful **INSIGHT** roll reveals that Caelur is closely watching all the Player-heroes, even as she pretends to be flighty and merry.", "entities": ["#tzfm7VopZOXgUueJogjCfMP", "#tLqt0PxPg8vUaGvWbKlpq45"], "entries": [], "guidance": [], "id": "#tgOOQqh7FbfDWf7qEDK2cQF", "kw": "SCENE", "name": "A Not-So-Chance Meeting", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "After parting from Caelur, the Company’s path winds north-west through the grey hills of Dunland. The going is hard; the brooding hills seem eager to betray travellers. What appears to be the right path may lead into a box canyon or into a field of thorns. The cloud-capped Misty Mountains block out the eastern sun, so mornings are invariably grey and miserable. The afternoons might be slightly brighter if not for the near-constant drizzle.\n\nAfter a few days, they come to the remains of an old Númenórean road, a side path off the old North-South Road. The road is overgrown and neglected, but is still straighter and more level than the hilly paths. It’s the road to Crow Hall.", "entities": [], "entries": [], "guidance": [], "id": "#tzvqghMY6MiDPhccYy6Woee", "kw": "SCENE", "name": "The Way Through the Hills", "props": [{"items": [{"value": "As they travel, a successful **HUNTING** roll from the Company’s Scout finds heavy tracks in the ditch at the side of the road — similar to the tracks they found near the despoiled farmstead in Part 1. There’s a large handprint in the mud, too, as if the traveller had stumbled and fallen. The tracks lead off the road up into the hills — if the Player-heroes follow these, they lead to **The Trail to Scepa** (see page 33).", "vk": "scalar"}], "name": "Rules", "of": "STRING", "vk": "list"}], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "Following the road, the Company approaches Crow Hall. Even in its diminished state, it is still a fortress worthy of note. Men of the South-kingdom built it as an outpost to watch over the road, more than two thousand years ago. The roof is mostly thatch, the windows bricked up, and parts have crumbled. A palisade of sharpened stakes guards the outer ring of the fort. Crows perch there, picking at the carcasses of enemies impaled on those stakes; thousands more crows roost next in the gloomy pines around the fort. The Player-heroes could not sneak up on Crow Hall unannounced, for the birds start cawing and croaking as soon as they see the Company.\n\nWithin the palisade is a small village of huts and animal pens — for pigs, chickens and other farm animals. Several pens are empty, and the people here have a gaunt, hungry look. A pair of crows squabble over a scrap of meat.\n\nDunlending warriors come out to challenge the newcomers. This band of guards is led by Dunrach (see box). He demands to know who they are and what business they bring to Crow Hall — and if their answers do not please him, he adds, hefting his axe, then the birds will eat well this evening.\n\nAs he leads the Player-heroes to the Hall, Dunrach mentions that it’s forbidden by ancient tradition to kill the crows of Crow Hall, and any stranger who troubles the crows will answer to him.", "entities": ["#t7yvykvQydz8g2zYI4RqkAT"], "entries": [], "guidance": [], "id": "#tPzBqMpcdRlq34vUFBdJXKN", "kw": "SCENE", "name": "Poor Welcomes", "props": [{"items": [{"value": "If the Player-heroes say they are messengers from Isengard, Dunrach scowls, but permits them to pass into Crow Hall. If they mention they bear a gift from Saruman, Dunrach demands they hand it over to him; he will convey it to the chieftain.", "vk": "scalar"}, {"value": "If they give a good reason for their presence (possibly requiring a successful **COURTESY** roll), they are also permitted to enter freely.", "vk": "scalar"}, {"value": "Otherwise, Dunrach expects tribute — a gift of Treasure or a Useful Item. Like, maybe, that silver box…", "vk": "scalar"}], "name": "Items", "of": "STRING", "vk": "list"}], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "The meeting with Gorsad can be set up using the rules for Councils, where the goal is for the Player-heroes to impress both the chieftain and the assembled warriors of the tribe. The attempt can be considered Reasonable (Resistance 3) if the Player-heroes have declared themselves as emissaries of Saruman, or Bold (Resistance 6) if they haven’t.\n\n**AWE** makes for a good Introduction, while a **COURTESY** or **RIDDLE** roll, although appreciated by Gorsad, is ill-suited to impress Dunrach and his warriors, and thus *loses (1d)*. During the Interaction the audience is Open, but it can be made Friendly by presenting the silver chest as a gift. Good Skills to use during this stage are **COURTESY**, **RIDDLE**, **SONG**, **LORE** (for tales of Saruman) or **BATTLE** (to discuss the defence of the hall against the Beast).\n\nGorsad does most of the talking for the Dunlendings, with the occasional interjection from Dunrach (or even Dunwalla — if a dramatic moment occurs in which she can make a suitable spooky entrance!). During the council, the chieftain recounts the tale of the Beast of Dunland:\n\nThe following questions are potential queries that the Player-heroes might pose to Gorsad, Dunrach, or the warriors and servants of Crow Hall.", "entities": ["#tr3wed44cnOiLaJACBTJCjb"], "entries": [], "guidance": [], "id": "#tcunOMGOJNKDMpN13cFk99o", "kw": "SCENE", "name": "A Council with the Crow Lord", "props": [{"items": [{"value": "The Beast first attacked some months ago, during the winter. It attacked sheep in the high hills, and shepherds fled from it — they said it was a fearsome monster, skull-faced and white-eyed.", "vk": "scalar"}, {"value": "Several weeks passed before it struck again — once more, devouring sheep.", "vk": "scalar"}, {"value": "It attacked again, this time closer to the Hall. The crows raised the alarm, and Dunrach and Toirlas were able to drive it away — but it fled before they could slay it.", "vk": "scalar"}, {"value": "The next attack was much more worrisome. That time, it somehow crept into the inner palisade without being seen, and prowled around the outside of the fort. Gorsad’s son Toirlas led a band of warriors out to hunt the monster, but they lost the trail in the mountains. Toirlas is still out adventuring; Gorsad hopes he will return soon.", "vk": "scalar"}, {"value": "Now the people of the village hide in Crow Hall for protection. The beast has returned twice since then, and each time the crows remained silent, providing no warning.", "vk": "scalar"}, {"value": "If Gorsad were healthier, then maybe he could have fought the beast. But given his present infirmity, his war-leader Dunrach advised it would be better to wait for Toirlas to return.", "vk": "scalar"}, {"value": "**What happens when the beast attacks? ***“When other foes come near the Hall, the crows give warning, and the warriors can prepare — but the beast strikes without warning, in deadly silence. Therefore, it’s become the custom of the people here to take refuge in the Hall by night. Three times, the monster’s gotten inside the outer palisade. We hear it snuffling and scratching at the door. The first time, we were all sleeping out in our huts, and it took three people. The second time, it took half the pigs and sheep. The third time, it took the rest. If it comes back again, who will it take?”*", "vk": "scalar"}, {"value": "**Where can we find this beast? ***“No-one knows. It’s been able to slip away from our best hunters. Maybe it is a ghost that leaves no tracks.”*", "vk": "scalar"}, {"value": "**Why do the crows here behave so strangely? ***“They are Crebain, and they were here long before any Men walked these lands. They have their own secrets, and their own wisdom that they rarely share. Dunwalla knows most about them.”*", "vk": "scalar"}, {"value": "**What ails Gorsad? ***“Some infirmity of the joints. It troubles him greatly, especially at night, and sometimes he is crippled by the pain of it. It is one thing for a chieftain to be less than whole of body — look at Ivoch son of Imlar, who has not walked since he was seven years old, but still strikes fear into the hearts of his enemies — but it is something else entirely when a chieftain loses his strength.”*", "vk": "scalar"}, {"value": "**Where is Toirlas? ***“Away hunting. He’s been gone a long time — sometimes, he goes down into the lands of the Forgoil * (the Strawheads — the Men of Rohan)* and steals from them. Dunwalla says he will come back soon, and we eagerly await that day.”*", "vk": "scalar"}], "name": "Items", "of": "STRING", "vk": "list"}], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "That evening, virtually the whole of the clan gather in Crow Hall. Every bench is full, and the Player-heroes must sit shoulder-to-shoulder with Dunlendings. The meal is a meagre one, and what little meat there is gets taken by Dunrach’s warriors (but if the Player-heroes got a Success on the Council, then Dunrach shares a fine portion of meat with them). It’s clear that the people of the settlement fear to sleep outside, and intend to stay here within the safety of the Hall.\n\nGossip throughout the hall is mainly focused around Gorsad’s ability to lead the clan, and speculating about what ill deed on his part is responsible for bringing such bad luck down upon them all — everyone knows that a weak leader brings troubled times. Maybe it would be better if Gorsad stepped down.\n\nDuring the meal, a strange woman enters the hall, coming down from the private apartments. A one-eyed crow sits on her shoulder, croaking into her ear. The Dunlendings fall silent as she makes her way across the room to sit next to Dunrach — for this is Dunwalla, his sister. She grins at the assembled crowd. *“Sleep lightly,”* she says, *“the crows are disturbed tonight. Maybe it is these strangers. Maybe not.”*\n\nMany of the Dunlendings make signs with their hands to ward off evil, and some even dare whisper that Dunwalla is a source of bad luck in herself. **INSIGHT** or **AWARENESS** rolls may reveal that Gorsad’s daughter Vila is especially scared of Dunwalla.", "entities": ["#thoJJlmqKBxMEUNytRwQpFX", "#tO8sdt0sdV7bBZeLbqTqpQK", "#tXHr0LiNozdaC5JLFikzYXy"], "entries": [], "guidance": [], "id": "#tWZ8Rw09tCB8dSKmZ1qhFGM", "kw": "SCENE", "name": "Night in Crow Hall", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "Searching for the trail of the beast in the lands around Crow Hall requires a **HUNTING** roll. However, if Dunwalla knows that the Player-heroes are looking for the beast, she sends crows to annoy them. The flapping and croaking of the birds makes the hunters *lose (1d)*, as the racket is distracting and alarms any potential quarries. If Dunwalla knows they’re agents of Saruman, she sends an even greater number of crows to harass them, making them *lose (2d)*.\n\nIf the **HUNTING** roll fails, the Player-heroes find no trails that day, and gain one point of Fatigue. They can try again the next day. If the Player-heroes are still sleeping in the barn, they cannot get rid of Fatigue points during a Prolonged Rest. On a success, they find either the trail to Scepa or Toirlas.\n\nAfter two days of searching, the Loremaster should move the story forward playing *The Homecoming of Toirlas* (see page 36). After five days, play *The Beast Attacks* (see page 38).", "entities": ["#tG0IfY2JtnqcSW6J0e4Kfk0", "#tKEU06MCRosbBsUUhUDaPHJ", "#tkADYJjO3zfnt8jT4bHAB3F"], "entries": [], "guidance": [], "id": "#t7UJ2V0rPSUHcxAYoN2hqsk", "kw": "SCENE", "name": "Hunting for the Beast", "props": [{"items": [{"value": "With a single [Success] icon, they find both trails and can choose to follow either.", "vk": "scalar"}, {"value": "With 2 or more [Success] icons or a Magical success, they also find the trail to the Eordscrafa (see below).", "vk": "scalar"}], "name": "Items", "of": "STRING", "vk": "list"}], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "Scepa is a shepherd; one of the two survivors of the raid on Sigulf’s farmstead (see page 23). The shepherd followed Toirlas’ raiders for days until he lost their trail, and ended up wandering half-mad in the hills around Crow Hall. The Player-heroes find him sleeping in a bed of branches like a wild man. If woken suddenly, Scepa attacks with panicked, flailing fists. A successful **AWE** or **COURTESY** roll is needed to calm him down.\n\nScepa is a giant of a man, and between his snow-covered clothing and wild hair and beard, the Player-heroes might be forgiven for mistaking him for a Troll. Any Dunlending warriors present think that he’s either a Troll or the ghost of Helm Hammerhand, and immediately assume that he’s responsible for the attacks (see *Scepa and the Dunlendings*, below).\n\nIf given the opportunity, Scepa haltingly tells his tale:\n\nOnce he sees that the Player-heroes are not Dunlendings (and especially if he knows any of them from their previous visits to Sigulf’s stead), he throws himself at their feet and begs for their help. He’s desperately hungry and thirsty, and will perish from exposure and hunger in a few days if not given aid by the Player-heroes.", "entities": ["#tHJ52rfJ7wB92aeXuz2R5mZ"], "entries": [], "guidance": [], "id": "#tqbNYri4uAaSRtEaBqX1vUN", "kw": "SCENE", "name": "Scepa’s Tale", "props": [{"items": [{"value": "He was a shepherd in the household of Sigulf. Sigulf was a good man, and kind. Even when times were hard, Sigulf saw to the needs of those who dwelt in his stead.", "vk": "scalar"}, {"value": "Raiders from Dunland attacked the stead. They were lean, hungry warriors.", "vk": "scalar"}, {"value": "They were led by a young warrior who wore crow feathers in his hair. At first, it seemed that the raiders were after the animals, and would be satisfied with taking a few sheep. Scepa was sent off to the high pastures to fetch down the flocks.", "vk": "scalar"}, {"value": "But then the crow-haired raider saw Sigulf’s daughter Gleodwyn, and he was determined to take her too. This Sigulf would not countenance, and the two fought. The Dunlending had the best of it, and slew Sigulf on the threshold of his own house", "vk": "scalar"}, {"value": "Scepa returned to the farmstead too late, and saw the raiders escaping with Gleodwyn and a great many sheep.", "vk": "scalar"}, {"value": "He followed the raiders on foot for many days — he doesn’t know how long — but lost the trail in these hills. He followed the crows to Crow Hall, assuming that the raider must have come from there.", "vk": "scalar"}, {"value": "He’s determined to have his revenge on the crow-haired warrior, and rescue Gleodwyn.", "vk": "scalar"}], "name": "Items", "of": "STRING", "vk": "list"}], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "Toirlas is a Dunlending prince. He wears crow-feathers in his hair, and his eyes have something of a bird about them too, nervous and predatory. He has a war-band of fellow young warriors, and spends his days wandering the hills hunting and making merry — and his chief delight is raiding other Dunlending clans or over the hills into Rohan. He thinks that his father Gorsad is book-weak and sickly, and considers Dunrach to be more of a mentor — but he’s also arrogant enough to think that a Dunlending chieftain can rule alone. When Toirlas becomes lord of Crow Hall, he’ll replace old Dunrach with one of his young cronies, and the old man can go sit by the fire with the other toothless greybeards. (He fears Dunwalla, though, and has no idea what to do about her.)\n\nWhen the beast attacked, Toirlas went out to hunt it; when he could not find it easily, he grew bored and decided to wander off on his favourite pastime of raiding. After all, he told himself, the monster has eaten half our sheep, so it’s a good thing to get more.\n\nOn this latest raid (the one that destroyed Sigulf’s stead), he kidnapped Gleodwyn, intending to bring her back to Crow Hall\n\n— as a prize or servant, he hasn’t decided yet. He’s taken a long road back to Crow Hall — partly because he visited various other Dunlending settlements to celebrate the successful raid, and partly because Gleodwyn has fought him every step of the way.\n\nIf the Player-heroes find Toirlas’ camp while hunting for the beast, they discover the young prince in the company of a half-dozen Dunlending warriors (and a few dozen stolen sheep, kept corralled by Toirlas’ beloved wolfhound Draug).", "entities": ["#tZ3eFhWXgfRvrNvXbQwUU74", "#t56LRMyUrq2X6RxIjkeXzNI"], "entries": [], "guidance": [], "id": "#tyKt6534d5a3JL28ql6vApH", "kw": "SCENE", "name": "Toirlas", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": null, "entities": [], "entries": [], "guidance": [], "id": "#tdLgXtoJqs9QTdHfcKxj5wp", "kw": "SCENE", "name": "Rumour", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": null, "entities": [], "entries": [], "guidance": [], "id": "#trBaMo9d8qW6TOZXjAWu7J5", "kw": "SCENE", "name": "Old Lore", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "From afar, the Eordscrafa appears as a small hill of scraggy green grass. It is not a natural mound, but a burial barrow, as its stone-linteled entrance suggests — an ancient tomb of a forgotten lord of Men from the Second Age. A massive structure of stone lies buried beneath tons of dirt, concealing a complex of subterranean chambers. The Dunlendings consider it a haunted and ill-omened place, but no evil spirits dwell there. Dunwalla knows it well; in her youth, she came here seeking lost secrets of the Elder Days, though she learned nothing from the carven stones.\n\nWhen her crows reported that the beast had taken up residence in the Eordscrafa, Dunwalla came here and left offerings for the monster, to keep it from returning into the mountains until Toirlas returned to slay it.", "entities": [], "entries": [], "guidance": [], "id": "#td30qyfHSPIU1fTmyxVaj7k", "kw": "SCENE", "name": "Background", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": null, "entities": ["#ttPp9jJGrGHgLAAP3pXHagf", "#t3tYogiEVzRgh28h5MuQAeU", "#tzpqhwBDGrOVvcSIMbm0Tdy"], "entries": [], "guidance": [], "id": "#tGxzE9oVQ1VrZlCT0XNw6om", "kw": "SCENE", "name": "Schemes and Troubles", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "The tale began with rumours of a beast troubling Crow Hall. How does it end? Presumably, the beast is slain, but who takes credit? Toirlas? The Player-heroes?\n\nWhat is the state of Gorsad’s chieftainship? Is he seen as a sickly, weak old man who will soon be replaced by his stronger son? Is his son under the influence of Dunwalla and Dunrach?\n\nWill the next chieftain of Crow Hall be indebted to Isengard, and heed the requests of the White Wizard?", "entities": [], "entries": [], "guidance": [], "id": "#t6SNrvHVWkBuXCikjO02f8s", "kw": "SCENE", "name": "Many Endings", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "On the way back to Isengard, the Player-heroes encounter the wandering singer Caelur once more. She eagerly asks them for news of Crow Hall (even if they did not mention where they were bound in their first meeting).\n\nOrdered by Saruman to do so, Caelur teases out what the Player-heroes did at Crow Hall and how they think events will play out in the coming years. Her key question is whether or not the chieftain of the hall (whoever that is) will be loyal to Isengard when the war comes.\n\nWhen the Player-heroes are back to Saruman, they are received briefly — the White Wizard is busy — but he assures them that he has been thoroughly informed of their deeds. He praises or scolds them according to their results, but if any misdeeds were done, he does not address them. *“Regretful, but perhaps inevitable,”* is his only comment.", "entities": [], "entries": [], "guidance": [], "id": "#tqfZnZDBEzINO2gkSSBCGG0", "kw": "SCENE", "name": "And Back Again…", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": null, "entities": [], "entries": [], "guidance": [], "id": "#tsJz5klxRyj5iuK2fi1GVt3", "kw": "SCENE", "name": "Preamble", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "The monster that threatens Crow Hall is a creature from the mountains, a Trollish thing that crawled out of some foul pit to trouble the world of Men. Perhaps it woke when Sauron returned in Mordor, for the Dark Lord is putting forth his will and waking all manner of evil things. The first attacks by the creature were as blindly cruel as winter winds.\n\nHowever, dissidents within Crow Hall intend to use the thing to shame Gorsad, the chieftain of the Dunlending Hall. Dunrach (captain of the guard) and his sister Dunwalla (a seer) would prefer for Gorsad to be replaced by his more pliable son, an energetic warrior and hunter called Toirlas. When Gorsad declared his intent to seek aid from Isengard, the conspirators saw a way to discredit the chieftain. Through her arts, Dunwalla can divine the movements of the Troll; Dunrach can then ensure that the hall’s defenders do not stop the monster. They intend to have the Troll be slain by Toirlas.\n\nTheir plans were delayed when Toirlas went off hunting, but soon he shall return…", "entities": [], "entries": [], "guidance": [], "id": "#tjUNuBhdFGsq1giBccQ9yh1", "kw": "SCENE", "name": "The Truth of the Tale", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "As helpers to Saruman, the Player-heroes’ task is to ensure that Crow Hall remains loyal to Isengard (and that Saruman’s ‘experiment’ remains a secret). They might do this through heroic deeds — by swiftly tracking down and slaying the monster, and dedicating their victory to the chieftain, or underhanded ones — discrediting Gorsad’s rivals, and replacing his heir Toirlas with a less independent Dunlending. They might get involved with the intrigues of the hall, or ignore them; they might go out of their way to help the victims of the Dunlending raiders, or turn a blind eye to those misdeeds.\n\nThis adventure is all about the Player-heroes’ choices as they meddle in the affairs of Crow Hall.", "entities": [], "entries": [], "guidance": [], "id": "#tFtLuiIFXs6vLgiZ5VHKkTE", "kw": "SCENE", "name": "Running the Adventure", "props": [{"items": [{"value": "If the Player-heroes are already agents of Saruman, they receive a message calling them to Isengard, and they come upon the scene described at the start of Part 1 below.", "vk": "scalar"}, {"value": "Otherwise, the Loremaster should present the same scene as they travel to Isengard, then run their first meeting with Saruman, incorporating the information presented on page 11 (*Meeting Saruman the Wise*).", "vk": "scalar"}], "name": "Items", "of": "STRING", "vk": "list"}], "refs": [], "table": null, "type": "Roleplay"}], "seq": [{"name": "Epigraph", "t": "prop"}, {"i": 0, "t": "location"}, {"i": 1, "t": "location"}, {"i": 2, "t": "location"}, {"i": 3, "t": "location"}, {"i": 4, "t": "location"}, {"i": 5, "t": "location"}, {"i": 6, "t": "location"}, {"i": 7, "t": "location"}, {"i": 8, "t": "location"}, {"i": 9, "t": "location"}, {"i": 10, "t": "location"}, {"i": 11, "t": "location"}, {"i": 12, "t": "location"}, {"id": "#ttVT6Ug0qGT9vEhex5SSkhj", "t": "scene"}, {"id": "#tgOOQqh7FbfDWf7qEDK2cQF", "t": "scene"}, {"id": "#tzvqghMY6MiDPhccYy6Woee", "t": "scene"}, {"id": "#tPzBqMpcdRlq34vUFBdJXKN", "t": "scene"}, {"id": "#tcunOMGOJNKDMpN13cFk99o", "t": "scene"}, {"id": "#tWZ8Rw09tCB8dSKmZ1qhFGM", "t": "scene"}, {"id": "#t7UJ2V0rPSUHcxAYoN2hqsk", "t": "scene"}, {"id": "#tqbNYri4uAaSRtEaBqX1vUN", "t": "scene"}, {"id": "#tyKt6534d5a3JL28ql6vApH", "t": "scene"}, {"id": "#tdLgXtoJqs9QTdHfcKxj5wp", "t": "scene"}, {"id": "#trBaMo9d8qW6TOZXjAWu7J5", "t": "scene"}, {"id": "#td30qyfHSPIU1fTmyxVaj7k", "t": "scene"}, {"id": "#tGxzE9oVQ1VrZlCT0XNw6om", "t": "scene"}, {"id": "#t6SNrvHVWkBuXCikjO02f8s", "t": "scene"}, {"id": "#tqfZnZDBEzINO2gkSSBCGG0", "t": "scene"}, {"id": "#tsJz5klxRyj5iuK2fi1GVt3", "t": "scene"}, {"id": "#tjUNuBhdFGsq1giBccQ9yh1", "t": "scene"}, {"id": "#tFtLuiIFXs6vLgiZ5VHKkTE", "t": "scene"}]}, {"cast": [], "cid": "tor2e-hands-the-sea-prince-of-the-shore", "container": "ARC", "dependsOn": ["tor2e"], "desc": "Rumour comes to Isengard of a charismatic new Prince who has arisen at the mouth of the Isen, a hero possessed of tremendous courage and wisdom. Saruman dispatches his agents, the Player-heroes, to investigate this tale. Secretly, he fears that the One Ring has been found by some barbarian of the shore, and it is his wish that it be recovered before others notice.\n\nIn truth, the Sea-prince’s source of power is quite different — he too is an agent of a greater power. In his case, he serves the Black Ship *Kathuphazgân*, an expedition from Umbar dispatched by Sauron to probe the defences of the Grey Havens and Rivendell. And for those masters, he has captured a prize — the Elf Gildor Inglorion, of Elrond’s household. When the Black Ship comes, its masters will break the Elf’s spirit and he will sing another song indeed.", "entries": [], "file": "tor2e-0.5-hands-the-sea-prince-of-the-shore.arc", "guidance": [{"concerns": [], "id": "#tbWq8GhyCqjq9LA01Ch04UV", "name": "Gold in the Muck (note)", "text": "*Hideous Toughness.* The creature is unaffected by unarmed attacks. Additionally, when an attack inflicts damage to the creature that would cause it to go to zero Endurance, it causes a Piercing Blow instead. Then, if the creature is still alive its Endurance score is set back at half its maximum rating.\n\n*Horrible Strength.* If the creature scores a Piercing Blow, spend 1 Hate to make the target’s Protection roll *Ill-favoured*.\n\n*Poison.* If an attack results in a Wound, the target is also poisoned.\n\nA NOTE TO THE LOREMASTER The poisoning of at least one of the Player-heroes would serve as a compelling ‘fortuitous’ event, as it gives the group a strong motivation to seek the Sea-prince’s assistance, enhancing the effectiveness of the scenario.", "topics": ["the sea-prince of the shore"]}, {"concerns": [], "id": "#twK5AFHlvJwMuI75nPvtRnv", "name": "The Tale of the Sea-prince", "text": "The Player-heroes might hear this tale in the tavern, or from Cradoc, or from virtually anyone they speak to in town.\n\n*The last few years have been hard for the tribe in Todden. The fishing’s been bad, there’s been hunger and sickness — and we’ve been raided by other tribes from up the coast.*\n\n*All seemed hopeless — and then a man came out of the sea. Strange of feature, and very tall, like the legendary Sea-kings of old. He brought gifts, and knowledge of healing spells. He cured sickness with his magic. He led the people of the village in counter-raids against their old rivals, and burnt their boats. For all these wonderful deeds and more, the people of Todden acclaimed the Sea-prince as their lord.*\n\n*Now the Prince dwells in an ancient tower out- side the village, and Old Cradoc (who was chief- tain before the Prince came) was appointed as steward. The Sea-prince has commanded Cradoc and his followers to gather food as an offering to the wild ruler of the Sea, the raging Storm-king.*\n\nThe ‘Sea-prince’ is a Black Númenórean named Nambar, from the crew of the *Kathuphazgân*. He was sent ashore to sway the Fisherfolk, and to gather provisions for the Black Ship so it does not need to return to the South to resupply.\n\nHe has succeeded in his mission — and found an unexpected treasure on the shore, too. The Elf Gildor Inglorion was wandering in this region on another errand, and Nambar has captured him. When the Black Ship returns, he intends to present Gildor to his mistress Zoril.", "topics": ["the sea-prince of the shore"]}, {"concerns": [], "id": "#tspDeCAJ0oADvD3EemEoKUC", "name": "Kathuphazgân and the Scouts from Umbar", "text": "As described in *Ruins of the Lost Realm*, the Black Númenóreans of Umbar have sent the gigantic warship *Kathuphazgân* north to the coastlands of Eriador. The ship’s mission is to prepare for the coming war; after taking Gondor, the forces of Sauron intend to destroy Lindon and Rivendell and prevent the remaining Elves from fleeing West over the Sea. There’s much more detail about the ship and its crew in *Ruins of the Lost Realm*.", "topics": ["the sea-prince of the shore"]}, {"concerns": [], "id": "#t1NPP4StnzgSwjQ71s8IVkU", "name": "The Musician and the Elf", "text": "A few months ago, Sellic met and befriended the Elf Gildor, who shares his love of music. Gildor had travelled to this distant land in search of the fabled Singer of the Shore. Gildor warned his new friend to keep his presence here a secret — Gildor had no desire to attract attention from superstitious mortals who might fear outsiders.\n\nWhile Sellic professed friendship with Gildor and swore to keep him hidden, in his heart Sellic grew jealous of the Elf’s infinitely deeper knowledge of musical arts.\n\nThen came the Sea-prince, and a terrible opportunity. Impressed by the Sea-prince, Sellic told him about Gildor. He had his servants capture him, and the Elf is now imprisoned in the dungeon under the sea-tower. The Sea-prince gave Sellic the Elf’s flute as a gift, and promised to take the minstrel with him when he returns to the sea.", "topics": ["the sea-prince of the shore"]}, {"concerns": [], "id": "#tGhlxZuDNOb9VVTyHBQcGVD", "name": "The Choices of Saruman, Part Ii", "text": "Raise Saruman’s Shadow by the fixed\n\namount decided at the start of the cam-\n\npaign (1, 2, or 3; see *The Fall of Saruman*,\n\non page 17).\n\nIf the Player-heroes committed Misdeeds\n\nover the course of the adventure collec-\n\ntively worth 4 Shadow points or more, raise Saruman’s Shadow by 1 point.\n\nIf the Player-heroes fail to discover the\n\norigin of the Sea-prince, raise Saruman’s\n\nShadow by 1.\n\nIf Gildor falls into the hands of the\n\nNúmenóreans, raise Saruman’s Shadow by 2. If the Player-heroes bring Saruman the\n\nSea-prince’s blue ring, raise Saruman’s\n\nShadow by 1.", "topics": ["the sea-prince of the shore"]}], "kind": "arc", "locations": [{"desc": "Market is too grand a term for this open space — there’s little trade here, just bartering for various necessities. The village is so isolated that outsiders never come, save the occasional brave traveller from western Gondor, and then only once every few years.\n\nRight now, the centre of the market is piled high with offerings to the Prince — dried fish, pickled and preserved food, sacks of grain, coils of rope and other necessities, just as he asked.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "LOCATION", "name": "1. The Market", "props": [], "refs": [], "table": null, "type": null}, {"desc": "The largest and oldest house in the town, which isn’t saying much. It smells strongly of fish, but so does everything here. Cradoc dwells here with his family, including his three large adult sons who serve as his enforcers (consider them **Southerner Raiders**).", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "LOCATION", "name": "2. Cradoc’s House", "props": [], "refs": [], "table": null, "type": null}, {"desc": null, "entities": [], "entries": [], "guidance": [], "id": null, "kw": "LOCATION", "name": "Todden", "props": [], "refs": [], "table": null, "type": null}, {"desc": "On the shore there’s a huge stone jetty, far larger than the village needs. A few fishing boats bob absurdly alongside it, underlining how strangely big it is. It’s clearly of far more advanced construction than anything else in the town. **LORE** or **RIDDLE** (for old tales) guesses it was built by the descendants of Númenor — but it looks relatively unweathered.\n\nIn truth, the landing was built by the Corsairs of Umbar about two centuries ago, when they landed a fleet here to support the Dunlending invasion. A ship far, far larger than the little fishing boats could dock here.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "LOCATION", "name": "3. The Old Landing", "props": [], "refs": [], "table": null, "type": null}, {"desc": "This simple building is an ale-house where the villagers gather around a bonfire to tell tales. It’s either smoky and dark, or cold and draughty depending on which way the wind blows.\n\nThere’s a musician here, **Sellic**, who’s the chief entertainer for the town. Sellic’s a clever and handsome young man — and he has a truly marvellous flute. A successful **LORE** roll recognises this flute as Elvish work. (A Player-hero who has spent a great deal of time at Rivendell automatically recognises the flute as very similar to one that belongs to **Gildor**, an Elf who often visits Elrond’s house).", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "LOCATION", "name": "4. The Tavern", "props": [], "refs": [], "table": null, "type": null}, {"desc": "The only way to reach the tower is by clambering up a narrow set of stairs. Long centuries of wind have worn these steps away, and sea-spray makes them slick. Player-heroes trying to run up to the tower (say, to avoid archers) must make an **ATHLETICS** roll to avoid slipping and falling, suffering a", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "LOCATION", "name": "1. Perilous Approach", "props": [], "refs": [], "table": null, "type": null}, {"desc": "moderate Endurance loss from falling and losing any advantage of speed or surprise.\n\nAs the Player-heroes approach the tower, they hear a faint but beautiful Elvish voice in the air. A successful **LORE** or **SONG** roll identifies the song as a fragment of the tale of Lúthien, when Beren and Finrod Felagund (the brother of Galadriel of Lórien) were imprisoned by the servants of Morgoth. Anyone who understands the words regains 1 point of Hope. The song seems to be coming from underground.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "LOCATION", "name": "The Ancient Tower", "props": [], "refs": [], "table": null, "type": null}, {"desc": "The door to the tower has been recently repaired and is well-fortified. During the day, one or two of the **Prince’s guards** keep watch here. Visitors are instructed to leave their weapons with the doorward, and to approach the Prince with their gifts. At night, it’s barred from within. Breaking it down requires a total of three successes on **ATHLETICS** rolls.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "LOCATION", "name": "2. The Guarded Door", "props": [], "refs": [], "table": null, "type": null}, {"desc": "The ground-floor room is the living quarters for the Prince’s guards and servants. They are all attired in the manner of the Fisher-folk from Todden, but something in their features and behaviour sets them apart: the servants speak only in whispers, bowing and scraping in the presence of guests, while the guards are exceedingly tall, solemn, and oddly formal.\n\nA successful **LORE** roll identifies some of the words used by the guards as *Adûnaic*, the ancient tongue of Númenor (and still used in Umbar). All the guards dress in coarse-woven tunics and wield simple spears like the rest of the Fisherfolk — but wear good chain shirts beneath those tunics, and the short swords at their sides are of excellent make.\n\nThere are always some guards here, and the stairs to the cellar are always watched.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "LOCATION", "name": "3. Lower Quarters", "props": [], "refs": [], "table": null, "type": null}, {"desc": "These chambers are piled with supplies in sacks, or hanging from the rafters. Some of the supplies are clearly for those dwelling in the tower — fresh fish, vegetables, firewood and lamp oil. Others are more suited for a long voyage — dried fish, salted meat, pots of preserved foods.\n\nConcealed amid supplies in the lowermost cellar are some well-made boxes (of timbers not found in these lands) containing swords, helms, armour and other such weapons. These weapons are non-magical, but of excellent quality — the smiths of Umbar do good work.\n\nThe door to the dungeon below is kept barred from this side.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "LOCATION", "name": "4. Cellars", "props": [], "refs": [], "table": null, "type": null}, {"desc": "Once, this small chamber must have held some treasure — coin to pay soldiers’ wages, maybe, or navigational maps and instruments, or books of lore. Now, it serves as a prison. Held here is Gildor Inglorion — and if the Player-heroes are captured, they’ll be thrown in here too.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "LOCATION", "name": "5. Dungeon", "props": [], "refs": [], "table": null, "type": null}, {"desc": "The Sea-prince has taken this middle chamber for his own. Embroidered cushions lie scattered about, and long woven curtains swirl in the sea-breeze. Braziers vomit sweet-smelling smoke that wafts throughout the chamber. The Prince sits with his back to the western window, overlooking the ocean, sunlight haloing him and hiding his features.\n\nIf the Player-heroes are welcome here, then the Prince has them sit or lie on cushions. See *An Audience With the Prince* or *The Healing Arts of the Prince* (page 54) for what they might seek from him. If they come here with violence in mind, then he calls for guards from the chamber below while trying to flee out the window.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "LOCATION", "name": "6. The Prince’s Chamber", "props": [], "refs": [], "table": null, "type": null}, {"desc": "Everything above this level has crumbled, but there remains a ring of stone that runs around the circumference of the tower. One of the Prince’s guards may be found here as a look-out during the day. There’s also a coiled rope tied to an iron ring, which can be used to rapidly escape from the tower in an emergency.\n\nOn the eastern side of the walkway is a new addition — a small altar, its surface blackened by ash. The Prince burns offerings to Sauron here.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "LOCATION", "name": "7. The Upper Walkway", "props": [], "refs": [], "table": null, "type": null}], "name": "The Sea-prince of the Shore", "page": 41, "phases": [{"desc": "Again, the Player-heroes are summoned to Isengard. The Loremaster should highlight any changes to Orthanc or the fortress that occurred since their last visit — it may have been months or years since they were last here.\n\nAgain, Saruman meets with them in the garden. *“There is a minor mystery that intrigues me. A trifling matter, most likely, but great troubles can arise from the smallest of things. Word has come to my ear of strange events near the mouth of the Isen. Tales of miracles and magical healings, of enchantment and…”* he raises a perfect white eyebrow. *“Wizardry.”*\n\nHe tells the Player-heroes that they are to follow the river west, beyond the Gap of Rohan and into the wild lands of southern Enedwaith. The coast of Enedwaith is lightly populated. Fisherfolk dwell on the shores of the Sea, Middle Men of little account in the great matters of the world. They are, Saruman warns, suspicious of outsiders and sometimes dangerous.\n\nA prince has arisen among them, said to be both valorous and wise, gifted with strange powers. The task is this — travel to the mouth of the Isen and seek out the man called the Sea-prince, and find out if he is dangerous, and if he possesses genuine power. *“He may be nothing more than a barbarian warrior, of little account. Or he might be like Dunwalla of Crow Hall, possessed of some fragments of old lore… or maybe he found some Elven relic of the Elder Days. Make sure that nothing untoward is going on, and if it is, take the appropriate action. I leave the details to your good judgement.”*", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "PHASE", "name": "Part 1: Word From the Shore", "props": [], "refs": [], "scenes": ["#th4451TI8MAs0s8g74rwQmL", "#tB42jkbqt15NyoWLGkndp02", "#tZHvGkUB2u2mLghiSJUh2Au"], "table": null, "type": null}, {"desc": null, "entities": ["#tImYSIFxd50fwJpSNMmQJBI", "#tce6CMMRcn2rordAlLVms1x"], "entries": [], "guidance": [], "id": null, "kw": "PHASE", "name": "Part 2: Todden, the Village by the Sea", "props": [], "refs": [], "scenes": ["#tbEuqzREmgbhk3Xsa2RkyBI", "#tGSEXMTQpZRkouHbsZdUG8U", "#tBjw08HxiXS9riKxwZth62W", "#tahSxPHRgpN45qRdIXTkzHN"], "table": null, "type": null}, {"desc": null, "entities": ["#ttc3Z7PTeSsGaOwuItLM9z3", "#tnriMTXCMTAnFw8oKtS2l22"], "entries": [], "guidance": [], "id": null, "kw": "PHASE", "name": "Part 3: The Ancient Tower", "props": [], "refs": [], "scenes": ["#tcHBs6TBMWd7KTF0lxQFlF7", "#tqWg6TeewXflmwS6WMGza5J", "#tDq2MI3BUbDHfvJ5Nj4yZeO", "#tp9O1pyi9AnDHlOuzCLG60Y"], "table": null, "type": null}, {"desc": "A few days after the Player-heroes arrive, a strange and unnatural fog rolls in across the ocean, swallowing Todden and the surrounding lands. The tower becomes a lonely spire, rising above the fog like a ship sailing on a sea of clouds. This fog cloaks the coming of the great ship *Kathuphazgân*.\n\nThe ship is too large to dock anywhere except at the old jetty in Todden; like some fabled sea-monster, she sails up the mouth of the Isen. Her size is staggering. No ship to match her has been built since the days of Númenor. The fog means observers only see fragments of her — massive masts like the spines of a dragon, the looming shadow of her titanic hull, the carven figurehead looming through the mist, the groaning of the many slaves at the oars and the chanting of the priests in the temple.\n\nShe passes the lighthouse tower, only her masts and black sails visible through the fog. To the Sea-prince’s devotees, this massive ship is the fulfilment of prophecy — did the Sea-prince not say that he would return to the ocean after a year and a day? Did he not say he was the emissary of the great King of Middle-earth? Everything he promised shall come to pass!", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "PHASE", "name": "Part 4: On Wings of Storm", "props": [], "refs": [], "scenes": ["#teLI65bAbdp2Jp2qzz9qfXv", "#tizqGX0z8ar6IKRC8DrZHOc"], "table": null, "type": null}], "props": [{"name": "Epigraph", "type": "STRING", "value": "“Have I not earnestly studied this matter? Into Anduin the Great it fell, and long ago, while Sauron slept, it was rolled down the River to the Sea.”", "vk": "scalar"}], "roots": [], "scenes": [{"desc": "Long is the path west, and though it passes through strange lands indeed, it begins in Rohan. The Player-heroes must pass the Fords of Isen, which in this time is well guarded by warriors of the Mark. The keeper of the Fords is a Rohir named **Erkenspere**; he hails the Player-heroes as friends if they present themselves as servants of Saruman, and speeds them on their way with fresh provisions. He cautions them that they have a choice of paths.\n\nErkenspere suggests that the Gore route is safer, but risks delay if the Player-heroes can’t find a way across the River.", "entities": ["#tngBRQWdTgH3j38QCeQzzVU", "#toUv3AxQzEyn73YHWhXSacY"], "entries": [], "guidance": [], "id": "#th4451TI8MAs0s8g74rwQmL", "kw": "SCENE", "name": "The Long Journey West", "props": [{"items": [{"value": "If they continue across the Ford, and keep the river on their right-hand side, then they will eventually pass into the West-march of Rohan, the region between the Isen and the River Adorn, a land called the Gore by its folk. The people who dwell there are part of the Kingdom of Rohan, but their loyalty cannot be guaranteed, for many cleave more to the Dunlendings. Still, they should be safe enough — but they will need to find a way to cross the river in the west of the Gore, and the waters there are so fierce that they are unfordable. They’ll need a boat or great good fortune.", "vk": "scalar"}, {"value": "The other option is to go back across the Ford, and take the harder path that keeps the river on their left-hand side, then they will be safe enough while they keep to the old North–South road. But soon road and river will diverge, and the path then will take them into very perilous lands where the worst of the Dunlendings dwell.", "vk": "scalar"}], "name": "Items", "of": "STRING", "vk": "list"}], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "After the junction of the Rivers, west of the Gore, the Company enters unknown and silent lands. The middle lands of Enedwaith were never part of the Old Kingdom, North or South, nor have the Elves ever dwelt here, unless it was in time out of memory. No folk live in these lands, and the few who pass down the river in boats do so hastily. Strange things lurk here.\n\nAs the Player-heroes pass through these lands, they may see some of the wonders listed in the table on page 44 — these are strange sights that the Loremaster may use as background description, or to flavour Events rolled along the journey (the butterflies might be a Joyful Sight, while the mire-spirits might be a Mishap or Short-Cut.)", "entities": ["#t6VZCK8w77yjBbArpYw7YgC"], "entries": [], "guidance": [], "id": "#tB42jkbqt15NyoWLGkndp02", "kw": "SCENE", "name": "The Silent Lands", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "As they travel, the Player-heroes come to another marshy region. Thick, sucking brown mud threatens to swallow their boots or drown the travellers entirely. If they try to go around the marsh, they discover it’s much more extensive than it looked at first glance (or else the marsh is somehow *following* them, reacting to their movements).\n\nAt the centre of this swamp is the Beithir. What is it? A failed dragon, maybe, a wingless worm, fiery breath long grown cold. A survivor from some previous age of the world. Fat it is, and long, a swollen tadpole with paddle-like limbs. It has a sting in its tail, and its slack, gaping maw has countless venomous teeth. It holds some unearthly power over the mud through the slime that it constantly secretes from its fleshy form.\n\nMost of all, it hungers. The Beithir’s preferred method of hunting is to poison a lone traveller, then swim away through the muck, waiting for the traveller to perish and sink into the marsh. Once the body is nicely fermented, the Beithir gobbles it up. Against a band of travellers, it relies on a furious assault, hoping to scatter them with terror.", "entities": ["#tsE0WAHAKeXNWe67l2YsRVL"], "entries": [], "guidance": [], "id": "#tZHvGkUB2u2mLghiSJUh2Au", "kw": "SCENE", "name": "The Poison of the Beithir", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": null, "entities": [], "entries": [], "guidance": [], "id": "#tbEuqzREmgbhk3Xsa2RkyBI", "kw": "SCENE", "name": "Rumour", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": null, "entities": [], "entries": [], "guidance": [], "id": "#tGSEXMTQpZRkouHbsZdUG8U", "kw": "SCENE", "name": "Old Lore", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "At last, the Player-heroes scent the sea — the Sea! If this is the first time the Player-heroes have beheld the great western ocean, take a moment to describe the staggering beauty of the waves crashing on the shores of Middle-earth; the sound of the gulls, the green-blue froth-capped waters stretching to the horizon, the waters that Eärendil the Mariner braved and that swallowed lost Númenor. Somewhere beyond the bent sphere of Earth lies the uttermost West, and Elvenhome forever. Indeed, for a moment the Player-heroes hear a snatch of song, telling of the wonders of the Elder Days.\n\nThen the enchantment passes, and the Player-heroes see a village by the mouth of the Isen. It’s a rough place — a few buildings of mud and straw, fish drying on wooden racks, inhabited by sullen fisher-folk. The town is called Todden in the local tongue, which means *the landing*.\n\nIf the Player-heroes are not obviously hostile, they are allowed entry into the town. The former master, and now steward, of the place is an old man named Cradoc. His sons escort the Player-heroes to his house so he may take a look\n\nat them. As they progress through the town, the heroes spot the huge pile of offerings in the market square, and hear strange music from the tavern.", "entities": [], "entries": [], "guidance": [], "id": "#tBjw08HxiXS9riKxwZth62W", "kw": "SCENE", "name": "Background", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": null, "entities": ["#tqO0FAkqApy3KngqlHi60TT", "#toM1gwRsNi0rQPe35hUeB60", "#t91jMs4VNmBGzqFPkg548gh", "#tVwtVGGrr6uY0BPWOCX0e38", "#t5PtQ4YXJ9wM1vxIDL4h5J8", "#tgCTe9mOuQoEkbXOvMJHjtD"], "entries": [], "guidance": [], "id": "#tahSxPHRgpN45qRdIXTkzHN", "kw": "SCENE", "name": "Schemes and Trouble", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": null, "entities": [], "entries": [], "guidance": [], "id": "#tcHBs6TBMWd7KTF0lxQFlF7", "kw": "SCENE", "name": "Rumour", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": null, "entities": [], "entries": [], "guidance": [], "id": "#tqWg6TeewXflmwS6WMGza5J", "kw": "SCENE", "name": "Old Lore", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "An ancient tower stands close to the village: according to the locals, it was built by the ancient Elves, but a successful **LORE** roll may reveal that its great foundations were laid by Númenórean masons, while the upper part is a later effort to repair a ruin, likely made at the time of Gondor.\n\nSilent and abandoned for centuries, the lighthouse has been claimed by the Sea-prince as his home while he resides near Todden. He dwells here with his guards.\n\nThe tower stands atop a stony headland, with steep cliffs on three sides. It seems to grow as the Player-heroes approach it, rising up like a wave of stone. In form and design, it is eerily reminiscent of Orthanc.", "entities": [], "entries": [], "guidance": [], "id": "#tDq2MI3BUbDHfvJ5Nj4yZeO", "kw": "SCENE", "name": "Background", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": null, "entities": ["#tPK7DygrPTOnOMdA5DzExRW", "#tqq6HrmKmJty6aTsTjegN9P", "#tyjMZj17V5wm9x2cb0keqIw", "#tGhOPC3ndJFPiQ770p2V7WC", "#toljJrD6tdxVyMSk35mEc3O"], "entries": [], "guidance": [], "id": "#tp9O1pyi9AnDHlOuzCLG60Y", "kw": "SCENE", "name": "Schemes and Trouble", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "On sighting the ship, the Sea-prince and his guards leave the tower and travel to Todden, taking Gildor (and any Player-hero prisoners) with them. It is a dangerous trek, with the unnatural fog making the steep path even more slippery, and it’s impossible to see more than a few feet ahead. It is the ideal time for any prisoners to escape, or for rescuers to come to their aid.\n\nThe ship docks. Armed guards (with weapons similar to those wielded by the Prince’s guards, but in far heavier war gear) secure the jetty, but no-one else descends from the mighty ship. Confused and fearful, most of the townsfolk (including Cradoc and his sons) wait to see what these strangers will do. A few people start carting offerings from the market square to the jetty.\n\nWhen the Sea-prince arrives, he and any prisoners are taken on board (assuming the Player-heroes don’t intercede). Sellic may be permitted to go too (if he does, then his body washes up on the shore a few days later, his heart cut out as a sacrifice to Sauron), but the Sea-prince forbids anyone else from Todden from boarding. *“I shall return,”* he says, holding up his blue ring so it catches the light, *“when the true King of Middle-earth commands it! Look to the East!”*\n\nIf the Sea-prince is dead or captured, then the ship waits only a short time before deciding his mission is a failure; the marines seize what supplies they can grab, and then the Corsairs hurl alchemical fire-bombs at Todden, destroying Cradoc’s house and other nearby buildings.", "entities": ["#tl3mvAePpF4pEYLURHpxeMH"], "entries": [], "guidance": [], "id": "#teLI65bAbdp2Jp2qzz9qfXv", "kw": "SCENE", "name": "Arrival", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "Once the ship departs, the Player-heroes may return to Isengard. What have they learned of the Sea-prince of the Shore? Some key questions follow, to help the Loremaster assess the situation:\n\nSaruman is best pleased if the Player-heroes interfered as little as possible. *“Better that the Corsairs think they have won, and that the fisher-folk are still their thralls. Defiance is to be expected and can be accounted for; but the turncoat who can deceive his allies and feigns loyalty until the right moment — his power is the greater because it is secret and unspoken.”*\n\nIf the Player-heroes defeated the Sea-prince and freed Todden, Saruman is concerned: *“This is a small victory, and temporary. They will come back and, now that they know they have an enemy, in greater numbers. We need to be prepared.”*\n\nIf Gildor has been taken to Umbar, Saruman is displeased: “*He knows many secrets, and they will be cruel to him. I will send word to my allies south, and try to extricate him from this situation. This is now beyond your abilities, or concerns, to deal with.”* If questioned later on, Saruman only replies that the Elf is being freed, or has been freed. The details remain unspoken: the destiny of Gildor is no concern of those who failed to free him.", "entities": [], "entries": [], "guidance": [], "id": "#tizqGX0z8ar6IKRC8DrZHOc", "kw": "SCENE", "name": "Return to Isengard", "props": [{"items": [{"value": "Was Gildor freed, or does he remain a captive of the Corsairs? He knows the location of the hidden valley of Imladris, making him a valuable prize for the Black Númenóreans.", "vk": "scalar"}, {"value": "What proof do the Player-heroes bring back to Isengard? Saruman can recognise the Corsairs from a description of the black ship, or by examining the swords and war-gear given to the Prince’s guards. Better by far, though, to bring him the Prince’s blue ring.", "vk": "scalar"}, {"value": "What becomes of the people of Todden? Is their village destroyed? Are they still deluded servants of the Sea-prince? What about the singer Sellic?", "vk": "scalar"}], "name": "Items", "of": "STRING", "vk": "list"}], "refs": [], "table": null, "type": "Roleplay"}, {"desc": null, "entities": [], "entries": [], "guidance": [], "id": "#ths99zHYTTD2AyBGbT9bTaD", "kw": "SCENE", "name": "Preamble", "props": [], "refs": [], "table": null, "type": "Roleplay"}], "seq": [{"name": "Epigraph", "t": "prop"}, {"i": 0, "t": "location"}, {"i": 1, "t": "location"}, {"i": 2, "t": "location"}, {"i": 3, "t": "location"}, {"i": 4, "t": "location"}, {"i": 5, "t": "location"}, {"i": 6, "t": "location"}, {"i": 7, "t": "location"}, {"i": 8, "t": "location"}, {"i": 9, "t": "location"}, {"i": 10, "t": "location"}, {"i": 11, "t": "location"}, {"i": 12, "t": "location"}, {"id": "#th4451TI8MAs0s8g74rwQmL", "t": "scene"}, {"id": "#tB42jkbqt15NyoWLGkndp02", "t": "scene"}, {"id": "#tZHvGkUB2u2mLghiSJUh2Au", "t": "scene"}, {"id": "#tbEuqzREmgbhk3Xsa2RkyBI", "t": "scene"}, {"id": "#tGSEXMTQpZRkouHbsZdUG8U", "t": "scene"}, {"id": "#tBjw08HxiXS9riKxwZth62W", "t": "scene"}, {"id": "#tahSxPHRgpN45qRdIXTkzHN", "t": "scene"}, {"id": "#tcHBs6TBMWd7KTF0lxQFlF7", "t": "scene"}, {"id": "#tqWg6TeewXflmwS6WMGza5J", "t": "scene"}, {"id": "#tDq2MI3BUbDHfvJ5Nj4yZeO", "t": "scene"}, {"id": "#tp9O1pyi9AnDHlOuzCLG60Y", "t": "scene"}, {"id": "#teLI65bAbdp2Jp2qzz9qfXv", "t": "scene"}, {"id": "#tizqGX0z8ar6IKRC8DrZHOc", "t": "scene"}, {"id": "#ths99zHYTTD2AyBGbT9bTaD", "t": "scene"}]}, {"cast": [], "cid": "tor2e-hands-the-disaster-of-the-gladden-fields", "container": "ARC", "dependsOn": ["tor2e"], "desc": "Three thousand years ago, Sauron was defeated. Isildur cut the Ring from the Dark Lord’s hand, and kept it as weregild for his father and brother. A scant few years later, Isildur himself was slain, and the Ring was lost. It fell into the river, Saruman says, and rolled down the Anduin to the Sea. But both Saruman and Sauron have spent centuries searching the banks of the Great River, looking for the glint of gold amid the mud. Neither found the precious Ring.\n\nBut Saruman found other things. In this adventure, the Player-heroes are sent to the aid of Saruman’s servant **Arcinyas**. The old scholar has been kidnapped by Goblins and dragged off into the depths of the earth — but it’s the treasures of his house that concern the White Wizard. Did Arcinyas find something in the Gladden Fields that *drew* the Orcs upon him?", "entries": [], "file": "tor2e-0.5-hands-the-disaster-of-the-gladden-fields.arc", "guidance": [{"concerns": [], "id": "#tzJzh5nfsVYODFU50rRPV4N", "name": "The Bones", "text": "These bones are perhaps the remains of Isildur himself, or one of the other soldiers who perished in that same ambush. Bringing them back to Isengard for Saruman to deal with is a neutral act for now (but see *The Choices of Saruman, Part III*, on page 72); taking time to inter the bones in a cairn or grave (or putting them on a boat and sending them down to the Falls of Rauros) allows each Player-hero to regain 1 point of Hope.", "topics": ["the disaster of the gladden fields"]}, {"concerns": [], "id": "#tqERUnBIrH8OzNO1aefpEO5", "name": "Who Rules Moria?", "text": "In the *Moria* sourcebook, control of the ruined city is split between three Orc factions — the Orcs of the Misty Mountains under a Great Orc called Malech One-eye control the upper city, Balrog-worshipping fanatics control the deeper levels, and a band of spies from Mordor have established a foothold in the mountains galleries above.\n\nRedtooth is in the service of Malech. If the Company visited Moria before, the balance of power may have changed. Still, Orcs are Orcs — Loremasters may adjust the description in this section to match their version of Moria.", "topics": ["the disaster of the gladden fields"]}, {"concerns": [], "id": "#tRUAP8XD5Pk6xFDoe5LWTrL", "name": "The Healing Arts of Arcinyas", "text": "Arcinyas is a student of Saruman, and has learned many healing techniques. He has even studied the weapons of the Enemy. If the Player-heroes are especially fatigued, then Arcinyas recovers a bottle of an Orcish liquor from a fallen foe, and explains that a draught can restore vigour to wearied limbs. The liquid tastes fiercely hot, but a drink from the flask removes 1 point of Fatigue instantly, at the cost of 1 point of Endurance. The flask contains six draughts.", "topics": ["the disaster of the gladden fields"]}, {"concerns": [], "id": "#tBnm5eWc3phubwAZy9CwdEo", "name": "Treasures of Isildur", "text": "The chief treasure found in the Gladden Fields by Arcinyas is no less than the *Elendilmir*, an heirloom of the royal house of Arnor. It is a gemstone that burns with its own inner light, set on a fillet of Mithril. Elendil wore it, and passed it to his son Isildur, who perished with it in the Gladden Fields.\n\nThe Star of Elendil is priceless beyond measure, as a symbol of kingship and authority.\n\nArcinyas also found remnants of a marvellous sword-belt, adorned with gems in the image of the constellation of Menelvagor the Swordsman, which was carried by Isildur along with the shards of his father’s sword. The shards were entrusted to Isildur’s squire Ohtar, so that he might carry them out of danger, but the belt remained with Isildur. The belt is a magnificent work of *Mithril* and steel, with the stars picked out in diamonds. It’s also woven around with potent spells of protection.\n\nAnyone passing a roll of LORE — or a Player-hero familiar with Gondor-lore — can instantly identify these treasures for what they are.\n\nThe third treasure is not described in any text preserved in Minas Tirith. It is a small casket of gold, attached to a broken chain so it might be worn around the neck. The little box is empty and unmarked by rune or token. At least, it’s empty *now* — but three thousand years ago, it held the One Ring.", "topics": ["the disaster of the gladden fields"]}, {"concerns": [], "id": "#tp4BxOqu1Kwrim2naPSEvwJ", "name": "Out of the Jaws of Defeat", "text": "What happens if the Player-heroes fail to recover the Elendilmir from the Orcs? The histories tell us that the jewel is found decades later by Gimli son of Gloin, while searching the tower of Orthanc long after the defeat of Saruman. How did it come to be there, if the Player-heroes did not bring it thence? On this matter, all we can guess is that Orcs can be swayed almost as easily as Men, and there must have been a beginning to the alliance of Saruman and the Orcs. Maybe Saruman bribed a company of ambitious Orcs to recover his stolen treasure, offering them shelter in Isengard afterwards — and from those Orcs spring the fighting Uruk-Hai of later years — another step on Saruman’s ruinous path.", "topics": ["the disaster of the gladden fields"]}, {"concerns": [], "id": "#tljXcm2XeXC1jJ7MK1Dvaxc", "name": "The Choices of Saruman, Part Iii", "text": "Raise Saruman’s Shadow by the fixed\n\namount decided at the start of the cam-\n\npaign (1, 2, or 3; see *The Fall of Saruman*,\n\non page 17).\n\nIf the Player-heroes committed Misdeeds over the course of the adventure collec-\n\ntively worth 4 Shadow points or more, raise Saruman’s Shadow by 1 point.\n\nIf Arcinyas is left behind, increase Saru-\n\nman’s Shadow by 1.\n\nIf the Company fails to recover the\n\nElendilmir, raise Saruman’s Shadow by 2.\n\nIf the Player-heroes accept the House of\n\nChimneys as a boon, increase Saruman’s\n\nShadow by 1.\n\nIf the Company brings the bones back to\n\nIsengard, make a note of it. If Saruman\n\nreaches Shadow 9 or more, this will trig-\n\nger the event *The Burning of the Bones*,\n\ndescribed on page 18.", "topics": ["the disaster of the gladden fields"]}], "kind": "arc", "locations": [{"desc": "Flames burn here no longer, but this once-great thoroughfare is mostly blocked by fallen masonry and blasted stones. Some terrible inferno (Durin’s Bane, of course) once swept through this place. The Orcs no longer use this passageway, although it’s possible to clamber and squeeze through the debris to reach the Door of Song.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "LOCATION", "name": "1. Chasm of Fire", "props": [], "refs": [], "table": null, "type": null}, {"desc": "Once, this was the great front door of the Harper’s Hall. It bears the image of a harp, and the words A Song Unheard by Men or Elves. The door is shut; it cannot be forced open, and has clearly not been used in centuries — in fact, it’s been shut since the fall of Moria. A song — specifically, a Magical success on a **SONG** roll — commands the door to open. Dwarves only need a normal success. The door opens soundlessly, and the singer may stop when it’s open by only a crack, letting the Player-heroes sneak unheard into the rooms beyond.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "LOCATION", "name": "2. Door of Song", "props": [], "refs": [], "table": null, "type": null}, {"desc": "These rooms were long ago looted and destroyed; nothing of value remains here, only Orc-filth and broken stone and masonry. The Player-heroes hear Redtooth’s followers in the hall beyond, either making merry with the loot and prizes they stole from the House of Chimneys or, if Baugrim and his company have arrived, falling suddenly silent. If the Player-heroes entered via the Door of Song, then their music echoes magically in this room.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "LOCATION", "name": "3. School of the Harpers", "props": [], "refs": [], "table": null, "type": null}, {"desc": "This was once a side entrance to the Hall. The Orcs use it now. Redtooth — aware of his somewhat precarious position in the hierarchy of Moria — keeps it guarded at all times, and the heavy doors are locked and barricaded from the far side. The Player-heroes can either wait for Orcs to enter or leave (which in effect means waiting for Baugrim’s company to arrive), somehow trick the Orcs into opening the door (maybe by having a Hobbit or other burglar lurking in the shadows, then the other Player-heroes knock and run away), or force it open with a roll of **ATHLETICS**.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "LOCATION", "name": "4. New Door", "props": [], "refs": [], "table": null, "type": null}, {"desc": "Once, this was a grand auditorium, where the harpers played for kings. The curved walls were made to reflect and amplify the sound. Now, bloody-handed Redtooth has set up his throne here, and all the walls echo are the raucous shouts and war-cries of the Orcs. There’s a fire-pit in the centre of the hall; the Orcs gather around it to tell tales of their raids on the surface world, while Redtooth lounges on his chair.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "LOCATION", "name": "5. Master-harper’s Hall", "props": [], "refs": [], "table": null, "type": null}, {"desc": "Redtooth has taken this chamber for his own. He keeps his stolen prizes here — a Greater Hoard. Little of it is Dwarf-stuff — Moria was plucked clean of loot long before Redtooth’s day, although he has taken some prizes from other Orc-chieftains. In addition to whatever coins or jewels are found in the hoard, here is where anything taken from the House of Chimneys gets dumped — see the *Treasures of Isildur* sidebar.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "LOCATION", "name": "6. Master-harper’s Chamber", "props": [], "refs": [], "table": null, "type": null}], "name": "The Disaster of the Gladden Fields", "page": 57, "phases": [{"desc": "This adventure begins when the Player-heroes are somewhere near Moria (on either side of the mountains). They are contacted by one of Saruman’s messengers. The minstrel **Caelur** (see page 25) is an excellent choice, as is **Drustan the Mercenary** (*Ruins of the Lost Realm*, page 42). Failing that, another messenger might have been sent on a hasty errand from Isengard, charging up to the Player-heroes on a horse ridden so hard that the poor beast keels over in front of them.\n\nIn all cases, the message is the same — get to the Gladden Fields *immediately* and *secretly*. There they will be briefed about a mission of the utmost importance. Saruman will send what other help he can from his allies among the Free Folk, but the Player-heroes must go *now*.\n\nTheir destination, the message says, is a house on the southern bank of the Gladden River, surrounded by a grove of thorn-trees. They will know it by its chimneys, a building technique unknown to most of the Men of Wilderland. A man named Arcinyas dwells there, a servant of Saruman, and he is in need of aid.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "PHASE", "name": "Part 1: The House of Chimneys", "props": [], "refs": [], "scenes": ["#t60hcICrIyDz6hV4rmBf8sU"], "table": null, "type": null}, {"desc": "The trail leads south-west. Depending on how much time has passed between the initial summons and the Player-heroes’ arrival at the House of Chimneys, the trail may be fresh or very cold. In either case, there would seem to be little hope of following a pack of Goblins up into their lair in the Misty Mountains, but the Player-heroes are blessed with good fortune — as they reach the foothills, one of them spots another scrap of green cloth, tucked into a crack in a boulder.\n\nSearching the nearby area reveals a shallow cave on the hillside. At the back of the cave, there is a secret passage leading underground. Opening it requires either a magical success or a great success on an **ATHLETICS** or **CRAFT** roll. Should they succeed, the Player-heroes are confronted by a band of Goblins from the Misty Mountains, stationed as a garrison at the entrance. There are two **Orc Soldiers** and one **Goblin Archer** for each Player-hero in the Company.\n\nIf they don’t spot the opening and linger after sundown, the Company members get ambushed by the Goblins when they come out at night.\n\nIf defeated, any surviving Goblins flee back into the secret passage. The Player-heroes can pursue, either sneaking after the Goblins before the door snaps shut, or harrying them with arrows and swords down into the dark.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "PHASE", "name": "Part 2: In Pursuit", "props": [], "refs": [], "scenes": ["#tYmILFkTdHg5QHdrLwbyEgg", "#tjLtM4iIh3NaqYYeHNScGsc", "#tPsOsddgn3uYUEt0pW90HK4", "#tKPFa25nujoOuO5bwN41NFc"], "table": null, "type": null}, {"desc": "Arcinyas has been taken down to the Ledge of Woe, a prison that lies in the Deeps below Durin’s Bridge, on the lip of the chasm. Prisoners taken by the Orcs are kept there until they can be brought down to the mines or put to other work.\n\nFortunately, a band of Orcs dragging prisoners leaves plenty of signs of their passage, so it is not difficult for the Company to follow Arcinyas’ trail. The Orcs cross Durin’s Bridge, then descend through a maze of stairs and ramps down to the levels below the Second Hall.\n\nOnce Arcinyas has been handed over to the gaolers, Redtooth and his followers proceed to their lair elsewhere in the city. Redtooth has claimed the Sixteenth Hall of Moria as his own, known as the Harper’s Hall. If the Player-heroes are close on their trail, they can choose to abandon the rescue of Arcinyas and instead follow Redtooth (see page 68).", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "PHASE", "name": "Part 3: The Rescue of Arcinyas", "props": [], "refs": [], "scenes": ["#tNmIN1tBz6WHPMaC4xHWevK", "#tw2KcLoZG1S4YPOOORPjesX"], "table": null, "type": null}, {"desc": null, "entities": ["#t9ChAghXmBg6IyGvhDMxBDg", "#tvLmZGB1VUASJJc456qellV", "#tkr3nZGlduWl0tDNrJhJVyH"], "entries": [], "guidance": [], "id": null, "kw": "PHASE", "name": "Part 4: The Harper’s Hall", "props": [], "refs": [], "scenes": ["#tYSulmlgxmzvDLtAT0oLfGZ", "#tKUAmVgqqWPOjzagbgP2auB", "#t6JvW9rSv23yyJ6EufXutdw", "#tBrHy2o0kdgvW456LLh9aVu", "#tByLxKwj0RDOOTPYzgZZvWL"], "table": null, "type": null}, {"desc": "If the Player-heroes are able to recover the Elendilmir through stealth or misdirection, then they can slip away quietly and head back towards the East-gate — at least, until the Orcs notice the theft and the alarm is raised.\n\nIf they’ve started a combat, then they must fight every step of the way out. It is clear to any Player-hero that standing and fighting against the Black Uruks is utterly hopeless — speed is their only chance of survival.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "PHASE", "name": "Part 5: Escape From Moria", "props": [], "refs": [], "scenes": ["#tKjrvwfTtdYzszkgjgnccSY", "#tZSdC36QapAFLFUUqZyKIHU", "#tQs0hvQiApu5VZ8FIys4nWs"], "table": null, "type": null}], "props": [{"name": "Epigraph", "type": "STRING", "value": "“ ‘And there in the dark pools amid the Gladden Fields,’ he said, ‘the Ring passed out of knowledge and legend; and even so much of its history is known now only to a few, and the Council of the Wise could discover no more.’ ”", "vk": "scalar"}], "roots": [], "scenes": [{"desc": "The Gladden River — Sîr Ninglor — rises in the Misty Mountains and tumbles swiftly down into the Vales of Anduin. It wends through wide, flat marshes laden with brightly coloured flowers, yellow and purple, until it joins the Great River. Those marshes are the Gladden Fields.\n\nAs the message promised, there is a grove of thorn trees on the south bank, about sixty miles from the foothills of the mountains. Visible in the midst of the thorns are the chimneys of a fine house. There is something very strange about this place — this is a lonely spot, with no other houses or signs of habitation visible within many miles. The thorn trees seem to catch the mists that hang over the marshes, hiding the house in a cloak of fog. When the Player-heroes step into the shadow of the thorn grove, it seems to swallow light and sound. It’s eerily quiet here — which makes for grisly contrast with the aftermath of battle.\n\nBodies lie scattered amid the trees, both Men and Goblins, some pierced by arrows, others cut by swords. Judging by their gear, the Goblins came down from the Misty Mountains. The Men are all of fighting age — mercenaries or outlaws, maybe. Some look familiar, as if the Player-heroes saw them on a visit to Isengard.\n\nA Goblin-trail leads off west into the hills\n\nThe house itself has been ransacked, the door forced open. Inside, if one is willing to overlook the trampled mud and other debris, and the general Goblin-mischief, they find a remarkably nice house — stout stone walls, a (formerly) well-stocked pantry, a fine kitchen, and bedrooms and a study (!) on the upper floor. Clearly, this was the home of a scholar.\n\nSearching about discovers several clues about the purpose of the place:", "entities": [], "entries": [], "guidance": [], "id": "#t60hcICrIyDz6hV4rmBf8sU", "kw": "SCENE", "name": "Battle Among the Thorns", "props": [{"items": [{"value": "A successful **BATTLE** roll determines that the Orcs carried the day, but at a high cost — the Goblins slew all the defenders of the house and looted it, carrying whatever prizes they could back into the mountains.", "vk": "scalar"}, {"value": "A successful **HUNTING** roll tells that the Goblins took at least one prisoner, judging by the tracks.", "vk": "scalar"}, {"value": "There is a remarkably detailed map of the Vales of Anduin, annotated with little scribbled notes like ‘three weeks — naught but a fishhook!’ or ‘found only leeches’ or ‘searched this bank until I caught cold’.", "vk": "scalar"}, {"value": "A trampled scroll titled *A History of the Kings of Arnor*, describing how Isildur perished when ambushed by Orcs. A **LORE** roll identifies this as a partial copy of a famous history written in Fornost Erain in the time of Arvedui the Seer; the hand is that of Saruman.", "vk": "scalar"}, {"value": "In the upper bedroom, there is a wardrobe. It has been looted like the rest of the rooms, the Orcs carrying off most of the clothes. A **SCAN** roll finds a tatter of green cloth caught on the door; if the Player-heroes have met Arcinyas the Healer before, they recognise it as a type of cloth he favours for his robes.", "vk": "scalar"}, {"value": "There was a secret compartment in the wardrobe — secret, until the Goblins broke it open. Inside is a wooden box, lined with fine silk — again, despoiled by the Goblins. Whatever treasures it once held are gone. However, some items do remain — a few rings of chain-mail, an Orcish arrow-head, a semi-circle that might be the rusted remnant of a horseshoe, scraps of blackened, ancient leather preserved in the bog, and a few rotten bones. The players may guess correctly that these are relics of Isildur’s company, discovered in the marshes many centuries later.", "vk": "scalar"}, {"value": "Thrown on the floor and stamped upon is a small flask of *Miruvor*, the travelling cordial of Rivendell. The Goblins thought it was foul poison and threw it aside, but the flask is intact and there are still nine draughts of the cordial available. A Player-hero who drinks a draught gains 1 less Fatigue on the next journey event.", "vk": "scalar"}], "name": "Items", "of": "STRING", "vk": "list"}], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "Following the path further underground leads to a Goblin lair at a crossroads. It is a small, claustrophobic maze of narrow Goblin-tunnels and low caverns, dimly lit by flickering torchlight. Waste and debris litter the ground, and the air is thick with the acrid smell of smoke and damp earth. At this junction, a Goblin chieftain dwells.\n\nAs the Player-heroes reach the crossroads, they see a grotesquely hunched Goblin surrounded by his bodyguards. He is sizing the Company up from the opposite passage, his face twisted in visible unhappiness and frustration. His snarling expression makes it clear that something has disturbed his mood.\n\n*“What now? More fools sneaking into my tunnels? Do you think Bugrag likes visitors? Especially after those Moria-orcs stole my prized trophies — my precious things. They’ve taken what’s mine, and yet here you are, creeping around as if you own the place.”*\n\nThe Player-heroes may choose to bargain with **Bugrag** to obtain information — perhaps offering to retrieve what the Moria-orcs stole from him (precious things amounting to a Lesser Hoard).\n\nAlternatively, they can decide to slay him and his guards and then question a human prisoner they spot hiding in the dark, with manacled hands and feet.\n\nEither Bugrag or the prisoner **Gambold** can tell the Player-heroes the following:\n\nHe’d found some valuable treasure he kept in a pouch around his neck. He had a prisoner, too — a white-haired old man called Arcinyas.", "entities": [], "entries": [], "guidance": [], "id": "#tYmILFkTdHg5QHdrLwbyEgg", "kw": "SCENE", "name": "An Encounter Underground", "props": [{"items": [{"value": "Orcs came from Moria, under the command of a mighty Orc-chieftain called Redtooth, and rested here before going on a raid of the surface. They knew where they were going — some other prisoner in Moria had let slip the location of a house by the Gladden Fields where there was much treasure to be found.", "vk": "scalar"}, {"value": "The Orcs went on their raid, taking many of Bugrag’s Goblins with them. Only a few of the raiders returned — but Redtooth was very pleased with the outcome.", "vk": "scalar"}, {"value": "Redtooth and his Orcs remained here for a while to tend their wounds before returning to the surface, dragging their prisoner along with them. Bugrag was furious that the Moria-orcs didn’t share any treasure with him — in fact, they had even robbed him of some prized weapons. Redtooth’s company only left last night, which means there’s still a chance the Player-heroes might catch them before they reach Moria!", "vk": "scalar"}], "name": "Items", "of": "STRING", "vk": "list"}], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "Redtooth left Bugrag’s lair through a different cave entrance than the Player-heroes used to enter. This second cave opens onto a steep, treacherous path that descends into a perilous gorge. Below, a fast-flowing stream — a tributary of the Gladden — races along the canyon floor, its waters churned and turbulent.\n\nOn the far side of the canyon dwell **Giants**. Difficult to notice at first — they rarely move and blend with the rock face of the mountain itself — they reveal their presence by hurling stones with great force. The Giants are quick to spot any travellers crossing their territory, and they aim their stones at anything that moves.\n\nOnce clear of the Giants’ threat, the Player-heroes can find the Orc-trail that leads south once more. It’s clear that this Redtooth has forced his Orcs to march at a ferocious pace, but the Orcs can only travel at night; they must shelter from the sun by day.\n\nDay by day, mile by mile, the great peak of Caradhras swells larger and larger. Evening sunlight on its snowy peak makes it a redtooth too, a gory spire that guards the gates of the underworld.", "entities": [], "entries": [], "guidance": [], "id": "#tjLtM4iIh3NaqYYeHNScGsc", "kw": "SCENE", "name": "On the Orc-trail", "props": [{"items": [{"value": "If at least one Player-hero succeeds on a **SCAN** roll, they spot the threat in time, allowing the Company to sneak past the Giants unnoticed. Otherwise, each Player-hero must make an **AWARENESS** roll to dodge the incoming stones as they fall — those who fail suffer a grievous Endurance loss from falling. Alternatively, the Player-heroes can skirt around the canyon, adding two days’ travel to their journey.", "vk": "scalar"}, {"value": "If the Player-heroes have avoided delay through mishaps or other events in the journey, then they catch up with the Orcs before they reach the safety of Moria (see **The Orcs Intercepted**, below). However, if the Player-heroes lingered or incurred some delay (due to the Giants, for example), then they see the Orcs in the distance as they run for the safety of the shadow of the East-gate.", "vk": "scalar"}], "name": "Rules", "of": "STRING", "vk": "list"}], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "If Redtooth spots pursuers, then he splits his forces in two. He sends his swiftest Orcs ahead to Moria to summon aid, and these runners carry their treasure. **Redtooth** (with the captive Arcinyas) and his remaining Orcs (one **Orc Guard** and two **Orc-soldiers** for each Player-hero) turn and make their stand on the eastern slope of Caradhras: here there are shallow caves and ruins where the Orcs can hide from the sun if they cannot reach safety before dawn.\n\nA successful **AWARENESS** roll spots the Orc-messengers sprinting for the Dimrill Gate, but if the Player-heroes go after them, Redtooth’s warriors can surround them on the open ground of the dale, and the Player-heroes will be outnumbered and at disadvantage. Should the Player-heroes triumph and rescue Arcinyas before he is brought into Moria, see *Arcinyas’ Tale* (on page 65).\n\nHowever, the Company must still recover the treasures carried by the runners. These runners go to the Harper’s Hall (see page 68) and wait there, expecting their leader Redtooth to soon return, triumphant from the battlefield. When it becomes clear that Redtooth is dead in the sunlight of the Dimrill Dale, the runners become fearful and paranoid, arguing over who should hold the treasures and who is responsible for this debacle (see *Hot Potato*, on page 70).", "entities": [], "entries": [], "guidance": [], "id": "#tPsOsddgn3uYUEt0pW90HK4", "kw": "SCENE", "name": "The Orcs Intercepted", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "If the Player-heroes fail to catch the Orcs before they enter Moria, then there’s a fearful choice before them. They can abandon their quest and return to Saruman to report their failure, ending the scenario (see *The Choices of Saruman, Part III* on page 72), or they can boldly (or stealthily) follow the Orcs into the long dark of Moria. The East-gate is presently unguarded, so the Player-heroes can just sneak along following the distant clamour of the triumphant Orcs as they descend into the depths.\n\nAlternatively, if the Player-heroes hesitate on the threshold and linger in the safety of the Dimrill Dale for a while to rest and recuperate, the Loremaster should refer to *Mordor-orcs!* (see page 66).", "entities": ["#tSD7VukaUa9CzpK6yhk3ouE"], "entries": [], "guidance": [], "id": "#tKPFa25nujoOuO5bwN41NFc", "kw": "SCENE", "name": "The Orcs Reach Moria", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "The Player-heroes reach the Ledge of Woe following the tracks of Redtooth and his minions. Loremasters with the *Moria* supplement can enhance this scene by consulting pages 158 and onward. Alternatively, they can improvise the underground combat encounter based on the following description: a guard-post leads to the ledge, and is watched by twice as many **Orc Guards** as there are Player-heroes — some fully armed, others serving as servants or thralls with improvised weapons. Further in, Gaoler **Grimnar** waits — a **Great Orc Bodyguard** armed with a cruel metal whip and holding the keys to the prisoners’ chains.\n\nSpeed is crucial here, as the Orcs will raise the alarm once attacked. If using the Eye Awareness rules (see *The One Ring*, page 169), a Revelation episode will call a host of Orcs down on the Player-heroes; otherwise, more Orcs will arrive if the fight drags on too long.", "entities": ["#t8bryKyeesGSTW5X0l1VWi2"], "entries": [], "guidance": [], "id": "#tNmIN1tBz6WHPMaC4xHWevK", "kw": "SCENE", "name": "To the Ledge of Woe", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "Old Arcinyas is grateful (and somewhat surprised) to be rescued, and blubbers his gratitude to Saruman, as he assumes that the Wizard sent the Player-heroes just to rescue him. Between sobs, he tells them that he was master of the House of Chimneys, and for many years he has done Saruman’s bidding by searching the banks of the Anduin for treasures. The river holds many secrets, and great treasures have been cast into the waters over the long years. Why, only last spring, the meltwaters washed down the Ninglor and exposed remains buried for an Age of the world. Old swords, bits of armour, bits and bridles, Orc-arrowheads\n\n— and oh, something else. Something he saw glinting in the mud, something he cannot speak of…\n\nWhen he realises that the treasure he found has been taken by the Orcs, Arcinyas grabs the nearest Player-hero and shakes them violently. They must get the treasure back! Saruman will be furious if they don’t.\n\nArcinyas tries to avoid saying what the treasure he found actually is, claiming it’s a matter that should only be discussed with Saruman. If pressed, he admits that he found ancient treasures. Prizes, he thinks, brought back from the victory of the Last Alliance.", "entities": ["#tFqIBYp5EhV8C9iN1GMC31i", "#tUplRQbNcDtR95pJ9fRfKrs", "#tXHRas17bN8vEkJceHoyxGm"], "entries": [], "guidance": [], "id": "#tw2KcLoZG1S4YPOOORPjesX", "kw": "SCENE", "name": "Arcinyas’ Tale", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": null, "entities": [], "entries": [], "guidance": [], "id": "#tYSulmlgxmzvDLtAT0oLfGZ", "kw": "SCENE", "name": "Rumour", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": null, "entities": [], "entries": [], "guidance": [], "id": "#tKUAmVgqqWPOjzagbgP2auB", "kw": "SCENE", "name": "Old Lore", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "Many wonders spring from Mithril. Among the rarest was the alloy *Thilevril*, used to make the famous harps of Khazad-dûm. The secret of these harps was kept in the Sixteenth Hall, called the Harper’s Hall. This was a guild-hall, ruled not by a Dwarven noble or prince, but by the master-harper. There, they preserved the ancient lore of the Dwarves in song and rhymes of lore.\n\nWhen the city fell, the harpers were trapped by flames, and much was lost. More despoliation came later, for when Orcs found the Hall, they broke the harps, and wove the strings into cruel whips and garottes instead.", "entities": [], "entries": [], "guidance": [], "id": "#t6JvW9rSv23yyJ6EufXutdw", "kw": "SCENE", "name": "Background", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": null, "entities": [], "entries": [], "guidance": [], "id": "#tBrHy2o0kdgvW456LLh9aVu", "kw": "SCENE", "name": "Map of the Harper’s Hall", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": null, "entities": ["#tllao9XzkP3SHHIChbuzbun", "#tViJJeOtzlDyniyYuKehSY1", "#t60PPdmpIZb4XmW1p4Ej9JQ"], "entries": [], "guidance": [], "id": "#tByLxKwj0RDOOTPYzgZZvWL", "kw": "SCENE", "name": "Schemes and Trouble", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "The flight to the East-gate can be played as a Skill Endeavour using **ATHLETICS**, **EXPLORE**, or **STEALTH**. Navigating the depths of Moria and retracing their steps back is a Laborious attempt (Resistance 6), with a time limit equal to 3, 4 or 5 (the Loremaster chooses based on how the Player-heroes fared in the Harper’s Hall. The time limit increases by 1 if the Player-heroes have a guide like Nidi.\n\nIf the Skill Endeavour fails, then the Player-heroes are cornered by Orcs in a dead end in Moria; the Orc-ranks part to reveal a snarling **Great Cave-Troll**. The Company must do battle with this monster to escape the dead-end corridor. If they survive — or escape in time — then they pass under an archway and suddenly they are in the open air, the stars blazing bright above them. The green grass of Dimrill Dale, black in the night, spills away down the slope towards the distant River. They’re out! They’re out!\n\nHowever, the Player-heroes see more shapes moving in the darkness. More Orcs! Those who pass an **AWARENESS** roll also see a dark shape circling overhead, its wings blotting out the stars as it flies. A great or extraordinary success confirms it’s a **Great Eagle**.\n\nBut first, the Company must face the Orcs.", "entities": [], "entries": [], "guidance": [], "id": "#tKjrvwfTtdYzszkgjgnccSY", "kw": "SCENE", "name": "Flight to the East-gate", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "The Orcs of Mordor do not approach; instead, they form a semi-circle around the Player-heroes. At the same time, a horde of Moria-orcs spill out of the East-gate, and they too halt, not daring to come closer. They form the other half of the circle; the Player-heroes are surrounded.\n\nAnd they are not alone in that circle. All the Player-heroes feel an intense and nameless dread wash over them. The stars seem to fade overhead as an unseen presence approaches them. As it draws closer, each Player-hero gains 4 Shadow points (Dread); those who gain any Shadow points dimly perceive the figure as a pale king holding a thin and dreadful sword.\n\nThe deadly voice of the **Ringwraith** speaks. *“WHAT HAVE YOU FOUND? YIELD IT OVER TO THE LORD OF THE RINGS.”*\n\nIf the Player-heroes all surrender the treasures to the Nazgûl, the wraith laughs thinly and vanishes. The Orcs swarm in, and the Player-heroes must last a single round of combat before help arrives. Surrendering the treasures when faced with hopeless odds is a Misdeed worth 2 Shadow points.\n\nIf they resist, even for a few moments, then they must stand and fight. The Ringwraith steps back, letting the Orcs attack. The Player-heroes must survive for two rounds of combat, with each one of them facing two Uruks. Then, at the start of the third combat round — hope unlooked-for rescues them from peril. For Saruman warned the Great Eagles to watch the Dale, and now they are coming! They swoop down from the heights above the valley, plucking the Player-heroes from the midst of the Orc-host and carrying them away south. The Ringwraith screeches in anger, and a terrible wind howls out of the East, but the Eagles are undeterred and fly the Player-heroes to safety.\n\nThe Eagles have neither the strength nor the inclination to carry the Player-heroes all the way to Isengard, instead depositing them on the far bank of the Nimrodel. A long trek south around the eaves of Fangorn Forest lies ahead of them, but (unless the Loremaster wishes otherwise) is uneventful.", "entities": [], "entries": [], "guidance": [], "id": "#tZSdC36QapAFLFUUqZyKIHU", "kw": "SCENE", "name": "The Last Peril", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "In Isengard, Saruman takes any relics recovered by the Player-heroes and treats them with reverence. *“These are treasures of the Kingdom of Arnor, lost just after the War of the Last Alliance. Great kings of old perished near the spot where you found them, and there hope may be found again.”* He thanks the Player-heroes for their service.\n\nIf they’ve rescued Arcinyas, Saruman declares that the old sage has served him long enough. Use this to signal the progress (or lack thereof) or Saruman’s corruption. If Saruman has gained 5 or less points of Shadow so far, then he allows Arcinyas to dwell within the fortress until he dies. If he has gained more than 5 Shadow points, he gives Arcinyas his last payment, then has the old man escorted out the gate of Isengard. (Either way, Arcinyas never gets the life-extending ring he so craves).\n\nIf the Player-heroes have a Treasure Hunter among them, then Saruman offers the House of Chimneys to that Player-hero as a base of operations. Saruman tells them that all they need to do in exchange for this boon is keep searching the banks of the River…", "entities": ["#tTazFYdrY5vSbAMB4SUfxjS", "#t7kbgw6eDl6NUsq8V5zXz7q", "#tHcofaIVvWXZSVDwXRmBurR"], "entries": [], "guidance": [], "id": "#tQs0hvQiApu5VZ8FIys4nWs", "kw": "SCENE", "name": "Aftermath", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": null, "entities": [], "entries": [], "guidance": [], "id": "#tdkdEkJDXs1zHbJTy6U8C2p", "kw": "SCENE", "name": "Preamble", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": null, "entities": [], "entries": [], "guidance": [], "id": "#tsP1jYJs0tUKmnh3mmPCbT9", "kw": "SCENE", "name": "Interlude: Mordor-orcs!", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": null, "entities": [], "entries": [], "guidance": [], "id": "#t0ZXg9p3ZMuqqWq9tDuUePY", "kw": "SCENE", "name": "Adversaries: Baugrim’s Black Uruks", "props": [], "refs": [], "table": null, "type": "Roleplay"}], "seq": [{"name": "Epigraph", "t": "prop"}, {"i": 0, "t": "location"}, {"i": 1, "t": "location"}, {"i": 2, "t": "location"}, {"i": 3, "t": "location"}, {"i": 4, "t": "location"}, {"i": 5, "t": "location"}, {"id": "#t60hcICrIyDz6hV4rmBf8sU", "t": "scene"}, {"id": "#tYmILFkTdHg5QHdrLwbyEgg", "t": "scene"}, {"id": "#tjLtM4iIh3NaqYYeHNScGsc", "t": "scene"}, {"id": "#tPsOsddgn3uYUEt0pW90HK4", "t": "scene"}, {"id": "#tKPFa25nujoOuO5bwN41NFc", "t": "scene"}, {"id": "#tNmIN1tBz6WHPMaC4xHWevK", "t": "scene"}, {"id": "#tw2KcLoZG1S4YPOOORPjesX", "t": "scene"}, {"id": "#tYSulmlgxmzvDLtAT0oLfGZ", "t": "scene"}, {"id": "#tKUAmVgqqWPOjzagbgP2auB", "t": "scene"}, {"id": "#t6JvW9rSv23yyJ6EufXutdw", "t": "scene"}, {"id": "#tBrHy2o0kdgvW456LLh9aVu", "t": "scene"}, {"id": "#tByLxKwj0RDOOTPYzgZZvWL", "t": "scene"}, {"id": "#tKjrvwfTtdYzszkgjgnccSY", "t": "scene"}, {"id": "#tZSdC36QapAFLFUUqZyKIHU", "t": "scene"}, {"id": "#tQs0hvQiApu5VZ8FIys4nWs", "t": "scene"}, {"id": "#tdkdEkJDXs1zHbJTy6U8C2p", "t": "scene"}, {"id": "#tsP1jYJs0tUKmnh3mmPCbT9", "t": "scene"}, {"id": "#t0ZXg9p3ZMuqqWq9tDuUePY", "t": "scene"}]}, {"cast": [], "cid": "tor2e-hands-there-let-them-lie-until-the-end", "container": "ARC", "dependsOn": ["tor2e"], "desc": "This adventure takes place anytime before the year 2990 in the Third Age. It concerns the fate of the Black Númenórean vessel *Kathuphazgân*, described on page 42. Before the adventure begins, the *Kathuphazgân* has sailed up the Greyflood as far as it could, and was then hauled further upstream until it could go no further. From the great wooden castle of the stranded ship, the Black Númenóreans plan to work mischief in the very heart of Eriador…", "entries": [], "file": "tor2e-0.5-hands-there-let-them-lie-until-the-end.arc", "guidance": [{"concerns": [], "id": "#tGx7hVVPeJUBIc3Z8cuzR3m", "name": "The Fate of Lond Daer", "text": "What has become of Lond Daer, the nascent settlement at the mouth of the Greyflood (*Ruins of the Lost Realm*, page 21)? The Corsair ship must have passed by that town on its way up the river. There are several possible options. Lond Daer Destroyed: If Lond Daer played little\n\npart in your campaign up until now, there’s no\n\nneed to dwell upon its fate. The ruthless Corsairs aboard *Kathuphazgân* made short work of the\n\nunskilled defenders of Lond Daer, and the townsfolk were slaughtered. You might also choose\n\nthis option if the Player-heroes are emotionally\n\nattached to Lond Daer, if you want to shock them with a sudden unexpected tragedy.\n\nLond Daer Assaulted: If you don’t want to have\n\nLond Daer destroyed, or the Player-heroes need\n\nmore clues leading them to *Kathuphazgân*, then the town might have already been attacked by\n\nthe Corsairs. The survivors give an account of how the Black Ship forced its way through the town’s defences and continued upriver. The folk of Lond Daer were so badly wounded and overcome by grief that they did not investigate further. Lond Daer Is About To Be Attacked: More ambitiously — if Lond Daer has played a major part in your campaign, then the Player-heroes have a chance to save it. In this setup, the Black Ship has not yet sailed up the Greyflood, although they have landed scouts that have gone as far upriver as the lands around Crow Hall. If the Loremaster chooses this path, the events described starting on page 88 take place in Lond Daer; instead of attacking the ship while it’s aground in the middle of the wilderness, the Player-heroes must sail out and battle *Kathuphazgân* in the harbour of Lond Daer.", "topics": ["there let them lie until the end"]}, {"concerns": [], "id": "#tl0m7dmjzKaEivGVrflID9F", "name": "The Command of a Host", "text": "In this adventure, the Player-heroes are accompanied by a Host of warriors. There is no need to track each individual Loremaster character — it will suffice to treat the Host as an abstract group. Its chief purpose is to fight against the crew of the Black Númenórean ship — either as a distraction, so the Player-heroes can go off and do their usual heroics, or as a screen, battling the lesser foes so the Company is not swarmed over by dozens of enemies and can concentrate on their commanders and champions (the Host is not large enough to take on the entire enemy crew by itself).\n\nIn a battle, the contribution of the Host is determined by rolling a Feat die at the start of the battle and consulting the Battle Outcome table below. The result determines what will happen by the end of the fight — the Loremaster should use the result of the roll to influence the description of the battle swirling around the Player-heroes. For example, if the roll suggests the Host will take severe casualties, then the Loremaster should describe how the members of the Host fall to enemy blades in great numbers.\n\nIf the Host enters battle ill-prepared or against over-\n\nwhelming odds, the roll on the Battle Outcome table\n\nis *Ill-favoured*. If the Player-heroes employ an unu-\n\nsually clever stratagem (with a successful BATTLE roll,\n\nfor example) or ENHEARTEN the Host with an inspiring\n\nspeech, the roll is *Favoured*.\n\nIn any event — the focus of the tale is on the Player-heroes, not their followers. The quest fails or succeeds based on the actions of the Company, not the Host.", "topics": ["there let them lie until the end"]}, {"concerns": [], "id": "#tpOPxB1Yf1HYShWsvHncnhN", "name": "The Blasting Powder", "text": "This is a volatile alchemical mixture created by Saruman, inspired by his studies of Orcish explosives. It appears as a coarse, dark-gray substance with a faint, acrid smell. Its use is dangerous, as it can be unpredictable if not handled carefully, but its destructive potential makes it a valuable tool for disruption and warfare.\n\nA jar of blasting powder adds 4 to a Player-hero’s Load — not because it is physically\n\nheavy, but because of the care that must be taken when handling it.\n\nA jar explodes if exposed to a spark or fire, inflicting a grievous Endurance loss from\n\nfire to those next to the jar, dropping to\n\nsevere for those further away. After this initial blast, the fire continues to rage, inflicting a moderate Endurance loss that continues until the fire is extinguished.\n\nThe magic of the powder is unstable — after this Adventuring Phase, it either decays\n\ninto uselessness or becomes so volatile it\n\nexplodes at random (whenever its bearer\n\nrolls an [Eye of Sauron] on *any* roll).", "topics": ["there let them lie until the end"]}, {"concerns": [], "id": "#tx3uv4cEn5JXf0wWRFjya6w", "name": "Key Foes", "text": "The leaders of the expedition are each major potential threats to the Player-heroes. Fuller descriptions of these villains may be found in the *Ruins of the Lost Realm* sourcebook. Captain Nerek: A veteran mariner, technically he is in command of the mighty warship, but in practice he\n\nis subordinate to Zoril and Usapthon. Nerek remains on board the Black Ship. He argued against bring-\n\ning the huge ship so far upriver — the *Kathuphazgân* was built for the open oceans, and he feared for the safety of his vessel in these shallow waters. He was\n\noverruled by the two servants of Sauron, but still he\n\nspends his time roaming the decks and fretting. For Nerek’s stats, see page 36 of *Ruins of the Lost Realm*. If you don’t own that sourcebook, use the stats of a Southerner Champion (see *The One Ring*, page 146). Lug, the Lord of the Lash: The Orcish master of the slave-sailors on the ship. When the *Kathuphazgân* is at sea, the Orc overseer whips the rowers, demanding greater speed from them. Now the rowers have exchanged oars for shovels, and are at work excavating the Admiral’s Tomb, but the Lord of the Lash is still a constant, belligerent presence. For Lug’s stats,", "topics": ["there let them lie until the end"]}, {"concerns": [], "id": "#tv16Ju7OLYs1m2jMPaXlQ5O", "name": "The Corsair Forces (note)", "text": "see page 37 of *Ruins of the Lost Realm*. If you don’t own that sourcebook, use the stats of Baugrim on page 66. Usapthon: A sorceress and priestess of Morgoth, Usapthon was raised almost from birth to worship the dark powers. She is cold and eerie, strange even to the other Corsairs of Umbar. She stays in her chambers on board the ship until her servants uncover the entrance to the Admiral’s Tomb, at which point she travels ceremoniously to the tomb to oversee its destruction. (See *The Tomb Is Defiled*, page 95).", "topics": ["there let them lie until the end"]}, {"concerns": [], "id": "#tfNPf7kQGk6FeWngFCbcr5r", "name": "The Corsair Forces (note)", "text": "Zoril: Zoril is a swashbuckling Corsair, a hero of Umbar. Ambitious and arrogant, she hopes to be made Queen of the North-kingdom after the war, and is desperate to show her zeal and eclipse Usapthon. She wields the enchanted flaming sword *Magolach*.\n\nThe Loremaster should use Zoril as a wildcard. She could be anywhere in the area, so she is always wherever is the worst possibility for the Player-heroes — if they go to investigate the tomb, she’s there. If they target the ship, she’s there.", "topics": ["there let them lie until the end"]}, {"concerns": [], "id": "#tmggTtCmNKS9eamZvCBjP5c", "name": "The Blade Magolach", "text": "By the arts of the enemy, Magolach retains the heat of its forging; when drawn, the blade becomes searing hot to the touch. Zoril carries a scabbard lined with a curious cloth from the south that does not burn, so the weapon can be sheathed safely. This long sword grants the *Fiery Blow* special damage option: Fiery Blow: The attack burns the target,\n\ninflicting a severe Endurance loss from fire damage (see page 134 of *The One Ring*).", "topics": ["there let them lie until the end"]}, {"concerns": [], "id": "#tNr1bLrNYxbVkN8zl5Vlc8k", "name": "Saruman’s Devilry", "text": "What if the devilry of Saruman works even better than expected? A ship that took years of work of skilled craftsmen to build, and weathered many storms, is destroyed in a deafening explosion, and everyone onboard dies a horrific death, so much that the Player-heroes must ask themselves: “Are we the villains?” The blasting powder is, after all, a wicked weapon which escalated the damage of war. Perhaps it should even be considered a major Misdeed to kill so many people with it…\n\nIf the ship is destroyed, most of the surviving enemy forces flee in terror, leaving only any surviving Key Foes and a small retinue of guards for the Player-heroes to deal with.", "topics": ["there let them lie until the end"]}, {"concerns": [], "id": "#tukziyzumKyL9ChitrIY8Un", "name": "The Choices of Saruman, Part Iv", "text": "Raise Saruman’s Shadow by the fixed\n\namount decided at the start of the cam-\n\npaign (1, 2, or 3; see *The Fall of Saruman*,\n\non page 17).\n\nIf the Player-heroes committed Misdeeds over the course of the adventure collec-\n\ntively worth 4 Shadow points or more, raise Saruman’s Shadow by 1 point.\n\nIf one or both of Usapthon or Zoril survive, raise Saruman’s Shadow by 1.\n\nIf the *Kathuphazgân* survives, raise Saru-\n\nman’s Shadow by 2.\n\nIf the Ents learn of Saruman’s blasting\n\npowder, raise the Wizard’s Shadow by 1.", "topics": ["there let them lie until the end"]}], "kind": "arc", "locations": [{"desc": "The sailors and the marines disembarked from the *Kathuphazgân*, along with crates and sacks of cargo removed to lighten the ship, and set up a large camp of tents.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "LOCATION", "name": "1. The Corsair Camp", "props": [], "refs": [], "table": null, "type": null}, {"desc": "The *Kathuphazgân* is anchored in the deepest part of the river bend.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "LOCATION", "name": "2. The Black Ship", "props": [], "refs": [], "table": null, "type": null}, {"desc": "To reach the Rock, the Player-heroes need to sneak past or distract the Corsair sentries stationed here. There is one Black Númenórean sailor and one soldier for each Player-hero.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "LOCATION", "name": "3. The Foot of the Rock", "props": [], "refs": [], "table": null, "type": null}, {"desc": "Thousands of years ago, a stone staircase ascended from the foot of the rock to the pillar at the top. The stair is now mostly lost beneath earth and weeds, but the rough outline of it is still visible, and the Corsairs have cleared the lower section so the steps are visible again.\n\nNotably, an **EXPLORE** or **SCAN** roll discovers the path splits in two — one path twines around the hill up to the summit, but the other branch leads off towards the river and the Window on the West.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "LOCATION", "name": "4. The Path", "props": [], "refs": [], "table": null, "type": null}, {"desc": "Tents and camps set up in the shelter of the rock. Umbar is much warmer and sunnier than these grim, dank northern climes, where every day seems to bring grey skies and a chilly drizzle, and the Corsairs retreat to the warmth of their tents when not working.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "LOCATION", "name": "5. The Corsair Work-camp", "props": [], "refs": [], "table": null, "type": null}, {"desc": "Here, under the encouragement of the Lord of the Lash, the Corsairs labour to excavate the entrance to the tomb. When the Player-heroes arrive, they have partially uncovered the long-buried doors and are labouring to force them open. The doors were once decorated with images of the Númenórean fleet at sea, and the Battle of the Gwathló — images of mighty ships at sea, similar to the *Kathuphazgân* but even larger, and images of a host of Númenórean soldiers charging into battle against Sauron and his servants.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "LOCATION", "name": "6. The Excavation", "props": [], "refs": [], "table": null, "type": null}, {"desc": "At the summit of the hill is a pile of fallen stones, long since overgrown with bracken. If one knows what to look for, though, it is possible to see those fallen stones for what they are — the weathered remnants of a once-great monument. A pillar once stood here, a shining beacon topped with a sphere of gold, gleaming so bright it was visible from the towers of Tharbad.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "LOCATION", "name": "7. The Fallen Pillar", "props": [], "refs": [], "table": null, "type": null}, {"desc": "On the western side of the hill is a steep cliff. Atop the cliff is a paved semi-circle; there was a west-facing bench here, once, and a memorial to fallen heroes. A close examination (**CRAFT** or **SCAN** roll) spots a small circular opening cut into the stone cliff directly below the paved section. It is mostly overgrown, and there is no way down to it apart from climbing. This carved opening leads to a shaft that runs into the tomb below (#11). When the sun sets, the light shines down the shaft; on Mid-year’s day, the light touches the Admiral’s tomb.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "LOCATION", "name": "8. The Window on the West", "props": [], "refs": [], "table": null, "type": null}, {"desc": "Here the Númenóreans stored trophies — armour, weapons, and the like — taken from the foes they defeated in the Battle of the Gwathló. And what foes they were! Sauron’s personal guard of Orcs and Trolls! Mortal kings, seduced into the service of the Enemy when he was guised as Annatar Lord-of-Gifts! And more, these foes were laden with treasure after the sack of Eregion, where they stole the works of the mightiest craftsmen of the Eldar in the Second Age of the world.\n\nThe greater part of those wonders and weapons lies enshrined in a chamber beneath the Hall of Trophies itself, its access hidden behind stone and spells of concealment that only a Magical Success with a **SCAN** roll will reveal. What still amounts to a Marvellous Hoard worthy of a Dragon is instead laid out in chests, on shelves, and even simply scattered across the floor, lying in wait for anyone daring to enter the tomb.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "LOCATION", "name": "9. The Hall of Trophies", "props": [], "refs": [], "table": null, "type": null}, {"desc": null, "entities": [], "entries": [], "guidance": [], "id": null, "kw": "LOCATION", "name": "The Tomb of the Admiral", "props": [], "refs": [], "table": null, "type": null}, {"desc": "However, if anyone begins collecting the treasure, the ceiling starts to creak ominously. Cracks spider across the chamber’s walls, and loose rocks begin to slide from above. As the vault begins to shift and buckle, tons of debris threaten to bury everyone under a crushing avalanche. If the searchers stop looting and step back, the trembling subsides; the collapse halts as if by magic, yet it resumes catastrophically if anyone steals but one point worth of Treasure. Each Player-hero must make an **ATHLETICS** roll to avoid suffering a grievous Endurance loss from falling; anyone who is knocked down to zero Endurance is buried beneath the rubble and becomes Dying.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "LOCATION", "name": "– Interior", "props": [], "refs": [], "table": null, "type": null}, {"desc": "As the name suggests, torches line the walls of this hallway. The walls are decorated with panels of beaten gold, engraved with images chronicling the Admiral’s deeds, and the deeds of other heroes. When an Elf or Dúnadan enters, then the torches burst into flame, all at once, and their dancing light seems to make the engravings come to life! There is Túrin fighting the dragon, and Beren watching Lúthien dance when the world was young! There is Tuor at the Fall of Gondolin, and Eärendil before the thrones of the Valar! The sight of all those mortal legends stirs the soul, and those who behold them in their glory may regain 1 point of Hope.\n\nThe enchanted torches also ward off evil and protect the Admiral’s tomb from malicious spirits. When the torches are burning, their light burns 1 Hate away each round from any servants of the Enemy. The magic of the torches lasts only a few minutes if they are removed from their sconces in the tomb.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "LOCATION", "name": "10. The Hall of Torches", "props": [], "refs": [], "table": null, "type": null}, {"desc": "At the heart of the complex is the tomb itself. It is a mighty sepulchre of stone, carved to resemble a Númenórean ship. A fast-flowing channel of river water guards the tomb, so would-be tomb robbers must leap across the gulf.\n\nWithin the ship’s burial, the Admiral was laid to rest in a shroud of sailcloth, and treasures and tokens were laid there by his followers. That was more than four thousand years ago, and in those years sailcloth and silk alike have perished, flesh has shrivelled, bone rotted, and even iron and steel turned to dust by the damp air — but the Admiral’s sword and helm were forged of *Mithril*, and are untouched by time.\n\nThe Admiral’s sword is a Long Sword made to be the Bane of Evil Men and Orcs, with the *Cleaving*, *Grievous*, and *Superior Fell* rewards. It additionally has a Load rating of 0. The Admiral’s helm is a *Close-fitting* Helm with a Load rating of 0.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "LOCATION", "name": "11. The Admiral’s Ship", "props": [], "refs": [], "table": null, "type": null}], "name": "There Let Them Lie Until the End", "page": 75, "phases": [{"desc": "Depending on their standing in Bree, the Player-heroes might be staying in the *Pony*, or in their own homes, or at the home of one of Saruman’s agents. By this period (some forty years before the events of *The Lord of the Rings*, with the *Long-expected Party* happening in 3001, only a few years hence), Saruman has intensified his watch on the Shire; his main spy in Bree is a trapper and bird catcher called **Midgewater Meg** (see next page). Her long journeys into the marshes provide plenty of cover for spying on the Shire. She has a house a little way outside Bree, on the north slope of Bree-hill.\n\nWherever the Player-heroes are staying, their rest is disturbed by uproar at the West-gate of the village. Investigating, they learn from the gatekeeper (young, excitable Bert Heatherton) that a ‘dead man’ came hammering on the gate, moaning and wailing ‘like them wights do in the stories’. Bill dumped most of his tea-kettle over the ‘wight’ and it fled.\n\nA quick search discovers the truth — the ‘wight’ was not a dead man at all, although he’s not far from death. Lying in the ditch near the West-gate is an unconscious Man, terribly pale and sickly. Any Player-heroes with knowledge of the Rangers recognise this fellow as **Minon**, son of Raudon. He’s clearly wounded and feverish; his skin is clammy, and he’s muttering and raving to himself about ‘Men from the Sea’ and ‘a great wave, a great wave mounting to the sky.’\n\nExamining Minon discovers a ghastly wound on his arm. The skin around the injury is festering and weeping; the veins nearby are purplish. The wound is poisoned.\n\nThrough lips flecked with spittle and swollen with poison, Minon tells his tale. He was off in the hills west of the Shire, when he encountered a curious band, a half-dozen strong at least. They were dressed in the manner of Bree-folk, and the one of them who spoke sounded like a native of these parts — but the others were strange-looking, and Minon suspects some of them were from the Far South. The strangers were on the verge of entering the Shire; Minon blocked their path, and they attacked him. They fled when he was wounded. At first, he thought his wounds were only superficial, but he’s grown sicker with each passing day.", "entities": ["#tKtljuLsYdJZENKDFSJ9JLZ"], "entries": [], "guidance": [], "id": null, "kw": "PHASE", "name": "Part 1: Intrigue in Bree", "props": [{"items": [{"value": "Minon has just enough strength for him to weakly describe what happened to him (see below) before he falls unconscious. A successful **HEALING** roll saves his life, but he’s still too weak to aid the characters in the rest of the adventure.", "vk": "scalar"}, {"value": "A Great or Extraordinary Success identifies the nature of the poison; it is a rare substance derived from a root found only in the Far South, beyond Harad.", "vk": "scalar"}], "name": "Items", "of": "STRING", "vk": "list"}], "refs": [], "scenes": ["#tiWge0u9udAR4CBAV2CrKLe"], "table": null, "type": null}, {"desc": "The black ship *Kathuphazgân* was dispatched to the North with several dreadful purposes in mind. Sauron knows that the great battle of the age will be in the South, in Gondor, but there are yet foes hiding among the ruins of the lost kingdom of Arnor. He intends to secure the Havens from which the Elves set sail, to reawaken the old powers of Angmar — and to destroy the last stronghold of the High Elves in their secret fortress at Rivendell.\n\nNow, Sauron’s forces have laid siege to Rivendell long ago (most recently in the year 1300 of the Third Age), but they never penetrated into the hidden valley, into the maze of gullies and watchful hills and girdle of enchantment that guard the House of Elrond. For some years now, the agents of the Black Ship have sought knowledge of Rivendell.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "PHASE", "name": "Part 2: Spies on the Road", "props": [], "refs": [], "scenes": ["#t4jXMETvcDrZReWYLuKmMOB", "#tSsnGqqEZ1ABT8Tq4eENfdO", "#tWJUfc3znhhWraPSWznSCrV"], "table": null, "type": null}, {"desc": "Once the Player-heroes bring news to Isengard, Saruman calls them to his chambers in Orthanc. This is the first time that the Player-heroes are let into the tower itself.\n\nThe Player-heroes ascend the narrow steps to the door of Orthanc and are met there by the Wizard, who guides them up the longer spiral staircase to his study high above. Saruman’s face is grave.\n\n*“The Enemy is moving. As I warned the White Council, our costly assault on Dol Guldur availed us nothing, for his agents have returned to that fortress. The Orcs have grown very numerous again in the Misty Mountains, and there are large Uruks among them. The Corsairs are attacking the coast of Gondor. From your reports, and those of other agents, I guess that some few Corsairs have been sent north to prepare Eriador for conquest by Sauron. While he does not suspect Eriador of harbouring any armies that might challenge him, he knows there are strongholds here that could resist him. You stand in the heart of one of them. Now his spies trouble the North, on the very threshold of…”* He pauses for a moment, as if contemplating what Sauron’s spies might be looking for. *“Imladris,”* he finishes.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "PHASE", "name": "Part 3: Counsel in Orthanc", "props": [], "refs": [], "scenes": ["#tPdoB4ea0FFziNLiBJv6w2p"], "table": null, "type": null}, {"desc": "At the head of Saruman’s warband, the Player-heroes set off in search of the Black Ship. They know it is somewhere along the Greyflood between Lond Daer and Tharbad, and far enough upstream that scouts from the ship were encountered by folk from Dunland.\n\nHow do the Player-heroes search? Considering the vastness of the territory to be explored, they must plan their hunt carefully, as time — and secrecy — are of the essence. Hopefully, clues about the whereabouts of the great ship of Umbar will emerge as they press on.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "PHASE", "name": "Part 4: A Forest of Ghosts", "props": [], "refs": [], "scenes": ["#tQQHH6pO2fGibrZdqBSUqN6", "#tlLG3WHbZIffVxuVPzDLmcp", "#tWeGEFdg9Eu08Tz9QmKl5bs", "#tavP1DEZPcutzukvyyOpCn3"], "table": null, "type": null}, {"desc": null, "entities": ["#tnoSGlT3QUALY2Z6PmiAmU3", "#tckYh73mJP9eWgcBx17iVCC"], "entries": [], "guidance": [], "id": null, "kw": "PHASE", "name": "Part 5: The Tomb of the Admiral", "props": [], "refs": [], "scenes": ["#tmbHdnbyVv9agtz0AViya3U", "#tN1uc5fvXre9TZT0nhqKKCU", "#tVGDkFQJ5zlwUk7ss81M2RF", "#tNUzWlVxtAeJbrGEKCek9p1", "#tRkwnqvdcW9uxuPnxBCpI61"], "table": null, "type": null}, {"desc": "Did the Player-heroes fulfil their mission and destroy the *Kathuphazgân*, as Saruman commanded? What is the state of the Black Ship and its crew? Do the corpses of the Corsairs lie at the bottom of the Greyflood, many leagues from their home in Umbar? Did they recover the treasures from the Admiral’s Tomb?\n\nIf the Company did thwart the Black Númenóreans, then Saruman is satisfied. *“We have shown the Enemy that there is still strength to resist him in unexpected places. He knows he shall soon have enough might to destroy the foes he knows, the foes he has already seen. It is the unknown that he dreads. He fears that some hitherto overlooked power might arise to challenge him. This victory has bought us valuable time.”* Insightful Player-heroes note that Saruman seems more pleased to have thwarted Sauron’s schemes than anything else; he barely mentions the fact that the Player-heroes have helped protect Rivendell or saved Númenórean relics.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "PHASE", "name": "Part 6: Aftermath", "props": [], "refs": [], "scenes": ["#txFG9Peb0aR7g37VDoLGGuY"], "table": null, "type": null}], "props": [{"name": "Epigraph", "type": "STRING", "value": "“Let those call it the wind who will;", "vk": "scalar"}], "roots": [], "scenes": [{"desc": null, "entities": [], "entries": [], "guidance": [], "id": "#tiWge0u9udAR4CBAV2CrKLe", "kw": "SCENE", "name": "The Course from Bree", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "The band that poisoned Minon consists of six individuals (at least six; their number should be two or three greater in number than the Player-heroes).", "entities": [], "entries": [], "guidance": [], "id": "#t4jXMETvcDrZReWYLuKmMOB", "kw": "SCENE", "name": "Rogues’ Gallery", "props": [{"items": [{"value": "Their leader is the Black Númenórean **Nambar**. He is a master duellist and assassin, and it was he who struck Minon with the poisoned blade. On a previous mission, he was the Sea-prince of the Shore (see page 52). If the Sea-prince was slain in that adventure, then replace him with his vengeful brother **Nambaz** (use the same stats for Nambar, but without his Blue Ring).", "vk": "scalar"}, {"value": "Their spokesman is **Beric Ashworth**, formerly a Man of Bree. Beric fled Bree as a young man after committing some crime in the village, and was assumed to have perished in the wilds. If any of the Player-heroes are Rangers or Men of Bree, then have one of them describe Beric’s crimes and how it came to be that he fled his homeland. Beric has the stats of a **Highway Robber** (see *The One Ring*, page 147).", "vk": "scalar"}, {"value": "Their guide comes from the village of Todden (see page 46). Depending on how the Company ended that adventure (which may be many years in the past), this might be the treacherous singer **Sellic**. Alternatively, if Sellic perished, the guide is an ill-favoured fellow called **Ulfwart**, another man of Todden that the Player-heroes faintly recall (perhaps one of the guards in the tower, or one of Sellic’s friends). Whoever the guide is, they have the stats of a **Ruffian Chief** (see *The One Ring*, page 147).", "vk": "scalar"}, {"value": "The remaining rogues are **Corsairs of Umbar**, although dressed in the manner of Bree-folk. Notably, one of them bears a spear adorned with crow-feathers that is not a weapon made in Umbar or Bree — it is a Dunlending weapon. In fact, it’s identical to those wielded by the warriors of Crow Hall (see page 27). It looks as though it was taken as a trophy in battle. For them, use the stats of the **Southerner Raiders** (*The One Ring*, page 146). There is one Corsair for each Player-hero.", "vk": "scalar"}], "name": "Items", "of": "STRING", "vk": "list"}], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "Neither threats nor torture are certain of compelling an Elf or Dúnadan to betray the secrets of Rivendell. Nambar and his rogues hope that by poisoning Minon, they have forced the Ranger to flee to Rivendell (or at least to another Ranger-haven). They intend to follow Minon until he finds help, then strike at those helpers in turn in the hope of unlocking the route to the Hidden Valley.\n\nSo, by aiding Minon, the Player-heroes have made themselves targets of the spies.\n\nIf they are heading for Rivendell, Nambar will ambush them on the Road. If they stay in Bree, the rogues strike at them in Bree (perhaps using Beric Ashworth to lure them into an ambush). The hill at Weathertop (*Ruins of the Lost Realm*, page 90) is an obviously evocative landmark for a desperate fight against servants of Sauron. The Last Bridge is an excellent place for an ambush; if the Player-heroes get as far as the Ettenmoors, then Nambar could call on aid from Trolls.\n\nAnother possible concern — who are the Player-heroes’ Patrons? This is an excellent opportunity to have a character like Gandalf, Tom Bombadil or Gilraen (backed up by a band of Rangers) show up in the nick of time, if the fight takes place near their homelands.\n\nWherever the battle takes place, it should be a challenging one for the Player-heroes. If the Company is especially battle-ready, then a number of **Footpads** join Nambar’s company for muscle (the Loremaster should add one or more for each Player-hero).", "entities": [], "entries": [], "guidance": [], "id": "#tSsnGqqEZ1ABT8Tq4eENfdO", "kw": "SCENE", "name": "A Sure Confrontation", "props": [{"items": [{"value": "To continue the adventure, the Loremaster must tailor the encounter with Nambar’s band to the choices of the players.", "vk": "scalar"}], "name": "Rules", "of": "STRING", "vk": "list"}], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "The rest of the adventure assumes that the Player-heroes encounter Nambar and his men, and at least survive the confrontation. After the battle, the Player-heroes are likely to recognise a connection between the spies and the Black Númenóreans. If any member of Nambar’s band is captured, they can be questioned. Even if all the foes are slain or have fled, the Player-heroes may have seen the crow-spear from Crow Hall or noticed the presence of a previous acquaintance from the village of Todden.\n\nMinon urges the Player-heroes to gather whatever information they can and bring it to the attention of the Wise.\n\nPossible routes of investigation include:\n\nAll these clues suggest Black Númenórean activity along the Greyflood. The Player-heroes may learn enough to identify the current location of the Black Ship, or they may learn just enough to bring their concerns to Saruman. Either way, the Wizard offers counsel in Orthanc.\n\nAfter *The Sea-prince of the Shore*, the Player-heroes know that Saruman is concerned about incursions from Harad along the coast of Eriador, and can guess that he would want to be informed immediately. Similarly, any other Patrons like Elrond or Gandalf tell the heroes to bring the news to Isengard without delay — Saruman is best placed to deal with this threat There is no need to make the return to Isengard into a full-fledged Journey; the Company has travelled the Greenway many times, and can obtain horses from Midgewater Meg or in Tharbad on the south bank of the Greyflood.", "entities": [], "entries": [], "guidance": [], "id": "#tWJUfc3znhhWraPSWznSCrV", "kw": "SCENE", "name": "Reading the Riddle", "props": [{"items": [{"value": "**The Wanderings of Beric Ashworth:** Beric was exiled from Bree several years ago, and the trail has gone cold. However, as the Player-heroes are near Bree, they may wish to investigate Beric’s past deeds to learn where he went and what he might have done. With considerable time and effort (hastened if the Company has local allies or Patrons to call upon) they can discover that Beric wandered west, causing trouble on the borders of the Shire and then further southwest. He was a brigand near Sarn Ford for a time, then continued down the Brandywine — causing mischief in Dwarf-land — before striking off towards Lond Daer. He was last seen by a traveller at Sarn Ford.", "vk": "scalar"}, {"value": "**The Village of Todden:** Todden is a long journey across the wilds of Minhiriath. If the travellers trek all the way there (or take ship from the Havens), they discover the village is deserted. A few fishermen still dwell on that haunted shore, and they speak of the coming of the same terrible black ship that was seen on the night the Sea-prince of the Shore departed. The fishermen say the ship sailed away north, and they saw it weeks later anchored at the mouth of the Greyflood.", "vk": "scalar"}, {"value": "**Crow Hall:** Crow Hall, at least, is on the road to Isengard, so the Player-heroes might stop there on the way to consult with Saruman. Who did the Player-heroes leave in charge of the Hall after the events of *The Beast of Dunland* (page 39), and how have circumstances changed in the intervening years? The Lord of Crow Hall tells the Player-heroes that they have encountered strangers in the wilds north-west of their territory, near the Greyflood. (See *Allies From Crow Hall*, on page 80, for more details).", "vk": "scalar"}, {"value": "**The Prisoner:** Any prisoner captured in Bree will not willingly speak to the Player-heroes, but Saruman can interrogate them and uncover their secrets.", "vk": "scalar"}], "name": "Items", "of": "STRING", "vk": "list"}], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "If the Player-heroes have not learned the nature of the Corsair ship yet, Saruman briefly describes the vessel and its mission.\n\n*“We must act, and swiftly. The enemy has stretched his hand out of Mordor, and we must give it such a wound that he snatches it back. You shall be my weapon in this. You — and this.”*\n\nFrom a heavy chest Saruman produces a porcelain vessel. It contains a greyish dust. *“This is one of the devices of the Enemy. I have refined it. When properly mixed and ignited, this powder bursts with great force, enough to equal the fury of a fire-drake. With this one jar, you could bring down the gates of Minas Tirith… or blast a hole in the hull of a black ship.”*\n\nHe then takes another jar from the chest, and another, and another. One jar for each Player-hero — enough power to wreak terrible destruction. *“You must use this to destroy the Corsair ship Kathuphazgân. But you shall not go alone.”*\n\nTo give his agents the best chance of success, Saruman intends to send a company of warriors with the Player-heroes. There are two possibilities for this:", "entities": ["#tgtf6GEUQP4RSsNyfoI65Le", "#toCAdH2xJyAHYONlFiHyaOY"], "entries": [], "guidance": [], "id": "#tPdoB4ea0FFziNLiBJv6w2p", "kw": "SCENE", "name": "The Black Ship Unveiled", "props": [{"items": [{"value": "The Corsairs of Umbar are infamous pirates. Umbar was a Númenórean city in days of old, part of the realm of Gondor. Indeed, it was at Umbar that the mighty fleet of Ar-Pharazôn the Golden came ashore, a force so mighty that the Enemy humbled himself before it, and surrendered to the justice of the King. (And if Ar-Pharazôn had wiser counsellors in those days, why, much evil might have been averted.)", "vk": "scalar"}, {"value": "Their ships are without equal in Middle-earth. They remember something of the arts of the mighty mariners of the Second Age. They are like sea-going fortresses.", "vk": "scalar"}, {"value": "The folk of Umbar worship Sauron as a god, and are among his most useful and able servants. Not few were the Rings he gave to them, long, long ago.", "vk": "scalar"}, {"value": "If Crow Hall is solidly under the influence of Isengard, then Saruman tells the Player-heroes to go there and ask for troops. He gives them a letter for the Lord.", "vk": "scalar"}, {"value": "If Crow Hall cannot be relied upon, then Saruman must provide troops from Isengard. *“There are other arts of the Enemy that I have studied, and yoked to my will. The soldiers I shall send with you are not fair to look upon, nor are their customs pleasant. But they are strong, and fierce, and unafraid to die.”*", "vk": "scalar"}], "name": "Items", "of": "STRING", "vk": "list"}], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "There are many ways to conduct a thorough search of the land following the meandering course of the river Greyflood. Here follow a number of options that the Player-heroes might consider:\n\n*Drawbacks:* Getting a boat or two for the Company is easy — getting a flotilla of small boats or a large barge to carry the entire warband is harder. And the Orcs, if they are present, object to going in boats. Do the Player-heroes leave some of their troops behind?\n\n*Drawbacks:* The main downside of this approach is the sheer effort involved, and the likelihood that the warband will be spotted by enemy scouts before they discover the ship.\n\nRegardless of the method they use, the search must be resolved as a Skill Endeavour. The task is Laborious (Resistance 6) and the time limit is set at 6, but for each day that Player-heroes rest or lose due to unforeseen circumstances, it must be reduced by 1.\n\nEach Skill roll represents a day of searching, and causes each Player-hero to gain 1 Fatigue point. If you’re using the Eye Awareness Rules (see *The One Ring*, page 169), each roll also increases the Company’s Eye Awareness by 1.\n\nSeveral Skills might apply to the Company’s search. Possible options include:", "entities": ["#tQokVmCLQSsM6Wiah5WgUsP", "#tkv1nozeFJzHaQs6xJxCsLr", "#tjtCr5xGZ3h7RxPQi1CGCTY"], "entries": [], "guidance": [], "id": "#tQQHH6pO2fGibrZdqBSUqN6", "kw": "SCENE", "name": "The Search", "props": [{"items": [{"value": "**By Boat:** The Player-heroes can obtain small boats in Tharbad (if they are in good standing with whoever rules there) or Lond Daer (if it still exists). Sailing down the Greyflood is easy. Sailing up is possible, through a combination of wind power, oars, and portage (the Corsairs add ‘dragging their ship by ropes’ and ‘vile sorcery’ to their repertoire of techniques). The Greyflood is one of the more navigable rivers in Middle-earth.", "vk": "scalar"}, {"value": "**Sweeping the Banks of the River:** The most arduous but perhaps the most thorough approach is to sweep along the banks, searching for the ship. This does let the Player-heroes keep their troops together, and ensures they will eventually find the ship.", "vk": "scalar"}, {"value": "**Dispatching Scouts:** The Player-heroes could establish a base at some central location — Tharbad is the obvious choice — and then either scout the river themselves, or send scouts in search of the ship.", "vk": "scalar"}, {"value": "**Gathering Information:** Similarly, the Player-heroes could wait for more news to come to them, gathering and sorting rumours. Alternatively, they could ask a well-travelled patron like Gandalf for aid.", "vk": "scalar"}, {"value": "** EXPLORE** or **HUNTING** to search the banks of the river", "vk": "scalar"}, {"value": "** PERSUADE** or **RIDDLE** to deal with informants and gather rumours", "vk": "scalar"}, {"value": "** LORE** or **TRAVEL** to study maps of the area and identify the most likely landing spots", "vk": "scalar"}], "name": "Items", "of": "STRING", "vk": "list"}], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "Long is the Greyflood, with many twists and tributaries. The maps the Player-heroes might examine in Orthanc do not wholly convey its complexity; there are many miles of river where the Black Ship might lurk. Those who remember the histories of Númenor might recall that in days of old it was called the River of Shadow, for it was concealed beneath the overhanging boughs of mighty trees along both banks. Few folk who walk along the Greyflood remember those long-vanished woods that stretched across the Enedwaith.\n\nBut the sorceress Usapthon remembers. Through her arts, and the power of the Enemy, she has awoken the buried memories in the earth. A forest of ghosts now grows on the southern bank of the Greyflood, concealing the ship.\n\nFrom a distance, it looks like a patch of thick mist. Walk closer, and a traveller might make out the shapes of bare branches and dark tree-trunks, as if the forest there is wreathed in fog — but there is no forest here, only the shadow-memory of one. This forest is treacherous and malicious — paths twist, turning intruders back the way they came or guiding them into bogs, deadfalls, or the waters of the Greyflood. Indeed, an unwary intruder might think they are forcing their way through a patch of thick undergrowth, until the sun comes out, the clouds part, and they realise they’ve waded out of their depth into the water, and they drown.\n\nThe Player-heroes must cross this unnatural barrier to reach the ship by land; alternatively, they could approach via the northern bank and cross the river by boat or swimming. Traversing this enchanted barrier — *the Girdle of Usapthon* — causes each Player-hero to gain 3 Shadow points (Sorcery). Those who fail the Shadow test or who are Miserable also suffer a grievous Endurance loss from suffocation.", "entities": [], "entries": [], "guidance": [], "id": "#tlLG3WHbZIffVxuVPzDLmcp", "kw": "SCENE", "name": "The Haunted Forest", "props": [{"items": [{"value": "If the Player-heroes have the Ent Lightroot with them, their Shadow test when navigating the forest *gains (2d)*.", "vk": "scalar"}, {"value": "If the Player-heroes wish to bring their Host through the forest, then one of them must succeed at an **ENHEARTEN** roll; if failed, the Host refuses to enter the haunted wood.", "vk": "scalar"}, {"value": "Slaying Usapthon lifts the spell; a Hero might also be able to use a Magical success on a **SONG** or **EXPLORE** roll to temporarily open a path through the ghost-wood.", "vk": "scalar"}], "name": "Items", "of": "STRING", "vk": "list"}], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "Eventually, the Player-heroes come to the edge of the ghost forest, and find themselves on the banks of the Greyflood once more. Ahead of them is the mighty Corsair vessel, and off to one side is a tall outcropping of hard stone, like the Carrock on the Anduin. There is a fresh scar in the side of this outcropping, where the Corsairs have dug away tons of dirt and vegetation built up over thousands of years, uncovering the entrance to the Admiral’s Tomb within the rock (see page 93).\n\nThe river turns against this rock, creating a wide, deep bend in its course. The Corsair ship lies at anchor in the deepest part of this pool, although she has only a few inches of water beneath her keel, and must wait for spring floods and high tides before she can sail again. The river is too deep to wade across, and reaching the ship requires either swimming or the use of a small boat, of which there are many along the shore, used by the Corsairs to disembark.\n\nSome of the Corsairs are off on missions across Eriador, like the assassins who attacked the Ranger in the opening scene. Others are busy at work in the excavation, and it is obvious, based on their frenetic activity and excitement, that they’re close to whatever they seek. The remainder are at rest in their camp, or — if the alarm has been raised — grabbing weapons, donning armour, and preparing to deal with any intruders.", "entities": ["#t9DLVtuTDvMlY4haU7kP5yU"], "entries": [], "guidance": [], "id": "#tWeGEFdg9Eu08Tz9QmKl5bs", "kw": "SCENE", "name": "Beyond the Girdle of Usapthon", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "What do the Player-heroes decide to do next? To answer this question, the players must first ask themselves what are their goals and tactics at this point. Do they focus on their mission of destruction, and try to get close enough to the *Kathuphazgân* to blow it up with Saruman’s powder? Do they explore the Admiral’s Tomb, in the hopes of thwarting whatever the Corsairs are planning? Do they try to create a diversion to divide the enemies’ forces?\n\nThe following elements can help the Loremaster to evaluate the course of action chosen by the players:\n\nand/or if the Ent Lightroot is with them.\n\nThe next section details some of the most likely options that the players may choose, providing guidance on possible strategies and their implications.", "entities": ["#tJwX1ZVLYW88oRwwcgZkkD3", "#tAseZQ0peAsyr7RWMpLht45", "#tbtMvvezu51HH1nGHwNu8Lo", "#tOL9oVXAPAKSTsuWfjWQFnI", "#tFXNo2rq9dxL1yrQtIm3Fij"], "entries": [], "guidance": [], "id": "#tavP1DEZPcutzukvyyOpCn3", "kw": "SCENE", "name": "The Plan Ahead", "props": [{"items": [{"value": "If the Player-heroes succeeded at the Skill Endeavour to search for the Black Ship, they arrive before the Corsairs are ready. If they failed, then the Corsairs are prepared for battle and on guard against intruders.", "vk": "scalar"}, {"value": "The combination of the ghost forest, the mist that clings to the riverbank, and the thick underbrush make it possible for the Player-heroes to move around unseen with **STEALTH** rolls — if they are cautious. These rolls *lose (1d)* if the enemy is on guard (as explained above)", "vk": "scalar"}, {"value": "If the Player-heroes have the Host with them and/or the Ent Lightroot, then they can be asked to engage the marines and Corsair sailors and distract them, while the Player-heroes deal with Usapthon, Zoril and other Key Foes. Chaos and uncertainty are likely the Player-heroes’ best allies. If the Player-heroes do not have the Host or Lightroot with them, then such a diversion is impossible — the Company will have to use stealth and cunning to overcome their foes.", "vk": "scalar"}], "name": "Items", "of": "STRING", "vk": "list"}], "refs": [], "table": null, "type": "Roleplay"}, {"desc": null, "entities": [], "entries": [], "guidance": [], "id": "#tmbHdnbyVv9agtz0AViya3U", "kw": "SCENE", "name": "Rumour", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": null, "entities": [], "entries": [], "guidance": [], "id": "#tN1uc5fvXre9TZT0nhqKKCU", "kw": "SCENE", "name": "Old Lore", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "The Corsairs have sailed up the river in search of a truly ancient monument — and the object of Sauron’s hatred, for it marks one of his great defeats. Long, long ago, Sauron attempted to seize control of the Rings of Power through the One Ring. When the Elves saw through his treachery and took off their rings, he turned to force to dominate Middle-earth. His armies of Orcs and evil Men swept through Eregion, destroying the city of Ost-in-Edhil. The great smith Celebrimbor was slain, his body hung from a pole as a ghastly banner. The remainder of the Elves retreated to Imladris, where they were besieged.\n\nAs it ever had, help came from over the Sea — not from the Powers of the West, the Valar, but from mortal Men. For in those days Númenor was mighty, but not consumed by pride. When the Elves called for aid, their allies answered. Tar-Minastir, the Eleventh King of Númenor, sent a fleet to the shores of Middle-earth, under the command of a great Admiral. This mortal hero outwitted Sauron; by dividing his forces and landing a diversionary force at Lindon, he was able to bring the remainder of his fleet up the Greyflood from Vinyalondë (which in later days would be called Lond Daer)\n\nand caught Sauron’s armies unawares.\n\nGreat was the victory. Sauron — even though he possessed not only the One, but many others of the Great Rings! — was defeated and forced to flee through the Gap of Rohan to the land of Mordor, where he took refuge.\n\nThe Númenórean Admiral returned home, and was received as a hero. His name was eclipsed by the title he bore, and most knew him only as the Admiral. He lived for many more years, but when he felt the hour of his death approaching, he declared he wished to go on one last sea-voyage. His kinsfolk sailed with him to Middle-earth, and he was entombed near the site of his great victory over the Enemy.\n\nAll that was many thousands of years ago. Númenor withdrew from the lands of Eregion, and the tomb was left to stand as a silent monument to past glories. When Sauron corrupted Ar-Pharazôn, he further tarnished the name of the Admiral, and by the time the Realms in Exile of Arnor and Gondor arose, the tomb was forgotten by all save a few scholars — and Sauron, who ever nursed hatred and resentment.", "entities": ["#tR9w2VTRDI6ymNXEqorWQ4G", "#tHxbujSd4Dgjspc76csfScj"], "entries": [], "guidance": [], "id": "#tVGDkFQJ5zlwUk7ss81M2RF", "kw": "SCENE", "name": "Background", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": null, "entities": [], "entries": [], "guidance": [], "id": "#tNUzWlVxtAeJbrGEKCek9p1", "kw": "SCENE", "name": "Exterior Map of the Tomb of the Admiral", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "Below are some of the challenges that could arise as the Player-heroes enter the Tomb of the Admiral.", "entities": ["#tlkh3h7Lw0AmuLDFODjEZTk", "#t1nEAhd4VKXyIEHIBbMsXky", "#tI6jB6hAJzmrtxJzCY6NFid", "#tYe3eia8e6g9kGt1bBBN3L6"], "entries": [], "guidance": [], "id": "#tRkwnqvdcW9uxuPnxBCpI61", "kw": "SCENE", "name": "Schemes and Troubles", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "Did the Player-heroes fulfil their mission and destroy the *Kathuphazgân*, as Saruman commanded? What is the state of the Black Ship and its crew? Do the corpses of the Corsairs lie at the bottom of the Greyflood, many leagues from their home in Umbar? Did they recover the treasures from the Admiral’s Tomb?\n\nIf the Company did thwart the Black Númenóreans, then Saruman is satisfied. *“We have shown the Enemy that there is still strength to resist him in unexpected places. He knows he shall soon have enough might to destroy the foes he knows, the foes he has already seen. It is the unknown that he dreads. He fears that some hitherto overlooked power might arise to challenge him. This victory has bought us valuable time.”* Insightful Player-heroes note that Saruman seems more pleased to have thwarted Sauron’s schemes than anything else; he barely mentions the fact that the Player-heroes have helped protect Rivendell or saved Númenórean relics.", "entities": [], "entries": [], "guidance": [], "id": "#txFG9Peb0aR7g37VDoLGGuY", "kw": "SCENE", "name": "Part 6: Aftermath", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": null, "entities": [], "entries": [], "guidance": [], "id": "#twbhI7r8k3qMz7pIKXsj6fZ", "kw": "SCENE", "name": "Preamble", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "The adventure begins in Bree. Ideally, the Player-heroes are there on some unrelated business — perhaps they are resting after some other adventure, or meeting up in the *Prancing Pony* after returning to their respective homelands for Yule. Alternatively, they might be here on another mission for Saruman — to collect reports from Midgewater Meg, to aid in the watch on the Shire, or carry a message to Rivendell.", "entities": [], "entries": [], "guidance": [], "id": "#tvOcx7Gk3aWOvFrCkv3ZPsP", "kw": "SCENE", "name": "Running the Adventure", "props": [], "refs": [], "table": null, "type": "Roleplay"}], "seq": [{"name": "Epigraph", "t": "prop"}, {"i": 0, "t": "location"}, {"i": 1, "t": "location"}, {"i": 2, "t": "location"}, {"i": 3, "t": "location"}, {"i": 4, "t": "location"}, {"i": 5, "t": "location"}, {"i": 6, "t": "location"}, {"i": 7, "t": "location"}, {"i": 8, "t": "location"}, {"i": 9, "t": "location"}, {"i": 10, "t": "location"}, {"i": 11, "t": "location"}, {"i": 12, "t": "location"}, {"id": "#tiWge0u9udAR4CBAV2CrKLe", "t": "scene"}, {"id": "#t4jXMETvcDrZReWYLuKmMOB", "t": "scene"}, {"id": "#tSsnGqqEZ1ABT8Tq4eENfdO", "t": "scene"}, {"id": "#tWJUfc3znhhWraPSWznSCrV", "t": "scene"}, {"id": "#tPdoB4ea0FFziNLiBJv6w2p", "t": "scene"}, {"id": "#tQQHH6pO2fGibrZdqBSUqN6", "t": "scene"}, {"id": "#tlLG3WHbZIffVxuVPzDLmcp", "t": "scene"}, {"id": "#tWeGEFdg9Eu08Tz9QmKl5bs", "t": "scene"}, {"id": "#tavP1DEZPcutzukvyyOpCn3", "t": "scene"}, {"id": "#tmbHdnbyVv9agtz0AViya3U", "t": "scene"}, {"id": "#tN1uc5fvXre9TZT0nhqKKCU", "t": "scene"}, {"id": "#tVGDkFQJ5zlwUk7ss81M2RF", "t": "scene"}, {"id": "#tNUzWlVxtAeJbrGEKCek9p1", "t": "scene"}, {"id": "#tRkwnqvdcW9uxuPnxBCpI61", "t": "scene"}, {"id": "#txFG9Peb0aR7g37VDoLGGuY", "t": "scene"}, {"id": "#twbhI7r8k3qMz7pIKXsj6fZ", "t": "scene"}, {"id": "#tvOcx7Gk3aWOvFrCkv3ZPsP", "t": "scene"}]}, {"cast": [], "cid": "tor2e-hands-the-quest-of-moria", "container": "ARC", "dependsOn": ["tor2e"], "desc": "In this adventure, the Player-heroes are sent in search of strange tidings out of Fangorn Forest. They discover some desperate, starving Dwarves, the survivors of Balin’s Expedition. Saruman sends the Player-heroes north to Moria, to learn what can be known about the remaining Dwarves and the lost Ring-lore of the city…\n\nThis adventure takes place in the year 2994.", "entries": [], "file": "tor2e-0.5-hands-the-quest-of-moria.arc", "guidance": [{"concerns": [], "id": "#tmDFA2QC8bEPolTij3yotMS", "name": "Our Friend Lightroot", "text": "If the Company met and befriended the Ent Lightroot in the previous adventure, they may be much more familiar with the shepherds of the trees of Fangorn. If they are still in touch with the Ent, he tells them that intruders with axes have trespassed in the north of Fangorn, but they are lost in the dark groves and may soon fall victim to the Huorns. Lightroot does not know if these intruders are servants of Saruman or not, but they are certainly two-legged outsiders and so the Player-heroes may be able to resolve the problem more swiftly than the Ents. Lightroot can lead the Player-heroes directly to the Black Glen and can sing the Huorns to sleep while the Company deal with the intruders (see page 100).", "topics": ["the quest of moria"]}, {"concerns": [], "id": "#t1CDLWHsog5rLKwxHlqyCdl", "name": "Doom!", "text": "Here, the tale of the Player-heroes scrapes against Tolkien’s tale of years. Balin’s expedition is almost certainly doomed, and while there is a chance that the Player-heroes can avert this fate, it is extremely unlikely. However, if the Player-heroes are determined to save the expedition, let them try: should they perish, this adventure can serve as a perfectly good ending to the campaign.", "topics": ["the quest of moria"]}, {"concerns": [], "id": "#tHNTRvLLDVUiKUb21LM1Tbd", "name": "The State of Moria", "text": "Gorgol, son of Bolg now commands the Orcs of Moria. This mighty Orc is the grandson of Azog, who was slain by King Dáin in the Battle of Dimrill Dale; his father Bolg fell at the Battle of Five Armies. Gorgol swore he would have his revenge on the Longbeards. It took him many years to secure his control over the Goblins of Mount Gundabad. By the 2950s, Gorgol was the mightiest of the warlords of the Misty Mountain, but Erebor had grown too strong for him to dare starting a war with Dáin’s kingdom.\n\nWhen word reached Gorgol that some of the hated companions of Thorin Oakenshield were close at hand and, more, had dared trespass in his grandfather’s kingdom, he gathered a host of his most loyal Orcs and marched south with great haste. They seized the East-gate and the Dimrill Dale, trapping Balin’s company underground. For more than a year, Gorgol besieged the Dwarves, cutting off any attempts at escape. In the\n\nend, Balin was caught when he dared go down to the Mirrormere in search of guidance.\n\nGorgol has yet to return to his halls in Gundabad. For many years, Moria was under the control of Orc-chieftains who paid tribute to Gorgol, the most prominent of which was Malech One-Eye. However, under Malech’s neglectful rule, all manner of trespassers and troublemakers have taken up residence in the Mines of Moria. Not only hateful stinking Dwarves, but strange mad fire-cultists, and even some slimy Orcs from *Mordor*. (Of course Gorgol’s going to do his bit in the War — when Barad-dûr calls, Gundabad will answer and all that — but he’s damned if he’s going to hand over the mines and all their potential wealth to some *pushdog* whelp from *Lugbúrz*. Moria belongs to him! To the line of Azog!) So, even once the Dwarves are all dead, Gorgol intends to remain in Moria and clean house.", "topics": ["the quest of moria"]}, {"concerns": [], "id": "#t5O37UCazplCD8or6CiCLQM", "name": "Other Ways in", "text": "*Moria: Through the Doors of Durin* describes other routes into Moria, such as the secret Dimrill Door and Tarloch’s Hall (pages 77 and 128, respectively). If the Player-heroes discovered these routes in a previous adventure, then they can use them instead.", "topics": ["the quest of moria"]}, {"concerns": [], "id": "#t16oOyqcKy80fURGvH2PNMz", "name": "The Ring of the Smith", "text": "If the Ring-wight is slain, the Player-heroes may take Kinir’s ring. Finir tries to snatch it if no-one else claims it. The Ring of the Smith is a heavy circle of solid *Mithril*, adorned with three blazing sapphires. It grants the Blessings of CRAFT and LORE to the wearer, giving them the knowledge and power needed to forge yet more magic rings.", "topics": ["the quest of moria"]}, {"concerns": [], "id": "#tIUUXHUrhLRTSGn4tONyPtq", "name": "A Fiery Miracle", "text": "If the Player-heroes are about to be overwhelmed, then the Balrog — Durin’s Bane itself! — may appear in the distance, the red flames of its fiery mane flickering in the dark. The Orcs flee in terror; so should the Player-heroes!", "topics": ["the quest of moria"]}, {"concerns": [], "id": "#t6cAefqn5CgPyit0FimStzr", "name": "The Choices of Saruman, Part V", "text": "Raise Saruman’s Shadow by the fixed\n\namount decided at the start of the cam-\n\npaign (1, 2, or 3; see *The Fall of Saruman*,\n\non page 17).\n\nIf the Player-heroes committed Misdeeds over the course of the adventure collec-\n\ntively worth 4 Shadow points or more, raise Saruman’s Shadow by 1 point.\n\nIf none of Balin’s company survived, raise Saruman’s Shadow by 1.\n\nIf Finir is slain, raise Saruman’s Shadow by 1. If the Player-heroes bring the Ring of\n\nthe Smiths back to Saruman, increase his\n\nShadow by 2.", "topics": ["the quest of moria"]}], "kind": "arc", "locations": [{"desc": "This corridor was once part of the grand guild-hall; most of the structure was destroyed in the chaotic years after the Fall of Moria, or despoiled by Orcs. The corridor is mostly blocked by rubble.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "LOCATION", "name": "1. Rubble-strewn Hall", "props": [], "refs": [], "table": null, "type": null}, {"desc": "Finir makes camp in this little room; it was once a guard-post, and the remains of a stone bench and arrow-slits are still visible. Fresh water flows from a pipe into a circular basin, trickling down from far above. There are no light sources here or anywhere else in the complex, save Finir’s dwindling supply of candles and whatever the Player-heroes brought with them.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "LOCATION", "name": "2. Finir’s Camp", "props": [], "refs": [], "table": null, "type": null}, {"desc": "Here, the master-smiths of old were prepared for burial. The funerary rites of the Dwarves are not for outsiders; the walls are covered in carvings and hieroglyphs in their secret tongue. A stone slab in the middle of the room was once used for the laying-out of the dead; chests at the side of the room contain various ritual relics, including silver bowls and ewers for washing the dead. These chests are unlooted — they count as a Lesser Hoard, but each Player-hero who loots them gains 1 Shadow point (Greed) (in addition to any other Shadow gain from Greed resulting from the Magical Treasure rolls).\n\nAn ancient anvil, cracked down the middle, stands on one side of the far door; on the wall opposite hangs a blacksmith’s hammer. Any non-Dwarf passing between the two is seized with the unnatural conviction that they are about to be struck with the hammer, their skull crushed against the unyielding anvil. A Player-hero must succeed at a **WISDOM** roll to enter the chamber; if this roll is failed, the Player-hero loses 1 Hope and only a successful **ENHEARTEN** roll from a companion allows for another attempt. Enemies must spend 1 Hate to brave the anvil door.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "LOCATION", "name": "4. The Ceremonial Chamber", "props": [], "refs": [], "table": null, "type": null}, {"desc": "The tombs of the smiths stand here in orderly ranks, their bodies locked away in stone until the doom that awaits the Dwarves at the world’s end comes to pass. Most of the tombs are identical, with only the runes denoting the name and lifespan of the smith and the inset bronze panels depicting their masterworks differing from tomb to tomb.\n\nLooting these tombs causes the Player-heroes to gain 2 Shadow points (Greed) (in addition to any other Shadow gain from Greed), but yields Magical Treasure comparable to a Greater Hoard.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "LOCATION", "name": "5. The Tombs of the Smiths", "props": [], "refs": [], "table": null, "type": null}, {"desc": "A successful **SCAN** roll or a laborious search of the whole complex discovers that the tombs in a section of the Crypt are empty — while there are names graven on the lids, no date of death is given, and the bronze panels depict abstract patterns of lines and curves, not images of the works of the deceased. If opened, there are no bones nor grave-goods within. These smiths are interred elsewhere — see *Moria: Through the Doors of Durin*, page 144. Successful **LORE** or **RIDDLE** rolls suggest that the bodies of these smiths could not be recovered.\n\nComparing the dates on these tombs to the other ones suggests that these empty tombs were built in the middle years of the Third Age, in the centuries leading up to the fall of Moria.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "LOCATION", "name": "6. The Empty Tombs", "props": [], "refs": [], "table": null, "type": null}, {"desc": "One tomb is different from all the rest. There is a name and date of death engraved on the lid — Kinir son of Minir, T.A. 1407–1682 — suggesting there is a body interred within. However, the bronze panels on the side are the same abstract designs found on the empty tombs, implying that whatever works this smith made are secret, forbidden, or deliberately forgotten.\n\nAs the name may suggest, Kinir is an ancestor of Finir — both genius and madness run deep in their bloodline.\n\nThe discovery of the tomb of Kinir triggers the events described in *The Siege of the Crypt* (see page 112). If they open this tomb, **Kinir the Ring-wight** rises and attacks.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "LOCATION", "name": "7. The Ring-wight’s Tomb", "props": [], "refs": [], "table": null, "type": null}, {"desc": "At the back of the crypt is a hidden door, discoverable with a successful **SCAN** roll — or instantly visible to one wearing the magic ring from Kinir’s tomb. This door was used by the Dwarven servants who tended the tombs, and leads up to a side corridor several levels above the crypt.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "LOCATION", "name": "8. The Secret Door", "props": [], "refs": [], "table": null, "type": null}], "name": "The Quest of Moria", "page": 97, "phases": [{"desc": "Saruman — visibly irritated — summons the Player-heroes to Isengard. This time, he meets them at the gates of the fortress, and does not invite them in.\n\n*“A minor errand, compared to some of the great tasks I have entrusted to you. There are trespassers, I am informed by a neighbour, in the Forest of Fangorn. Most likely Orcs from the Misty Mountains. You are to ride around the northern edge of the forest, and look for signs of these troublemakers. Find them, then bring them back here so I may question them.”*\n\nIf pressed about this neighbour, Saruman is evasive and claims that the request comes from *“an old creature — a mere curiosity of Middle-earth — that cares nothing for anything beyond his borders.”* He continues, with an air of dismissal: *“This… thing, called Treebeard by the uncouth, suspects that the trespassers are servants of Isengard, so he brought his complaint to me. Of course, this is nonsense; I haven’t sent anyone into Fangorn recently. Still, there’s no advantage in ignoring Treebeard. He is slow but stubborn, and that would only push him to come knocking at my door sooner or later.”*\n\nIf the Player-heroes don’t inquire about the source of the complaint, Saruman refrains from mentioning Treebeard unless his Shadow is 10 or higher; in that case, he grandly complains about the Ents in a way that hints at his growing suspicion.\n\nSaruman does warn the Player-heroes to be careful of the forest. They need only make a show of patrolling the forest edges, and for no reason they are to light no fire under the\n\nshadow of the trees, nor are they to cut any living wood. They certainly should also avoid the forest at night, especially the darker dales in the foothills of the Mountains.\n\nHorses are provided to carry the Player-heroes swiftly north along the Westemnet.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "PHASE", "name": "Part 1: A Favour for a Neighbour", "props": [], "refs": [], "scenes": ["#tEJ114Hmhcl38U5WUzkWepq", "#t7Bq4nz4Y4P9FZNvAXN3B8m", "#tvWM1ZlvdFQKRHaO5DW40SC", "#tX4KCu1JAPZ5lUYYAAQP3vM"], "table": null, "type": null}, {"desc": "The rescued Dwarves are in a sorry state — they are starving, battered, haunted and broken. It’s not just their imprisonment by the Huorns. These poor Dwarves have clearly been through a nightmarish ordeal. With successful **HEALING** and **ENHEARTEN** rolls, the Player-heroes can restore the six Dwarves to some measure of health. Their leader, **Nidi**, introduces her companions — her cousin Sidi, and their friends Lofar, Lomar and Ljomi, and Vignir.\n\n(If the Player-heroes played through *The Disaster of the Gladden Fields*, they may already know Nidi. If for some reason she died during that adventure, have Sidi take her place as the leader of the Dwarves).\n\nThey were on a long journey — a Quest — in the Mountains when they were attacked by Orcs and… other things. They tried to escape, but the Orcs pursued them, blocking the route to the Ford of the Beornings, forcing them south until they hid in this forest. The Dwarves have no idea where they are — the lands of the southern Anduin are unknown to them, and they have never heard of Fangorn Forest (or Saruman, for that matter).\n\nIf there are Dwarves in the Company, or the Player-heroes win Nidi’s trust, she admits that she and her companions were part of an expedition led by the famous Balin, one of the companions of the great Thorin Oakenshield. Balin led them south to the fabled lost city of Moria, hoping to retake it from the Orcs who stole it from the Dwarves a thousand years ago. Alas! Nidi and her companions were separated from the rest of the expedition when Orcs attacked. Unable to fight their way back to Balin’s Halls, they fled in the hopes of fetching aid.\n\n(Especially heroic Player-heroes may immediately assume that the right thing to do is charge off and bring help to those poor beleaguered Dwarves in Moria. If that’s the case, the Loremaster may gently remind the Player-heroes that Saruman ordered them to bring the intruders back to Isengard, but skip onto Part 3 if they rush off heroically. Nidi gives them the information contained in *Nidi’s Account*, on page 102, before they go.)", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "PHASE", "name": "Part 2: The Tale of the Dwarves", "props": [], "refs": [], "scenes": ["#tgwl4kKoY6s8PRiVfLsglQb", "#t4hhu0dVbC1xwPaoCEOcLYZ"], "table": null, "type": null}, {"desc": "Setting out from Isengard (or from the northern edge of Fangorn, if the Player-heroes go directly after meeting Nidi), the Player-heroes face a choice. How do they intend to enter Moria? The East-gate in Dimrill Dale is well known. Nidi mentioned that Balin knew of a door on the west side of the Mountains, the Doors of Durin, although that entrance is remembered only by the Dwarves and the Wise. Nidi also spoke of a Goblin-cave that connected to Moria, although she could not recall exactly where this entrance lies. So, do the Player-heroes head for the Dimrill Dale, or go up into the mountains in search of a mysterious cave? Or do they cross the Misty Mountains and seek the Doors of Durin?", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "PHASE", "name": "Part 3: To Moria", "props": [], "refs": [], "scenes": ["#toa1aonYzqoqFZamCxnFGUM", "#tiDrjNgfCSmp8hyLAB4mSxv"], "table": null, "type": null}, {"desc": "Once the Player-heroes have gained entry to Moria, a choice is before them. They know that Balin’s company were under siege in the Twenty-first Hall, which according to Nidi’s Map is located in the western portion of the Dwarrowdelf, the ancient city of the Dwarves near the East-gate. They also know that Finir set off down the underground Road, heading for West Moria near the Hollin-gate.\n\nWhere do the Player-heroes go? Do they seek out Balin’s refuge to the east (see *Drums in the Deep*, below), or set out west in search of Finir (see *Finir and the Ring-smiths*, on page 108)?\n\nThe Loremaster can use the tables on pages 72–73 to improvise encounters along the Company’s underground trek (again, *Moria: Through the Doors of Durin* offers more detailed rules for underground journeys). Moria is more dangerous in this era, so all rolls on the Hazard table are *Ill-favoured*.\n\nThe number of Hazard rolls required to reach a destination is noted in the table below.", "entities": ["#tZPSXxN5cr7KPlcslau0pMo"], "entries": [], "guidance": [], "id": null, "kw": "PHASE", "name": "Part 4: In the Long Dark", "props": [], "refs": [], "scenes": ["#tkDUeVwGtMe88aBYSqxpbQm", "#tMzOlU7gX7EaCR6ua4vaFdy"], "table": null, "type": null}, {"desc": null, "entities": ["#tpAWxJLQYndyN3V3JkBuled", "#tqW8LrOkXXj0HXKSAuETOe0"], "entries": [], "guidance": [], "id": null, "kw": "PHASE", "name": "Part 5: The Crypt of the Smiths", "props": [], "refs": [], "scenes": ["#tZvOzp5YEe4cqfjbjwQjypB", "#thl6o9W7B5Aa26EUBVv3QeD", "#tSLlxeakB532fd4E5EpN7q3", "#tjGGtQnzggrtScOrmmHLpdb", "#tsGbO2nvVUBZSrRKduayKHV"], "table": null, "type": null}, {"desc": "How do the Player-heroes escape Moria? They *cannot* use the entrance they used as their exit; whichever way they came is blocked by a host of pursuing Orcs. So, if they entered using the hidden Goblin-cave, they must exit via the East or West-gate, with Orcs on their heels throughout.\n\nThe escape is conducted as a Skill Endeavour. The Resistance depends on which exit the Player-heroes are using, assuming they’re fleeing from the Crypt.\n\nAlternatively, the Player-heroes may be given the chance to fight Gorgol and his bodyguards, and if they manage to slay Gorgol in combat, the Orcs are so dismayed the Player-heroes can escape in the confusion.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "PHASE", "name": "Part 6: Escaping Moria", "props": [{"items": [{"value": "**West-gate:** Resistance 3", "vk": "scalar"}, {"value": "**Goblin-cave or Another Exit:** Resistance 6", "vk": "scalar"}, {"value": "**East-gate:** Resistance 9 The Time Limit depends on circumstances.", "vk": "scalar"}, {"value": "The Player-heroes crept in and out with minimal delay: 6", "vk": "scalar"}, {"value": "The Player-heroes have lingered or suffered some delay: 5", "vk": "scalar"}, {"value": "The Orcs are on their heels: 4 Each failed roll means a roll on the Moria Hazard table (page 73) or a brief combat with some Orcs. If the Skill Endeavour fails, then the Player-heroes are caught and slaughtered in the dark — unless they have some way to save themselves, like one of them making a heroic sacrifice or the players coming up with a brilliant and unexpected way to evade the Orcs.", "vk": "scalar"}], "name": "Items", "of": "STRING", "vk": "list"}], "refs": [], "scenes": ["#tEmpgnuwEmY83hdIxjIhoFM"], "table": null, "type": null}], "props": [{"name": "Epigraph", "type": "STRING", "value": "“... they are crebain out of Fangorn and Dunland. I do not know what they are about: possibly there is some trouble away south from which they are fleeing, but I think they are spying out the land…”", "vk": "scalar"}], "roots": [], "scenes": [{"desc": null, "entities": [], "entries": [], "guidance": [], "id": "#tEJ114Hmhcl38U5WUzkWepq", "kw": "SCENE", "name": "Preamble", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "Day after day, the endless grey-green expanse of the forest of Fangorn rolls by as the Player-heroes ride north. The Company pass by some Rohirrim settlements, although this region is only lightly populated; most of the folk of Rohan dwell in the south. These are lonely lands that few call home.\n\nIf the Player-heroes scout the forest edge, they find nothing but fallen branches and old gnarled trees heavy with ivy and old man’s beard, but cannot shake the feeling that they are being watched by unseen eyes. They cross the fords of the Entwash first, then the Limlight, and, coming to the shoulder of Fangorn, turn westward toward the distant peaks of the Misty Mountains.\n\nAt last, along the northern edge of the woods, the Player-heroes find a clue to their quarry — the corpses of a half-dozen Orcs, hacked apart by axes and left for the crows. There’s also a pile of stones — a hastily but well-built burial cairn. Dwarves, or any other Player-hero with at least two ranks in **CRAFT**, can guess it is Dwarf-work. (Opening the cairn without cause is a Misdeed worth 1 Shadow point; it contains the corpse of a Dwarf-woman.)\n\nA roll of **HUNTING** lets the Player-heroes find the trail of the intruders. From their deep, booted footprints, they are likely Dwarves. It looks like they were heading for the forest’s eastern edge, but have now turned back and are heading west along the northern border of Fangorn. There are other tracks, too — more Orcs.", "entities": [], "entries": [], "guidance": [], "id": "#t7Bq4nz4Y4P9FZNvAXN3B8m", "kw": "SCENE", "name": "Scouting the Forest Eaves", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "As the Player-heroes follow the trail of the intruders, they encounter a band of Orcs. A successful **AWARENESS** roll from the Company’s Look-out allows the Player-heroes to come upon the Orcs in daylight, and have the advantage of the sun above the Misty Mountains. On a failure, the Orcs ambush in the twilight after the sun has sunk into the west. There are two **Orc Soldiers** and one **Goblin Archer** for each Player-hero.\n\nOne or more ranks in **BATTLE** suggest that these Orcs are the rear-guard of a larger force ahead. However, the next day the Player-heroes see no sign of more Orcs — but do come across an oddly churned up section of ground, a great swathe of mud and broken earth. It’s as if some giant had dragged his plough across the ground (or as if a host of trees marched out of the forest, smashed a band of Orcs, and then returned to Fangorn, which is exactly what happened.)\n\nContinuing on the track of the Dwarves, the Player-heroes discover it plunges into the forest. There’s a minor pass in the mountains, near the springs of Limlight, and it looks like the Dwarves are heading that way.", "entities": [], "entries": [], "guidance": [], "id": "#tvWM1ZlvdFQKRHaO5DW40SC", "kw": "SCENE", "name": "Following The Trail", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "Weirdly, there’s a wide and clear path through the forest of Fangorn, as if the trees have been herded aside. The branches overhead intertwine, making the path into a dark tunnel, but it continues straight and true towards the pass for more than a mile — then abruptly twists down a steep slope, leading the Company into a marshy glen. This is the Black Glen, an ancient haunt of the Huorns.\n\nDark and twisted trees, their tangled branches eerily like hands, like faces, grow from the black mud. It’s airless under the trees, and deathly quiet — although a successful **AWARENESS** roll allows a Player-hero to detect a distant tapping, like someone striking their fists against a hollow tree (the noise of the Dwarves trapped inside a hollow stump). Worse, it’s almost impossible to turn back — the ground seems to sink and slip under the feet of the Player-heroes, causing them to slide down the muddy slope. Hoary tree-roots buried beneath the muck trip and catch those trying to escape.\n\nLurking in the glen are violent and murderous **Huorns** — one for every two Player-heroes (use the stats of **Lightroot**, on page 84). Many, many more Huorns lurk in the forest around the Black Glen, and they quickly join the fray if the battle goes on more than a few rounds.", "entities": ["#tZNR6C8Nen0J2dHtxdE8AJt"], "entries": [], "guidance": [], "id": "#tX4KCu1JAPZ5lUYYAAQP3vM", "kw": "SCENE", "name": "The Black Glen", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "In Isengard, Saruman’s servants tend to the Dwarves’ injuries, and the Wizard himself interviews Nidi. After a few days, the Dwarf is much recovered, and greets the Player-heroes as friends, promising them that she is eternally at their service for rescuing her from the dreadful forest.\n\nShe draws maps of the explored region of Moria from memory, and briefly describes the history of the expedition. (If you have *Moria: Through the Doors of Durin*, the chronology on page 8 applies here).", "entities": ["#t7W5A4Fr2FK7Qa1Dtz8FHUx"], "entries": [], "guidance": [], "id": "#tgwl4kKoY6s8PRiVfLsglQb", "kw": "SCENE", "name": "Recuperation in Isengard", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "Saruman summons the Player-heroes before him. It is clear that he is displeased.\n\nUse Saruman’s current Shadow total as a guide to how to play this scene.\n\n*“Our Dwarf guest was guarded in her speech, but she revealed much in her thought. As you may have guessed, she and her companions dared enter Moria — and they were not alone. It seems a great many Dwarves attempted to reclaim that ancient fastness, under the leadership of Balin son of Fundin. Of him I have heard much. He is a creature of Gandalf the Grey; long have they conspired together.*\n\n*There is much that worries me in this. The Dwarves of Moria were close allies of the Elves of Eregion — the Ring-smiths of old. It is written that Narvi of Moria was high in the esteem of Celebrimbor himself. I have long suspected that lore is preserved in the ruins of Khazad-dûm — and the Dwarf spoke of this smith Finir searching for the chambers of Narvi.”*\n\nSaruman seizes the arm of one of the Player-heroes. *“I fear most of the Dwarves are dead, but that will not be an end to it. Go to Moria, and find what the Dwarves uncovered in the darkness under the mountain.”*\n\n(Again, the Loremaster should adjust Saruman’s speech based on his Shadow total; if he still retains some measure of hope, then he is more optimistic about the prospect of rescuing Balin, although he remains convinced that the expedition is doomed).\n\nThe Dwarves will not accompany the Player-heroes to Moria — Saruman says that he will see them returned safely to Erebor, where they may inform King Dáin of the fate of the Moria colony (if Saruman’s Shadow by the end of the campaign is 15 or less, he keeps his word. Otherwise, the Dwarves are set labouring in the pits of Isengard until the survivors are found by the Ents in T.A. 3017.)\n\nSo, the tasks before the Company are:", "entities": [], "entries": [], "guidance": [], "id": "#t4hhu0dVbC1xwPaoCEOcLYZ", "kw": "SCENE", "name": "The Counsel of the White Wizard", "props": [{"items": [{"value": "**If it is below 10**, then Saruman is concerned that the Dwarves might have stirred up evil, and his primary concern is determining the state of Moria — and rescuing Balin’s company, if possible. He mutters that this is another example of the folly of witless fools, and if only they’d listen to him, the world would be more orderly. Retrieving Ring-lore is a secondary matter for him.", "vk": "scalar"}, {"value": "**If it is between 10 and 15**, then play Saruman as paranoid and nervous. He paces back and forth furiously, muttering about how Gandalf is plotting against him again, or how this is all a scheme to damage Saruman’s own reputation. He sends the Player-heroes north to counter the Grey Wizard’s meddling as much as anything else.", "vk": "scalar"}, {"value": "**If it is 16 or more,** then Saruman is cold and determined; he already knows that victory can come only by allying with Mordor and, in the confusion of the war, seizing the Ruling Ring. To this end, he seeks the Ring-lore of Moria above all else.", "vk": "scalar"}, {"value": "Travel to Moria and learn the fate of Balin’s colony, offering what aid they can.", "vk": "scalar"}, {"value": "Searching for any lost lore — and finding Finir if they can.", "vk": "scalar"}], "name": "Items", "of": "STRING", "vk": "list"}], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "If the Player-heroes stay east of the Mountains, they encounter packs of Wargs. These demonic wolves are hunting Nidi and other escapees from Moria. There are three **Wild Wolves** for each Player-hero, plus one **Wolf-chieftain** (see *The One Ring*, pages 156 and 157). If the Player-heroes hide from the Wargs, they overhear them talking with their Goblin allies by night about the current state of Moria (see sidebar on page 103).", "entities": [], "entries": [], "guidance": [], "id": "#toa1aonYzqoqFZamCxnFGUM", "kw": "SCENE", "name": "Wargs!", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "There are several ways the Player-heroes may take to enter the Black Chasm: these are detailed below.", "entities": ["#tJqkGmZepj96Nvvd2aVhdw8", "#twXOU9PSboejoxiBaWbJ5Cr", "#tE82F4DUKKmyweQnfNWsA5i"], "entries": [], "guidance": [], "id": "#tiDrjNgfCSmp8hyLAB4mSxv", "kw": "SCENE", "name": "Entering Moria", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "The Dwarves numbered their halls in the order they were built, so the first hall is just inside the eastern gate, the second beyond the first, and so forth. Each hall was the seat of a great family or guild; it was not just a single chamber, but a complex of rooms centred around a grand feast-hall or council. Pile the Golden Hall of Meduseld upon itself seven times, and you scarcely equal the size and grandeur of the least of the Halls of the Dwarves.\n\nThe Twenty-first Hall of Moria lies high up on the western side of the Dwarrowdelf. It is near to the underground City Gate that leads to the long Road through the dark, and next to the Chamber of Mazarbul, the Dwarven hall of records….\n\nAs the Player-heroes make their way through the ruined wonders of Moria, they hear a strange sound in the distance. At first it is faint, and might be mistaken for their own heartbeats, but it grows louder and louder as they draw closer to the Twenty-first Hall.\n\nIt is the sound of drums. Drums in the deep. Ahead, the corridor the Company is traversing widens into a gallery overlooking a great chasm, a void in the heart of the mountain. Far below, torches burn in the dark, revealing a matching gallery on the opposite side of the chasm, parallel to the one the Player-heroes stand in. There, a multitude of Orcs charges eagerly forward. The sound of beating war-drums echoes up from the depths but is drowned out as the Orcs bash their swords against their shields, creating a deafening clamour. Then, the chanting begins: GOR-GOL! GOR-GOL! GOR-GOL!\n\nIf the Player-heroes are unfamiliar with the name, a successful **LORE** roll guesses that it’s likely the name of an Orcish warlord.", "entities": ["#t0YpSDOZRmOJ4XtWOMK67NJ"], "entries": [], "guidance": [], "id": "#tkDUeVwGtMe88aBYSqxpbQm", "kw": "SCENE", "name": "Drums in the Deep", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "In Eregion of old dwelt the Ring-makers, and chief among them was Celebrimbor. Now Celebrimbor was a friend of the Dwarves, and from them he learned much craft, and he shared with them a part of his knowledge. Indeed, the Dwarves believe that the First of the Seven, the ring of Durin III, was given to him by the Elves and not by Sauron, and so it is unsullied by the Enemy’s influence.\n\nAfter the fall of Eregion, the Dwarves of Moria closed the doors of their city for many centuries and hid themselves away from the surface world. In the fortress of West Moria, closest to Eregion, the Dwarf-smiths continued to experiment with the making of rings, even though they lacked the wisdom and knowledge of the High Elves. (*Moria: Through the Doors of Durin* contains more information on their folly, including the sealed tomb that was once the Citadel of the Ring-smiths.)\n\nMost of this lore was lost in the long decline of Khazad-dûm, or destroyed in the tumult of its fall. But a little was preserved, hidden away in old tomes and cryptic inscriptions. In his search, the smith Finir found one such cache of lore…", "entities": ["#t8PNrELLio26F6k8vO3WPkD", "#tf4zlNrO2T97gZGI5UB8Vml", "#ti6nmbhULYrOf5xMstPN3gn"], "entries": [], "guidance": [], "id": "#tMzOlU7gX7EaCR6ua4vaFdy", "kw": "SCENE", "name": "Finir and the Ring-smiths", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": null, "entities": [], "entries": [], "guidance": [], "id": "#tZvOzp5YEe4cqfjbjwQjypB", "kw": "SCENE", "name": "Rumour", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": null, "entities": [], "entries": [], "guidance": [], "id": "#thl6o9W7B5Aa26EUBVv3QeD", "kw": "SCENE", "name": "Old Lore", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "The Guild of Smiths was one of the ancient craft-guilds of the city of the Dwarrowdelf, responsible for the instruction and verification of all metal-workers. The guild-master was as wealthy and well-respected as any prince in Durin’s house. During the Second Age, when the Dwarves grew in friendship with the Elves of Eregion, a second guild-hall was built in West Moria. Adjoining this guild-hall was a crypt where the masters of the guild were laid to rest.\n\nAfter the fall of Eregion and the War of the Elves and Sauron, the Dwarves became insular, and closed their doors. Narvi and a few other Dwarves continued to research into Ring-lore for a time (see *Moria: Through the Doors of Durin*, page 141), but their efforts foundered. It was not until the last years of Moria, when the shadow of Angmar grew and\n\n**3 4**", "entities": ["#tsvGAzKfV3hphmyBRynhXVI", "#tYNIaSOxDBOlZanW1y9Sw3H"], "entries": [], "guidance": [], "id": "#tSLlxeakB532fd4E5EpN7q3", "kw": "SCENE", "name": "Background", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": null, "entities": [], "entries": [], "guidance": [], "id": "#tjGGtQnzggrtScOrmmHLpdb", "kw": "SCENE", "name": "Map of the Crypt of the Smiths", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": null, "entities": ["#thfBe9RRvTDtaLewSh4cm7g", "#t8NOn6CTvi15UHBBhgeaGxD"], "entries": [], "guidance": [], "id": "#tsGbO2nvVUBZSrRKduayKHV", "kw": "SCENE", "name": "Schemes and Trouble", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "Assuming the Player-heroes survive their ordeal in Moria, they stumble out into the stark light of day and stagger down the mountain slope towards safety. What have they brought out of Moria?", "entities": [], "entries": [], "guidance": [], "id": "#tEmpgnuwEmY83hdIxjIhoFM", "kw": "SCENE", "name": "A Darkness in the Sunlight", "props": [{"items": [{"value": "If Finir is still alive, then he intends to return with Nidi (if she lives) and bring word of the fate of the expedition to Dáin — but do the Player-heroes let him go?", "vk": "scalar"}, {"value": "If the Player-heroes have found the Ring of the Smith, then Finir claims it as his inheritance by right of both blood and heritage — he is a Dwarven master-smith *and* a descendant of the ring-smith Kinir. Do the Player-heroes let him keep it? If they try to keep the ring from him (a Misdeed worth 3 Shadow points), Finir attacks — do they slay him, or drive him away while sparing his life (in which case, he’ll stalk them obsessively)?", "vk": "scalar"}, {"value": "What was the fate of Balin’s expedition? Did everyone perish in the dark, or were the Player-heroes able to rescue some of the Dwarves?", "vk": "scalar"}, {"value": "What of loyal Nidi? Did she survive yet another expedition into Moria, or has her luck run out at last? If she’s alive, how does she react to the Player-heroes’ decisions?", "vk": "scalar"}, {"value": "Finally, what Ring-lore do the Player-heroes bring back to Saruman?", "vk": "scalar"}], "name": "Items", "of": "STRING", "vk": "list"}], "refs": [], "table": null, "type": "Roleplay"}, {"desc": null, "entities": [], "entries": [], "guidance": [], "id": "#tnIOvuue4J3u8SuX3lAW4g5", "kw": "SCENE", "name": "Preamble", "props": [], "refs": [], "table": null, "type": "Roleplay"}], "seq": [{"name": "Epigraph", "t": "prop"}, {"i": 0, "t": "location"}, {"i": 1, "t": "location"}, {"i": 2, "t": "location"}, {"i": 3, "t": "location"}, {"i": 4, "t": "location"}, {"i": 5, "t": "location"}, {"i": 6, "t": "location"}, {"id": "#tEJ114Hmhcl38U5WUzkWepq", "t": "scene"}, {"id": "#t7Bq4nz4Y4P9FZNvAXN3B8m", "t": "scene"}, {"id": "#tvWM1ZlvdFQKRHaO5DW40SC", "t": "scene"}, {"id": "#tX4KCu1JAPZ5lUYYAAQP3vM", "t": "scene"}, {"id": "#tgwl4kKoY6s8PRiVfLsglQb", "t": "scene"}, {"id": "#t4hhu0dVbC1xwPaoCEOcLYZ", "t": "scene"}, {"id": "#toa1aonYzqoqFZamCxnFGUM", "t": "scene"}, {"id": "#tiDrjNgfCSmp8hyLAB4mSxv", "t": "scene"}, {"id": "#tkDUeVwGtMe88aBYSqxpbQm", "t": "scene"}, {"id": "#tMzOlU7gX7EaCR6ua4vaFdy", "t": "scene"}, {"id": "#tZvOzp5YEe4cqfjbjwQjypB", "t": "scene"}, {"id": "#thl6o9W7B5Aa26EUBVv3QeD", "t": "scene"}, {"id": "#tSLlxeakB532fd4E5EpN7q3", "t": "scene"}, {"id": "#tjGGtQnzggrtScOrmmHLpdb", "t": "scene"}, {"id": "#tsGbO2nvVUBZSrRKduayKHV", "t": "scene"}, {"id": "#tEmpgnuwEmY83hdIxjIhoFM", "t": "scene"}, {"id": "#tnIOvuue4J3u8SuX3lAW4g5", "t": "scene"}]}, {"cast": [], "cid": "tor2e-hands-the-ithil-stone", "container": "ARC", "dependsOn": ["tor2e"], "desc": "This adventure takes place in or around the year 3,000 of the Third Age. Sauron has begun his final preparations: within a few short years, the War of the Ring shall begin, and the Shadow will fall over all the free lands of the West. All things shall be under the dominion of the Lidless Eye.\n\nFew obstacles remain in the path of Sauron’s conquest. Only Minas Tirith has the military might to resist; only the Great River of Anduin and the wide forest of Mirkwood present any physical obstacle to his armies. Once the Tower of Guard falls, once the crossings of the Great River are under Sauron’s control, then the hosts of Mordor can sweep west and north. Lórien will fall, and Dale and Erebor, and Rivendell, and Lindon — and Isengard.\n\nHow can hope endure in the face of hate?", "entries": [], "file": "tor2e-0.5-hands-the-ithil-stone.arc", "guidance": [{"concerns": [], "id": "#tJ4oZ00L8SmJGVlsTOx4VM6", "name": "Refusing the Quest", "text": "Player-heroes may balk at this perilous mission — especially if they are mortal heroes, and too old for such exertions. Others may decide that they have seen enough, and conclude that Saruman has fallen to madness or despair if he thinks that such a suicidal quest is the only way to resist the Enemy. If the players choose this, let them — but that betrayal tips Saruman over the edge. In his despair, he turns to the *palantír* for insight — and is caught by Sauron’s will, gaining 10 Shadow. It was the Player-heroes who doomed the White Wizard, in the end…", "topics": ["the ithil-stone"]}, {"concerns": [], "id": "#tEbwo75km4ehMNNquK7ZbZo", "name": "The Road", "text": "The other path the Player-heroes might take is the land route to Minas Tirith — they could ride through the settled portion of Rohan, past Edoras and the Firien Wood to the borders of Gondor. They would then turn north at the Drúadan Forest, and make for Cair Andros.\n\nThis route is arguably safer, and is certainly more crowded. There are two potential downsides to this path: Firstly, there’s the risk of drawing attention from\n\nordinary rogues and thieves. Greedy eyes see chests of treasure where others see metal casks containing unstable high explosive. Second, and more worrisome — in this era, Sauron\n\nhas more spies and watchers abroad, especially\n\non such a vital artery as the Great Road. Increase any Eye Awareness gains by 1 if the Player-heroes are on the Road.\n\nAn upside is that by now Théoden is king of Rohan, and a friend of Isengard; his chief concern is fighting against the encroaching Dunlendings from the west, and in this he receives wise counsel from Saruman, who through his magical arts can sometimes predict where the raiders will strike before they cross the border. Théoden owes several victories over the Dunlendings entirely to the wisdom of the White Wizard — how fortunate is Meduseld to have such an ally!", "topics": ["the ithil-stone"]}, {"concerns": [], "id": "#td0ijmMpjRSjC65d8hL5l1p", "name": "Revealing the Quest", "text": "*“ ‘Alas for the folly of these days!’ said Legolas. ‘Here all are enemies of the one Enemy, and yet I must walk blind*…*’ ”* — The Fellowship of the Ring™\n\nPlayer-heroes may wonder why Saruman does not present this stratagem to the Steward Denethor, and say *“I have a plan to safeguard your realm, shall we not work together on this endeavour?”* There are several reasons why Saruman might keep his plan a secret from the Steward. Among them: pride, for Saruman considers himself the leader of the West and would not ask for permission from Denethor; paranoia, for fear that involving Gondor might let slip some information; the desire to keep his secrets held close, and fear that Gandalf might interfere and steal this triumph from him.\n\nHowever, none of these restrictions apply to the Player-heroes. Isengard is far away so they could, if they chose, go to the Lords of Gondor (Denethor or Boromir, or Húrin Snowhair — see next page) and explain their quest. This requires a Council — it is a Reasonable request to be granted passage into Ithilien, a Bold request to do so without telling the Lord what they intend to do there, and an Outrageous request to ask for troops or other aid from Gondor.\n\nOf the three likely lords who might be approached, Denethor is Reluctant for he fears provoking Minas Morgul, while Boromir is Open, and Húrin is even Friendly, for he welcomes anyone who might strike against Mordor.\n\nHowever, Saruman is watching the progress of the Company through his *palantír*, and if he sees them betray him, he grows wrathful and his Shadow is immediately increased by 3. The players perceive this as strange, unnatural events — black crows from Dunland circling around them, a bitterly cold wind howling from the west, a glimpse of a white-clad figure.", "topics": ["the ithil-stone"]}, {"concerns": [], "id": "#tMwnCu8GaXDIjftdCZQFtAg", "name": "Accompanying Boromir", "text": "Glory-seeking Player-heroes may decide to cast away the quest laid upon them by Saruman, and instead accompany Boromir to Osgiliath. This is a suitably epic finale for the campaign — albeit not the one that Saruman intended. The casks of blasting powder can be profitably employed against the fortifications there. However, increase Saruman’s Shadow by 10 if the Player-heroes turn aside in this fashion (to signal the effects of their betrayal, see also *Revealing the Quest*, on page 124).", "topics": ["the ithil-stone"]}, {"concerns": [], "id": "#tVvCWwjzwdEqVlyoy4xj6r9", "name": "The Black Shadow", "text": "A victim of the Black Shadow remains unconscious for a week or until they are revived with a Magical success on a HEALING roll (or with a normal success if using *athelas*). On each of these days, the victim gains 3 Shadow points (Dread) — or 2 Shadow points (Dread) if the victim is a Dwarf or an Elf — and cannot Harden Will.Should a stricken Player-hero’s Shadow score reach their maximum Hope rating during the malady, then the Player-hero slips into ever deeper dreams and eventually dies. If the Player-hero resists for the length of the malady, they finally overcome their sickness and wake up (but maintain the new Shadow score).", "topics": ["the ithil-stone"]}, {"concerns": [], "id": "#tVP2WJUfQmXzUYqdVF5Ay2y", "name": "The Choices of Saruman, Final Part", "text": "*To the dismay of those that stood by, about the body of Saru- man a grey mist gathered, and rising slowly to a great height like smoke from a fire, as a pale shrouded figure it loomed over the Hill. For a moment it wavered, looking to the West, but out of the West came a cold wind, and it bent away, and with a sigh dissolved into nothing.*\n\nThree possible fates await Saruman in this adventure, and his destiny is bound to that of the Player-heroes. The fate depends on Saruman’s Shadow score. In each case, Saruman dares to look in the Seeing Stone of Orthanc to bend his will upon the events in the Morgul Vale; in each case, he is caught by the dreadful power of Sauron, who possesses the Ithil-stone. But *why* Saruman contemplates his orb, and what it means for the Player-heroes, differs.\n\nIn each case, it is up to the Loremaster to pick the most dramatic moment. Saruman’s fall should come at or very close to the climax of the scenario — as the Player-heroes sneak past Minas Morgul, as they plant the casks of blasting powder, or as the Ringwraiths appear…\n\nThe Heroic Ending (Shadow 15 or less): In this scenario, through the kindness and heroic example of the Player-heroes, Saruman retains something of his wisdom and purpose. Here, Saruman puts forth all his strength to ward off some terrible fate. This might be: The Player-heroes being spotted by the Enemy. The Player-heroes failing the Skill Endeavour while\n\nplanting the blasting powder. The Ringwraiths appearing.\n\nThe doomed heroes perceive a *presence*, unseen but shining brightly, and have the sudden impression that Saruman is with them — like Frodo on Amon Hen heard the Voice of Gandalf and saw the Eye of Sauron. The presence of the White Wizard saves them from whatever misfortune or folly was about to doom them. Maybe the gaze of the Lidless Eye is drawn away from the Player-heroes (countering a Revelation episode). Maybe the dropped cask of blasting powder miraculously catches on a rocky spike, or maybe Shelob recoils as she too senses the presence of an *Istar*.\n\nBut there is a cost to this divine intervention — the rescued Player-hero senses the Eye turn its burning gaze full force on Saruman. The White Wizard wails, and immediately gains 10 Shadow — but at least the Player-heroes have escaped doom.\n\nAlternatively, if the Loremaster is willing to deviate wildly from Tolkien’s storyline, then if the Player-heroes manage to escape the vale without Saruman having to intercede, then the Wizard never needs to look into the *palantír* and so is never caught by Sauron’s will. Saruman remains unfallen! Through their courage and kindness, the Player-heroes have saved him from himself!\n\nThe Despairing Ending (Shadow 16 to 20): In this scenario, Saruman does not intervene; instead, he falls to despair when it seems as if the Player-heroes are about to fail. As described above, the Player-heroes sense an unseen presence at a crucial moment of failure — but here, Saruman does not intervene. He merely *withdraws*, abandoning the Player-heroes to their doom. *The West has failed*, he seems to say, *now all that remains is coming to an accommodation with the rising Shadow*.\n\nExcellent times to stage this encounter include: The Player-heroes being spotted by the Enemy. The Player-heroes failing the Skill Endeavour while planting the blasting powder. The Ringwraiths appearing.\n\nSaruman has lost all hope, but there might still be a chance. The Player-heroes can rise to the occasion, and do what the Wizard cannot. Or, perhaps they too despair in the face of darkness, and fall at the last.\n\nThe Treacherous Ending (Shadow 21+): If Saruman has completely fallen to evil and malice, then this whole quest was a lie — the Player-heroes are his *offering* to Sauron, to show the loyalty of Isengard. Through the *palantír*, Orthanc speaks to Barad-dûr, warning the Dark Tower of the peril that even now threatens to choke the vital pass. Run this scene when the Player-heroes *succeed* at a critical test — maybe they just barely avoid being spotted, or they’re about to detonate the blasting powder and seal the pass. Just as the Player-heroes approach the threshold of victory, they sense the presence of Saruman projecting his thoughts through the *palantír* — and hear his cold laughter on the wind.\n\nThat successful test is now a *failure with woe*. So, so much woe. The Player-heroes have been revealed to the Enemy, sacrificed to Sauron’s ambition.\n\nThis scenario doesn’t necessarily mean that *all* the Player-heroes perish here — but if any of them are to survive, it will be on account of their own wit and luck, for Saruman has betrayed them and sold them out to Mordor.", "topics": ["the ithil-stone"]}], "kind": "arc", "locations": [{"desc": "A great shoulder of rock blocks the sight of the city from travellers until they are nearly upon it. Following the road, the Company behold a long valley, like a gulf of shadow, running between the forbidding mountains. A stream — the Morgulduin — runs through the valley; its waters are cold and clear, but seems to glow with an eerie light that somehow puts the Player-heroes in mind of luminescent glow-worms.\n\nThere is no movement, no sound save the trickling of water and the sighing of the wind in the peaks. The atmosphere is not oppressive — it is *alien* and *remote*, as if the travellers have come to some place beyond the circles of the world, some unknown and airless realm.\n\nThe sight is worth 2 Shadow points (Dread).", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "LOCATION", "name": "1. The Entrance to Imlad Morgul", "props": [], "refs": [], "table": null, "type": null}, {"desc": null, "entities": [], "entries": [], "guidance": [], "id": null, "kw": "LOCATION", "name": "The Morgul Vale", "props": [], "refs": [], "table": null, "type": null}, {"desc": "Many battles have been fought at Imlad Morgul. As the Player-heroes proceed down the path, they spot traces of these old wars. A fragment of bleached bone there, a shard of a broken sword there, scraps of armour there — as if the grey earth groans, too full of death to hold all the corpses who lie here. The further the Player-heroes go, the more remains they encounter, and the more disturbing and hallucinatory the scene becomes. Each Player-hero gains 3 Shadow points (Dread); those who fail their Shadow test panic and quail, or see their comrades as the walking dead, ghastly skeletons stumbling forwards on some utterly futile and long-forgotten purpose, and suffer a grievous Endurance loss from poison — they trip and fall on a rusty spear, or tumble down the rocks into the poisonous waters of Morgulduin.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "LOCATION", "name": "2. The Field of Bones", "props": [], "refs": [], "table": null, "type": null}, {"desc": "The road that runs through the vale is narrow, and is forced to wind around the feet of the unclimbable mountains deeper in the pass. Here, though, it is straight and level, clearly the work of the master-masons of Gondor of old. The road’s surface is covered in a whitish dust that rises in little clouds whenever anyone steps on it; this dust chokes and stains any travellers on the road. It glows faintly in the dark; any Player-heroes who get covered in this dust *lose (1d)* on **STEALTH** rolls for the rest of the adventure, or until they find a way to clean their clothes.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "LOCATION", "name": "3. The Morgul-road", "props": [], "refs": [], "table": null, "type": null}, {"desc": "A once-beautiful bridge, now eerie and ghost-like, arches over the Morgulduin on the road to the White City. Carven figures, both bestial and human, guard the bridge; like the Watchers at Cirith Ungol, these statues cry out in alarm if any foes pass between them. Only a Magical success (or the intervention of Saruman) can silence this alarm if the Player-heroes trigger it.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "LOCATION", "name": "4. The White Bridge", "props": [], "refs": [], "table": null, "type": null}, {"desc": "The city of Minas Morgul is, alas, beyond the scope of this adventure. Should the Player-heroes foolishly follow in the footsteps of King Eärnur, they will perish as he did.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "LOCATION", "name": "5. The City of the Ringwraiths", "props": [], "refs": [], "table": null, "type": null}, {"desc": "Fields of strange lilies and other white flowers grow here. These are corpse-flowers; they smell sweetly of rot, of decay, of alluring death. Any Player-heroes who come close to them gain 3 Shadow points (Sorcery); those who fail their Shadow test or who are Miserable are drawn towards the White Bridge and the city beyond, walking blindly until another Player-hero aids them with **ENHEARTEN**.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "LOCATION", "name": "6. Gardens of the Moon", "props": [], "refs": [], "table": null, "type": null}, {"desc": "To reach the foot of the Straight Stair, the Player-heroes must pass through this region of broken ground. The terrain is a nightmare of twisted stone, sucking mud, thorn-bushes and weirdly preserved ruined structures. It is as though the end of the world has come and gone here already, and all that remains is the blasted, desiccated remains of the past.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "LOCATION", "name": "7. The Festering Vale", "props": [], "refs": [], "table": null, "type": null}, {"desc": "Here, the path diverges from the base of the valley and climbs up the mountainside. The stair is terribly steep; most of it is walkable, but in places the Player-heroes must climb (with **ATHLETICS** rolls needed to make progress). Up and up the path goes, a dizzying ascent into the eerie heights. In places it runs through a dark tunnel bored for hundreds of feet through solid rock. Then it begins to wind, and along its winding course it comes to…", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "LOCATION", "name": "8. The Straight Stair", "props": [], "refs": [], "table": null, "type": null}, {"desc": "*— The Two Towers™*\n\nHere is the last glimpse of the Morgul Vale, before the Winding Stair climbs up and on to the peaks of Shadow, and the tunnel of Torech Ungol. If the cliffs below Eärnur’s Edge were destroyed, the narrow mouth of the Pass of Shadow would be blocked for a mortal lifetime!\n\nCall for an **AWARENESS** roll as the Player-heroes reach Eärnur’s Edge. Those who succeed notice that there is a huge spiderweb covering much of the cliff face below…", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "LOCATION", "name": "9. Eärnur’s Edge", "props": [], "refs": [], "table": null, "type": null}], "name": "The Ithil-stone", "page": 115, "phases": [{"desc": "As he has done many times before, Saruman calls the Player-heroes to attend him in Isengard.\n\nWhere are the Player-heroes at this point in their careers? Decades have passed since they first entered the service of Orthanc. By now, mortals have grown old (unless they have the blood of Númenor) and even Dwarves are no longer young. How many of the original Player-heroes are left? How many are still loyal to their original patron?\n\nAs the Company approaches Isengard, they see a veil of smoke hanging over the Wizard’s Vale. Describe the state of both Isengard and Saruman depending on Saruman’s current Shadow total.\n\nsoldiers drill in the courtyard, their ironshod boots trampling the grass. The fortress has been restored and refortified. Saruman, bent by many cares, is more like an aged general than a Wizard. Agents bring him reports from across the land, from Edoras and Minas Tirith and further afield. But Saruman still greets the Player-heroes with the flicker of a smile.\n\nAgain, the Player-heroes are brought to Saruman’s study within the tower. On his desk are maps depicting the lands of Ithilien and the Mountains of Shadow.\n\nThe Wizard sits down opposite the Player-heroes. *“A Power is rising in Middle-earth, a power against which there can be no defence, against which force of arms and courage of spirit will not avail us. The Elves are fading, fleeing. The Dwarves, scattered. Mortal Men — perhaps, in time, with proper guidance, there might be a chance through them. My colleagues on the White Council — they refuse to look into the darkness. They prefer to cling to blind hope, to gamble on the whims of fate. They put their trust in the Valar, and the Valar will send no further help. We must take charge of our own destiny.”*\n\nHe spreads the maps of Ithilien and the Morgul Vale before them.\n\n*“The Enemy must seize the crossings of the Great River at Osgiliath and Cair Andros. Without those crossings, all his armies are of little use. Gondor guards the crossings, so he must take Minas Tirith, too. This much is obvious.*\n\n*There are two gates from the Land of Shadow. The chief gate is at the Morannon, here, the Towers of the Teeth. There the Last Alliance challenged the Enemy at the Battle of Dagorlad. Now, should Sauron send an army out from that gate, the Men of Gondor have adequate time to prepare a defence. A few true-hearted warriors can hold the narrows against ten thousand, if they have time to prepare.”*\n\nWith a long fingernail, he traces the path from the Morannon through Ithilien, down to the shoulder of Emyn Arnen.\n\n*“But there is another door to the Dark Land. The Morgul-road.”*\n\nHe taps the place marked *Minas Ithil*, and then draws a quick line down the road, as if cutting Ithilien in twain. *“The Enemy controls the Tower of the Moon, and cloaks it in shadow. A great host could come down the Morgul-road, and thence to the Crossings with almost no warning. In days of old, the seeing stones might have provided some defence, but they cannot be used. This is my fear — that Sauron strikes like a serpent, winning the western shore with a sudden assault from the Morgul Vale.*\n\n*We must prevent this. The blasting powder I prepared is the key to the salvation of Middle-earth. If the Vale is choked with rubble, if the Morgul-road is blocked, then there can be no sudden attack. Instead, Sauron will have to grind Minas Tirith into submission through long war and siege — and that will take time. Time I shall use wisely.*\n\n*This, then, is the task I lay upon you. Make your way in secret to the Morgul Vale, and block the Morgul-road!”*\n\nLikely questions:", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "PHASE", "name": "Part 1: The Final Summons", "props": [{"items": [{"value": "**Less than 10 Shadow:** Isengard is a hive of activity. Men — mostly Dunlendings — labour in the forges;", "vk": "scalar"}, {"value": "**10–15 Shadow:** Black smoke belches from the forges where Men and a few Orcs work, hammering out swords and axes. Isengard is preparing for war. Saruman maintains a veneer of authority and cool control, but there is terror in his eyes, like a cornered beast. He knows everything is slipping away, that these are the last fleeting minutes of dusk before a never-ending night.", "vk": "scalar"}, {"value": "**16+ Shadow:** Isengard is an armed camp. There are as many Orcs as Men, and it is hard to tell which is which. Saruman seems haughty and remote, and the Player-heroes have the impression that he looks at them like pieces on a chessboard.", "vk": "scalar"}, {"value": "**How do we get past Minas Morgul?*** “The Enemy is not expecting anyone to sneak into Mordor. They will be watchful, of course, but with cunning and guile you will find a way. There are also scouts from Minas Tirith operating in Ithilien; Rangers, Men call them. They may be of aid — but they cannot be trusted entirely. Do not tell them your business.”*", "vk": "scalar"}, {"value": "**Won’t the Enemy clear the pass or just attack Minas Tirith directly?*** “With time, yes. Did you think Sauron the Terrible could be defeated by some little thing, by a single lucky stroke? These are not the days of Beren or Túrin Turambar. The Elder Days are gone, and the Middle Days are fading. This Age will turn on cunning, not courage.”*", "vk": "scalar"}, {"value": "**Where do we put the casks of blasting powder?*** “High above the Morgul-road is another, lesser pass — the Stairs of Cirith Ungol. There are two portions to Cirith Ungol — the steep straight stair, and the long winding stair. Near the base of the winding stair, the path comes close to a perilous cliff, looking down upon the Morgul-road. Eärnur’s Edge, Men call in. If the casks are lowered by ropes and planted along the face of the cliff, the ensuing landslide will block the narrowest point of the pass and seal the Morgul-road with enough debris that it will take many years to clear.”*", "vk": "scalar"}, {"value": "**How do we escape? ***“There are fuses supplied with the blasting powder. Set the casks, then fall back down the Vale. The blast and dust cloud should provide adequate cover.”*", "vk": "scalar"}], "name": "Items", "of": "STRING", "vk": "list"}], "refs": [], "scenes": ["#tQ2C3ShKhZRaG6de79YFMy9", "#tZqJKUs0iT8d8S4b8AoeSXe", "#tOhDe5yCsNUj1Oevki8TwhH", "#tsxnVQGGyKQCgSIyqfzqKIY"], "table": null, "type": null}, {"desc": "The Company begin by travelling east on ponies. Even if they intend to take a boat down the Entwash and hence to the Anduin, they need to carry the powder casks to where the boat waits at the eastern edge of Fangorn.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "PHASE", "name": "Part 2: The Journey East", "props": [], "refs": [], "scenes": ["#tzK4FdNXKcXs93L4AGZntQ6", "#ttfluJYuxC7M3EIIORL82BG", "#trfSZUuVg1Eb39vu4FDkg1C", "#tmkdDzUTWaA2Ga8cPlWmBnl"], "table": null, "type": null}, {"desc": "*— The Two Towers™*\n\nThe Player-heroes are now East of the Great River, and close to the border of the lands of the Enemy. The end of the quest is not far away — but many perils lie between them and the Morgul Vale.", "entities": [], "entries": [], "guidance": [], "id": null, "kw": "PHASE", "name": "Part 3: The Crossing of Ithilien", "props": [], "refs": [], "scenes": ["#twQE0So1R0kTYZ8ibGE0f8B", "#trq36YD18FCJKFndAmoFze8", "#tECvCwV9czcoIKsLUKDQOfO", "#taPSJG7S9Ismljnr4MTUW7j", "#tA8dWNkGp8aAp2co19jV61m"], "table": null, "type": null}, {"desc": null, "entities": ["#tRicfRKMY7j9vj8ID6Yxmm1", "#t9M88oXTalAilPUkTgxUPO3"], "entries": [], "guidance": [], "id": null, "kw": "PHASE", "name": "Part 4: The Morgul Vale", "props": [], "refs": [], "scenes": ["#t5fHPn369vxOInyUG2L6QFZ", "#t8ncxF2RewH1rkVTTj22ZQQ", "#tBElSh5gGJnrsJPGMDy9q9R", "#tQTcRxifYVRv1n15aQ2xwM3"], "table": null, "type": null}], "props": [{"name": "Epigraph", "type": "STRING", "value": "The shadow of Mordor lengthens. Saruman dares use the Palantír of Orthanc, but becomes ensnared by Sauron, who has the Ithil-stone…", "vk": "scalar"}], "roots": [], "scenes": [{"desc": null, "entities": [], "entries": [], "guidance": [], "id": "#tQ2C3ShKhZRaG6de79YFMy9", "kw": "SCENE", "name": "Preamble", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "A considerable quantity of the blasting powder is required to block the stair — the equivalent of 20 points of Load, as much as two stout ponies could comfortably bear. Saruman suggests taking a boat down the Entwash, then either braving the marshes or going cross-country to Cair Andros — but the route and method of travel is up to the Player-heroes. They have the full resources of Isengard to draw upon, with the caveat that they must obviously be as stealthy as possible, if they are to pass the sentries of Minas Morgul.\n\nThe Player-heroes may take whatever gear they wish from the storehouses and foundries, in the form of up to two Useful Items each. The players do not need to specify which Skills these items apply to until they actually make the test (“aha! I brought rope!”).\n\nSaruman has procured a sturdy riverboat, with old Bar or some sullen Men of the Lake as crew; sturdy ponies are also available.", "entities": [], "entries": [], "guidance": [], "id": "#tZqJKUs0iT8d8S4b8AoeSXe", "kw": "SCENE", "name": "Preparations for the Journey", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "When the Company is ready to depart, servants bring the blasting powder up from the pits dug beneath the fortress. The powder is stored in four heavy metal casks (Load 8 each — 5 Load worth of powder, and 3 of cask). Within these sealed casks, the powder is protected from misfortune or stray sparks. The servants demonstrate (with an empty cask!) how to open the lid so a torch or fuse may be inserted. The powder can be decanted into sacks (reducing the Load to just that of the powder), but then there’s the risk of accident.\n\nSaruman watches the Player-heroes depart Isengard from the balcony of Orthanc, but he does not descend to bid them farewell or wish them good fortune. What use are empty words?", "entities": [], "entries": [], "guidance": [], "id": "#tOhDe5yCsNUj1Oevki8TwhH", "kw": "SCENE", "name": "Departing Isengard", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "Saruman, succumbing to temptation, watches the progress of the Player-heroes using the *palantír*. A Magical Success on an **AWARENESS** roll can sense the unseen eye watching them; even those who lack such supernatural perception may have the prickly sensation they are being watched. Saruman should be a *presence* in this adventure more than any other. The Player-heroes might glimpse an old man dressed in white, or dream of the Wizard, or hear his voice in the back of their minds.\n\nSimilarly, as the adventure goes on, the Loremaster should emphasise the weight of the explosive casks, echoing the burden of the Ring on Frodo. Contrast the differing approaches of the two Wizards; Gandalf will put his faith in the rejection of dominion over others, in putting aside power, in simple folk, whereas Saruman trusts in power, in technology, in obedience and stratagems.", "entities": [], "entries": [], "guidance": [], "id": "#tsxnVQGGyKQCgSIyqfzqKIY", "kw": "SCENE", "name": "Visions of the White Wizard", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "A day after leaving Isengard, their Look-out glimpses a sudden plume of black smoke not too far away. **Raiders from Dunland** have crossed the Isen and attacked an outpost of Rohan. Do the Player-heroes investigate, or keep moving?\n\nThe Dunlendings are warriors from Crow Hall — a dozen **Southerner Raiders** led by a **Southerner Champion**. They are all young, their leader no more than twenty years old; the events of *The Beast of Dunland* are old tales to them, and even if the Player-heroes visited Crow Hall during *There Let Them Lie Until the End*, the raiders were but children then. The target of the raid is a stead where shepherds gather in winter, and where stocks of wool and hide are stored.\n\nAs the Player-heroes arrive, they see that there are still a few Rohirrim fighting in one of the buildings, even as the thatched roof burns. The Dunlendings stand athwart the doorways, preventing the defenders from fleeing. A breeze from the east fills the air with burning red sparks.\n\nDo the Player-heroes intervene? If so, how? Do they attack the Dunlendings — or attempt to **AWE** or **PERSUADE** them as old friends of Crow Hall? Do they reveal Saruman’s influence over the tribes of Dunland?", "entities": [], "entries": [], "guidance": [], "id": "#tzK4FdNXKcXs93L4AGZntQ6", "kw": "SCENE", "name": "The Raiders", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "If the Player-heroes choose the river route, then they can board the ship Saruman prepared for them near the spot where the Entwash exits the forest and wanders across the open plain. The boat is a sturdy, flat-bottomed ship — not swift, but well suited for navigating the marshes of the Mouths of Entwash.", "entities": ["#tK37ZBmIFklDcVMfPcLXfLh", "#t7IwWSDnfXmDoaEEmE0fXDF"], "entries": [], "guidance": [], "id": "#ttfluJYuxC7M3EIIORL82BG", "kw": "SCENE", "name": "The River Path", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "At the end of the journey, the Company come to Cair Andros, about two weeks after they set out from Isengard. The island is a long narrow outcrop of stone, reminiscent of a mighty ship; huge fountains of white spray rise as its stony prow cuts through the onrushing river. The isle has long been a fortress of Gondor; tunnels and storehouses have been cut into the rock, and there are watchtowers, castles and other fortifications all along the isle, especially on the eastern side. Ancient steel chains run between the island and the shore, allowing the soldiers to block river traffic. If the Player-heroes are still on a boat, they must stop here.\n\nThe whole island is under the jurisdiction of a military governor; it is forbidden for outsiders to land here without permission. On the western bank is a jetty and landing area, surrounded by what was once but an outpost, but in recent years has swelled into a mid-sized town — Ithilien was abandoned fifty years ago, and many of those who once dwelled across the river now live here.\n\nOn the far side of the river, on the eastern bank, there is another jetty, but this one is heavily fortified.\n\nAll travellers must stop on the west bank of the Anduin. Only those with good reason to visit the fortified island may land on Cair Andros itself; only the Rangers may cross into Ithilien.", "entities": ["#tuEEdjqq1iZgKu83DCIShsi", "#tCC9FkoF59foe4c92FudUOY", "#tlOU3uJ94OmDayEpuL1HurS", "#twGuOhw91r2LJGKhzYRQXhS"], "entries": [], "guidance": [], "id": "#trfSZUuVg1Eb39vu4FDkg1C", "kw": "SCENE", "name": "Arrival at Cair Andros", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "It is possible that the Player-heroes may decide to take a different route. The key question is ‘where do they cross the river?’ Crossing between Cair Andros and the southern edge of the Nindalf risks running into Ranger patrols along the shore. A landing further north means dragging those heavy casks over the marshes. Wait until the River brings them further south, and the Player-heroes must travel through Gondor in a time of rising tension, when strangers are less than welcome.\n\nThe other danger is that the east bank is watched. The Rangers keep Orcs and other spies of the Enemy away from the sheltered Forest of Cormallen near Cair Andros, but if the Player-heroes land at another point on the Anduin, they may be watched by foes — unless they come up with a clever way of hiding their movements, increase their Eye Awareness by 2.", "entities": ["#tq1uHaJyhhSTWzx9E0r6H43"], "entries": [], "guidance": [], "id": "#tmkdDzUTWaA2Ga8cPlWmBnl", "kw": "SCENE", "name": "Bypassing Cair Andros", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "Once the fair garden of Gondor, Ithilien was abandoned nearly a century ago when the depredations of Orcs grew too terrible to endure. Its inhabitants fled over the Anduin, save a few stubborn holdouts — and most of them left when Sauron returned. There are yet defiant folk in isolated places who refuse to leave their homes, but their numbers dwindle each year. The traces of this abandonment are everywhere — empty farmsteads that feel as if the inhabitants have just stepped out for a moment, tilled fields engulfed by weeds, herds of wild cattle, weeds growing over paved roads.\n\nNow, Ithilien is Gondor’s outer line of defence. The Enemy regularly probes the fortifications of Osgiliath and the other crossings of the Anduin (Cair Andros, and occasionally as far south as Pelargir). The Black Gate vomits armies of Orcs, Trolls and Easterlings, and they march south through Ithilien.\n\nThe Rangers of Ithilien spy on the movements of the Enemy’s forces, harassing and sabotaging them when they can. A network of hidden fortresses and outposts ensures the Rangers can strike swiftly and then melt away into their concealed fastnesses. But the Rangers are not enough to stop all of the Enemy’s assaults, and in recent months a host of Uruks and Hill-trolls have encamped in the eastern ruins of Osgiliath and fortified their position, so they can make regular attacks on the surviving bridges.\n\nBoromir, at the behest of his father the Steward, intends to catch these Orcs unawares. By crossing at Cair Andros and travelling south at speed, he hopes to attack with such force that the Orcs are dismayed and defeated. It is a bold stratagem, at odds with Gondor’s traditional military approach of defending and slowly retreating. Not since the days of Last-king Eärnur has Gondor made such a direct attack against Mordor.", "entities": [], "entries": [], "guidance": [], "id": "#twQE0So1R0kTYZ8ibGE0f8B", "kw": "SCENE", "name": "The State of Ithilien in T.A. 3000", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "A wood dominated by yellow-blossomed laburnum trees, and the black-trunks of *lebethron*, the Forest of Cormallen shrouds the eastern bank of the Anduin. There is a great green field, near the confluence of the waters where the host from Cair Andros musters.\n\nIf the Player-heroes crossed with Boromir’s host, then they need to slip away into the trees. This can be accomplished with a **STEALTH** roll; failure means the Company are spotted and pursued by Rangers (see *The Rangers of Ithilien*, on page 129). The roll *loses (1d)* if the Company have ponies with them.", "entities": [], "entries": [], "guidance": [], "id": "#trq36YD18FCJKFndAmoFze8", "kw": "SCENE", "name": "The Forest of Cormallen", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "The journey across the breadth of Ithilien is some thirty miles — two days of travel, through a mix of forest and overgrown farmland. Compared to many of the places the Player-heroes have gone in their service of Saruman, this is easy terrain. Were it not for the looming shadow of the Ephel Dúath and the oppressive darkness of the smoke-stained sky, this would be a beautiful land. As it is, it is melancholic, autumnal, and fading.\n\nA **STEALTH** roll from the Scout is required as the Company travel. If the roll fails, then the Player-heroes are spotted by Rangers of Ithilien. The Look-out may make an **AWARENESS** roll to spot these pursuers — otherwise, the Rangers stalk the Company unseen.", "entities": ["#tFtTAMTCmAUzvHk4uuzDqdi"], "entries": [], "guidance": [], "id": "#tECvCwV9czcoIKsLUKDQOfO", "kw": "SCENE", "name": "From The Field of Cormallen to Morgul Vale", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "The Rangers are sworn to protect Ithilien and slay any trespassers who enter this land without the Steward’s permission. If they happen upon the Player-heroes trespassing, there are several ways the scene can play out.\n\nThe Ranger-company consists of two **Rangers** per Player-hero, plus their Captain, **Heledirien**.", "entities": ["#tFkRrXsDwamSqJrYSbDt51a"], "entries": [], "guidance": [], "id": "#taPSJG7S9Ismljnr4MTUW7j", "kw": "SCENE", "name": "The Rangers of Ithilien", "props": [{"items": [{"value": "The Rangers confront and surround the Company as they travel through the woods.", "vk": "scalar"}, {"value": "The Rangers surround the Company as they sleep; unless woken by the Look-out, the Player-heroes are woken by knives at their throats.", "vk": "scalar"}, {"value": "The Rangers encounter the Company around the same time they run into the *Swift Foes From Mordor* (see page 130).", "vk": "scalar"}], "name": "Items", "of": "STRING", "vk": "list"}], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "As Saruman feared, the Morgul-road allows the Enemy to respond swiftly to threats. Soon after Boromir’s host crossed the Anduin, foes marched out from the plain of Gorgoroth to counter this attack. The forces of Mordor lack cavalry in significant numbers (apart from a few steeds for the Nazgûl and other messengers, there are no horses in Mordor, and Sauron has yet to call up the bulk of his Easterlings; neither are there Wargs), but he has troops who can respond swiftly to an attack. Lightly-armoured Uruks, Hill-trolls who are maddened by sunlight instead of turned to stone, and flying insects the size of a Hobbit-child that buzz and swarm overhead, sheltering the fast-marching forces.\n\nThere are several ways this encounter might play out:\n\nShould the Player-heroes do battle with these foes, there are two **Black Uruk Soldiers** (see page 66) for each Player-hero, plus a **Black Uruk Captain** (use the stats of **Baugrim** on page 66) if the Player-heroes either attack in concert with the Rangers, or engage only a part of the host (say, if the heroes are spotted and pursued by a detachment of foes). If the Player-heroes stand athwart the Road and try to stop the host on their own, then they face double the **Black Uruk Soldiers**, and one **Hill-troll** (see below).\n\nThe Loremaster should emphasise the chaotic nature of this battle. If the Rangers are involved, they do not stand in ranks out in the open; they are archers and skirmishers, attacking from cover, using their great bows.\n\nThe most likely setting for this scene is at or near the Crossroads, where the roads between Osgiliath and Minas Ithil, and the long road between far-off Harad and the Morannon meet.", "entities": [], "entries": [], "guidance": [], "id": "#tA8dWNkGp8aAp2co19jV61m", "kw": "SCENE", "name": "Swift Foes From Mordor", "props": [{"items": [{"value": "The Player-heroes might see the swift-moving force as it marches down the Road towards Osgiliath; if they stay hidden, they can wait until it passes, or do battle with the enemies.", "vk": "scalar"}, {"value": "The Player-heroes might see the Rangers of Ithilien ambushing these swift foes. If they do not intervene, then the Rangers are all slain, but they deal enough damage to the forces from Mordor for it to be a pyrrhic victory.", "vk": "scalar"}, {"value": "If the Player-heroes have been captured by the Rangers of Ithilien, then the swift foes from Mordor might interrupt their conversation at just the wrong moment (or the right one, if the Player-heroes are about to be executed).", "vk": "scalar"}], "name": "Items", "of": "STRING", "vk": "list"}], "refs": [], "table": null, "type": "Roleplay"}, {"desc": null, "entities": [], "entries": [], "guidance": [], "id": "#t5fHPn369vxOInyUG2L6QFZ", "kw": "SCENE", "name": "Rumour", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": null, "entities": [], "entries": [], "guidance": [], "id": "#t8ncxF2RewH1rkVTTj22ZQQ", "kw": "SCENE", "name": "Old Lore", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "*Imlad Morgul* is a pass that runs through the Mountains of Shadow. Its western end is guarded by the Tower of the Moon, *Minas Ithil* — or so it was called when it was built by Isildur.\n\nIndeed, in the early years of the South-kingdom, Minas Ithil was considered the greater of the two fortresses, for it was here that the Prince of Gondor had his throne, and here the first White Tree flourished for a time.\n\nHowever, the Seventh King, Ostoher, preferred the sun, and he greatly expanded and improved the fortress of Minas Anor, making it into a summer-city where the kings dwelt from time to time. It may be that this was a sign of the slow decline of the Men of the West, that they turned away from their vigil over the Land of Mordor.\n\nMinas Ithil became a fortress of scholars, of healers, and of stargazers. Strange and fey were the folk of that city, burdened by the constant presence of the Shadow, but many of the greatest champions of Gondor came of their line. Armies from Minas Ithil fought in the many wars that beset the realm. During the Kinstrife, enemies of King Eldacar sought to make Minas Ithil their capital, but they were rejected, and fled instead to Umbar.\n\nThe folk of Ithilien and Minas Ithil in particular suffered greatly in the Plague that followed; it is said that so many perished that whole districts of the city were afterwards abandoned and never entered again. Minas Ithil was besieged during the attacks of the Wainriders, but the city was well guarded by the narrow pass, and endured. Still, by now only a handful of folk still dwelt here; the City of the Moon was in eclipse, and would soon fall into shadow.\n\nIn the Year 2000 of the Third Age, the Nine Ringwraiths gathered for the first time under the command of their Captain, the Witch-king of Angmar, and laid siege to Minas Ithil. This was not a conquest through force of arms, but through sheer terror. No living man dared stand against the Nazgûl; no army or supplies could cross the bridge while the wraiths held it. The few defenders behind the walls endured for two years until starvation and despair drove them to madness, and they threw open the gates and invited the Witch-king to enter.\n\nThe city was corrupted, and became Minas Morgul, the Tower of Dark Sorcery, a skull grinning across the marshes. For a thousand years it has stood, a ghastly mockery of its lost beauty, the former gaoler of Sauron turned into the citadel of his greatest servants. It is the city of the wraiths, and it commands the pass into the Dark Land.", "entities": [], "entries": [], "guidance": [], "id": "#tBElSh5gGJnrsJPGMDy9q9R", "kw": "SCENE", "name": "Background", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": null, "entities": ["#tjB25fRS8YcLtFFhqULF80W", "#t7TX6IaVDquaWu1z2sfbuUU", "#tXql7ACjtO8NZFHlDJrNvx4", "#tE3KTdIb1Bo590MtlVcpXPj", "#tBmTp922LeSYlli8quvP7X3", "#tX8NeUsRzDKSA42P3jjTs6Z"], "entries": [], "guidance": [], "id": "#tQTcRxifYVRv1n15aQ2xwM3", "kw": "SCENE", "name": "Schemes and Troubles", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": null, "entities": [], "entries": [], "guidance": [], "id": "#tTTJb5Q9uyQFX9Hi73a2Ncp", "kw": "SCENE", "name": "Preamble", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "If the survivors return to Isengard, then depending on circumstances, they may find Saruman to be a changed individual. He has fallen from the path of wisdom — but was this a slow and inevitable decline, or a misfortune born out of pride, or even misplaced courage?", "entities": [], "entries": [], "guidance": [], "id": "#tkQPWUa6wCtaV0g164EMTCQ", "kw": "SCENE", "name": "Aftermath", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "If Saruman’s final Shadow is 16 or more, then later events transpire as related in *The Lord of the Rings*. Saruman comes to the conclusion that the Enemy cannot be defeated, and that therefore the wisest course of action is to *ally* with the Shadow. (*“We can bide our time, we can keep our thoughts in our hearts, deploring maybe evils done by the way, but approving the high and ultimate purpose: Knowledge, Rule, Order; all the things that we have so far striven in vain to accomplish, hindered rather than helped by our weak or idle friends.”*)\n\nIn the years to come, the Wizard consolidates his power. If his Shadow is 20 or less, then the Player-heroes are offered places at his side in Isengard or sent as his agents to courts around the land. They likely end up as creatures like Gríma Wormtongue. Those he suspects of insufficient loyalty are dismissed from his service — but he invites them to send their children to Isengard for fostering and education, when they are ready.\n\nIf Saruman’s Shadow is 21 or more, then he likely eliminates the surviving Player-heroes — he invites them to dine with him in the gardens of Isengard, just as he did when they first arrived to serve him all those years ago… but this time, the wine is poisoned. Should the Player-heroes become aware of the plot, Saruman will be forced to confront them directly.\n\nSaruman is assisted by one **Black Uruk Soldier** for each Player-hero, plus the Uruk-captain **Gurthaur** (use the stats of **Baugrim** and his soldiers, on page 66).", "entities": [], "entries": [], "guidance": [], "id": "#toRSdPn8bcUuZRNogufV7qa", "kw": "SCENE", "name": "Inevitable Despair", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "If Saruman’s final Shadow is 15 or less, then the players are to be commended — they have achieved an astoundingly unlikely deed, and saved the White Wizard from his own folly. And what are the consequences of this? With Saruman unfallen, then Gandalf is there to escort Frodo to Rivendell, and there is no knife in the dell at Weathertop. With no threat from Isengard and Dunland, with no Wormtongue whispering poison in Theoden’s ear, then Rohan’s full strength can be put to the aid of Minas Tirith. Maybe the knowledge of that stalwart ally puts Boromir’s fears to rest enough that he can resist the temptation of the Ring, and the Fellowship is never broken. Maybe it is Saruman the White who holds the gates of the city against the Witch-king, while Gandalf Greyhame helps guide Frodo into Mordor. Think on it! Prince Theodred riding to the defence of the White City with Boromir! Denethor, the last steward, solemnly surrendering his authority to the King Elessar and retiring with honour from his post. So much suffering would be spared… and the Shire would never be scoured.\n\nAnd at the end, at the Grey Havens — Saruman and Gandalf would ride to the last ship together, and return to the West. There would be no need for the Ringbearer to seek healing, and he might instead enjoy the fruits of his victory in the Shire.\n\nAll this might come to pass though — if the deeds of the Player-heroes are enough to move the heart of Ilúvatar.", "entities": [], "entries": [], "guidance": [], "id": "#tctd0Bgxeu7biEqd7VXGYpo", "kw": "SCENE", "name": "Hope Unlooked-for", "props": [], "refs": [], "table": null, "type": "Roleplay"}, {"desc": "Pick one of the surviving Player-heroes — ideally, the one who was most closely aligned with Saruman over the course of the campaign. Many years later, in the Year 3017 of the Third Age, that Player-hero hears a knock at their door. **Gandalf the Grey** stands on the threshold. He has travelled far and fast, on an urgent errand, but still he turns aside to ask one key question of the Player-hero.\n\n*“For many years, you served Saruman. You know his mind as well as any living soul — and I need his wisdom and his Ring-lore more than ever. Tell me truthfully — can the White Wizard be trusted?”*", "entities": [], "entries": [], "guidance": [], "id": "#t6djZEakTISePHWvq95okMY", "kw": "SCENE", "name": "Epilogue: The Last Question", "props": [], "refs": [], "table": null, "type": "Roleplay"}], "seq": [{"name": "Epigraph", "t": "prop"}, {"i": 0, "t": "location"}, {"i": 1, "t": "location"}, {"i": 2, "t": "location"}, {"i": 3, "t": "location"}, {"i": 4, "t": "location"}, {"i": 5, "t": "location"}, {"i": 6, "t": "location"}, {"i": 7, "t": "location"}, {"i": 8, "t": "location"}, {"i": 9, "t": "location"}, {"id": "#tQ2C3ShKhZRaG6de79YFMy9", "t": "scene"}, {"id": "#tZqJKUs0iT8d8S4b8AoeSXe", "t": "scene"}, {"id": "#tOhDe5yCsNUj1Oevki8TwhH", "t": "scene"}, {"id": "#tsxnVQGGyKQCgSIyqfzqKIY", "t": "scene"}, {"id": "#tzK4FdNXKcXs93L4AGZntQ6", "t": "scene"}, {"id": "#ttfluJYuxC7M3EIIORL82BG", "t": "scene"}, {"id": "#trfSZUuVg1Eb39vu4FDkg1C", "t": "scene"}, {"id": "#tmkdDzUTWaA2Ga8cPlWmBnl", "t": "scene"}, {"id": "#twQE0So1R0kTYZ8ibGE0f8B", "t": "scene"}, {"id": "#trq36YD18FCJKFndAmoFze8", "t": "scene"}, {"id": "#tECvCwV9czcoIKsLUKDQOfO", "t": "scene"}, {"id": "#taPSJG7S9Ismljnr4MTUW7j", "t": "scene"}, {"id": "#tA8dWNkGp8aAp2co19jV61m", "t": "scene"}, {"id": "#t5fHPn369vxOInyUG2L6QFZ", "t": "scene"}, {"id": "#t8ncxF2RewH1rkVTTj22ZQQ", "t": "scene"}, {"id": "#tBElSh5gGJnrsJPGMDy9q9R", "t": "scene"}, {"id": "#tQTcRxifYVRv1n15aQ2xwM3", "t": "scene"}, {"id": "#tTTJb5Q9uyQFX9Hi73a2Ncp", "t": "scene"}, {"id": "#tkQPWUa6wCtaV0g164EMTCQ", "t": "scene"}, {"id": "#toRSdPn8bcUuZRNogufV7qa", "t": "scene"}, {"id": "#tctd0Bgxeu7biEqd7VXGYpo", "t": "scene"}, {"id": "#t6djZEakTISePHWvq95okMY", "t": "scene"}]}, {"cid": "tor2e-hands-worksheet-saruman-s-shadow-score", "container": "EXTENSION", "dependsOn": [], "desc": null, "file": "tor2e-0.5-hands-worksheet-saruman-s-shadow-score.ttrpg", "guidance": [], "kind": "ttrpg", "name": "Hands of the White Wizard - Saruman’s Shadow Score", "page": 143, "props": [], "roots": ["#t4tH0BF1gelfgVc1eyhWAuw"]}, {"cid": "tor2e-hands-map-legend", "container": "EXTENSION", "dependsOn": [], "desc": null, "file": "tor2e-0.5-hands-map-legend.ttrpg", "guidance": [], "kind": "ttrpg", "name": "Hands of the White Wizard - Map Legend", "page": 147, "props": [], "roots": ["#tFg9suxiqd8lNSbOeXBtrB9"]}, {"file": "adversaries/", "kind": "actors", "name": "Adversaries", "page": null, "roots": ["#txS2G8xdSIIa8N6IokdR2X4", "#t8u6HGdPNa2MphoyooagB2S", "#tyri1I1C0YSc6a0lgaDMfba", "#tTcQWQzyiCvbzvBszrfqWZ3", "#t0xTQ3YVL1NgckQFBiXpwd8", "#tNEPdxJeIDn0Iwmw3m8aDrb", "#tPT2xq9wIKGQ1dqfuebZbU6", "#tBf2FTSa7gG9AFodWciv6pp", "#tNFZnhWFzOFLWiXIiGTAkRc", "#tHL0IAfH68fnIaVZ8cYxhdn", "#tkqbWk8K0sfbQeWInCmW2LH", "#t9UJV4XQfNzE4BOYiG289mQ", "#t46xqBMGCEkTLrTyAAobCjz", "#twkcFKGNaNieEoKnz6lgq0t", "#tcErS7xso6tTr1GJih6CoDV", "#tElWlKGGjJC7JD5HA04oBeG", "#tLDy0HBJ5OJkESN2F8Yzted", "#tnQAXMYVHrLsxfko0YdTQWk", "#tI1x2BruIh54zxtgiEvlyPq", "#te0zhdAuZsdnIBrKRUrBhNV", "#tGuITJbPVWfImGKUJu6Jy8c", "#tb6bfcB8cYBm1Rc2xJDHu6t"]}, {"file": "loremaster-characters/", "kind": "actors", "name": "Loremaster characters", "page": null, "roots": ["#tCLS3Jakdvobmq4RDbo3TkI", "#tlwi0zkO65dW3gxAFBrdWfe", "#tnI5soOxfgM720Whui7LKs0", "#tl2E6XWKwBvyi4XnZ320AEp", "#t3OJ6FfzBqBs0ru4lKcbrPx", "#til3ET6BzIaUeghw0sf0XMZ", "#tlANy3rAKYzeWuGiMSr9s7r", "#txQcEnuguqivxhLy3zTqYOY", "#twoA3c3k6SEV0Vq7924SRtp", "#tPjVCvJEWzXrDMUsfr9AvNg", "#tqP1syXyFNdmYbFFpP0XjH9", "#tEYR65WPzyh18cxNl6WVT5E", "#tr5Q1TIG3zKHYLuy8GnmcPE", "#t55kzO6Yxrk55EFauXX0Ot4", "#tpeeSgB8iA4YvhpP3JRYdq7", "#talyPNTJ9n9DL5d1je8Ofed", "#t9A6li9z71ISkF8tvFU7z3m", "#t3ykt1WJCAEzCnY6uBKMEvO", "#tVODwScuM37eEnFXd38LzeD", "#thKnwvX16tQ2jUO5d1K7AQV", "#t1UxUO8LtMBstuBlAgbkbVV", "#t8qXMpDzGONpdDdOffNPvkH"]}], "entities": ["#tv6SJ9aoTwWOzFRiPUOW880", "#trhzOwG5SR561o83VFZVUKV", "#tz8ibzN9UkMTUNLV7TVtSOX", "#tISoGUNZz2VE9kykXX8Ohtc", "#tt3qThmdMDDeiOEa4SfoqQ1", "#t5mXLkdNrxFIXVCfT0kUbiu", "#tYTRDNCyEPe4yv1Uy7AZqe8", "#t4tH0BF1gelfgVc1eyhWAuw", "#tFg9suxiqd8lNSbOeXBtrB9", "#txS2G8xdSIIa8N6IokdR2X4", "#t8u6HGdPNa2MphoyooagB2S", "#tyri1I1C0YSc6a0lgaDMfba", "#tTcQWQzyiCvbzvBszrfqWZ3", "#t0xTQ3YVL1NgckQFBiXpwd8", "#tNEPdxJeIDn0Iwmw3m8aDrb", "#tPT2xq9wIKGQ1dqfuebZbU6", "#tBf2FTSa7gG9AFodWciv6pp", "#tNFZnhWFzOFLWiXIiGTAkRc", "#tHL0IAfH68fnIaVZ8cYxhdn", "#tkqbWk8K0sfbQeWInCmW2LH", "#t9UJV4XQfNzE4BOYiG289mQ", "#t46xqBMGCEkTLrTyAAobCjz", "#twkcFKGNaNieEoKnz6lgq0t", "#tcErS7xso6tTr1GJih6CoDV", "#tElWlKGGjJC7JD5HA04oBeG", "#tLDy0HBJ5OJkESN2F8Yzted", "#tnQAXMYVHrLsxfko0YdTQWk", "#tI1x2BruIh54zxtgiEvlyPq", "#te0zhdAuZsdnIBrKRUrBhNV", "#tGuITJbPVWfImGKUJu6Jy8c", "#tb6bfcB8cYBm1Rc2xJDHu6t", "#tCLS3Jakdvobmq4RDbo3TkI", "#tlwi0zkO65dW3gxAFBrdWfe", "#tnI5soOxfgM720Whui7LKs0", "#tl2E6XWKwBvyi4XnZ320AEp", "#t3OJ6FfzBqBs0ru4lKcbrPx", "#til3ET6BzIaUeghw0sf0XMZ", "#tlANy3rAKYzeWuGiMSr9s7r", "#txQcEnuguqivxhLy3zTqYOY", "#twoA3c3k6SEV0Vq7924SRtp", "#tPjVCvJEWzXrDMUsfr9AvNg", "#tqP1syXyFNdmYbFFpP0XjH9", "#tEYR65WPzyh18cxNl6WVT5E", "#tr5Q1TIG3zKHYLuy8GnmcPE", "#t55kzO6Yxrk55EFauXX0Ot4", "#tpeeSgB8iA4YvhpP3JRYdq7", "#talyPNTJ9n9DL5d1je8Ofed", "#t9A6li9z71ISkF8tvFU7z3m", "#t3ykt1WJCAEzCnY6uBKMEvO", "#tVODwScuM37eEnFXd38LzeD", "#thKnwvX16tQ2jUO5d1K7AQV", "#t1UxUO8LtMBstuBlAgbkbVV", "#t8qXMpDzGONpdDdOffNPvkH"], "id": "hands", "kind": "book", "label": "Hands of the White Wizard"}, "entities": {"#t0YpSDOZRmOJ4XtWOMK67NJ": {"book": "hands", "children": [], "choices": [], "desc": "The corridor ends in a staircase that wends upward until the Player-heroes reach a narrow passage above the east gate of the Twenty-first Hall. From two tall, narrow windows, they see a large number of Orcs and Trolls smashing and hewing at a stone door on the northern wall of the hall.\n\nDirecting the assault is a terrifying Great Orc — **Gorgol, Son of Bolg**, ruler of the Orcs of Moria and lord of Mount Gundabad (see *Moria: Through the Doors of Durin*, page 54). In one hand he wields the scimitar of his grandfather Azog, a sorcerous blade forged in Carn Dûm. In the other, he tosses a small leather pouch that jingles when caught — containing a few coins of little worth, to be given to the last Dwarf alive in Moria.\n\nThe doors leading to the Chamber of Mazarbul are breaking! The Orcs bare their fangs, anticipating the slaughter to come! It’s clear that this is the last stand of the Dwarves in Moria, and that they face overwhelming odds.\n\nWhat do the Player-heroes do?\n\nIf by some miracle the Player-heroes manage to slay Gorgol, then the Orcs are thrown into disarray and terror, especially as the various Orc-chieftains who serve Gorgol start squabbling among themselves over who’s going to be the new overlord. Slaying Gorgol right at the moment of his triumph could change the course of history and save Balin’s expedition from destruction!", "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-quest-of-moria.arc", "form": "DEF", "guidance": [], "id": "#t0YpSDOZRmOJ4XtWOMK67NJ", "key": "They Are Coming!", "name": "They Are Coming!", "parent": null, "props": [{"items": [{"value": "**Attack Gorgol:** This is undeniably the most heroic action, but also the most perilous. If the Player-heroes attack Gorgol, the attention of the Orcs turns away from the doors, giving the Dwarves a chance to escape. The downside is that the Player-heroes face the full wrath of the Orcs, with little hope of survival. At best, one or two Player-heroes could remain behind to hold the passageway while the rest flee — but make no mistake, this option means the deaths of some of the Company. There’s **Gorgol** himself, two **Great Orc Bodyguards** for each Player-hero, plus *countless* **Orc Guards** (and maybe even one or more **Great Cave-trolls**).", "vk": "scalar"}, {"value": "**Aid the Dwarves:** More reasonable options include: circling around to another, more lightly defended entrance to the Twenty-first Hall, and helping the Dwarves escape through there; dividing the Orc forces once they begin their assault, or causing confusion once the doors are breached, giving the Dwarves a chance at a counterattack. There is no chance of saving the expedition as a whole, but a few Dwarves might make it out alive. If the Player-heroes choose this option, they must face one **Great Orc Bodyguard** for each Player-hero, plus a rabble of **Goblin Archers** and **Orc Soldiers** (at least one of each for every Player-hero). Defeating those foes lets a handful of Dwarves flee.", "vk": "scalar"}, {"value": "**Sneak Away:** Alas, some fates cannot be averted. Did Dáin Ironfoot not say that another power must come to Moria before it can be reclaimed by the Dwarves? Turning their backs on Balin’s expedition is potentially a Misdeed worth 3 Shadow points, but is it not better to be burdened with regret and live? After all, the Player-heroes were sent to discover the fate of the expedition, not save it…", "vk": "scalar"}], "name": "Items", "of": "STRING", "vk": "list"}], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#t0xTQ3YVL1NgckQFBiXpwd8": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "adversaries/tor2e-0.5-hands-gorgol.actor", "form": "DEF", "guidance": [], "id": "#t0xTQ3YVL1NgckQFBiXpwd8", "key": "Gorgol", "name": "Gorgol", "parent": null, "props": [{"name": "Name", "type": "STRING", "value": "Gorgol", "vk": "scalar"}, {"items": [{"value": "Bold", "vk": "scalar"}, {"value": "Cunning", "vk": "scalar"}], "name": "Distinctive Features", "of": "STRING", "vk": "list"}, {"name": "Attribute Level", "type": "INTEGER", "value": 8, "vk": "scalar"}, {"name": "Endurance", "type": "INTEGER", "value": 60, "vk": "scalar"}, {"name": "Might", "type": "INTEGER", "value": 2, "vk": "scalar"}, {"name": "Hate", "type": "INTEGER", "value": 8, "vk": "scalar"}, {"name": "Parry", "type": "STRING", "value": "+4", "vk": "scalar"}, {"name": "Armour", "type": "STRING", "value": "4", "vk": "scalar"}, {"items": [{"fields": [{"name": "Weapon", "type": "STRING", "value": "Scimitar of Azog", "vk": "scalar"}, {"name": "Rating", "type": "INTEGER", "value": 3, "vk": "scalar"}, {"name": "Damage", "type": "INTEGER", "value": 6, "vk": "scalar"}, {"name": "Injury", "type": "INTEGER", "value": 20, "vk": "scalar"}, {"items": [{"value": "Break Shield and Pierce", "vk": "scalar"}], "name": "Special Damage", "of": "STRING", "vk": "list"}, {"name": "Printed", "type": "STRING", "value": "Scimitar of Azog 3 (6/20, Break Shield and Pierce)", "vk": "scalar"}], "vk": "def"}], "name": "Combat Proficiencies", "of": "Adversary Combat Proficiency", "ofHash": "#tor5AdvCombat000001", "vk": "list"}, {"items": [{"fields": [{"name": "Name", "type": "STRING", "value": "Hatred (Dwarves)", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "All attack rolls are Favoured against Dwarves.", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Name", "type": "STRING", "value": "Hate Sunlight", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "Gorgol loses 1 Hate at the start of each round he is exposed to the full light of the sun.", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Name", "type": "STRING", "value": "Horrible Strength", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "If Gorgol scores a Piercing Blow, spend 1 Hate to make the target’s Protection roll Ill-favoured.", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Name", "type": "STRING", "value": "Snake-like Speed", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "When targeted by an attack, spend 1 Hate to make the attack roll Ill-favoured.", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Name", "type": "STRING", "value": "Yell of Triumph", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "Spend 1 Hate to restore 1 Hate to all other Orcs in the fight.", "vk": "scalar"}], "vk": "def"}], "name": "Fell Abilities", "of": "Fell Ability", "ofHash": "#tor5FellAbility0001", "vk": "list"}], "refs": [], "slot": null, "table": null, "type": "Adversary", "typeHash": "#TOR0020000000000"}, "#t1FVKSXZ73A6ZfL42p4fxbk": {"book": "hands", "children": ["#tRFySySTYybexfRSFWyg5bl"], "choices": [], "desc": null, "entries": [], "enum": null, "file": "tor2e-0.5-hands-worksheet-saruman-s-shadow-score.ttrpg", "form": "DEF", "guidance": [], "id": "#t1FVKSXZ73A6ZfL42p4fxbk", "key": "The Disaster of the Gladden Fields", "name": "The Disaster of the Gladden Fields", "parent": "#t4tH0BF1gelfgVc1eyhWAuw", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#t1UxUO8LtMBstuBlAgbkbVV": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "loremaster-characters/tor2e-0.5-hands-urien-blackthorn.actor", "form": "DEF", "guidance": [], "id": "#t1UxUO8LtMBstuBlAgbkbVV", "key": "Urien Blackthorn", "name": "Urien Blackthorn", "parent": null, "props": [{"name": "Name", "type": "STRING", "value": "Urien Blackthorn", "vk": "scalar"}, {"name": "Occupation", "type": "STRING", "value": "Warleader", "vk": "scalar"}, {"items": [{"value": "Cautious", "vk": "scalar"}, {"value": "Loyal", "vk": "scalar"}], "name": "Distinctive Features", "of": "STRING", "vk": "list"}, {"name": "Location", "type": "STRING", "value": "The Black Ship Unveiled", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "Urien is the leader of the Dunlending soldiers. A dour old warrior, he believes the whole expedition is doomed. His eyes are sharp and cautious, his words few. Though he considers the mission risky, he is determined to see it through. He never discusses the orders of Saruman, the White Hand.", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Loremaster Character", "typeHash": "#TOR0030000000000"}, "#t1nEAhd4VKXyIEHIBbMsXky": {"book": "hands", "children": [], "choices": [], "desc": "The Hall of Trophies gleams with the promise of treasure. As soon as the Corsair rowers see this, they fall to their knees and start grabbing handfuls of coins and other trophies. Smelling trouble, the Lord of the Lash cracks his whip and restores order, in time to avoid the collapse. In the confusion, a disguised Player-hero or two could (with a **STEALTH** roll) slip by into the tomb beyond.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-there-let-them-lie-until-the-end.arc", "form": "DEF", "guidance": [], "id": "#t1nEAhd4VKXyIEHIBbMsXky", "key": "Looting the Hall of Trophies", "name": "Looting the Hall of Trophies", "parent": null, "props": [], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#t2AP0rtPW3EPKTzT8XKAEFB": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [{"fields": [{"name": "Shadow", "type": "INTEGER", "value": 10, "vk": "scalar"}], "name": "The Player-heroes refuse the quest", "vk": "def"}], "enum": null, "file": "tor2e-0.5-hands-worksheet-saruman-s-shadow-score.ttrpg", "form": "DEF", "guidance": [], "id": "#t2AP0rtPW3EPKTzT8XKAEFB", "key": "The Ithil-stone Shadow Score", "name": "The Ithil-stone Shadow Score", "parent": "#tCdNX4pnNaR79xoMwjAixSq", "props": [], "refs": [], "slot": null, "table": {"columns": ["Trigger", "Shadow", "Tally"], "rows": [["The Player-heroes refuse the quest", "+10", ""]]}, "type": "Table", "typeHash": "#tor5Table0000000001"}, "#t3OJ6FfzBqBs0ru4lKcbrPx": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "loremaster-characters/tor2e-0.5-hands-caelur-the-minstrel.actor", "form": "DEF", "guidance": [], "id": "#t3OJ6FfzBqBs0ru4lKcbrPx", "key": "Caelur the Minstrel", "name": "Caelur the Minstrel", "parent": null, "props": [{"name": "Name", "type": "STRING", "value": "Caelur the Minstrel", "vk": "scalar"}, {"name": "Occupation", "type": "STRING", "value": "Minstrel, Spy", "vk": "scalar"}, {"items": [{"value": "Inquisitive", "vk": "scalar"}, {"value": "Subtle", "vk": "scalar"}], "name": "Distinctive Features", "of": "STRING", "vk": "list"}, {"name": "Location", "type": "STRING", "value": "A Not-So-Chance Meeting", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "Caelur hails originally from the Vales of Anduin. She left those lands behind long ago and went a-wandering, but in certain lights she has the fox-like wariness of the Woodmen of Mirkwood. She’s always quick to smile, but the smile rarely reaches her dark eyes. She’s travelled all over Rohan and Gondor, and has sung before King Thengel in his golden hall.\n\nIn truth, Caelur is another agent of Saruman; the White Wizard told her to watch and test the Player-heroes, as they have not yet proven themselves to his satisfaction. (If the Player-heroes suspect she is a servant of evil and threaten to attack her, she shows them a letter she keeps inside her psaltery bearing the sigil of Saruman, proving that she too is in the service of Isengard, but otherwise she conceals her true allegiance).", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Loremaster Character", "typeHash": "#TOR0030000000000"}, "#t3tYogiEVzRgh28h5MuQAeU": {"book": "hands", "children": [], "choices": [], "desc": "The tomb is too cramped for more than one Player-hero to fight the beast at any one time. Extra Player-heroes can fit in, but *all* of them *lose (1d)* on attack rolls for each additional combatant in the fight. So, if three Player-heroes try to battle the beast in the confined tomb, they all *lose (2d)* on their attack rolls. (Hobbits don’t contribute towards the total).\n\nThe beast won’t leave the tomb during daylight, but can be lured out at night with the right bait — like a juicy sheep, or a Dunlending.\n\nIf Toirlas and his company are present, then they let the Player-heroes go in first — but Toirlas waits by the entrance, looking for a chance to join the fray at just the right moment to strike the killing blow.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-beast-of-dunland.arc", "form": "DEF", "guidance": [], "id": "#t3tYogiEVzRgh28h5MuQAeU", "key": "Battling the Monster in Its Lair", "name": "Battling the Monster in Its Lair", "parent": null, "props": [], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#t3ykt1WJCAEzCnY6uBKMEvO": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "loremaster-characters/tor2e-0.5-hands-sellic.actor", "form": "DEF", "guidance": [], "id": "#t3ykt1WJCAEzCnY6uBKMEvO", "key": "Sellic", "name": "Sellic", "parent": null, "props": [{"name": "Name", "type": "STRING", "value": "Sellic", "vk": "scalar"}, {"name": "Occupation", "type": "STRING", "value": "Minstrel", "vk": "scalar"}, {"items": [{"value": "Fair-spoken", "vk": "scalar"}, {"value": "Secretive", "vk": "scalar"}], "name": "Distinctive Features", "of": "STRING", "vk": "list"}, {"name": "Location", "type": "STRING", "value": "Locations", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "Young Sellic is a talented singer; there is a special gift of music and song for those born along this shore. In another life, in another land, Sellic might have become a bard for lords and kings, but there are no kings on the sea any more. Here in Todden, he sings songs of surpassing beauty to entertain fishermen and seamstresses who would be equally entertained if he belched the tune.\n\nSellic dreams of leaving Todden, but he’s no adventurer — he fears to travel alone in the Wild.\n\nAs the most courteous and sophisticated of the Fisherfolk, it’s Sellic who goes to speak with strangers. INSIGHT picks up that Sellic’s suave demeanour conceals inner nervousness, especially around Elves, and that he’s not half as clever or worldly as he pretends to be.", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Loremaster Character", "typeHash": "#TOR0030000000000"}, "#t46xqBMGCEkTLrTyAAobCjz": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "adversaries/tor2e-0.5-hands-ringwraith.actor", "form": "DEF", "guidance": [], "id": "#t46xqBMGCEkTLrTyAAobCjz", "key": "Ringwraith", "name": "Ringwraith", "parent": null, "props": [{"name": "Name", "type": "STRING", "value": "Ringwraith", "vk": "scalar"}, {"items": [{"value": "Merciless", "vk": "scalar"}, {"value": "Proud", "vk": "scalar"}], "name": "Distinctive Features", "of": "STRING", "vk": "list"}, {"name": "Attribute Level", "type": "INTEGER", "value": 7, "vk": "scalar"}, {"name": "Endurance", "type": "INTEGER", "value": 60, "vk": "scalar"}, {"name": "Might", "type": "INTEGER", "value": 2, "vk": "scalar"}, {"name": "Hate", "type": "INTEGER", "value": 7, "vk": "scalar"}, {"name": "Parry", "type": "STRING", "value": "—", "vk": "scalar"}, {"name": "Armour", "type": "STRING", "value": "3", "vk": "scalar"}, {"items": [{"fields": [{"name": "Weapon", "type": "STRING", "value": "Long Sword", "vk": "scalar"}, {"name": "Rating", "type": "INTEGER", "value": 3, "vk": "scalar"}, {"name": "Damage", "type": "INTEGER", "value": 5, "vk": "scalar"}, {"name": "Injury", "type": "INTEGER", "value": 18, "vk": "scalar"}, {"items": [{"value": "Pierce", "vk": "scalar"}], "name": "Special Damage", "of": "STRING", "vk": "list"}, {"name": "Printed", "type": "STRING", "value": "Long Sword 3 (5/18, Pierce)", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Weapon", "type": "STRING", "value": "Black Dart", "vk": "scalar"}, {"name": "Rating", "type": "INTEGER", "value": 3, "vk": "scalar"}, {"name": "Damage", "type": "INTEGER", "value": 4, "vk": "scalar"}, {"name": "Injury", "type": "INTEGER", "value": 16, "vk": "scalar"}, {"items": [{"value": "Pierce", "vk": "scalar"}], "name": "Special Damage", "of": "STRING", "vk": "list"}, {"name": "Printed", "type": "STRING", "value": "Black Dart 3 (4/16, Pierce)", "vk": "scalar"}], "vk": "def"}], "name": "Combat Proficiencies", "of": "Adversary Combat Proficiency", "ofHash": "#tor5AdvCombat000001", "vk": "list"}, {"items": [{"fields": [{"name": "Name", "type": "STRING", "value": "Black Breath", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "At the start of the first round of the battle, all Player-heroes near one or more Ringwraiths gain 4 Shadow points (Dread). The VALOUR roll is Ill-favoured while in darkness. Those who fail their Shadow test fall unconscious for the rest of the fight. A successful HEALING roll from another Player-hero (who must spend their main action to do so) revives the target, who is daunted and cannot spend Hope for the rest of the fight. If the Shadow test failed with an [Eye of Sauron] , then the Player-hero has been stricken by the Black Shadow (see box).", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Name", "type": "STRING", "value": "Deadly Voice", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "Once per round, spend 1 Hate to make all Player-heroes in sight gain 2 Shadow points (Dread). The VALOUR roll is Ill-favoured while in darkness. Those who fail their Shadow test or are Miserable are daunted and cannot spend Hope for the rest of the fight. Those who fail their Shadow test and are Miserable suffer the same effects as failing the Shadow test against the Black Breath (see above).", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Name", "type": "STRING", "value": "Dwimmerlaik", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "The Ringwraith is immune to Endurance loss and Wounds from all sources of injury except fire and magical weapons, and can spend 1 Hate to cancel a Wound from such weapons (unless they have been wrought for the Bane of the Undead). When an attack inflicts damage to the Ringwraith that would cause it to go to zero Endurance, it causes a Piercing Blow instead. Then, if the Ringwraith is still alive, its Endurance score is set back at half its maximum rating.", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Name", "type": "STRING", "value": "Fear of Fire", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "The creature loses 1 Hate at the start of each round it is engaged in close combat with an adversary wielding a torch or other sort of burning item.", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Name", "type": "STRING", "value": "Hate Sunlight", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "The creature loses 1 Hate at the start of each round if it is exposed to the full light of the sun.", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Name", "type": "STRING", "value": "Heartless", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "The creature is not affected by the Intimidate Foes combat task, unless a Magical success is obtained.", "vk": "scalar"}], "vk": "def"}], "name": "Fell Abilities", "of": "Fell Ability", "ofHash": "#tor5FellAbility0001", "vk": "list"}, {"name": "Description", "type": "STRING", "value": "*“Nine (rings) he gave to Mortal Men, proud and great, and so ensnared them. Long ago they fell under the dominion of the One, and they became Ringwraiths, shadows under his great Shadow, his most terrible servants.”*", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Adversary", "typeHash": "#TOR0020000000000"}, "#t4NY9AKVE56II4EXWo5gCGI": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [{"fields": [], "name": "* Note that Saruman as a Patron was originally presented in *Ruins of the Lost Realm*. That version gives a different (and more powerful) advantage compared to the one described in this book. Since this campaign focuses on Saruman’s patronage, it is recommended to use this version of the Patron for the adventures presented here.", "vk": "def"}], "enum": null, "file": "tor2e-0.5-hands-introduction.ttrpg", "form": "DEF", "guidance": [], "id": "#t4NY9AKVE56II4EXWo5gCGI", "key": "Additional Advantage", "name": "Additional Advantage", "parent": "#tdjfCMCvCSACYpLTAdEXypq", "props": [{"name": "Note", "type": "STRING", "value": "*The Voice of Wisdom* At the start of each Adventuring Phase, the Company chooses three Skills, which remain the same until the start of the next Fellowship Phase. You can spend Fellowship points to obtain a Magical Success with the chosen Skills. Additionally, at the end of a Council you can spend a number of Fellowship points to add an equal number of successes to its outcome.*", "vk": "scalar"}], "refs": [], "slot": null, "table": {"columns": ["AGENDA: Study the arts of the Enemy, research Ring-lore, defeat the Dark Lord."], "rows": [["* Note that Saruman as a Patron was originally presented in *Ruins of the Lost Realm*. That version gives a different (and more powerful) advantage compared to the one described in this book. Since this campaign focuses on Saruman’s patronage, it is recommended to use this version of the Patron for the adventures presented here."]]}, "type": "Table", "typeHash": "#tor5Table0000000001"}, "#t4ca0dPzLyI2Ao6bQdFa6ou": {"book": "hands", "children": [], "choices": [], "desc": "One of the joys of playing *The One Ring* is getting to interact with characters like Gandalf or Aragorn. Bringing important characters from the books into the game carries a degree of peril — not only do the players bring strong preconceptions about how that character ‘should’ behave, but the very nature of the game means there’s no chance for a second draft or judicious edit if something goes amiss.\n\n**Loremaster (to the players):*** The Wizard Saruman stands before you, clad in shimmering white.* **Player:*** Galar bows before him.* **Loremaster (as Saruman):*** Nah, stand, master Dwarf. You have had a long journey from… *(the Loremaster’s mind goes blank — what’s the name of the Dwarf place again?)*… from… *\n\n*from… Eregion. Eriador. Ah, ****. Erebor!* **Player:*** It’s Saruman the Senile!*\n\nHere are listed a few techniques to avoid such calamities:", "entries": [], "enum": null, "file": "tor2e-0.5-hands-introduction.ttrpg", "form": "DEF", "guidance": [{"concerns": [{"hash": "#t4ca0dPzLyI2Ao6bQdFa6ou", "name": "Roleplaying Saruman"}], "id": "#tTeNqrZqg3N6fC1PRFq2rqR", "name": "Interweaving Other Adventures", "text": "Our assumption here is that the Player-heroes do not reside permanently in Isengard, nor are all their days taken up in the service of Saruman. Instead, they are infrequently summoned when the Wizard has need of them — there can be gaps of a decade or more between adventures. That means Loremasters can interweave other adventures (and, indeed, other campaigns!) with this one. The Player-heroes might be Rangers fighting to defend the Free Folk of the North, or wandering adventurers in Eriador or Rhovanion, or explorers in the ruins of Moria in between these adventures.\n\nA Loremaster intending to interweave adventures should carefully read ahead in this supplement and look for places where other plots might clash with the material presented therein. If the supplement is used on its own, there may be extensive downtime between adventures, allowing the players the freedom to narrate what their heroes do when not serving Saruman.", "topics": []}], "id": "#t4ca0dPzLyI2Ao6bQdFa6ou", "key": "Roleplaying Saruman", "name": "Roleplaying Saruman", "parent": "#tu6xvtsz0RGddvPh1RmG6Ld", "props": [{"items": [{"value": "**Use Intermediaries:** Instead of having the Player-heroes regularly meet Saruman directly, have him send messengers. Have him write letters that you can prepare in advance. Have Loremaster characters refer to him instead of having the Player-heroes meet him directly. Imagine that your campaign is a television series, and Saruman is a hugely expensive special guest star you can only afford to bring on screen when it’s absolutely critical.", "vk": "scalar"}, {"value": "**Let the Players Fill In Details:** Instead of speaking in character, try describing conversations or prompting the players. For example, instead of playing Saruman as he greets Galar the Dwarf, the Loremaster could turn to Galar’s player and say: *“Saruman greets you in the secret tongue of the Dwarves — what wise words does he have for you in the hour of your meeting?”*", "vk": "scalar"}, {"value": "**Play on Backstories and Shadow Flaws:** Saruman has supernatural insight into the personalities and thoughts of the Player-heroes. Assume he knows their hidden secrets and subconscious motivations. In particular, look at the Shadow Flaws for each Player-hero’s Calling; even if the hero has yet to acquire any Shadow Flaws, the potential for such behaviour is there, and Saruman can play on it. You can even have Saruman know secrets that the Player-heroes don’t know themselves. For example, if you’re using the Heroic Lineage plotline from *Tales from the Lone-Lands*, then Saruman might know that a Player-hero is the heir to the hero of old long before the player discovers this themselves…", "vk": "scalar"}, {"value": "**Co-opt the Players:** Ask the players questions directly to help you set the scene. For example, you might say ‘the White Wizard fixes you with a piercing gaze, and you feel like he can see right through you, to your deepest, most hidden secret. What do you fear Saruman knows about you?’", "vk": "scalar"}, {"value": "**Be Helpful:** Players are much better disposed to characters who help them. Especially in the early stages of the campaign, be generous with minor boons like Useful Items or other gear. If a player has a clever idea, then have Saruman agree and support that plan instead of overruling them.", "vk": "scalar"}, {"value": "**Script Scenes:** Write out lines of dialogue, short speeches and answers to likely questions in advance. You can even adapt lines from the book!", "vk": "scalar"}, {"value": "**Challenge the Players:** The White Wizard needs followers who can gather information, assess threats and make decisions — sometimes hard ones. If the players express doubt at the difficulty of a mission, or expect the Wizard to have all the answers at all times, have Saruman remind them that he selected them because of their intelligence and courage, and that he trusts them to act on their own initiative.", "vk": "scalar"}], "name": "Items", "of": "STRING", "vk": "list"}], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#t4tH0BF1gelfgVc1eyhWAuw": {"book": "hands", "children": ["#tkzG1FdwMCe3MPe5QNOqLI9", "#tacqhIkqLkxHyp4COBTNEbn", "#t1FVKSXZ73A6ZfL42p4fxbk", "#tpJlHhqZkg9A5XXth6GJn5l", "#tlona8YOY48U8Xm0NFaScgP", "#tCdNX4pnNaR79xoMwjAixSq"], "choices": [], "desc": null, "entries": [], "enum": null, "file": "tor2e-0.5-hands-worksheet-saruman-s-shadow-score.ttrpg", "form": "DEF", "guidance": [], "id": "#t4tH0BF1gelfgVc1eyhWAuw", "key": "Saruman’s Shadow Score", "name": "Saruman’s Shadow Score", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#t4xGhgzU1PTvzRUZqrHDFaw": {"book": "hands", "children": [], "choices": [], "desc": "When Orthanc was shut, the Lord of Isengard dwelt in a house of stone, a mansion more suited to the reduced importance of the fortress. Today, the house is occupied by the Captain of the Guard of Isengard. The house is chiefly notable for the grand stone fireplace in the main hall, and the chimney above; chimneys are unknown to the simple folk of Rohan and Dunland, and to have such a large fire inside the hall without choking or blinding the guests secured the reputation of the Lord of Isengard as a magician.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-introduction.ttrpg", "form": "DEF", "guidance": [], "id": "#t4xGhgzU1PTvzRUZqrHDFaw", "key": "4. Captain’s House", "name": "4. Captain’s House", "parent": "#tcMxywq75NOL2ves69gurzl", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#t55kzO6Yxrk55EFauXX0Ot4": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "loremaster-characters/tor2e-0.5-hands-minon-the-ranger.actor", "form": "DEF", "guidance": [], "id": "#t55kzO6Yxrk55EFauXX0Ot4", "key": "Minon the Ranger", "name": "Minon the Ranger", "parent": null, "props": [{"name": "Name", "type": "STRING", "value": "Minon the Ranger", "vk": "scalar"}, {"name": "Occupation", "type": "STRING", "value": "Ranger", "vk": "scalar"}, {"items": [{"value": "Loyal", "vk": "scalar"}, {"value": "Wary", "vk": "scalar"}], "name": "Distinctive Features", "of": "STRING", "vk": "list"}, {"name": "Description", "type": "STRING", "value": "A Troll on the Trollshaws broke Minon’s leg, and he has carried a limp ever since. Frostbite once claimed two fingers from his left hand. Still, Minon remains committed to his oath to defend the Free Folk of Eriador. Some call him ill-favoured by luck — he only hopes to live long enough to see the king restored.\n\nOptionally, if the players have gone through *Tales From the Lone-lands*, consider replacing Minon with Orothel the Ranger — Minon’s plight becomes more meaningful if the wounded Ranger is an old friend of the Company.", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Loremaster Character", "typeHash": "#TOR0030000000000"}, "#t56LRMyUrq2X6RxIjkeXzNI": {"book": "hands", "children": [], "choices": [], "desc": "Toirlas’ return is met with cheers from the folk of Crow Hall, and quiet smiles from Dunrach and Dunwalla. Vila greets her older brother with a hug. If Gorsad has been healed of his gout, he rises and embraces his son; otherwise, he tries to rise from his seat, but the pain is too much and he falls back.\n\nOne of the stolen sheep is killed and roasted, and there is a grand feast in the Hall. Toirlas enthusiastically boasts that he’ll kill the monster when it next shows its ugly face, then tells the tale of his raid on Sigulf’s stead. Gorsad mutters about restraint and not engaging in pointless violence, but no-one listens. If Gorsad is cured, he speaks much more forcefully, telling his son that it would be better to deal with the beast instead of causing trouble for others.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-beast-of-dunland.arc", "form": "DEF", "guidance": [], "id": "#t56LRMyUrq2X6RxIjkeXzNI", "key": "The Homecoming of Toirlas", "name": "The Homecoming of Toirlas", "parent": null, "props": [], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#t5PtQ4YXJ9wM1vxIDL4h5J8": {"book": "hands", "children": [], "choices": [], "desc": "If he suspects the Player-heroes of being a threat to him or the Prince, Sellic takes action against them. There are three possible ways for this scheme to play out.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-sea-prince-of-the-shore.arc", "form": "DEF", "guidance": [], "id": "#t5PtQ4YXJ9wM1vxIDL4h5J8", "key": "Sellic’s Song", "name": "Sellic’s Song", "parent": null, "props": [{"items": [{"value": "If the Player-heroes are sleeping in or near Todden, then he plays a soothing song on the flute to lull any of them who are on watch into slumber. The Player-hero on watch must attempt a **WISDOM** roll; if the roll fails, they fall asleep. If the **WISDOM** roll is successful, they gain 1 point of Fatigue but stay awake. Elves are immune to this magic. If all Player-heroes are sleeping, then Sellic and the Prince’s guards capture them without a fight (see *Prisoners of the Prince*, on page 54).", "vk": "scalar"}, {"value": "If the Player-heroes are in the tavern, Sellic could stir up the fears and prejudices of the people of Todden with a violent, war-like tune. The fisher-folk present little threat to hardened adventurers — Sellic’s goal here is to force the Player-heroes to fight back, injuring some of the locals and forcing Cradoc to send his sons to deal with them.", "vk": "scalar"}, {"value": "The third option is for Sellic to go to the Prince directly to warn him of the strangers from Isengard.", "vk": "scalar"}], "name": "Items", "of": "STRING", "vk": "list"}], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#t5mXLkdNrxFIXVCfT0kUbiu": {"book": "hands", "children": ["#trrsIsdiZhun8EZ0hfQu1yy", "#tyvTftqCa4y4SeCHmaUAT3A", "#tPExYVVfffbh9WRrROyQfid", "#tmEPsmd9yzwujvUDreCjgyc", "#tykyYOIjLQ8uC9haE6KYbFV", "#tcMxywq75NOL2ves69gurzl", "#tKxDnQmGjaye3G8q8eX33MP"], "choices": [], "desc": "*— The Two Towers™*", "entries": [], "enum": null, "file": "tor2e-0.5-hands-introduction.ttrpg", "form": "DEF", "guidance": [], "id": "#t5mXLkdNrxFIXVCfT0kUbiu", "key": "Isengard", "name": "Isengard", "parent": null, "props": [{"name": "Epigraph", "type": "STRING", "value": "Partly it was shaped in the making of the mountains, but mighty works the Men of Westernesse had wrought there of old; and Saruman had dwelt there long and had not been idle.", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#t5xZuLwtFQZcV29V8Xh7kkK": {"book": "hands", "children": ["#tNZWrRIk1IbzXlHF1lHvc8P"], "choices": [], "desc": "Saruman is known throughout the land as a peerless scholar and mighty Wizard. He was the head of the White Council while it lasted, and he is still considered the *de facto* leader of any coalition of the Wise. Although others may disagree with his methods or plans, his loyalty and purpose remain unquestioned.\n\nSaruman has the singular advantage of dwelling in a place that is easy to find, instead of living in a hidden valley or wandering about. If the Player-heroes need to consult a lore-master, especially about some device of the Enemy, or if they need healing, then they might seek out Saruman in Isengard (see page 12). The White Wizard does not have time to waste, and the gates of his fortress do not open to every traveller — but Saruman is keen-sighted, and therefore would aid the Player-heroes in exchange for the promise of future service.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-introduction.ttrpg", "form": "DEF", "guidance": [], "id": "#t5xZuLwtFQZcV29V8Xh7kkK", "key": "Seeking Saruman’s Aid", "name": "Seeking Saruman’s Aid", "parent": "#tt3qThmdMDDeiOEa4SfoqQ1", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#t60PPdmpIZb4XmW1p4Ej9JQ": {"book": "hands", "children": [], "choices": [], "desc": "Baugrim and his company arrive at the Sixteenth Hall, guided by Moria scouts from the East-gate. The tension between the two Orc factions is obvious — the scrawnier, more feral Moria-orcs bristle and snarl at the well-equipped, well-disciplined Orcs from Mordor, while the Uruks would like nothing more than for Baugrim to permit them to teach these mountain-maggots a lesson. Baugrim, though, is much more diplomatic and cunning than most Orcs. He argues that “the Big Push” — the war for control of Middle-earth — is coming soon now that *“Lugbúrz is looking west again,”* and that ambitious, sensible Orcs of Moria would be best served by pleasing the Eye and handing over any “war materiel or other treasures” they might have come across.\n\nIf present, Redtooth is displeased at being threatened in his own hall — but for the Orcs of Dol Guldur to take such action means there’s more at stake here than he first guessed. He tries to stall the Uruks, arguing that they’re in *his* hall and that they should pay him more respect, instead of demanding he hand over his prizes before he’s even counted them. Baugrim brings forth the chest of tribute — and when Redtooth bounds over to inspect it, Baugrim grabs Redtooth’s arm with a taloned hand and whispers in his ear. Redtooth immediately orders his Orcs to bring out everything they took from the House of Chimneys. (The Player-heroes can’t hear what Baugrim says, but he’s warning Redtooth that there’s a Ringwraith lurking on the threshold…)\n\nUnless stopped, Baugrim’s Uruks collect the loot from the House of Chimneys and depart.\n\nAt any point, the Player-heroes may intervene — they might take advantage of the distraction caused by Baugrim’s arrival, sow discord between the two Orc-bands, or ambush Baugrim as he leaves.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-disaster-of-the-gladden-fields.arc", "form": "DEF", "guidance": [], "id": "#t60PPdmpIZb4XmW1p4Ej9JQ", "key": "An Unexpected and Dreadful Party", "name": "An Unexpected and Dreadful Party", "parent": null, "props": [], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#t6VZCK8w77yjBbArpYw7YgC": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [{"fields": [{"name": "Event", "type": "STRING", "value": "Glimpse of Giants: In the distance, the Player-heroes see what might be a lone tree, immensely tall but almost leafless as if autumn has found it early — and then, it turns and lopes away, vanishing into the mist, never to be seen again.", "vk": "scalar"}], "name": "1", "vk": "def"}, {"fields": [{"name": "Event", "type": "STRING", "value": "Laughing Spirits of the Mire: While passing through a marshy region on the banks of the Isen, the Player-heroes hear laughter nearby. They never see anything, but they hear merry voices (speaking a very archaic form of Elvish), and see footprints appearing in the mud as if invisible creatures are nearby. These spirits, whatever they are, are mischievous but not dangerous, and run away laughing if threatened.", "vk": "scalar"}], "name": "2", "vk": "def"}, {"fields": [{"name": "Event", "type": "STRING", "value": "Dancing Stones: The Player-heroes come upon a circle of standing stones, and in the undergrowth nearby are more carved stones, these ones like the statues of the Púkel-men near Dunharrow in Rohan: *“carved in the likeness of men, * *huge and clumsy-limbed, squatting cross-legged with their stumpy arms folded on fat bellies. Some in the wearing * *of the years had lost all features save the dark holes of their eyes that still stared sadly at the passers-by.”* At night, when no one is around, the standing stones move, grinding across the ground to take the spot recently occupied by another of its companions, dancing an intricate dance.", "vk": "scalar"}], "name": "3", "vk": "def"}, {"fields": [{"name": "Event", "type": "STRING", "value": "Field of Butterflies: The Player-heroes behold what looks like a field of brightly coloured flowers, stretching to the horizon in all directions — but when disturbed, the flowers take flight as hundreds of thousands of butterflies flit into the sky.", "vk": "scalar"}], "name": "4", "vk": "def"}, {"fields": [{"name": "Event", "type": "STRING", "value": "Ghost Forest: When the Player-heroes wake, they have the strange impression that they’re in the middle of a forest. Spectral trees of mist have appeared all around them, the ghost of the great forest that once grew here. A breath of wind — or the touch of an iron axe — drives these phantoms away.", "vk": "scalar"}], "name": "5", "vk": "def"}, {"fields": [{"name": "Event", "type": "STRING", "value": "Huge Snail: The Player-heroes encounter a gigantic snail, as big as a hill. There’s what looks like a small stone cottage atop its shell, but the cottage is long abandoned and empty. The snail is not hostile, but slowly slithers away across the plains.", "vk": "scalar"}], "name": "6", "vk": "def"}], "enum": null, "file": "tor2e-0.5-hands-the-sea-prince-of-the-shore.arc", "form": "DEF", "guidance": [], "id": "#t6VZCK8w77yjBbArpYw7YgC", "key": "Wonders of Enedwaith", "name": "Wonders of Enedwaith", "parent": null, "props": [], "refs": [], "slot": "SCENE", "table": {"columns": ["SUCCESS DIE", "EVENT"], "rows": [["1", "Glimpse of Giants: In the distance, the Player-heroes see what might be a lone tree, immensely tall but almost leafless as if autumn has found it early — and then, it turns and lopes away, vanishing into the mist, never to be seen again."], ["2", "Laughing Spirits of the Mire: While passing through a marshy region on the banks of the Isen, the Player-heroes hear laughter nearby. They never see anything, but they hear merry voices (speaking a very archaic form of Elvish), and see footprints appearing in the mud as if invisible creatures are nearby. These spirits, whatever they are, are mischievous but not dangerous, and run away laughing if threatened."], ["3", "Dancing Stones: The Player-heroes come upon a circle of standing stones, and in the undergrowth nearby are more carved stones, these ones like the statues of the Púkel-men near Dunharrow in Rohan: *“carved in the likeness of men, * *huge and clumsy-limbed, squatting cross-legged with their stumpy arms folded on fat bellies. Some in the wearing * *of the years had lost all features save the dark holes of their eyes that still stared sadly at the passers-by.”* At night, when no one is around, the standing stones move, grinding across the ground to take the spot recently occupied by another of its companions, dancing an intricate dance."], ["4", "Field of Butterflies: The Player-heroes behold what looks like a field of brightly coloured flowers, stretching to the horizon in all directions — but when disturbed, the flowers take flight as hundreds of thousands of butterflies flit into the sky."], ["5", "Ghost Forest: When the Player-heroes wake, they have the strange impression that they’re in the middle of a forest. Spectral trees of mist have appeared all around them, the ghost of the great forest that once grew here. A breath of wind — or the touch of an iron axe — drives these phantoms away."], ["6", "Huge Snail: The Player-heroes encounter a gigantic snail, as big as a hill. There’s what looks like a small stone cottage atop its shell, but the cottage is long abandoned and empty. The snail is not hostile, but slowly slithers away across the plains."]]}, "type": "Table", "typeHash": "#tor5Table0000000001"}, "#t6YiTOCzvfKGAY2EbunEWNO": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [{"fields": [{"name": "Shadow", "type": "STRING", "value": "+1/2/3", "vk": "scalar"}], "name": "Fixed amount", "vk": "def"}, {"fields": [{"name": "Shadow", "type": "INTEGER", "value": 1, "vk": "scalar"}], "name": "The Player-heroes committed Misdeeds collectively worth 4 Shadow points or more", "vk": "def"}, {"fields": [{"name": "Shadow", "type": "INTEGER", "value": 1, "vk": "scalar"}], "name": "The Player-heroes fail to discover the origin of the Sea-prince", "vk": "def"}, {"fields": [{"name": "Shadow", "type": "INTEGER", "value": 2, "vk": "scalar"}], "name": "Gildor falls into the hands of the Númenóreans", "vk": "def"}, {"fields": [{"name": "Shadow", "type": "INTEGER", "value": 1, "vk": "scalar"}], "name": "The Player-heroes bring Saruman the Sea-prince’s blue ring", "vk": "def"}], "enum": null, "file": "tor2e-0.5-hands-worksheet-saruman-s-shadow-score.ttrpg", "form": "DEF", "guidance": [], "id": "#t6YiTOCzvfKGAY2EbunEWNO", "key": "The Sea-prince of the Shore Shadow Score", "name": "The Sea-prince of the Shore Shadow Score", "parent": "#tacqhIkqLkxHyp4COBTNEbn", "props": [], "refs": [], "slot": null, "table": {"columns": ["Trigger", "Shadow", "Tally"], "rows": [["Fixed amount", "+1/2/3", ""], ["The Player-heroes committed Misdeeds collectively worth 4 Shadow points or more", "+1", ""], ["The Player-heroes fail to discover the origin of the Sea-prince", "+1", ""], ["Gildor falls into the hands of the Númenóreans", "+2", ""], ["The Player-heroes bring Saruman the Sea-prince’s blue ring", "+1", ""]]}, "type": "Table", "typeHash": "#tor5Table0000000001"}, "#t6bKeB4hnomDGMtaFdLYgSW": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-beast-of-dunland.arc", "form": "DEF", "guidance": [], "id": "#t6bKeB4hnomDGMtaFdLYgSW", "key": "Old Lore", "name": "Old Lore", "parent": null, "props": [], "refs": [], "slot": "PHASE", "table": null, "type": null, "typeHash": null}, "#t6kos2scs41cWKv6Au7s6fQ": {"book": "hands", "children": [], "choices": [], "desc": "This avenue is lined with beautiful old elm trees. The progenitors of these trees, it is said, were planted by the King when Isengard was first built, and the present guardians of the path have grown tall and strong. The Road of Elms runs from Orthanc to the gate.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-introduction.ttrpg", "form": "DEF", "guidance": [], "id": "#t6kos2scs41cWKv6Au7s6fQ", "key": "3. The Road of Elms", "name": "3. The Road of Elms", "parent": "#tcMxywq75NOL2ves69gurzl", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#t74k6w0QD0NMcmYyVrOsNxa": {"book": "hands", "children": [], "choices": [], "desc": "The steep slopes of Methedras, the last peak of the Misty Mountains, guard the northern approaches to Isengard. The mountain is treacherous, and many have met their end trying to cross that rocky terrain. In years gone by, the Gondorian garrison cut a secret stair in the rock, zig-zagging up the slope. Their craft is such that the steps can only be seen when one is close to them; from a distance, they blend into the rock face.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-introduction.ttrpg", "form": "DEF", "guidance": [], "id": "#t74k6w0QD0NMcmYyVrOsNxa", "key": "9. The Mountain-stair", "name": "9. The Mountain-stair", "parent": "#tcMxywq75NOL2ves69gurzl", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#t7IwWSDnfXmDoaEEmE0fXDF": {"book": "hands", "children": [], "choices": [], "desc": "The river slows and broadens, and the eastern horizon seems to glimmer under the sun. This is the great confluence of the Entwash and the Anduin, the inland delta that makes the fens of Rohan. Small islands of mud and weeds appear in the water, mounds of silt anchored with greenery, until it looks as though the river has split into a thousand thousand channels. These are the Mouths of Entwash, the gateway to the fens of Wetwang.\n\nJust before the Entwash becomes a watery labyrinth, there is a small town and a mighty stone jetty attached to a crumbling fortress, built in ancient days when this was the Gondorian province of Calenardhon. Now the green flag and white horse fly over the towers, and the fort is called Walburg. The Player-heroes may disembark here and take the road, or follow the river into the perilous marshes.\n\nEast of the fort, the landscape becomes beautiful but desolate. There’s no sign of any habitation, no signs of Elf or mortal at all save rare glimpses of hunters and trappers who seek the birds and eels that live here in great numbers.\n\nNavigating the Wetwang is difficult — what seems like a wide stream can suddenly soak away into the soil, leaving the boat entangled or trapped in the mud. Three **EXPLORE** rolls are needed; failure causes each Player-hero to gain 1 Fatigue, as they toil to pull the boat out of the mud, while a failure with an [Eye of Sauron] means the boat is caught inextricably and must be abandoned.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-ithil-stone.arc", "form": "DEF", "guidance": [], "id": "#t7IwWSDnfXmDoaEEmE0fXDF", "key": "The Wetwang", "name": "The Wetwang", "parent": null, "props": [], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#t7TX6IaVDquaWu1z2sfbuUU": {"book": "hands", "children": [], "choices": [], "desc": "Horrors lurk in the shadows of the Morgul Vale. Player-heroes sneaking through the rocky slopes above the Morgul-road risk encountering strange creatures. These are lesser perils, but may still cause delay or injury. Roll a Success die or choose one entry from the Morgul Vale Encounters table.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-ithil-stone.arc", "form": "DEF", "guidance": [], "id": "#t7TX6IaVDquaWu1z2sfbuUU", "key": "Terrors of the Vale", "name": "Terrors of the Vale", "parent": null, "props": [], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#t7W5A4Fr2FK7Qa1Dtz8FHUx": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-quest-of-moria.arc", "form": "DEF", "guidance": [], "id": "#t7W5A4Fr2FK7Qa1Dtz8FHUx", "key": "Nidi’s Account", "name": "Nidi’s Account", "parent": null, "props": [{"items": [{"value": "Balin’s company arrived in Moria five years ago, in 2989 (according to the Tale of Years, the expedition is either already destroyed, or about to be overcome; the Player-heroes don’t know this, of course.)", "vk": "scalar"}, {"value": "In the first few years, the colony prospered. They drove Orcs out of the eastern halls and secured the East-gate of Moria.", "vk": "scalar"}, {"value": "In the third year of the colony, more Orcs attacked in the Dimrill Dale, trapping the Dwarves in Moria. The eastern halls were lost; Balin and company retreated to the well-defended Twenty-first Hall and held out against this renewed assault.", "vk": "scalar"}, {"value": "Balin and his followers searched for ancient treasures, including the Axe of Durin. Some dared hope that such weapons could save the colony, and hold back the attacking Orcs. Others guessed that Balin sought some prize that could justify the huge expense and loss of life incurred so far — if Moria could not be reclaimed, then at least they could return to Erebor with some worthy prize.", "vk": "scalar"}, {"value": "Now, among Balin’s followers was an eccentric Dwarf named **Finir**. He was among the greatest metallurgists of Erebor, an expert in alloys and esoteric metalworking techniques. It was his grandfather who made the fabled Black Arrow that brought down the Dragon, forged of a rare alloy. He studied among the masters of the Blue Mountains until he learned of Balin’s plans to return to Moria; he immediately travelled to Erebor to join the expedition, in the hopes of being able to work with Mithril.", "vk": "scalar"}, {"value": "With the East-gate held by Orcs, Balin looked west. If the Dwarves could reach the Hollin-gate of West Moria, they could bring supplies and help from the outside world, maybe even reinforcements from the Blue Mountains. Nidi and his companions were chosen to be part of this second expedition. Finir volunteered to go, over Balin’s objections, for the smiths of West Moria were said to possess techniques learned from the Elves that no other Dwarves mastered. A successful **INSIGHT** roll lets the Player-heroes guess that Saruman extensively questioned Nidi and the other survivors about Finir, which is why the Dwarf sprang to Nidi’s mind.", "vk": "scalar"}, {"value": "They set off down the long dark road, but were waylaid by Orcs. Nidi and the rest were separated in the caverns and got lost. They tried to find their way back to the Twenty-first Hall, but ended up climbing high into the upper Levels and emerging in the mountains above the city through a Goblin-cave. Wargs found their trail, and the Orcs pursued them.", "vk": "scalar"}, {"value": "Nidi does not know the fate of Balin, or Ori, or Finir — but she prays they are all still alive.", "vk": "scalar"}], "name": "Items", "of": "STRING", "vk": "list"}], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#t7kbgw6eDl6NUsq8V5zXz7q": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [{"fields": [{"name": "Location", "type": "STRING", "value": "A ruined foundry, smithy or other workshop, abandoned in haste, tools still lying where they were dropped.", "vk": "scalar"}], "name": "7", "vk": "def"}, {"fields": [{"name": "Location", "type": "STRING", "value": "The subterranean mansion of a Dwarven extended family. Perhaps the door was barricaded, and the dead still lie entombed within; more likely, the house was long since broken into and defiled by Orcs.", "vk": "scalar"}], "name": "8", "vk": "def"}, {"fields": [{"name": "Location", "type": "STRING", "value": "A wide passageway, one of the main streets of the underground city.", "vk": "scalar"}], "name": "9", "vk": "def"}, {"fields": [{"name": "Location", "type": "STRING", "value": "One of the holy places of the Dwarrowdelf — the tomb of a king, a grand palace or library or civic building, a hall raised by Durin himself.", "vk": "scalar"}], "name": "10", "vk": "def"}, {"fields": [{"name": "Location", "type": "STRING", "value": "A refuge — an easily fortified chamber, a well with drinkable water, a light-shaft that lets sunlight into the dark. The Company can rest here safely.", "vk": "scalar"}], "name": "[Gandalf Rune]", "vk": "def"}], "enum": null, "file": "tor2e-0.5-hands-the-disaster-of-the-gladden-fields.arc", "form": "DEF", "guidance": [], "id": "#t7kbgw6eDl6NUsq8V5zXz7q", "key": "Aftermath Table 2", "name": "Aftermath Table 2", "parent": null, "props": [], "refs": [], "slot": "SCENE", "table": {"columns": ["FEAT DIE", "LOCATION"], "rows": [["7", "A ruined foundry, smithy or other workshop, abandoned in haste, tools still lying where they were dropped."], ["8", "The subterranean mansion of a Dwarven extended family. Perhaps the door was barricaded, and the dead still lie entombed within; more likely, the house was long since broken into and defiled by Orcs."], ["9", "A wide passageway, one of the main streets of the underground city."], ["10", "One of the holy places of the Dwarrowdelf — the tomb of a king, a grand palace or library or civic building, a hall raised by Durin himself."], ["[Gandalf Rune]", "A refuge — an easily fortified chamber, a well with drinkable water, a light-shaft that lets sunlight into the dark. The Company can rest here safely."]]}, "type": "Table", "typeHash": "#tor5Table0000000001"}, "#t7yvykvQydz8g2zYI4RqkAT": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-beast-of-dunland.arc", "form": "DEF", "guidance": [], "id": "#t7yvykvQydz8g2zYI4RqkAT", "key": "Crow Hall", "name": "Crow Hall", "parent": null, "props": [], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#t8NOn6CTvi15UHBBhgeaGxD": {"book": "hands", "children": [], "choices": [], "desc": "They are coming, again! Depending on events earlier in the adventure, these may be Orc scouts investigating the disturbance at the West-gate, or Gorgol’s forces pursuing the intruders who disrupted the attack at the Chamber of Mazarbul.\n\nThe Orcs swarm in through the same door that the Player-heroes used to reach the crypt. They attack in waves:\n\nBetween each wave, there’s a brief break — enough time for the Player-heroes to tend to their wounds or take a short rest. The Player-heroes can use this time to continue the search or flee the crypt.\n\nThere are far too many Orcs for the Player-heroes to defeat. Escape is the only option, or they will eventually be overwhelmed and slaughtered amid the tombs.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-quest-of-moria.arc", "form": "DEF", "guidance": [], "id": "#t8NOn6CTvi15UHBBhgeaGxD", "key": "The Siege of the Crypt", "name": "The Siege of the Crypt", "parent": null, "props": [{"items": [{"value": "**1st Wave:** One **Goblin Archer** and two **Orc Soldiers** for each Player-hero, who balk at passing the anvil door.", "vk": "scalar"}, {"value": "**2nd Wave:** Two **Orc Guards** for each Player-hero plus an **Orc-chieftain** arrive; the Orc-chieftain’s *Yell of Triumph* forces the rabble through the door.", "vk": "scalar"}, {"value": "**3rd Wave:** The drums begin beating in the distance, echoing through the empty halls, summoning reinforcements. A **Great Cave-troll** arrives, accompanied by one **Orc Guard** for each Player-hero.", "vk": "scalar"}, {"value": "**4th Wave:** Either **Gorgol** or a **Great Orc Chief**, accompanied by two **Great Orc Bodyguards** for each Player-hero.", "vk": "scalar"}], "name": "Items", "of": "STRING", "vk": "list"}], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#t8PNrELLio26F6k8vO3WPkD": {"book": "hands", "children": [], "choices": [], "desc": "Of the ‘mad smith’ of Balin’s Expedition, a little more may be said here. As Nidi said, he was the talented scion of a line of master-smiths, and lived in honour in the Blue Mountains until he heard rumour of Balin’s Expedition. The thought of being the first Dwarf in a thousand years to work *unsullied Mithril* — to smelt it, to refine it, to alloy it with other metals — that thought consumed him.\n\nWhen the expedition of Balin arrived in Moria, it was Finir who pushed for them to explore deeper and deeper into the mines. His obsession grew with each passing month, until the other Dwarves feared he would harm himself if they did not bring him some ore to experiment upon. He claimed that the mountain was calling to him, that the ancient forge-fires of Moria yearned to be relit by his hands. Balin tolerated Finir’s eccentricities, for the colony needed his talents to repair and restore the damaged sections of Moria, but the other Dwarves never trusted or liked him.\n\nWhen Balin first sent Óin in search of the upper armouries of the Third Deep, in the Third Year of the Colony, Finir begged to be allowed to go to West Moria and look for the Chambers of Narvi. Balin refused him then, unwilling to risk the colony’s master-smith on such an errand. However, after Balin’s death, with the colony in desperate straits, no-one dared gainsay Finir when he demanded to be included in another expedition west with Nidi.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-quest-of-moria.arc", "form": "DEF", "guidance": [], "id": "#t8PNrELLio26F6k8vO3WPkD", "key": "Finir", "name": "Finir", "parent": null, "props": [], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#t8bryKyeesGSTW5X0l1VWi2": {"book": "hands", "children": [], "choices": [], "desc": "The Ledge of Woe is a narrow lip of stone, barely wide enough to stand on. Beyond is the fathomless abyss of the chasm; somewhere far above, lost in shadow, is the span of Durin’s Bridge. The Dwarves used this place long ago as a prison reserved only for traitors and the worst enemies of the King; now, the Orcs throw all their prisoners here, until they can be divided up between the various Orc-factions. Most prisoners are sent down to the mines, others worked to death in the Orc-fortresses on the lower levels. A few are given over to the Balrog-cult and sacrificed to the flames.\n\nThis day there are at least three prisoners on the ledge, including Arcinyas, all chained together with bonds of iron. The chains are bolted into the rock wall, to prevent prisoners from escaping their fate by hurling themselves into the depths.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-disaster-of-the-gladden-fields.arc", "form": "DEF", "guidance": [], "id": "#t8bryKyeesGSTW5X0l1VWi2", "key": "The ‘prison Without Bars’", "name": "The ‘prison Without Bars’", "parent": null, "props": [], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#t8qXMpDzGONpdDdOffNPvkH": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "loremaster-characters/tor2e-0.5-hands-vila.actor", "form": "DEF", "guidance": [], "id": "#t8qXMpDzGONpdDdOffNPvkH", "key": "Vila", "name": "Vila", "parent": null, "props": [{"name": "Name", "type": "STRING", "value": "Vila", "vk": "scalar"}, {"name": "Occupation", "type": "STRING", "value": "Nursemaid/Princess", "vk": "scalar"}, {"items": [{"value": "Fearful", "vk": "scalar"}, {"value": "Secretive", "vk": "scalar"}], "name": "Distinctive Features", "of": "STRING", "vk": "list"}, {"name": "Location", "type": "STRING", "value": "A Council with the Crow Lord", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "The young daughter of the chieftain is wise beyond her years, and very observant — she’s seen her brother fall under the influence of Dunrach, and she fears the malice and magic of Dunwalla. She worries that one day, her father will be found dead and she’ll be married off to one of Toirlas’ cronies (or even, in her nightmares, Dunrach). She’s hidden a bag of food and a knife in a corner of the hall, and is ready to flee at a moment’s notice.", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Loremaster Character", "typeHash": "#TOR0030000000000"}, "#t8u6HGdPNa2MphoyooagB2S": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "adversaries/tor2e-0.5-hands-black-uruk-soldier.actor", "form": "DEF", "guidance": [], "id": "#t8u6HGdPNa2MphoyooagB2S", "key": "Black Uruk Soldier", "name": "Black Uruk Soldier", "parent": null, "props": [{"name": "Name", "type": "STRING", "value": "Black Uruk Soldier", "vk": "scalar"}, {"items": [{"value": "Fierce", "vk": "scalar"}, {"value": "Strong", "vk": "scalar"}], "name": "Distinctive Features", "of": "STRING", "vk": "list"}, {"name": "Attribute Level", "type": "INTEGER", "value": 5, "vk": "scalar"}, {"name": "Endurance", "type": "INTEGER", "value": 20, "vk": "scalar"}, {"name": "Might", "type": "INTEGER", "value": 1, "vk": "scalar"}, {"name": "Hate", "type": "INTEGER", "value": 5, "vk": "scalar"}, {"name": "Parry", "type": "STRING", "value": "+2", "vk": "scalar"}, {"name": "Armour", "type": "STRING", "value": "3", "vk": "scalar"}, {"items": [{"fields": [{"name": "Weapon", "type": "STRING", "value": "Broad-bladed Sword", "vk": "scalar"}, {"name": "Rating", "type": "INTEGER", "value": 3, "vk": "scalar"}, {"name": "Damage", "type": "INTEGER", "value": 4, "vk": "scalar"}, {"name": "Injury", "type": "INTEGER", "value": 16, "vk": "scalar"}, {"items": [{"value": "Pierce", "vk": "scalar"}], "name": "Special Damage", "of": "STRING", "vk": "list"}, {"name": "Printed", "type": "STRING", "value": "Broad-bladed Sword 3 (4/16, Pierce)", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Weapon", "type": "STRING", "value": "Bow of Horn", "vk": "scalar"}, {"name": "Rating", "type": "INTEGER", "value": 3, "vk": "scalar"}, {"name": "Damage", "type": "INTEGER", "value": 3, "vk": "scalar"}, {"name": "Injury", "type": "INTEGER", "value": 14, "vk": "scalar"}, {"items": [{"value": "Pierce", "vk": "scalar"}], "name": "Special Damage", "of": "STRING", "vk": "list"}, {"name": "Printed", "type": "STRING", "value": "Bow of Horn 3 (3/14, Pierce)", "vk": "scalar"}], "vk": "def"}], "name": "Combat Proficiencies", "of": "Adversary Combat Proficiency", "ofHash": "#tor5AdvCombat000001", "vk": "list"}, {"items": [{"fields": [{"name": "Name", "type": "STRING", "value": "Horrible Strength", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "If the Black Uruk Soldier scores a Piercing Blow with a close combat attack, spend 1 Hate to make the target’s Protection roll Ill-favoured.", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Name", "type": "STRING", "value": "Thick Armour", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "Spend 1 Hate to gain (2d) on a Protection roll.", "vk": "scalar"}], "vk": "def"}], "name": "Fell Abilities", "of": "Fell Ability", "ofHash": "#tor5FellAbility0001", "vk": "list"}], "refs": [], "slot": null, "table": null, "type": "Adversary", "typeHash": "#TOR0020000000000"}, "#t91jMs4VNmBGzqFPkg548gh": {"book": "hands", "children": [], "choices": [], "desc": "Seeking out **Magga** — an eccentric woman who makes a living plucking mussels and other shellfish from the rocks — gets her account. She claims that she saw Sellic in conversation with ‘an Elf out of the sea’ on a lonely beach up the shore, where strange songs are often heard. But everyone knows Magga sees things that aren’t there — she probably heard Sellic singing the tale of some king of old, and imagined the rest.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-sea-prince-of-the-shore.arc", "form": "DEF", "guidance": [], "id": "#t91jMs4VNmBGzqFPkg548gh", "key": "Magga’s Tale", "name": "Magga’s Tale", "parent": null, "props": [], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#t9A6li9z71ISkF8tvFU7z3m": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "loremaster-characters/tor2e-0.5-hands-scepa-the-shepherd.actor", "form": "DEF", "guidance": [], "id": "#t9A6li9z71ISkF8tvFU7z3m", "key": "Scepa the Shepherd", "name": "Scepa the Shepherd", "parent": null, "props": [{"name": "Name", "type": "STRING", "value": "Scepa the Shepherd", "vk": "scalar"}, {"name": "Occupation", "type": "STRING", "value": "Shepherd", "vk": "scalar"}, {"items": [{"value": "Slow-witted", "vk": "scalar"}, {"value": "Strong", "vk": "scalar"}], "name": "Distinctive Features", "of": "STRING", "vk": "list"}, {"name": "Location", "type": "STRING", "value": "Scepa’s Tale", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "It’s whispered that Scepa is half-giant, for he is both mighty and slow-witted. He has never been more than a few days’ walk from Sigulf’s stead before, and has no idea about the wider world. While he seeks to murder Toirlas, and certainly looks capable of such a deed like Helm Hammerhand of old, Scepa’s no trained fighter. Sword or spear in hand, Toirlas will easily defeat him.", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Loremaster Character", "typeHash": "#TOR0030000000000"}, "#t9ChAghXmBg6IyGvhDMxBDg": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-disaster-of-the-gladden-fields.arc", "form": "DEF", "guidance": [], "id": "#t9ChAghXmBg6IyGvhDMxBDg", "key": "Rumour", "name": "Rumour", "parent": null, "props": [], "refs": [], "slot": "PHASE", "table": null, "type": null, "typeHash": null}, "#t9DLVtuTDvMlY4haU7kP5yU": {"book": "hands", "children": [], "choices": [], "desc": "The enemies ranged against the Company consists of the leaders of the Corsair expedition — the swashbuckling Corsair **Zoril**, the pallid sorceress **Usapthon**, the gruff old captain **Nerek**, the Orc **Lug**, and the crew of the ship. On other expeditions, the mighty *Kathuphazgân* carries as many as five hundred souls on board; presently, with the need to lighten her considerably to sail upriver, and with so many of the Corsairs off on other missions across Eriador, there are far fewer than that number present. Most of the sailors are on board the ship itself, while the majority of the soldiers have encamped on the shore. A mixed group of sailors and soldiers are excavating the Admiral’s Tomb.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-there-let-them-lie-until-the-end.arc", "form": "DEF", "guidance": [], "id": "#t9DLVtuTDvMlY4haU7kP5yU", "key": "The Corsair Forces", "name": "The Corsair Forces", "parent": null, "props": [], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#t9M88oXTalAilPUkTgxUPO3": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-ithil-stone.arc", "form": "DEF", "guidance": [], "id": "#t9M88oXTalAilPUkTgxUPO3", "key": "Old Lore", "name": "Old Lore", "parent": null, "props": [], "refs": [], "slot": "PHASE", "table": null, "type": null, "typeHash": null}, "#t9UJV4XQfNzE4BOYiG289mQ": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "adversaries/tor2e-0.5-hands-redtooth.actor", "form": "DEF", "guidance": [], "id": "#t9UJV4XQfNzE4BOYiG289mQ", "key": "Redtooth", "name": "Redtooth", "parent": null, "props": [{"name": "Name", "type": "STRING", "value": "Redtooth", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "An ambitious Orc-chieftain, Redtooth has prospered by gathering loyal and viciously effective Orcs around him. His warband may be small, but his Orcs fight as a tight unit instead of a disorganised rabble, and Redtooth himself is daring enough to risk raids far beyond the Dimrill Dale, winning him renown. Physically, Redtooth is a wiry Orc, his muscular frame covered in battle scars, many of which were self-inflicted in his younger days, to improve his resistance to pain. His company consists of one Orc Guard, two Orc-soldiers and one Goblin Archer per Player-hero; they are all Moria-orcs, differing from the Orcs of the North by possessing the *Denizen of the Dark* Fell Ability in addition to their other abilities.", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Adversary", "typeHash": "#TOR0020000000000"}, "#t9ZI429ynJJHdK9A49rL5cx": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [{"fields": [{"name": "Shadow", "type": "STRING", "value": "+1/2/3", "vk": "scalar"}], "name": "Fixed amount", "vk": "def"}, {"fields": [{"name": "Shadow", "type": "INTEGER", "value": 1, "vk": "scalar"}], "name": "The Player-heroes committed Misdeeds collectively worth 4 Shadow points or more", "vk": "def"}, {"fields": [{"name": "Shadow", "type": "INTEGER", "value": 1, "vk": "scalar"}], "name": "None of Balin’s company survive", "vk": "def"}, {"fields": [{"name": "Shadow", "type": "INTEGER", "value": 1, "vk": "scalar"}], "name": "Finir is slain", "vk": "def"}, {"fields": [{"name": "Shadow", "type": "INTEGER", "value": 2, "vk": "scalar"}], "name": "The Player-heroes bring the Ring of the Smiths back to Saruman", "vk": "def"}], "enum": null, "file": "tor2e-0.5-hands-worksheet-saruman-s-shadow-score.ttrpg", "form": "DEF", "guidance": [], "id": "#t9ZI429ynJJHdK9A49rL5cx", "key": "The Quest of Moria Shadow Score", "name": "The Quest of Moria Shadow Score", "parent": "#tlona8YOY48U8Xm0NFaScgP", "props": [], "refs": [], "slot": null, "table": {"columns": ["Trigger", "Shadow", "Tally"], "rows": [["Fixed amount", "+1/2/3", ""], ["The Player-heroes committed Misdeeds collectively worth 4 Shadow points or more", "+1", ""], ["None of Balin’s company survive", "+1", ""], ["Finir is slain", "+1", ""], ["The Player-heroes bring the Ring of the Smiths back to Saruman", "+2", ""]]}, "type": "Table", "typeHash": "#tor5Table0000000001"}, "#tAseZQ0peAsyr7RWMpLht45": {"book": "hands", "children": [], "choices": [], "desc": "A Host of two or three dozen warriors might be a roughly equal match for any *one* of the three Númenórean detachments present (one group on the ship, one at the camp, one on the hill). Fighting two such detachments likely means bloody defeat; against all three, the chances are even slimmer. If the Player-heroes do risk a direct confrontation, the Loremaster must roll on the Battle Outcome table once for each engagement. If the Host survives the first engagement, the following rolls on the Battle Outcome table become *Ill-favoured*, and the result must be moved one step towards [Eye of Sauron] for each previous confrontation. If the Player-heroes have Lightroot with them, they can move a single result on the Battle Outcome table one step towards [Gandalf Rune] , but the Ent will be so bruised and battered afterwards that he will leave.\n\nIn each engagement, the Player-heroes face one or more Key Foes and a supporting group of enemy sailors or soldiers, while in the background the warriors of the Host fight against the bulk of the lesser enemy forces:\n\nFor the soldiers, use the stats of the **Sea-prince Guards** on page 51, while the sailors are **Southerner Raiders**.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-there-let-them-lie-until-the-end.arc", "form": "DEF", "guidance": [], "id": "#tAseZQ0peAsyr7RWMpLht45", "key": "Attacking the Enemy", "name": "Attacking the Enemy", "parent": null, "props": [{"items": [{"value": "If the Company uses the Host to attack the detachment on the ship, each Player-hero must fight two sailors, plus **Captain Nerek** (and **Usapthon**, if she’s still on board the ship).", "vk": "scalar"}, {"value": "If the Company uses the Host to attack the detachment at the camp, each Player-hero must fight two soldiers. This is also where **Zoril** is most likely to be found, in which case she will join the battle.", "vk": "scalar"}, {"value": "If the Company uses the Host to attack the detachment excavating the Admiral’s Tomb, each Player-hero must fight one soldier and one sailor, plus **Lug** (and **Usapthon**, if she has moved here).", "vk": "scalar"}], "name": "Items", "of": "STRING", "vk": "list"}], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#tBf2FTSa7gG9AFodWciv6pp": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "adversaries/tor2e-0.5-hands-kinir-the-ring-wight.actor", "form": "DEF", "guidance": [], "id": "#tBf2FTSa7gG9AFodWciv6pp", "key": "Kinir The Ring-Wight", "name": "Kinir The Ring-Wight", "parent": null, "props": [{"name": "Name", "type": "STRING", "value": "Kinir The Ring-Wight", "vk": "scalar"}, {"items": [{"value": "Doleful", "vk": "scalar"}, {"value": "Dreadful", "vk": "scalar"}], "name": "Distinctive Features", "of": "STRING", "vk": "list"}, {"name": "Attribute Level", "type": "INTEGER", "value": 7, "vk": "scalar"}, {"name": "Endurance", "type": "INTEGER", "value": 50, "vk": "scalar"}, {"name": "Might", "type": "INTEGER", "value": 2, "vk": "scalar"}, {"name": "Hate", "type": "INTEGER", "value": 7, "vk": "scalar"}, {"name": "Parry", "type": "STRING", "value": "—", "vk": "scalar"}, {"name": "Armour", "type": "STRING", "value": "4", "vk": "scalar"}, {"items": [{"fields": [{"name": "Weapon", "type": "STRING", "value": "Ancient Hammer", "vk": "scalar"}, {"name": "Rating", "type": "INTEGER", "value": 3, "vk": "scalar"}, {"name": "Damage", "type": "INTEGER", "value": 6, "vk": "scalar"}, {"name": "Injury", "type": "INTEGER", "value": 16, "vk": "scalar"}, {"items": [{"value": "Break Shield", "vk": "scalar"}], "name": "Special Damage", "of": "STRING", "vk": "list"}, {"name": "Printed", "type": "STRING", "value": "Ancient Hammer 3 (6/16, Break Shield)", "vk": "scalar"}], "vk": "def"}], "name": "Combat Proficiencies", "of": "Adversary Combat Proficiency", "ofHash": "#tor5AdvCombat000001", "vk": "list"}, {"items": [{"fields": [{"name": "Name", "type": "STRING", "value": "Deathless", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "Spend 1 Hate to cancel a Wound. When an attack inflicts damage to the creature that would cause it to go to zero Endurance, spend 1 Hate to bring the creature back to full Endurance again. This ability is ineffective against Player-heroes wielding a magical weapon enchanted with spells for the Bane of the Undead.", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Name", "type": "STRING", "value": "Dreadful Spells", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "Spend 1 Hate to make one Player-hero gain 3 Shadow points (Sorcery). Targets who fail their Shadow Test or who are Miserable fall victim to Moria-madness, seeing the city as it was in the days of old, not its present fallen state. A victim of Moria-madness may only be restored to reality with an ENHEARTEN roll from a companion (who must spend their main action to do so, if in combat). Otherwise, they wander blinded by glory for one hour.", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Name", "type": "STRING", "value": "Hate Sunlight", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "The creature loses 1 Hate at the start of each round it is exposed to the full light of the sun.", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Name", "type": "STRING", "value": "Heartless", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "The creature is not affected by the Intimidate Foes combat task, unless a Magical Success is obtained.", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Name", "type": "STRING", "value": "Thing of Terror", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "At the start of the first round of the battle, all Player-heroes in sight of one or more creatures with this ability gain 3 Shadow points (Dread). Those who fail their Shadow test are daunted and cannot spend Hope for the rest of the fight.", "vk": "scalar"}], "vk": "def"}], "name": "Fell Abilities", "of": "Fell Ability", "ofHash": "#tor5FellAbility0001", "vk": "list"}], "refs": [], "slot": null, "table": null, "type": "Adversary", "typeHash": "#TOR0020000000000"}, "#tBmTp922LeSYlli8quvP7X3": {"book": "hands", "children": [], "choices": [], "desc": "The Player-heroes have come to the place called Eärnur’s Edge. Here, the cliff drops precipitously into a deep ravine, with the Morgul-road running far below. Midway along this cliff is a spur of rock, twisted and agonised. There’s something almost human or giant-like about the formation, as if a man was trapped within the stone and was caught in the moment of fighting his way free. The spur is a hundred feet lower below the level of the Stair, so to plant the blasting charges, the Player-heroes must climb or rappel down the sheer cliff face, place the casks in the crevices of the rock, and then light the devilry of Orthanc.\n\nPlanting the blasting powder is a Skill Endeavour.\n\nThe time limit is 4, or 3 if the Player-heroes have been detected and are being pursued by foes. If Saruman’s Shadow is 10 or less, increase the time limit by 1, as he sends a flock of *Crebain* to distract the forces of Minas Morgul. Appropriate Skills include **ATHLETICS**, **CRAFT**, or **SCAN** (to find the right crack).\n\n**Lighting the Powder:** If the Player-heroes manage to detonate the blasting powder, then they unleash the fires of doom. The Mountains of Shadow quake and quail as the thunderous blast shakes earth and sky. Far away across Gorgoroth, Orodruin roars in answer, flame spouting into the sky like dragonfire. With majestic, glacial slowness, the cliff face cracks, slips… and then it is like the Wrath of the Valar in the first days, like the Downfall of Númenor, as the world is shattered and remade. Millions of tonnes of stone cascade down into the Morgul Vale.\n\nIf the Player-heroes time it correctly, the Orc army is engulfed and utterly destroyed.\n\nSo too, alas, are any Player-heroes who do not have time to flee the cataclysm. But if they perish here, then they could not ask for a better cairn of stones, for few have won such a victory.\n\n**The Sappers Discovered:** If the Player-heroes fail to complete the Skill Endeavour in time, then pick one of the following horrible fates for them.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-ithil-stone.arc", "form": "DEF", "guidance": [], "id": "#tBmTp922LeSYlli8quvP7X3", "key": "The Blast on Eärnur’s Edge", "name": "The Blast on Eärnur’s Edge", "parent": null, "props": [{"items": [{"value": "Setting a fuse and igniting it with time to clear the immediate area is a Daunting goal (Resistance 9).", "vk": "scalar"}, {"value": "Planting the powder without a fuse (so someone must remain nearby to detonate the explosion) is a Laborious goal (Resistance 6).", "vk": "scalar"}, {"value": "If they have already been spotted by the forces of Minas Morgul, then the Ringwraiths sweep up the Stair of Cirith Ungol like a black wind, and catch the Company at Eärnur’s Edge. It is still possible that the Player-heroes complete their quest — but likely, they will perish here.", "vk": "scalar"}, {"value": "If they have somehow escaped detection by Minas Morgul, then another foe — one unsuspected even by Saruman — finds them. **Shelob**, Daughter of Ungoliant, dwells not far from this spot, in the haunted tunnels of Torech Ungol, and she hungers for sweeter meat than Orc or fly. The Spider comes skittering across the cliff, clinging to the rockface, a horror of the ancient world beyond the designs or schemes of Saruman. Defeating Shelob is likely a task beyond the Player-heroes — although they could wound her enough to drive her away.", "vk": "scalar"}], "name": "Items", "of": "STRING", "vk": "list"}], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#tCC9FkoF59foe4c92FudUOY": {"book": "hands", "children": [], "choices": [], "desc": "If the Player-heroes choose to wait, then a Success die roll is required to determine the number of days they must stand by — and the Eye Awareness score increases by 2. If this takes the Company over their Hunt Threshold, then the *Alagoson Arrested* event must be played (see next page).\n\nWhile the island is dominated by the various military forts and watchtowers, there are areas of farmland, and plenty of places for the Player-heroes to shelter in comfort. Indeed, it’s obvious that the fortress is built for a much larger garrison; Gondor can only muster a fraction of the military force it once commanded. Alagoson visits the Player-heroes regularly, asking them questions about their service to Saruman and their errand in Ithilien. He can also be a source of information about the lands ahead (see *The State of Ithilien in T.A. 3000*, on page 127). Play up the feeling of delay, of frustration. Cair Andros is a fortress at war, but a lot of war is standing around in the damp, waiting for something — *anything* — to happen. Mention the constant brooding presence of Mordor; the eastern horizon is dominated by the distant shadow of the mountains, and the constant black fumes from Mount Doom. When it rains — and it rains a lot — the raindrops leave gritty black soot smeared over everything.\n\nAt last — the host arrives from Minas Tirith, and it is a glorious sight indeed. Knights of the Citadel and Dol Amroth, mounted on fine warhorses from Rohan, with the banner of the White Tree fluttering in the breeze. At the head of the company rides the prince of Minas Tirith — **Boromir**, son of the steward. He is twenty-two years of age, but has already won acclaim for his heroic defence of Osgiliath.\n\nThere is little time to prepare — the expedition arrives in the evening, and departs with the dawn, ferrying across to the far shore in the grey morning. Alagoson helps the Player-heroes slip into the host’s vanguard.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-ithil-stone.arc", "form": "DEF", "guidance": [], "id": "#tCC9FkoF59foe4c92FudUOY", "key": "Waiting for the Expedition", "name": "Waiting for the Expedition", "parent": null, "props": [], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#tCLS3Jakdvobmq4RDbo3TkI": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "loremaster-characters/tor2e-0.5-hands-alagoson-the-smuggler.actor", "form": "DEF", "guidance": [], "id": "#tCLS3Jakdvobmq4RDbo3TkI", "key": "Alagoson the Smuggler", "name": "Alagoson the Smuggler", "parent": null, "props": [{"name": "Name", "type": "STRING", "value": "Alagoson the Smuggler", "vk": "scalar"}, {"name": "Occupation", "type": "STRING", "value": "Guard", "vk": "scalar"}, {"items": [{"value": "Grim", "vk": "scalar"}, {"value": "Secretive", "vk": "scalar"}], "name": "Distinctive Features", "of": "STRING", "vk": "list"}, {"name": "Location", "type": "STRING", "value": "Arrival at Cair Andros", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "Although Ithilien is mostly abandoned, there are still a few hold-outs who live there, and they need supplies and goods from the hinterlands of Gondor. Similarly, there are things in Ithilien (furs and hides, fruit and spices, in particular) that cannot be obtained elsewhere. So, despite the Steward’s edicts, there’s still trade across the river, and a sizeable portion of that trade goes through the sticky hands of Alagoson of Cair Andros.\n\nHis hands may be dirty, but he believes his heart is pure. He’s still a loyal man of Gondor — but a man must eat, after all, and what harm if he makes a little coin on the side while guarding Cair Andros.", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Loremaster Character", "typeHash": "#TOR0030000000000"}, "#tCdNX4pnNaR79xoMwjAixSq": {"book": "hands", "children": ["#t2AP0rtPW3EPKTzT8XKAEFB"], "choices": [], "desc": null, "entries": [], "enum": null, "file": "tor2e-0.5-hands-worksheet-saruman-s-shadow-score.ttrpg", "form": "DEF", "guidance": [], "id": "#tCdNX4pnNaR79xoMwjAixSq", "key": "The Ithil-stone", "name": "The Ithil-stone", "parent": "#t4tH0BF1gelfgVc1eyhWAuw", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#tE3KTdIb1Bo590MtlVcpXPj": {"book": "hands", "children": [], "choices": [], "desc": "If the Player-heroes are detected in the Morgul Vale, one **Ringwraith** for each Player-hero (see below) rides forth to investigate — and at their head is the same Ringwraith that the Player-heroes may have encountered outside Moria (see *The Disaster of the Gladden Fields*, on page 71). This time, the Nazgûl are cloaked in black, and ride black horses — and here, within the borders of Sauron’s domain, they are much more powerful. The Nazgûl pursue the Player-heroes across the vale and up the Stair, intending to use their power of unreasoning fear and the Black Breath to drive the Player-heroes to their deaths over the cliff edge.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-ithil-stone.arc", "form": "DEF", "guidance": [], "id": "#tE3KTdIb1Bo590MtlVcpXPj", "key": "The Ringwraiths Ride Forth", "name": "The Ringwraiths Ride Forth", "parent": null, "props": [], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#tE82F4DUKKmyweQnfNWsA5i": {"book": "hands", "children": [], "choices": [], "desc": "Finding the Goblin-cave amid the mountains requires a Skill Endeavour using **ATHLETICS**, **EXPLORE**, **HUNTING**, or **TRAVEL**. The Resistance is 6; the time limit is 5 in Summer, 4 in Spring or Autumn, and 3 in Winter. For every Skill roll during the Endeavour, each Player-hero gains 1 Fatigue. A roll failed with an [Eye of Sauron] means the Player-heroes either run into Wargs or Orcs, or suffer some other misfortune like falling into a ravine or running low on supplies.\n\nIf the Player-heroes exceed the allotted time limit, then a blizzard blows down from the north; they may continue to search for the cave, but for every Skill roll each Player-hero now gains 2 Fatigue instead of 1, and also suffers a moderate Endurance loss from extreme cold.\n\nIf the Player-heroes find the right cave — identifiable by fresh Goblin footprints near the entrance — then in the dark recesses right at the back they can discover a cunning false door with a **SCAN** roll. Opening it reveals a passageway that worms endlessly through the mountains, barely wide enough in places for a Goblin to crawl through. The passage ends in a side tunnel off the straight Road connecting Old Moria to the east and the Dwarrowdelf to the west (see also *Moria: Through the Doors of Durin*, page 132).", "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-quest-of-moria.arc", "form": "DEF", "guidance": [], "id": "#tE82F4DUKKmyweQnfNWsA5i", "key": "The Goblin-cave", "name": "The Goblin-cave", "parent": null, "props": [], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#tEYR65WPzyh18cxNl6WVT5E": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "loremaster-characters/tor2e-0.5-hands-hurin-snowhair.actor", "form": "DEF", "guidance": [], "id": "#tEYR65WPzyh18cxNl6WVT5E", "key": "Húrin Snowhair", "name": "Húrin Snowhair", "parent": null, "props": [{"name": "Name", "type": "STRING", "value": "Húrin Snowhair", "vk": "scalar"}, {"name": "Occupation", "type": "STRING", "value": "Commander", "vk": "scalar"}, {"items": [{"value": "Eager", "vk": "scalar"}, {"value": "Honourable", "vk": "scalar"}], "name": "Distinctive Features", "of": "STRING", "vk": "list"}, {"name": "Location", "type": "STRING", "value": "Arrival at Cair Andros", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "The elderly commander of Cair Andros, Húrin is well respected both by those who serve under him, and those who rely on his wise counsel. All his life, Húrin has fought the long defeat — he’s watched the strength of Minas Tirith dwindle, watched the frontiers of Gondor roll back mile by mile, year by year. But perhaps the bitterest thought is that when the war does come, when the Enemy’s long-anticipated assault begins, he will be too old to make a difference. His time as commander is coming to an end; it will be some other, younger warrior who faces the true test, and all Húrin’s deeds will amount to nothing of consequence.\n\nMaybe that’s why Húrin, long the dependable, steadfast shieldbearer of Gondor, has in his old age discovered an appetite for risk. In his secret heart, he wishes he could strike one real blow against the Enemy, and sometimes dreams of riding off to challenge the Witch-king of Minas Morgul as King Eärnur did in days of old. It was Húrin who encouraged Prince Boromir’s bold plan to attack the Crossings, and he’s looking for other ways to inflict more damage on Mordor before his watch is done.", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Loremaster Character", "typeHash": "#TOR0030000000000"}, "#tElWlKGGjJC7JD5HA04oBeG": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "adversaries/tor2e-0.5-hands-shelob.actor", "form": "DEF", "guidance": [], "id": "#tElWlKGGjJC7JD5HA04oBeG", "key": "Shelob", "name": "Shelob", "parent": null, "props": [{"name": "Name", "type": "STRING", "value": "Shelob", "vk": "scalar"}, {"items": [{"value": "Stealthy", "vk": "scalar"}, {"value": "Swift", "vk": "scalar"}], "name": "Distinctive Features", "of": "STRING", "vk": "list"}, {"name": "Attribute Level", "type": "INTEGER", "value": 11, "vk": "scalar"}, {"name": "Endurance", "type": "INTEGER", "value": 130, "vk": "scalar"}, {"name": "Might", "type": "INTEGER", "value": 3, "vk": "scalar"}, {"name": "Hate", "type": "INTEGER", "value": 11, "vk": "scalar"}, {"name": "Parry", "type": "STRING", "value": "—", "vk": "scalar"}, {"name": "Armour", "type": "STRING", "value": "5", "vk": "scalar"}, {"items": [{"fields": [{"name": "Weapon", "type": "STRING", "value": "Beak and Claws", "vk": "scalar"}, {"name": "Rating", "type": "INTEGER", "value": 3, "vk": "scalar"}, {"name": "Damage", "type": "INTEGER", "value": 9, "vk": "scalar"}, {"name": "Injury", "type": "INTEGER", "value": 16, "vk": "scalar"}, {"items": [{"value": "Seize", "vk": "scalar"}], "name": "Special Damage", "of": "STRING", "vk": "list"}, {"name": "Printed", "type": "STRING", "value": "Beak and Claws 3 (9/16, Seize)", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Weapon", "type": "STRING", "value": "Sting", "vk": "scalar"}, {"name": "Rating", "type": "INTEGER", "value": 2, "vk": "scalar"}, {"name": "Damage", "type": "INTEGER", "value": 9, "vk": "scalar"}, {"name": "Injury", "type": "INTEGER", "value": 14, "vk": "scalar"}, {"items": [{"value": "Pierce", "vk": "scalar"}], "name": "Special Damage", "of": "STRING", "vk": "list"}, {"name": "Printed", "type": "STRING", "value": "Sting 2 (9/14, Pierce)", "vk": "scalar"}], "vk": "def"}], "name": "Combat Proficiencies", "of": "Adversary Combat Proficiency", "ofHash": "#tor5AdvCombat000001", "vk": "list"}, {"items": [{"fields": [{"name": "Name", "type": "STRING", "value": "Beloved Flesh", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "Each time Shelob is Wounded, she also loses 1 Hate. In addition, whenever Shelob loses or spends Hate, increase that loss or expenditure by 1 for each Wound she has.", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Name", "type": "STRING", "value": "Craven", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "When affected by the Intimidate Foe combat task, the creature also loses 1 Hate.", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Name", "type": "STRING", "value": "Foul Reek", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "Spend 1 Hate to cause all Player-heroes engaged with Shelob to lose (1d) on all rolls for the round.", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Name", "type": "STRING", "value": "Great Leap", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "Spend 1 Hate to attack any Player-hero, in any combat stance, including Rearward.", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Name", "type": "STRING", "value": "Hate Sunlight", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "The creature loses 1 Hate at the start of each round if it is exposed to the full light of the sun.", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Name", "type": "STRING", "value": "Hideous Toughness", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "The creature is unaffected by unarmed attacks. Additionally, when an attack inflicts damage to the creature that would cause it to go to zero Endurance, it causes a Piercing Blow instead. Then, if the creature is still alive its Endurance score is set back at half its maximum rating.", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Name", "type": "STRING", "value": "Shelob Poisons", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "If an attack results in a Wound, the target immediately suffers a grievous Endurance loss from poison. If the poison reduces the target to zero Endurance, Shelob can choose that the target does not become Dying.", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Name", "type": "STRING", "value": "Snake-like Speed", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "When targeted by an attack, spend 1 Hate to make the attack Ill-favoured.", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Name", "type": "STRING", "value": "Thick Hide", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "Spend 1 Hate to gain (2d) on a Protection roll.", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Name", "type": "STRING", "value": "Thing of Terror", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "At the start of the first round of battle all Player-heroes in sight gain 3 Shadow points (Dread). Those who fail their Shadow test are daunted and cannot spend Hope for the rest of the fight.", "vk": "scalar"}], "vk": "def"}], "name": "Fell Abilities", "of": "Fell Ability", "ofHash": "#tor5FellAbility0001", "vk": "list"}], "refs": [], "slot": null, "table": null, "type": "Adversary", "typeHash": "#TOR0020000000000"}, "#tEtuAuHUkGiym4yINCBMxSe": {"book": "hands", "children": [], "choices": [], "desc": "Beneath Methedras is a network of caverns, carved from the mountain by the flow of water over aeons. The Gondorians drained some of these caverns, and found deposits of iron and other ores there. These mines are no longer in use, but the chilly caves are used as storerooms for meat and perishable foods.\n\nTales say that the Misty Mountains are riddled with hidden tunnels and caves, and that an Orc can go from Mount Gundabad to Methedras without setting foot above ground. In days of old these caves were patrolled and secured by soldiers of Gondor, but it’s been a long time since anyone checked the deeper regions…", "entries": [], "enum": null, "file": "tor2e-0.5-hands-introduction.ttrpg", "form": "DEF", "guidance": [{"concerns": [{"hash": "#tEtuAuHUkGiym4yINCBMxSe", "name": "10. The Iron Caves"}], "id": "#tKD2r2F7iHlEok2yI7aFFWz", "name": "Secrets of Isengard", "text": "Isengard is a fortress that has been in nearly continuous use for more than three thousand years. Almost every part of the complex, apart from Orthanc itself, has been built and rebuilt, neglected and restored, abandoned and repurposed several times over. It has been home to scholars who knew Númenor before the fall, and to reavers who barely spoke a word of the Common Tongue and who worshipped strange powers in the forgotten hills. It has been home to wise Lords who brought justice and order to the surrounding lands, and tyrants who used it as a base for conquest. The Ring of Isengard is as complex and densely-tunnelled as an anthill, and there might be almost anything in those myriad chambers.", "topics": []}], "id": "#tEtuAuHUkGiym4yINCBMxSe", "key": "10. The Iron Caves", "name": "10. The Iron Caves", "parent": "#tcMxywq75NOL2ves69gurzl", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#tFXNo2rq9dxL1yrQtIm3Fij": {"book": "hands", "children": [], "choices": [], "desc": "These are some of the things the Player-heroes might try (and their potential consequences):", "entries": [], "enum": null, "file": "tor2e-0.5-hands-there-let-them-lie-until-the-end.arc", "form": "DEF", "guidance": [], "id": "#tFXNo2rq9dxL1yrQtIm3Fij", "key": "More Mischief", "name": "More Mischief", "parent": null, "props": [{"items": [{"value": "**Spying on the Corsairs:** As long as the Player-heroes stick to the edge of the woods, they can move about unseen. Stealthy heroes could even creep up to eavesdrop on gossip around the campfires. Most of the talk is grumbling about the cold weather, but it’s also clear that the Corsairs are worried about their situation — between the forest of ghosts, the possibly-haunted tomb, and the fact that they’re half-stranded in the middle of Enedwaith, everyone’s on edge. Rumours about what the tomb is run rife, but it is commonly guessed that they are here for some sorcerous purpose of Usapthon’s. Something Elvish, no doubt. Maybe Rivendell’s hidden here under the ground.", "vk": "scalar"}, {"value": "**Stealing Corsair Garbs:** As the Southerners find the weather cold and damp, everyone is wrapped in heavy hooded cloaks. The Player-heroes can therefore steal cloaks to move about without attracting immediate attention (the cloaks count as Useful Items here, and Player-heroes wearing them *gain [1d]* on **STEALTH** rolls while on board).", "vk": "scalar"}, {"value": "**Using the Powder in Battle:** While the powder is designed to blow up stationary targets, it can be used to dismay and distract enemies and gain advantage in battle. It can also be used to break bones and blast flesh too, but to do so is to sink to the level of goblins who delight in such mischief...", "vk": "scalar"}, {"value": "**Turning Usapthon’s Spell Back on Her:** With a Magical Success on a **SONG** roll, a Player-hero could awaken the ghost trees of Usapthon’s forest, and remind them that they were cut down by ancestors of the Corsairs with a subsequent **PERSUADE** or **RIDDLE** roll. If the Ent Lightroot is present, the latter roll *gains (2d)*. If the Player-heroes are inside Usapthon’s temple on board the ship, a Magical Success on a **SONG** roll can be obtained even if none of them would have the means to do so, at the cost of spending 1 Hope and gaining 3 Shadow points (Sorcery). If successful, the ghost forest sweeps down to the banks of the river, driving the Corsairs into the water, where they drown. A roll of **INSIGHT** or **LORE** senses the power of the temple and its connection to the ghost forest.", "vk": "scalar"}], "name": "Items", "of": "STRING", "vk": "list"}], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#tFg9suxiqd8lNSbOeXBtrB9": {"book": "hands", "children": [], "choices": [], "desc": "**Border Lands** **Wild Lands** **Dark Lands** **Impassable Terrain** **Perilous Area** 1 hex = 20 miles", "entries": [], "enum": null, "file": "tor2e-0.5-hands-map-legend.ttrpg", "form": "DEF", "guidance": [], "id": "#tFg9suxiqd8lNSbOeXBtrB9", "key": "Hex-map of the Campaign Area", "name": "Hex-map of the Campaign Area", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#tFkRrXsDwamSqJrYSbDt51a": {"book": "hands", "children": [], "choices": [], "desc": "This scene is played as a Council, albeit one with high stakes. If the Council ends in a disaster, then the Rangers attempt to slay the Player-heroes, believing them to be spies sent by the Enemy!\n\nSet the Resistance as follows:\n\n**COURTESY** or **RIDDLE** works best for introductions, although dropping Saruman’s name works in concert with **AWE** (however, it also immediately raises Saruman’s Shadow by 3).\n\nIf the Council is going badly, the Loremaster may consider having the *Swift Foes From Mordor* show up and give the Player-heroes a chance to fight side-by-side with the Rangers.\n\nAssuming she doesn’t have the Player-heroes murdered and buried in unmarked graves, then Heledirien invites them to rest under the protection of the Rangers for the evening. Possible topics of discussion include:\n\nruns through the vale were to be destroyed. In ages past, Isildur built the tower of Minas Ithil to guard the Morgul-road, for even then it was clear that it was a key route to the realm of the Enemy. Sauron and the Witch-king went to great effort to conquer Minas Ithil, partly to secure that road.\n\nShe warns that the Morgul Vale is exceedingly perilous. The evil that dwells in Minas Morgul does not sleep, and is ever watchful. If the Player-heroes are discovered, there will be no escape for them. She fears they are throwing their lives away.\n\nIf the Player-heroes succeed especially well in the Council, then Heledirien offers to provide some aid. She could (choose one):", "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-ithil-stone.arc", "form": "DEF", "guidance": [], "id": "#tFkRrXsDwamSqJrYSbDt51a", "key": "Heledirien’s Challenge", "name": "Heledirien’s Challenge", "parent": null, "props": [{"items": [{"value": "Asking Heledirien to let them turn back and return to the west bank of the Anduin is a Reasonable request (Resistance 3). The Player-heroes can try sneaking back afterwards, but the delay increases Eye Awareness by +2.", "vk": "scalar"}, {"value": "Asking Heledirien to let the Company proceed is a Bold request (Resistance 6).", "vk": "scalar"}, {"value": "If the Company demand help from her, or demand that their mission be kept secret, the request is Outrageous (Resistance 9).", "vk": "scalar"}, {"value": "**The Morgul Vale:** Heledirien is one of the few folk of Gondor who have dared set foot within the Morgul Vale, creeping even as far as the foot of the pass of Cirith Ungol. She agrees that it would hugely benefit the fortune of Minas Tirith if the Morgul-road that", "vk": "scalar"}, {"value": "**The Blasting Powder:** Heledirien dislikes Saruman’s blasting powder. In Númenor of old, clever men invented similar weapons — and they led to disaster and the Downfall. Some tools should not be used.", "vk": "scalar"}, {"value": "**Boromir’s Host:** Heledirien can offer little help to the Company, for her Rangers are bound to watch the Road in case enemies issue forth from Mordor and go to Osgiliath. She knows Lord Boromir’s host intends to attack the Orcs there, so her Rangers must serve as rearguard.", "vk": "scalar"}, {"value": "Allow the Company to take a Prolonged Rest under her protection.", "vk": "scalar"}, {"value": "Treat their Wounds.", "vk": "scalar"}, {"value": "Reduce the Company’s Eye Awareness by 2.", "vk": "scalar"}], "name": "Items", "of": "STRING", "vk": "list"}], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#tFqIBYp5EhV8C9iN1GMC31i": {"book": "hands", "children": [], "choices": [], "desc": "As well as Arcinyas, the Orcs have captured Nidi, a Dwarven treasure-hunter from the Blue Mountains. Since the defeat of the Orcs at the Battle of Five Armies, more Dwarves have dared explore the lands around their ancestral halls, looking for treasures lost when Moria fell. Nidi was captured by Orcs near the Dimrill Pass, and dragged deeper into those ancestral halls than she ever expected. She’s no warrior, but her aid makes the Player-heroes *gain (1d)* on any **EXPLORE** and **TRAVEL** rolls made in Moria — and she heard Redtooth talking about the Sixteenth Hall, the Harper’s Hall. She can help guide the Player-heroes there once freed.\n\nReaching the Harper’s Hall requires another two rolls on the Moria Hazards table.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-disaster-of-the-gladden-fields.arc", "form": "DEF", "guidance": [], "id": "#tFqIBYp5EhV8C9iN1GMC31i", "key": "Other Prisoners", "name": "Other Prisoners", "parent": null, "props": [], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#tFtTAMTCmAUzvHk4uuzDqdi": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [{"fields": [{"name": "Encounter", "type": "STRING", "value": "Trap: One of the Player-heroes blunders into a spike-lined pit trap. An AWARENESS roll avoids the trap; otherwise, the Player-hero is Wounded.", "vk": "scalar"}], "name": "[Eye of Sauron]", "vk": "def"}, {"fields": [{"name": "Encounter", "type": "STRING", "value": "Shower of Ash and Sparks: Thunder rolls across the land, and the eastern sky flashes red. A while later, hot ash and burning cinders rain down, starting small forest fires — and igniting anything flammable. Each Player-hero suffers a moderate Endurance loss from fire.", "vk": "scalar"}], "name": "1", "vk": "def"}, {"fields": [{"name": "Encounter", "type": "STRING", "value": "Orc Scavengers: The Company encounter a band of roaming Orcs (one Black Uruk Soldier for each Player-hero, see page 66).", "vk": "scalar"}], "name": "2", "vk": "def"}, {"fields": [{"name": "Encounter", "type": "STRING", "value": "Treacherous Terrain: An unstable bridge over a ravine, a muddy hillside, a tangled forest — some terrain that would normally be quite passable, but not if the heroes are hauling heavy metal casks; an ATHLETICS roll is needed to avoid jarring or dropping one of them.", "vk": "scalar"}], "name": "3", "vk": "def"}, {"fields": [{"name": "Encounter", "type": "STRING", "value": "Exposed Region: The terrain ahead is exposed and treeless. If the Company cross it, increase their Eye Awareness by 2.", "vk": "scalar"}], "name": "4", "vk": "def"}, {"fields": [{"name": "Encounter", "type": "STRING", "value": "Impassable Terrain: The land ahead consists of a deep ravine, a forest of thorns or some other obstacle. Navigating it requires an EXPLORE roll; on a failure, each Player-hero gains 2 Fatigue.", "vk": "scalar"}], "name": "5", "vk": "def"}, {"fields": [{"name": "Encounter", "type": "STRING", "value": "Ruined Watchtower: An old Gondorian tower. Roll a Success die: the tower is inhabited by Orcs (1–3), empty (4–5) or used as a Ranger-cache (6).", "vk": "scalar"}], "name": "6", "vk": "def"}, {"fields": [{"name": "Encounter", "type": "STRING", "value": "Old Road: The Company come to an old road, leading towards Morgul Vale. Do they follow this clear path, or stay out of sight?", "vk": "scalar"}], "name": "7", "vk": "def"}, {"fields": [{"name": "Encounter", "type": "STRING", "value": "Wild Beasts: A pack of wild dogs, the descendants of hounds left behind by those fleeing Ithilien, stalks the heroes. However, the beasts hate Orcs more than anything.", "vk": "scalar"}], "name": "8", "vk": "def"}, {"fields": [{"name": "Encounter", "type": "STRING", "value": "Ruined Village: An old village, overgrown and empty — but there might still be useful supplies or tools left behind.", "vk": "scalar"}], "name": "9", "vk": "def"}, {"fields": [{"name": "Encounter", "type": "STRING", "value": "Inhabited Farmstead: The Player-heroes come to one of the few farmsteads still inhabited; this fortified house is the home of Egeth, an old woman of Ithilien. While she refuses to leave, her daughter Heledirien is a Ranger and watches over her farmstead (see below).", "vk": "scalar"}], "name": "10", "vk": "def"}, {"fields": [{"name": "Encounter", "type": "STRING", "value": "A Moment of Kindness: Have one of the players describe some minor kindness their hero does for one of the others. Either that Player-hero regains 1 Hope *or* the kind deed is spotted by any Rangers watching the Player-heroes, making them better disposed towards these intruders.", "vk": "scalar"}], "name": "[Gandalf Rune]", "vk": "def"}], "enum": null, "file": "tor2e-0.5-hands-the-ithil-stone.arc", "form": "DEF", "guidance": [], "id": "#tFtTAMTCmAUzvHk4uuzDqdi", "key": "Encounters in Ithilien", "name": "Encounters in Ithilien", "parent": null, "props": [], "refs": [], "slot": "SCENE", "table": {"columns": ["FEAT DIE", "ENCOUNTER"], "rows": [["[Eye of Sauron]", "Trap: One of the Player-heroes blunders into a spike-lined pit trap. An AWARENESS roll avoids the trap; otherwise, the Player-hero is Wounded."], ["1", "Shower of Ash and Sparks: Thunder rolls across the land, and the eastern sky flashes red. A while later, hot ash and burning cinders rain down, starting small forest fires — and igniting anything flammable. Each Player-hero suffers a moderate Endurance loss from fire."], ["2", "Orc Scavengers: The Company encounter a band of roaming Orcs (one Black Uruk Soldier for each Player-hero, see page 66)."], ["3", "Treacherous Terrain: An unstable bridge over a ravine, a muddy hillside, a tangled forest — some terrain that would normally be quite passable, but not if the heroes are hauling heavy metal casks; an ATHLETICS roll is needed to avoid jarring or dropping one of them."], ["4", "Exposed Region: The terrain ahead is exposed and treeless. If the Company cross it, increase their Eye Awareness by 2."], ["5", "Impassable Terrain: The land ahead consists of a deep ravine, a forest of thorns or some other obstacle. Navigating it requires an EXPLORE roll; on a failure, each Player-hero gains 2 Fatigue."], ["6", "Ruined Watchtower: An old Gondorian tower. Roll a Success die: the tower is inhabited by Orcs (1–3), empty (4–5) or used as a Ranger-cache (6)."], ["7", "Old Road: The Company come to an old road, leading towards Morgul Vale. Do they follow this clear path, or stay out of sight?"], ["8", "Wild Beasts: A pack of wild dogs, the descendants of hounds left behind by those fleeing Ithilien, stalks the heroes. However, the beasts hate Orcs more than anything."], ["9", "Ruined Village: An old village, overgrown and empty — but there might still be useful supplies or tools left behind."], ["10", "Inhabited Farmstead: The Player-heroes come to one of the few farmsteads still inhabited; this fortified house is the home of Egeth, an old woman of Ithilien. While she refuses to leave, her daughter Heledirien is a Ranger and watches over her farmstead (see below)."], ["[Gandalf Rune]", "A Moment of Kindness: Have one of the players describe some minor kindness their hero does for one of the others. Either that Player-hero regains 1 Hope *or* the kind deed is spotted by any Rangers watching the Player-heroes, making them better disposed towards these intruders."]]}, "type": "Table", "typeHash": "#tor5Table0000000001"}, "#tG0IfY2JtnqcSW6J0e4Kfk0": {"book": "hands", "children": [], "choices": [], "desc": "The Player-heroes follow deep, stumbling footsteps in the snow, like the ones the Player-heroes may have seen at the Rohan farmstead (see page 23) or near the road to Crow Hall (see page 26). If the Player-heroes saw Scepa during the night, the trail runs right past the palisade. The trail leads through the Forest of Eyes and up into the hills south of the Hall (see *Scepa’s Tale* on page 34).", "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-beast-of-dunland.arc", "form": "DEF", "guidance": [], "id": "#tG0IfY2JtnqcSW6J0e4Kfk0", "key": "The Trail to Scepa", "name": "The Trail to Scepa", "parent": null, "props": [], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#tGhOPC3ndJFPiQ770p2V7WC": {"book": "hands", "children": [], "choices": [], "desc": "To rescue Gildor, the Player-heroes must storm the tower, fighting their way past the guards, and then open the barred door to the dungeon. It’s much easier to deal with the guards if they’re distracted — this is an excellent opportunity for the players to split the party, with some confronting the Prince while others sneak downstairs.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-sea-prince-of-the-shore.arc", "form": "DEF", "guidance": [], "id": "#tGhOPC3ndJFPiQ770p2V7WC", "key": "Freeing the Prisoner", "name": "Freeing the Prisoner", "parent": null, "props": [], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#tGuITJbPVWfImGKUJu6Jy8c": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "adversaries/tor2e-0.5-hands-usapthon.actor", "form": "DEF", "guidance": [], "id": "#tGuITJbPVWfImGKUJu6Jy8c", "key": "Usapthon", "name": "Usapthon", "parent": null, "props": [{"name": "Name", "type": "STRING", "value": "Usapthon", "vk": "scalar"}, {"items": [{"value": "Secretive", "vk": "scalar"}, {"value": "Unsettling", "vk": "scalar"}], "name": "Distinctive Features", "of": "STRING", "vk": "list"}, {"name": "Attribute Level", "type": "INTEGER", "value": 7, "vk": "scalar"}, {"name": "Endurance", "type": "INTEGER", "value": 28, "vk": "scalar"}, {"name": "Might", "type": "INTEGER", "value": 2, "vk": "scalar"}, {"name": "Hate", "type": "INTEGER", "value": 7, "vk": "scalar"}, {"name": "Parry", "type": "STRING", "value": "+3", "vk": "scalar"}, {"name": "Armour", "type": "STRING", "value": "2", "vk": "scalar"}, {"items": [{"fields": [{"name": "Weapon", "type": "STRING", "value": "Club", "vk": "scalar"}, {"name": "Rating", "type": "INTEGER", "value": 4, "vk": "scalar"}, {"name": "Damage", "type": "INTEGER", "value": 4, "vk": "scalar"}, {"name": "Injury", "type": "INTEGER", "value": 14, "vk": "scalar"}, {"items": [{"value": "Knockback*", "vk": "scalar"}], "name": "Special Damage", "of": "STRING", "vk": "list"}, {"name": "Printed", "type": "STRING", "value": "Club 4 (4/14, Knockback)", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Weapon", "type": "STRING", "value": "Dagger", "vk": "scalar"}, {"name": "Rating", "type": "INTEGER", "value": 3, "vk": "scalar"}, {"name": "Damage", "type": "INTEGER", "value": 2, "vk": "scalar"}, {"name": "Injury", "type": "INTEGER", "value": 12, "vk": "scalar"}, {"items": [{"value": "Pierce", "vk": "scalar"}], "name": "Special Damage", "of": "STRING", "vk": "list"}, {"name": "Printed", "type": "STRING", "value": "Dagger 3 (2/12, Pierce)", "vk": "scalar"}], "vk": "def"}], "name": "Combat Proficiencies", "of": "Adversary Combat Proficiency", "ofHash": "#tor5AdvCombat000001", "vk": "list"}, {"items": [{"fields": [{"name": "Name", "type": "STRING", "value": "Combat Sorcerer", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "Usapthon can cast a Dreadful Spell in place of one of her attacks. If she does so, she can cast the spell without spending Hate.", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Name", "type": "STRING", "value": "Denizen of the Dark", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "All attack rolls are Favoured while in darkness.", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Name", "type": "STRING", "value": "Dreadful Spells: Lure of Shadow", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "Usapthon weaves a web of darkness around her victim. Spend 1 Hate to make one Player-hero gain 3 Shadow points (Sorcery). Targets who both are Miserable and fail their Shadow test suffer a Bout of Madness.", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Name", "type": "STRING", "value": "Dreadful Spells: Misfortune", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "Usapthon curses her foes with bad luck. Spend 1 Hate to make one Player-hero gain 3 Shadow points (Sorcery). Targets who fail their Shadow test or who are Miserable increase all their Attribute TNs by their Shadow score for the rest of the combat.", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Name", "type": "STRING", "value": "Fearless", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "Usapthon’s Might is considered 1 higher for the purpose of resisting the Intimidate Foe combat task.", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Name", "type": "STRING", "value": "Strike Fear", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "Spend 1 Hate to make all Player-heroes in sight gain 2 Shadow points (Dread). Those who fail their Shadow Test are daunted and cannot spend Hope for the rest of the fight.", "vk": "scalar"}], "vk": "def"}], "name": "Fell Abilities", "of": "Fell Ability", "ofHash": "#tor5FellAbility0001", "vk": "list"}], "refs": [], "slot": null, "table": null, "type": "Adversary", "typeHash": "#TOR0020000000000"}, "#tHJ52rfJ7wB92aeXuz2R5mZ": {"book": "hands", "children": [], "choices": [], "desc": "It’s likely that the Dunlendings assume Scepa is the Troll responsible for the attacks.\n\nIf the Dunlendings are outnumbered by the Player-heroes, then they just urge the Player-heroes to slay the monster, but take no action themselves.\n\nIf by some chance there are more Dunlendings than Player-heroes present, then the Player-heroes must succeed at an **AWE** roll to stay their hands (or use force to protect Scepa). Alternatively, they can **PERSUADE** them to take Scepa back to Crow Hall for judgement by Gorsad (see* Part 6: The Judgements of Gorsad*, on page 39).", "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-beast-of-dunland.arc", "form": "DEF", "guidance": [], "id": "#tHJ52rfJ7wB92aeXuz2R5mZ", "key": "Scepa and the Dunlendings", "name": "Scepa and the Dunlendings", "parent": null, "props": [], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#tHL0IAfH68fnIaVZ8cYxhdn": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "adversaries/tor2e-0.5-hands-nambar-the-sea-prince.actor", "form": "DEF", "guidance": [], "id": "#tHL0IAfH68fnIaVZ8cYxhdn", "key": "Nambar, the Sea-prince", "name": "Nambar, the Sea-prince", "parent": null, "props": [{"name": "Name", "type": "STRING", "value": "Nambar, the Sea-prince", "vk": "scalar"}, {"items": [{"value": "Arrogant", "vk": "scalar"}, {"value": "Vain", "vk": "scalar"}], "name": "Distinctive Features", "of": "STRING", "vk": "list"}, {"name": "Attribute Level", "type": "INTEGER", "value": 6, "vk": "scalar"}, {"name": "Endurance", "type": "INTEGER", "value": 24, "vk": "scalar"}, {"name": "Might", "type": "INTEGER", "value": 2, "vk": "scalar"}, {"name": "Hate", "type": "INTEGER", "value": 6, "vk": "scalar"}, {"name": "Parry", "type": "STRING", "value": "+3", "vk": "scalar"}, {"name": "Armour", "type": "STRING", "value": "4", "vk": "scalar"}, {"items": [{"fields": [{"name": "Weapon", "type": "STRING", "value": "Long Sword", "vk": "scalar"}, {"name": "Rating", "type": "INTEGER", "value": 3, "vk": "scalar"}, {"name": "Damage", "type": "INTEGER", "value": 5, "vk": "scalar"}, {"name": "Injury", "type": "INTEGER", "value": 18, "vk": "scalar"}, {"items": [{"value": "Pierce", "vk": "scalar"}], "name": "Special Damage", "of": "STRING", "vk": "list"}, {"name": "Printed", "type": "STRING", "value": "Long Sword 3 (5/18, Pierce)", "vk": "scalar"}], "vk": "def"}], "name": "Combat Proficiencies", "of": "Adversary Combat Proficiency", "ofHash": "#tor5AdvCombat000001", "vk": "list"}, {"items": [{"fields": [{"name": "Name", "type": "STRING", "value": "Fearless", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "This creature’s Might is considered 1 higher for the purpose of resisting the Intimidate Foes combat task.", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Name", "type": "STRING", "value": "Lesser Ring", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "Spend 1 Hate to either recover 6 Endurance or heal 1 Wound.", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Name", "type": "STRING", "value": "Snake-like Speed", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "When targeted by an attack, spend 1 Hate to make the attack roll Ill-favoured.", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Name", "type": "STRING", "value": "Yell of Triumph", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "Spend 1 Hate to restore 1 Hate to all allies in the fight.", "vk": "scalar"}], "vk": "def"}], "name": "Fell Abilities", "of": "Fell Ability", "ofHash": "#tor5FellAbility0001", "vk": "list"}, {"name": "Description", "type": "STRING", "value": "Nambar trained in the fighting pits and duelling schools of Umbar, and thought it was his destiny to win renown in the conquest of Gondor. Instead, he finds himself on a strange and distant shore. At first, he was furious to be given this task — he wanted to win glory in battle, not tarry with these barbarians. However, his time here has awoken some atavistic desire in him. Did the Sea-kings of old not conquer the coasts of Middle-earth? Is it not fitting that their heir rule? With every passing month, Nambar’s ego grows along with his belly and his taste for the potent spirits brewed in the tavern of Todden. He’s still a dangerous foe, especially with the power of the blue ring entrusted to him by Usapthon, but he’s grown comfortable in his role as pampered Prince.", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Adversary", "typeHash": "#TOR0020000000000"}, "#tHcofaIVvWXZSVDwXRmBurR": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [{"fields": [{"name": "Hazard", "type": "STRING", "value": "Fires burn in the deep! Smoke and hot sparks flood the chamber from below. One Player-hero suffers a grievous Endurance loss from fire.", "vk": "scalar"}, {"name": "Fatigue Points Gained", "type": "INTEGER", "value": 3, "vk": "scalar"}], "name": "[Eye of Sauron]", "vk": "def"}, {"fields": [{"name": "Hazard", "type": "STRING", "value": "Something stalks the Player-heroes. It might be a Nameless Thing from the depths, or some other terror. The creature, whatever it is, does not attack, but each Player-hero gains 2 Shadow points (Dread) as the presence looms heavily over them.", "vk": "scalar"}, {"name": "Fatigue Points Gained", "type": "INTEGER", "value": 2, "vk": "scalar"}], "name": "1", "vk": "def"}, {"fields": [{"name": "Hazard", "type": "STRING", "value": "The mountain quakes and groans, or the passage of the Player-heroes disturbs some precariously-balanced structure. One Player-hero must make a CRAFT roll to assess the condition of the tunnels: on a failure, each Player-hero is struck by falling stones, suffering a severe Endurance loss from falling.", "vk": "scalar"}, {"name": "Fatigue Points Gained", "type": "INTEGER", "value": 2, "vk": "scalar"}], "name": "2", "vk": "def"}, {"fields": [{"name": "Hazard", "type": "STRING", "value": "The darkness becomes especially oppressive for one member of the Company, driving them into despair. One Player-hero gains 2 Shadow points (Dread).", "vk": "scalar"}, {"name": "Fatigue Points Gained", "type": "INTEGER", "value": 2, "vk": "scalar"}], "name": "3", "vk": "def"}, {"fields": [{"name": "Hazard", "type": "STRING", "value": "A wandering Cave-troll Slinker snuffles past; each Player-hero must make a STEALTH roll to remain undetected.", "vk": "scalar"}, {"name": "Fatigue Points Gained", "type": "INTEGER", "value": 2, "vk": "scalar"}], "name": "4", "vk": "def"}, {"fields": [{"name": "Hazard", "type": "STRING", "value": "An Orc-snare lies waiting in the shadows. The Company’s Look-out must pass a successful AWARE- NESS roll or trigger the trap (Loremaster’s choice — either it sounds the alarm and summons Orcs, or it inflicts a severe Endurance loss from poison to one Player-hero).", "vk": "scalar"}, {"name": "Fatigue Points Gained", "type": "INTEGER", "value": 2, "vk": "scalar"}], "name": "5", "vk": "def"}, {"fields": [{"name": "Hazard", "type": "STRING", "value": "The way ahead is guarded by Orc sentries. How can the Company sneak past or silence them without raising the alarm?", "vk": "scalar"}, {"name": "Fatigue Points Gained", "type": "INTEGER", "value": 2, "vk": "scalar"}], "name": "6", "vk": "def"}, {"fields": [{"name": "Hazard", "type": "STRING", "value": "The way ahead is dangerous, requiring the Player-heroes to climb over or squeeze through an obstacle. Everyone must pass an ATHLETICS test; anyone who fails gains 1 additional Fatigue.", "vk": "scalar"}, {"name": "Fatigue Points Gained", "type": "INTEGER", "value": 2, "vk": "scalar"}], "name": "7", "vk": "def"}, {"fields": [{"name": "Hazard", "type": "STRING", "value": "A patrol of Orcs passes by. The adventurers can hide and wait for them to go past, or follow them.", "vk": "scalar"}, {"name": "Fatigue Points Gained", "type": "INTEGER", "value": 2, "vk": "scalar"}], "name": "8", "vk": "def"}, {"fields": [{"name": "Hazard", "type": "STRING", "value": "The way ahead is blocked by fallen stones or debris. Does the Company seek another route (with a TRAVEL roll), or labour to clear the path (with either CRAFT or ATHLETICS)?", "vk": "scalar"}, {"name": "Fatigue Points Gained", "type": "INTEGER", "value": 2, "vk": "scalar"}], "name": "9", "vk": "def"}, {"fields": [{"name": "Hazard", "type": "STRING", "value": "The Player-heroes risk becoming lost in the depths. The Scout must pass an EXPLORE roll to find the way, or the Company becomes delayed.", "vk": "scalar"}, {"name": "Fatigue Points Gained", "type": "INTEGER", "value": 1, "vk": "scalar"}], "name": "10", "vk": "def"}, {"fields": [{"name": "Hazard", "type": "STRING", "value": "The Company has a stroke of luck or other boon — the Orcs are distracted by some other business or feud among themselves, the Player-heroes find a shortcut or a place to shelter, or they glimpse some surviving vestige of the glories of old Moria, brightening their spirits. Everyone in the Company regains 1 Hope.", "vk": "scalar"}, {"name": "Fatigue Points Gained", "type": "STRING", "value": "—", "vk": "scalar"}], "name": "[Gandalf Rune]", "vk": "def"}], "enum": null, "file": "tor2e-0.5-hands-the-disaster-of-the-gladden-fields.arc", "form": "DEF", "guidance": [], "id": "#tHcofaIVvWXZSVDwXRmBurR", "key": "Moria Hazards", "name": "Moria Hazards", "parent": null, "props": [], "refs": [], "slot": "SCENE", "table": {"columns": ["FEAT DIE", "HAZARD", "FATIGUE POINTS GAINED"], "rows": [["[Eye of Sauron]", "Fires burn in the deep! Smoke and hot sparks flood the chamber from below. One Player-hero suffers a grievous Endurance loss from fire.", "3"], ["1", "Something stalks the Player-heroes. It might be a Nameless Thing from the depths, or some other terror. The creature, whatever it is, does not attack, but each Player-hero gains 2 Shadow points (Dread) as the presence looms heavily over them.", "2"], ["2", "The mountain quakes and groans, or the passage of the Player-heroes disturbs some precariously-balanced structure. One Player-hero must make a CRAFT roll to assess the condition of the tunnels: on a failure, each Player-hero is struck by falling stones, suffering a severe Endurance loss from falling.", "2"], ["3", "The darkness becomes especially oppressive for one member of the Company, driving them into despair. One Player-hero gains 2 Shadow points (Dread).", "2"], ["4", "A wandering Cave-troll Slinker snuffles past; each Player-hero must make a STEALTH roll to remain undetected.", "2"], ["5", "An Orc-snare lies waiting in the shadows. The Company’s Look-out must pass a successful AWARE- NESS roll or trigger the trap (Loremaster’s choice — either it sounds the alarm and summons Orcs, or it inflicts a severe Endurance loss from poison to one Player-hero).", "2"], ["6", "The way ahead is guarded by Orc sentries. How can the Company sneak past or silence them without raising the alarm?", "2"], ["7", "The way ahead is dangerous, requiring the Player-heroes to climb over or squeeze through an obstacle. Everyone must pass an ATHLETICS test; anyone who fails gains 1 additional Fatigue.", "2"], ["8", "A patrol of Orcs passes by. The adventurers can hide and wait for them to go past, or follow them.", "2"], ["9", "The way ahead is blocked by fallen stones or debris. Does the Company seek another route (with a TRAVEL roll), or labour to clear the path (with either CRAFT or ATHLETICS)?", "2"], ["10", "The Player-heroes risk becoming lost in the depths. The Scout must pass an EXPLORE roll to find the way, or the Company becomes delayed.", "1"], ["[Gandalf Rune]", "The Company has a stroke of luck or other boon — the Orcs are distracted by some other business or feud among themselves, the Player-heroes find a shortcut or a place to shelter, or they glimpse some surviving vestige of the glories of old Moria, brightening their spirits. Everyone in the Company regains 1 Hope.", "—"]]}, "type": "Table", "typeHash": "#tor5Table0000000001"}, "#tHxbujSd4Dgjspc76csfScj": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "tor2e-0.5-hands-there-let-them-lie-until-the-end.arc", "form": "DEF", "guidance": [], "id": "#tHxbujSd4Dgjspc76csfScj", "key": "– Exterior", "name": "– Exterior", "parent": null, "props": [], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#tI1x2BruIh54zxtgiEvlyPq": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "adversaries/tor2e-0.5-hands-the-beithir.actor", "form": "DEF", "guidance": [], "id": "#tI1x2BruIh54zxtgiEvlyPq", "key": "The Beithir", "name": "The Beithir", "parent": null, "props": [{"name": "Name", "type": "STRING", "value": "The Beithir", "vk": "scalar"}, {"items": [{"value": "Hungry", "vk": "scalar"}, {"value": "Stealthy", "vk": "scalar"}], "name": "Distinctive Features", "of": "STRING", "vk": "list"}, {"name": "Attribute Level", "type": "INTEGER", "value": 8, "vk": "scalar"}, {"name": "Endurance", "type": "INTEGER", "value": 80, "vk": "scalar"}, {"name": "Might", "type": "INTEGER", "value": 2, "vk": "scalar"}, {"name": "Hate", "type": "INTEGER", "value": 8, "vk": "scalar"}, {"name": "Parry", "type": "STRING", "value": "—", "vk": "scalar"}, {"name": "Armour", "type": "STRING", "value": "3", "vk": "scalar"}, {"items": [{"fields": [{"name": "Weapon", "type": "STRING", "value": "Bite", "vk": "scalar"}, {"name": "Rating", "type": "INTEGER", "value": 3, "vk": "scalar"}, {"name": "Damage", "type": "INTEGER", "value": 6, "vk": "scalar"}, {"name": "Injury", "type": "INTEGER", "value": 16, "vk": "scalar"}, {"items": [{"value": "Seize", "vk": "scalar"}], "name": "Special Damage", "of": "STRING", "vk": "list"}, {"name": "Printed", "type": "STRING", "value": "Bite 3 (6/16, Seize)", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Weapon", "type": "STRING", "value": "Stinging Tail", "vk": "scalar"}, {"name": "Rating", "type": "INTEGER", "value": 3, "vk": "scalar"}, {"name": "Damage", "type": "INTEGER", "value": 6, "vk": "scalar"}, {"name": "Injury", "type": "INTEGER", "value": 14, "vk": "scalar"}, {"items": [{"value": "Pierce", "vk": "scalar"}], "name": "Special Damage", "of": "STRING", "vk": "list"}, {"name": "Printed", "type": "STRING", "value": "Stinging Tail 3 (6/14, Pierce)", "vk": "scalar"}], "vk": "def"}], "name": "Combat Proficiencies", "of": "Adversary Combat Proficiency", "ofHash": "#tor5AdvCombat000001", "vk": "list"}, {"items": [{"fields": [{"name": "Name", "type": "STRING", "value": "Foul Slime", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "Spend 1 Hate to cause all combatants engaged with the Beithir to lose (1d) on all rolls for the round.", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Name", "type": "STRING", "value": "Hate Sunlight", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "The Beithir loses 1 Hate at the start of each round it is exposed to the full light of the sun.", "vk": "scalar"}], "vk": "def"}], "name": "Fell Abilities", "of": "Fell Ability", "ofHash": "#tor5FellAbility0001", "vk": "list"}], "refs": [], "slot": null, "table": null, "type": "Adversary", "typeHash": "#TOR0020000000000"}, "#tI6jB6hAJzmrtxJzCY6NFid": {"book": "hands", "children": [], "choices": [], "desc": "The magical flames of the Hall of Torches bar the Corsairs from penetrating deeper into the tomb. When the Lord of the Lash realises that there is a power here opposed to that of Sauron, he hastily sends runners down to the shore to summon the sorceress Usapthon from the *Kathuphazgân*. She leaves her temple on the ship, takes a rowboat to the shore, and climbs up to the tomb entrance. There, she chants prayers and makes offerings to Sauron (including the sacrifice of any captured Player-heroes or allies), then snuffs out the torches, allowing her forces to access the innermost chamber.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-there-let-them-lie-until-the-end.arc", "form": "DEF", "guidance": [], "id": "#tI6jB6hAJzmrtxJzCY6NFid", "key": "Usapthon Snuffs the Torches", "name": "Usapthon Snuffs the Torches", "parent": null, "props": [], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#tISoGUNZz2VE9kykXX8Ohtc": {"book": "hands", "children": [], "choices": [], "desc": "*— The Fellowship of the Ring™*\n\nLet’s consider, for a moment, Saruman’s perspective.\n\nHe is the head of the Order of Wizards and the leader of the White Council. To him falls the solemn duty of coordinating the efforts of all who oppose the schemes of the Dark Lord Sauron. Yet, at this time, the power of the Elves is fading. Their strength of old is gone, and many are retreating over the Sea. The time of Men is coming, but they are weak and divided. In his wisdom, Saruman approached their leaders soon after his arrival in Middle-earth, becoming first a counsellor to the Kings of Gondor and later to its Stewards. He then established his seat close to the Kingdom of Rohan and set himself the task of civilising the wild folk of Dunland.\n\nAnd then, there is Gandalf. Saruman has always been somewhat suspicious of the Grey Wizard. Mithrandir was closer in friendship to the leaders of the Elves, such as Círdan the Shipwright, Elrond, and Galadriel.\n\nSaruman suspected that these high lords and ladies might see in the Grey Pilgrim only a means to hold onto their dwindling realms — a distraction from the greater purpose of defeating Sauron. Moreover, Gandalf, it seemed to Saruman, squandered his time wandering the backroads and wild places, far from the centres of power, while the fate of Middle-earth would be determined along the fords and bridges of the Anduin and on the battlefields of Lebennin and Ithilien — and perhaps, though this was a secret thought, in the finding of a small gold ring.\n\nIn the year 2939, Saruman discovered that the Necromancer’s forces were searching the banks of the Great River, without any doubt looking for the long-lost One Ring. The time had come for action! In 2941, the White Council under Saruman assaulted the Necromancer’s stronghold at Dol Guldur, and drove the Enemy back to his old fortress in Mordor. Saruman knew that this temporary victory only signalled the coming of a Great War — deprived of any hope of recovering the Ruling Ring, Sauron would have to rely solely on force of arms. It would be a bloody, grinding and terrible war, certainly filled with many defeats and sacrifices, but there was a chance of inflicting a second, final defeat on the Enemy.\n\nBut that same year came news from the North that the Dragon of Erebor had been defeated. The Kingdom under the Mountain was restored, the city of Dale rebuilt, the Goblins of the Misty Mountains slaughtered, and friendship forged in battle between Elf, Dwarf, and Man — and all agreed that Gandalf the Grey had a hand in it! What Saruman had dismissed as chance-meetings and Gandalf’s time-wasting had suddenly crystallised into a resounding success for the Grey Wizard.\n\nThis — this was tantamount to treachery! Why had Gandalf not sought approval for this plan? Why had he consulted with Elrond and not Saruman?\n\nClearly, not even the other members of the White Council could be trusted. By the year 2953, Saruman resolved to rely almost exclusively on his own forces, hiring agents and spies to further his designs.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-introduction.ttrpg", "form": "DEF", "guidance": [], "id": "#tISoGUNZz2VE9kykXX8Ohtc", "key": "Saruman the White", "name": "Saruman the White", "parent": null, "props": [{"items": [{"value": "“Hobbits are, or were, no concern of his. Yet he is great among the Wise.", "vk": "scalar"}, {"value": "He is the chief of my Order and head of the council.”", "vk": "scalar"}, {"value": "Saruman", "vk": "scalar"}], "name": "Epigraphs", "of": "STRING", "vk": "list"}], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#tImYSIFxd50fwJpSNMmQJBI": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-sea-prince-of-the-shore.arc", "form": "DEF", "guidance": [], "id": "#tImYSIFxd50fwJpSNMmQJBI", "key": "Rumour", "name": "Rumour", "parent": null, "props": [], "refs": [], "slot": "PHASE", "table": null, "type": null, "typeHash": null}, "#tJqc068EbHQuvQTbmu3Hqbj": {"book": "hands", "children": [], "choices": [], "desc": "Made of a black gleaming stone that looks as though it was hewn from a single block instead of built, the tower of Orthanc is among the greatest works of the masons and architects of Gondor. The secrets of its making were lost long ago, and no living craftsman knows how to make imperishable stone, nor build so high a tower. Twenty-seven steps rise from the ground to the main entrance, and that is blocked by a gate of metal and stone that can only be opened by the right key within the tower — who can say? It was locked for centuries until the key was entrusted to Saruman, and few have entered it since. Once, it held apartments and audience halls for the Lord of Isengard, chambers for customs officials and tax collectors and heralds and messengers in the service of the King, armouries and archives for the western provinces. On the upper levels was an observatory, where learned scholars watched the stars and recorded the changing seasons.\n\nNow, only Saruman and his most trusted servants dwell within Orthanc. Visitors may get to see the entrance hall and the audience chamber on the lowest level, but the rest of the tower is a secret shared with very few.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-introduction.ttrpg", "form": "DEF", "guidance": [], "id": "#tJqc068EbHQuvQTbmu3Hqbj", "key": "1. Orthanc", "name": "1. Orthanc", "parent": "#tcMxywq75NOL2ves69gurzl", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#tJqkGmZepj96Nvvd2aVhdw8": {"book": "hands", "children": [], "choices": [], "desc": "The Dimrill Gate is guarded by Gorgol’s troops. By night, there are **Goblin Archers** and scouts throughout the Dale, but the gate itself is surprisingly unwatched, as the sentries are more focussed on watching for would-be escapees from *within* instead of enemies from *without*; sneaking in requires a **STEALTH** roll, and the Player-heroes *lose (1d)* unless they have some way to distract or eliminate the archers.\n\nBy day, a Watch-troll named **Pestle** is stationed just inside the shadow of the gates, wielding a club decorated with many bells so it sounds the alarm even as it’s beating intruders to a fine paste. Sneaking past him requires a simple **STEALTH** roll; if failed, the Player-heroes must fight him — a **Cave-troll Slinker** (see *The One Ring*, page 152). If you’re using the Eye Awareness rules, every time Pestle attacks with his Club he also raises the Eye Awareness of the Company by 1.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-quest-of-moria.arc", "form": "DEF", "guidance": [], "id": "#tJqkGmZepj96Nvvd2aVhdw8", "key": "The East-gate", "name": "The East-gate", "parent": null, "props": [], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#tJwX1ZVLYW88oRwwcgZkkD3": {"book": "hands", "children": [], "choices": [], "desc": "The best use of the Host is to send it to sow chaos in the Númenórean camp, drawing enemies away from either the ship or the Tomb of the Admiral. The aim here is not to defeat the forces of Umbar, but to draw their attention away from the Company.\n\nWhile the battle in the camp is ongoing, the Player-heroes do not need to make **STEALTH** tests to move around. However, without the Player-heroes’ help, the Host—despite inflicting heavy losses on the enemy forces—is doomed not to survive the battle.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-there-let-them-lie-until-the-end.arc", "form": "DEF", "guidance": [], "id": "#tJwX1ZVLYW88oRwwcgZkkD3", "key": "Distracting the Enemy", "name": "Distracting the Enemy", "parent": null, "props": [], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#tK37ZBmIFklDcVMfPcLXfLh": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [{"fields": [{"name": "Encounter", "type": "STRING", "value": "A Strange Encounter: In the dead of night, a bizarre creature — man-shaped, but only half-high, like an emaciated child — crawls onto the boat. It sneaks around and steals food and one or two useful items, muttering to itself: “*gol-* *lum, gollum*.” A successful AWARENESS roll from the Look-outs disturbs the creature before it steals anything; it slips over the rail and swims away.", "vk": "scalar"}], "name": "[Eye of Sauron]", "vk": "def"}, {"fields": [{"name": "Encounter", "type": "STRING", "value": "Eerie Willows: The Company encounter a stand of twisted willow trees. There is an unsettling air to the place; each Player-hero gains 1 Shadow point (Dread). The island vanishes the next morning.", "vk": "scalar"}], "name": "1", "vk": "def"}, {"fields": [{"name": "Encounter", "type": "STRING", "value": "Fierce Storms: Wild winds roar down from the north, tossing the river. Each Player-hero must make an ATHLETICS roll; those who fail suffer a moderate Endurance loss from extreme cold.", "vk": "scalar"}], "name": "2", "vk": "def"}, {"fields": [{"name": "Encounter", "type": "STRING", "value": "Tangling Roots: Strangely long roots from trees grab at the boat. If the Player-heroes have the friendship of an Ent like Lightroot, the roots release the boat; otherwise, they must be hewed apart, delaying passage by a day and causing everyone in the Company to gain 1 Fatigue.", "vk": "scalar"}], "name": "3", "vk": "def"}, {"fields": [{"name": "Encounter", "type": "STRING", "value": "Leaking Timbers: The boat starts to leak. A CRAFT roll repairs the leak; otherwise, the boat must be abandoned before the Player-heroes reach their destination.", "vk": "scalar"}], "name": "5", "vk": "def"}, {"fields": [{"name": "Encounter", "type": "STRING", "value": "Miserable Weather: Heavy rain, cold winds, and the unchanging landscape prey on the Company’s mood. Each Player-hero gains 1 Fatigue.", "vk": "scalar"}], "name": "4", "vk": "def"}, {"fields": [{"name": "Encounter", "type": "STRING", "value": "Herdsmen Watering Their Flocks: The boat passes a group of Rohirrim herdsmen and their flocks of sheep or cattle. The herdsmen hail the boat. A RIDDLE roll is required to allay suspicion; failing increases the Eye Awareness of the Company by 1.", "vk": "scalar"}], "name": "6", "vk": "def"}, {"fields": [{"name": "Encounter", "type": "STRING", "value": "A Body in the Water: A corpse floats by the boat. Roll a Success die: on a 1, the corpse is too rotten to tell; on a 2–3, he was a Dunlending Raider; on a 4–5, he was a Rohirrim peasant; on a 6, he was a Rider of Rohan.", "vk": "scalar"}], "name": "7", "vk": "def"}, {"fields": [{"name": "Encounter", "type": "STRING", "value": "Fair Weather: Sunlight and fair winds make the journey pleasant, even tranquil. The urgency of their mission fades away.", "vk": "scalar"}], "name": "8", "vk": "def"}, {"fields": [{"name": "Encounter", "type": "STRING", "value": "Traders on the River: The Company encounter another river-boat; a travelling merchant trading in tools and trinkets. The Player-heroes may each obtain 1 useful item if they have coin to spare.", "vk": "scalar"}], "name": "9", "vk": "def"}, {"fields": [{"name": "Encounter", "type": "STRING", "value": "Spears in the Sun: In the distance, the Player-heroes glimpse a company of riders of Rohan, their polished spears flashing in the sun. They are young and brave and handsome, signifying hope for the coming Age of Men.", "vk": "scalar"}], "name": "10", "vk": "def"}, {"fields": [{"name": "Encounter", "type": "STRING", "value": "A Dream of Better Days: The Player-heroes have a strangely vivid dream while sailing down the river. They imagine all the days of their life as tableaus on the banks of the river. Ahead is a region of darkness, but on the far side, they can glimpse the silver of the river and a green, bright country. Everyone in the Company regains 1 Hope.", "vk": "scalar"}], "name": "[Gandalf Rune]", "vk": "def"}], "enum": null, "file": "tor2e-0.5-hands-the-ithil-stone.arc", "form": "DEF", "guidance": [], "id": "#tK37ZBmIFklDcVMfPcLXfLh", "key": "Encounters on the Open River", "name": "Encounters on the Open River", "parent": null, "props": [], "refs": [], "slot": "SCENE", "table": {"columns": ["FEAT DIE", "ENCOUNTER"], "rows": [["[Eye of Sauron]", "A Strange Encounter: In the dead of night, a bizarre creature — man-shaped, but only half-high, like an emaciated child — crawls onto the boat. It sneaks around and steals food and one or two useful items, muttering to itself: “*gol-* *lum, gollum*.” A successful AWARENESS roll from the Look-outs disturbs the creature before it steals anything; it slips over the rail and swims away."], ["1", "Eerie Willows: The Company encounter a stand of twisted willow trees. There is an unsettling air to the place; each Player-hero gains 1 Shadow point (Dread). The island vanishes the next morning."], ["2", "Fierce Storms: Wild winds roar down from the north, tossing the river. Each Player-hero must make an ATHLETICS roll; those who fail suffer a moderate Endurance loss from extreme cold."], ["3", "Tangling Roots: Strangely long roots from trees grab at the boat. If the Player-heroes have the friendship of an Ent like Lightroot, the roots release the boat; otherwise, they must be hewed apart, delaying passage by a day and causing everyone in the Company to gain 1 Fatigue."], ["5", "Leaking Timbers: The boat starts to leak. A CRAFT roll repairs the leak; otherwise, the boat must be abandoned before the Player-heroes reach their destination."], ["4", "Miserable Weather: Heavy rain, cold winds, and the unchanging landscape prey on the Company’s mood. Each Player-hero gains 1 Fatigue."], ["6", "Herdsmen Watering Their Flocks: The boat passes a group of Rohirrim herdsmen and their flocks of sheep or cattle. The herdsmen hail the boat. A RIDDLE roll is required to allay suspicion; failing increases the Eye Awareness of the Company by 1."], ["7", "A Body in the Water: A corpse floats by the boat. Roll a Success die: on a 1, the corpse is too rotten to tell; on a 2–3, he was a Dunlending Raider; on a 4–5, he was a Rohirrim peasant; on a 6, he was a Rider of Rohan."], ["8", "Fair Weather: Sunlight and fair winds make the journey pleasant, even tranquil. The urgency of their mission fades away."], ["9", "Traders on the River: The Company encounter another river-boat; a travelling merchant trading in tools and trinkets. The Player-heroes may each obtain 1 useful item if they have coin to spare."], ["10", "Spears in the Sun: In the distance, the Player-heroes glimpse a company of riders of Rohan, their polished spears flashing in the sun. They are young and brave and handsome, signifying hope for the coming Age of Men."], ["[Gandalf Rune]", "A Dream of Better Days: The Player-heroes have a strangely vivid dream while sailing down the river. They imagine all the days of their life as tableaus on the banks of the river. Ahead is a region of darkness, but on the far side, they can glimpse the silver of the river and a green, bright country. Everyone in the Company regains 1 Hope."]]}, "type": "Table", "typeHash": "#tor5Table0000000001"}, "#tKEU06MCRosbBsUUhUDaPHJ": {"book": "hands", "children": [], "choices": [], "desc": "In the distance, the Player-heroes spot smoke from a campfire. This is the camp of Toirlas and his war-band, slowly returning from their raid on Rohan (see *Toirlas*, on page 34).", "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-beast-of-dunland.arc", "form": "DEF", "guidance": [], "id": "#tKEU06MCRosbBsUUhUDaPHJ", "key": "The Trail to Toirlas", "name": "The Trail to Toirlas", "parent": null, "props": [], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#tKtljuLsYdJZENKDFSJ9JLZ": {"book": "hands", "children": [], "choices": [], "desc": "What do the Player-heroes do with Minon? If he has reason to trust the Company, he says he is bound for Rivendell and the healing arts of Master Elrond. He then asks the Player-heroes to help him reach there, or at least to find some of his Ranger kinfolk who can aid him.\n\nPossible options include:\n\n*If the Company chooses this path, they will run into the Black Númenórean company on their next journey — possibly as fellow-travellers on the road.*\n\n*If the Company chooses this path, then they are stalked by the Black Númenórean spies on the way.*\n\nfrom the *Long-expected Party*, and getting restless), Gandalf, or Tom Bombadil. If the Player-heroes are closely aligned with Saruman, they know **Midgewater Meg**, his current agent in Bree, and they can go to her for help.\n\n*If the Company chooses this option, then whoever they seek out can aid Minon while they decide what to do next.*", "entries": [], "enum": null, "file": "tor2e-0.5-hands-there-let-them-lie-until-the-end.arc", "form": "DEF", "guidance": [], "id": "#tKtljuLsYdJZENKDFSJ9JLZ", "key": "The Course from Bree", "name": "The Course from Bree", "parent": null, "props": [{"items": [{"value": "**Leave Him in Bree:** If the Player-heroes have no strong connection to Minon, they might be tempted to just leave him to recuperate in the Pony. Abandoning Minon in his time of need is a Misdeed worth 1 Shadow point.", "vk": "scalar"}, {"value": "**Set Out for Rivendell:** Rivendell is the best part of three weeks away — assuming the Player-heroes know the way there, and that Minon is healthy enough to travel. This is Minon’s preferred option, as he hopes he will encounter fellow Rangers on the way.", "vk": "scalar"}, {"value": "**Seek Aid Nearby:** Player-heroes familiar with the region may decide to look for help. Minon weakly argues against this — Gandalf has urged the Rangers to keep watch on the Shire, and worries that the attack on him was a deliberate distraction to draw sentries away. The Player-heroes may overrule him, or seek out nearby patrons like Bilbo (only a few years away", "vk": "scalar"}, {"value": "**Hunt the Attackers:** Vengeful Player-heroes may decide that the attackers know more of this strange poison, and that the best way to heal Minon is to hunt them down.", "vk": "scalar"}], "name": "Items", "of": "STRING", "vk": "list"}], "refs": [], "slot": "PHASE", "table": null, "type": null, "typeHash": null}, "#tKxDnQmGjaye3G8q8eX33MP": {"book": "hands", "children": [], "choices": [], "desc": "Isengard has a small population of soldiers and farmers who see the White Wizard as their legitimate lord. The following is a list of the characters that the Player-heroes are most likely to have dealings with, but the Loremaster may create others according to need to turn Isengard into a living and useful location, or possibly a Haven for the Company.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-introduction.ttrpg", "form": "DEF", "guidance": [{"concerns": [{"hash": "#tKxDnQmGjaye3G8q8eX33MP", "name": "The Folk of Isengard"}], "id": "#tM78XccT0TGrjXTesFcP0xr", "name": "Ruins of the Lost Realm", "text": "*The Ruins of the Lost Realm* supplement presents a number of additional characters that can be met in Isengard: Frecana, the Dunlending Princess, and Drustan the Mercenary (both on page 42 of that publication), or Woleth of Orthanc (page 61). So too might old Arcinyas the Healer (page 41) — but he gets sent back to his old haunts in the Gladden Fields a few years before the events of *The Disas- ter of the Gladden Fields* (see page 58).", "topics": []}], "id": "#tKxDnQmGjaye3G8q8eX33MP", "key": "The Folk of Isengard", "name": "The Folk of Isengard", "parent": "#t5mXLkdNrxFIXVCfT0kUbiu", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#tLDy0HBJ5OJkESN2F8Yzted": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "adversaries/tor2e-0.5-hands-snow-troll.actor", "form": "DEF", "guidance": [], "id": "#tLDy0HBJ5OJkESN2F8Yzted", "key": "Snow-Troll", "name": "Snow-Troll", "parent": null, "props": [{"name": "Name", "type": "STRING", "value": "Snow-Troll", "vk": "scalar"}, {"items": [{"value": "Fierce", "vk": "scalar"}, {"value": "Stealthy", "vk": "scalar"}], "name": "Distinctive Features", "of": "STRING", "vk": "list"}, {"name": "Attribute Level", "type": "INTEGER", "value": 9, "vk": "scalar"}, {"name": "Endurance", "type": "INTEGER", "value": 70, "vk": "scalar"}, {"name": "Might", "type": "INTEGER", "value": 2, "vk": "scalar"}, {"name": "Hate", "type": "INTEGER", "value": 9, "vk": "scalar"}, {"name": "Parry", "type": "STRING", "value": "—", "vk": "scalar"}, {"name": "Armour", "type": "STRING", "value": "3", "vk": "scalar"}, {"items": [{"fields": [{"name": "Weapon", "type": "STRING", "value": "Bite", "vk": "scalar"}, {"name": "Rating", "type": "INTEGER", "value": 3, "vk": "scalar"}, {"name": "Damage", "type": "INTEGER", "value": 6, "vk": "scalar"}, {"name": "Injury", "type": "INTEGER", "value": 14, "vk": "scalar"}, {"items": [{"value": "Pierce", "vk": "scalar"}], "name": "Special Damage", "of": "STRING", "vk": "list"}, {"name": "Printed", "type": "STRING", "value": "Bite 3 (6/14, Pierce)", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Weapon", "type": "STRING", "value": "Crush", "vk": "scalar"}, {"name": "Rating", "type": "INTEGER", "value": 3, "vk": "scalar"}, {"name": "Damage", "type": "INTEGER", "value": 6, "vk": "scalar"}, {"name": "Injury", "type": "INTEGER", "value": 12, "vk": "scalar"}, {"items": [{"value": "Seize", "vk": "scalar"}], "name": "Special Damage", "of": "STRING", "vk": "list"}, {"name": "Printed", "type": "STRING", "value": "Crush 3 (6/12, Seize)", "vk": "scalar"}], "vk": "def"}], "name": "Combat Proficiencies", "of": "Adversary Combat Proficiency", "ofHash": "#tor5AdvCombat000001", "vk": "list"}, {"items": [{"fields": [{"name": "Name", "type": "STRING", "value": "Dull-witted", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "Player-heroes can attempt a special combat task against the creature while in Forward stance. The acting player makes a RIDDLE roll as the main action for the round: on a success, the Troll loses 1 point of Hate, plus 1 point for each Success icon ( [Success] ) rolled.", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Name", "type": "STRING", "value": "Fear of Fire", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "The creature loses 1 Hate at the start of each round it is engaged in close combat with an adversary wielding a torch or other burning item.", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Name", "type": "STRING", "value": "Fierce", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "Spend 1 Hate point to gain (1d) on an attack roll and make it Favoured.", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Name", "type": "STRING", "value": "Hideous Toughness", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "The creature is unaffected by unarmed attacks. Additionally, when an attack inflicts damage to the creature that would cause it to go to zero Endurance, it causes a Piercing Blow instead. Then, if the creature is still alive its Endurance score is set back at half its maximum rating.", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Name", "type": "STRING", "value": "Horrible Strength", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "If the creature scores a Piercing Blow, spend 1 Hate to make the target’s Protection roll Ill-favoured.", "vk": "scalar"}], "vk": "def"}], "name": "Fell Abilities", "of": "Fell Ability", "ofHash": "#tor5FellAbility0001", "vk": "list"}], "refs": [], "slot": null, "table": null, "type": "Adversary", "typeHash": "#TOR0020000000000"}, "#tLqt0PxPg8vUaGvWbKlpq45": {"book": "hands", "children": [], "choices": [], "desc": "If the Player-heroes don’t tell Caelur where they’re going, she calls after them as they head north, and tells them that they will find little welcome in Dunland, but that Gorsad of Crow Hall is more hospitable than most. If they do tell her, Caelur says she has visited Crow Hall before and shares some gossip.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-beast-of-dunland.arc", "form": "DEF", "guidance": [], "id": "#tLqt0PxPg8vUaGvWbKlpq45", "key": "Tales of Crow Hall", "name": "Tales of Crow Hall", "parent": null, "props": [{"items": [{"value": "Gorsad is chieftain at Crow Hall; he is known for wit and wisdom. There is a man who appreciates a poet! In his youth, he was a skilled warrior, but in recent years he has suffered from various indignities and infirmities, and is old before his time.", "vk": "scalar"}, {"value": "His son is Toirlas; he lacks his father’s polish, and is quick to take offence at any slight. Be wary of him.", "vk": "scalar"}, {"value": "He has a daughter too, Vila, but she is not yet of age.", "vk": "scalar"}, {"value": "Dunrach and his sister Dunwalla are also important figures in Crow Hall; Dunrach leads the chieftain’s guard, and Dunwalla is said to be a witch. They are cousins of Gorsad. If Toirlas perishes without an heir, it will be Dunrach who inherits the chieftainship (or has best claim on it — the Dunlendings have various rites of challenge, so the lordship does not always pass smoothly to the next heir.)", "vk": "scalar"}, {"value": "Beyond the intrigue in the council chamber, Caelur says that Crow Hall is stout-walled and well situated — it’s a good place to rest.", "vk": "scalar"}], "name": "Items", "of": "STRING", "vk": "list"}], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#tNEPdxJeIDn0Iwmw3m8aDrb": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "adversaries/tor2e-0.5-hands-heledirien.actor", "form": "DEF", "guidance": [], "id": "#tNEPdxJeIDn0Iwmw3m8aDrb", "key": "Heledirien", "name": "Heledirien", "parent": null, "props": [{"name": "Name", "type": "STRING", "value": "Heledirien", "vk": "scalar"}, {"items": [{"value": "Fierce", "vk": "scalar"}, {"value": "True-hearted", "vk": "scalar"}], "name": "Distinctive Features", "of": "STRING", "vk": "list"}, {"name": "Attribute Level", "type": "INTEGER", "value": 7, "vk": "scalar"}, {"name": "Endurance", "type": "INTEGER", "value": 28, "vk": "scalar"}, {"name": "Might", "type": "INTEGER", "value": 1, "vk": "scalar"}, {"name": "Resolve", "type": "INTEGER", "value": 7, "vk": "scalar"}, {"name": "Parry", "type": "STRING", "value": "+1", "vk": "scalar"}, {"name": "Armour", "type": "STRING", "value": "3", "vk": "scalar"}, {"items": [{"fields": [{"name": "Weapon", "type": "STRING", "value": "Spear", "vk": "scalar"}, {"name": "Rating", "type": "INTEGER", "value": 3, "vk": "scalar"}, {"name": "Damage", "type": "INTEGER", "value": 4, "vk": "scalar"}, {"name": "Injury", "type": "INTEGER", "value": 16, "vk": "scalar"}, {"items": [{"value": "Pierce", "vk": "scalar"}], "name": "Special Damage", "of": "STRING", "vk": "list"}, {"name": "Printed", "type": "STRING", "value": "Spear 3 (4/16, Pierce)", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Weapon", "type": "STRING", "value": "Great Bow", "vk": "scalar"}, {"name": "Rating", "type": "INTEGER", "value": 3, "vk": "scalar"}, {"name": "Damage", "type": "INTEGER", "value": 4, "vk": "scalar"}, {"name": "Injury", "type": "INTEGER", "value": 16, "vk": "scalar"}, {"items": [{"value": "Pierce", "vk": "scalar"}], "name": "Special Damage", "of": "STRING", "vk": "list"}, {"name": "Printed", "type": "STRING", "value": "Great Bow 3 (4/16, Pierce)", "vk": "scalar"}], "vk": "def"}], "name": "Combat Proficiencies", "of": "Adversary Combat Proficiency", "ofHash": "#tor5AdvCombat000001", "vk": "list"}, {"items": [{"fields": [{"name": "Name", "type": "STRING", "value": "Fearless", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "Heledirien’s Might is considered 1 higher for the purpose of resisting the Intimidate Foes combat task.", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Name", "type": "STRING", "value": "Wind-like Speed", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "When targeted by an attack, spend 1 Resolve to make the attack roll Ill-favoured.", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Name", "type": "STRING", "value": "Yell of Triumph", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "Spend 1 Resolve to restore 1 Resolve to all allies in the fight.", "vk": "scalar"}], "vk": "def"}], "name": "Fell Abilities", "of": "Fell Ability", "ofHash": "#tor5FellAbility0001", "vk": "list"}, {"name": "Description", "type": "STRING", "value": "Her kinfolk have dwelt in Ithilien since long before Elendil came over the sea. She fiercely loves the dryad loveliness of Ithilien, so she volunteered for the Rangers when she came of age. She takes every Orc trespass as a personal affront, making her seem blood-thirsty compared to the more restrained knights of the Tower. However, she can be soft-hearted too — she protects those who still dwell in Ithilien in defiance of the Steward’s command. How can she do otherwise? She understands all too well their desire to dwell in this beautiful land.", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Adversary", "typeHash": "#TOR0020000000000"}, "#tNFZnhWFzOFLWiXIiGTAkRc": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "adversaries/tor2e-0.5-hands-lightroot.actor", "form": "DEF", "guidance": [], "id": "#tNFZnhWFzOFLWiXIiGTAkRc", "key": "Lightroot", "name": "Lightroot", "parent": null, "props": [{"name": "Name", "type": "STRING", "value": "Lightroot", "vk": "scalar"}, {"items": [{"value": "Eager", "vk": "scalar"}, {"value": "Wary", "vk": "scalar"}], "name": "Distinctive Features", "of": "STRING", "vk": "list"}, {"name": "Attribute Level", "type": "INTEGER", "value": 8, "vk": "scalar"}, {"name": "Endurance", "type": "INTEGER", "value": 60, "vk": "scalar"}, {"name": "Might", "type": "INTEGER", "value": 2, "vk": "scalar"}, {"name": "Resolve", "type": "INTEGER", "value": 8, "vk": "scalar"}, {"name": "Parry", "type": "STRING", "value": "—", "vk": "scalar"}, {"name": "Armour", "type": "STRING", "value": "3", "vk": "scalar"}, {"items": [{"fields": [{"name": "Weapon", "type": "STRING", "value": "Crush", "vk": "scalar"}, {"name": "Rating", "type": "INTEGER", "value": 3, "vk": "scalar"}, {"name": "Damage", "type": "INTEGER", "value": 8, "vk": "scalar"}, {"name": "Injury", "type": "INTEGER", "value": 12, "vk": "scalar"}, {"items": [{"value": "Seize", "vk": "scalar"}], "name": "Special Damage", "of": "STRING", "vk": "list"}, {"name": "Printed", "type": "STRING", "value": "Crush 3 (8/12, Seize)", "vk": "scalar"}], "vk": "def"}], "name": "Combat Proficiencies", "of": "Adversary Combat Proficiency", "ofHash": "#tor5AdvCombat000001", "vk": "list"}, {"items": [{"fields": [{"name": "Name", "type": "STRING", "value": "Fear of Fire", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "Lightroot loses 1 Resolve at the start of each round he is engaged in close combat with an adversary wielding a torch or other burning item.", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Name", "type": "STRING", "value": "Great Strength", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "If Lightroot scores a Piercing Blow, spend 1 Resolve to make the target’s Protection roll Ill-favoured.", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Name", "type": "STRING", "value": "Mighty Toughness", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "Lightroot is unaffected by unarmed attacks. Additionally, when an attack inflicts damage to Lightroot that would cause him to go to zero Endurance, it causes a Piercing Blow instead. Then, if Lightroot is still alive his Endurance score is set back at half its maximum rating.", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Name", "type": "STRING", "value": "Thick Bark", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "Spend 1 Resolve point to gain (2d) on a Protection roll.", "vk": "scalar"}], "vk": "def"}], "name": "Fell Abilities", "of": "Fell Ability", "ofHash": "#tor5FellAbility0001", "vk": "list"}], "refs": [], "slot": null, "table": null, "type": "Adversary", "typeHash": "#TOR0020000000000"}, "#tNZWrRIk1IbzXlHF1lHvc8P": {"book": "hands", "children": [], "choices": [], "desc": "The Company’s Patron likely knows Saruman, and could send the Player-heroes to help the White Wizard when he is in need of adventurers.\n\nOf the Patrons described in *The One Ring* rulebook:\n\nIf the Player-heroes are suspicious, or if they have already had dealings with some of Saruman’s more dubious servants, they might even be sent as double agents, tasked with reporting on Saruman’s activities by a more trustworthy Patron. Either way, any doubts the Wise may harbour about the White Wizard do not pertain to his loyalty to the cause of the Free Peoples, but rather to his dealings with allies that are not always reliable, such as the Dunlendings and the various spies and agents he keeps throughout Middle-earth (see *Chapter 1: The Beast of Dunland*, or *The White Hand of Saruman* in *Ruins of the Lost Realm*).", "entries": [], "enum": null, "file": "tor2e-0.5-hands-introduction.ttrpg", "form": "DEF", "guidance": [{"concerns": [{"hash": "#tNZWrRIk1IbzXlHF1lHvc8P", "name": "Sent by a Patron"}], "id": "#tUNBcWCVwhwZR6wxaOp67Pu", "name": "Treachery Revealed", "text": "If the Player-heroes are sent to spy on Saruman by another patron, then it’s possible that, at some point over the course of the campaign, their true purpose might be discovered by Saruman. Maybe the Player-heroes give themselves away through some foolish words, or Saruman’s spies spot them talking to their Patron — or one of the Player-heroes confesses to the White Wizard.\n\nThe campaign can continue even after this revelation; Saruman pretends to be magnanimous and forgiving. He\n\nsighs wearily. *“Things are now moving that will require the union of all our strengths, and we must forgive the doubts of small and fearful minds. I do not blame you — you were led astray by those who should have known better. Nor shall I banish you from my service, for I have need of your courage. We have work to do.”* Saruman even permits Player-heroes to report back to their Patrons.\n\nInwardly, Saruman seethes. Increase his Shadow score by 3 (see below).", "topics": []}], "id": "#tNZWrRIk1IbzXlHF1lHvc8P", "key": "Sent by a Patron", "name": "Sent by a Patron", "parent": "#t5xZuLwtFQZcV29V8Xh7kkK", "props": [{"items": [{"value": "Círdan, Gandalf and Gilraen have all met Saruman, and might send the Player-heroes to him. Gilraen has no reason to suspect Saruman of any malice; an **INSIGHT** roll when speaking to Círdan or Gandalf might detect the tiniest spark of doubt in their hearts.", "vk": "scalar"}, {"value": "Bilbo or Balin know Saruman only by distant reputation as the greatest lore-master in this age of the world.", "vk": "scalar"}, {"value": "Tom Bombadil probably met Saruman at some point, but the two certainly don’t get on.", "vk": "scalar"}], "name": "Items", "of": "STRING", "vk": "list"}], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#tO8sdt0sdV7bBZeLbqTqpQK": {"book": "hands", "children": [], "choices": [], "desc": "If Gorsad is given Saruman’s medicine (correctly prepared), his pain is eased and he moves more easily. This brings cheer to the warriors of the Hall — but not to Dunrach and Dunwalla. A successful **INSIGHT** roll catches them glancing worriedly at one another.\n\nIf the Player-heroes gave the silver box to either Dunwalla or Dunrach, then Dunwalla takes the vial of medicine and hides it in her shrine.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-beast-of-dunland.arc", "form": "DEF", "guidance": [], "id": "#tO8sdt0sdV7bBZeLbqTqpQK", "key": "The Healing of Gorsad", "name": "The Healing of Gorsad", "parent": null, "props": [], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#tOL9oVXAPAKSTsuWfjWQFnI": {"book": "hands", "children": [], "choices": [], "desc": "The *Kathuphazgân* is a massive ship, a floating fortress — although, given the shallowness of the water here, she is only really floating on a good day. She has four decks, as well as a forecastle. With most of her crew and cargo unloaded onto the shore, she’s eerily cavernous and deserted.\n\nMoving around the ship requires **STEALTH** rolls; these rolls *lose (2d)* if the Ent Lightroot is with the Player-heroes. While there are plenty of places to hide, the quarters are so close that strangers are easily noticed unless they are heavily disguised. If the Player-heroes are spotted, the sentries alert the nearest Key Foe (see page 86) to investigate the intrusion.\n\nKey locations on board include:", "entries": [], "enum": null, "file": "tor2e-0.5-hands-there-let-them-lie-until-the-end.arc", "form": "DEF", "guidance": [], "id": "#tOL9oVXAPAKSTsuWfjWQFnI", "key": "Exploring the Black Ship", "name": "Exploring the Black Ship", "parent": null, "props": [{"items": [{"value": "**Usapthon’s Temple:** Located on the topmost deck, this chamber is where Usapthon worships Morgoth and practises her dark rites. It is a dreadful place — those who enter gain 3 Shadow points (Dread). Those who fail their Shadow test or who are Miserable are unable to cross the threshold.", "vk": "scalar"}, {"value": "**The Armoury:** While most of the equipment and war gear have been removed to the shore, the ship’s armoury still holds Corsair mail and swords — if the Player-heroes wish to disguise themselves as armed members of the crew, they can do so here.", "vk": "scalar"}, {"value": "**The Map Room:** This cramped room holds copies of ancient Gondorian maps of Eriador — and a more recent map, describing the explorations of the *Kathuphazgân*. There are copies of old books, including histories of the Admiral (see below). There is lore here that has been locked away in the archives of Umbar since the Kin-strife (lore that Saruman covets — if the Player-heroes are able to salvage any of it, the Wizard will reward them.)", "vk": "scalar"}, {"value": "**The Treasury:** Located in the bowels of the ship, locked away behind doors of steel — is a vast fortune. It is a Greater Hoard, with lots of Precious Objects.", "vk": "scalar"}, {"value": "**The Lowest Hold:** This is the best place to place Saruman’s blasting powder — right next to a storeroom containing barrels of potent alcoholic spirits.", "vk": "scalar"}], "name": "Items", "of": "STRING", "vk": "list"}], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#tPExYVVfffbh9WRrROyQfid": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "tor2e-0.5-hands-introduction.ttrpg", "form": "DEF", "guidance": [], "id": "#tPExYVVfffbh9WRrROyQfid", "key": "Rumour", "name": "Rumour", "parent": "#t5mXLkdNrxFIXVCfT0kUbiu", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#tPK7DygrPTOnOMdA5DzExRW": {"book": "hands", "children": [], "choices": [], "desc": "Depending on how the Player-heroes approach the situation, events may play out in many different ways. The Loremaster should use the information below to portray the Prince and determine his actions and what the players might learn through conversation, eavesdropping or force.\n\nNambar presents himself not as a conqueror or monarch, but as a healer and guardian, claiming to have been sent out of the Sea by the ‘King of Middle-earth’ to defend the good and the faithful. He can only stay on the shore for a year and a day, and then he must return to the sea — but he will return again, in time, and set the world to rights.\n\nThe Prince, at least initially, cuts a rather noble figure — he’s of Númenorean blood after all. Moreover, he plays on half-forgotten memories of the greatness of the kings of old, and vague prophecies about better times to come. To the average inhabitant of north-western Middle-earth he feels fey and other-worldly. He also acts older than he actually is.\n\nIf he can, the Prince seeks to learn who the Player-heroes serve, and if they know anything of the great lords and strongholds west of the Misty Mountains. His primary goal is finding Rivendell, but the Corsairs also seek knowledge of potential allies and enemies in the war to come. He may even try to seduce weak-willed Player-heroes into the service of Umbar.\n\nIf the Player-heroes speak of hearing a strange song while approaching the tower, he references the tale of the Singer on the Shore to dispel any suspicion.\n\nIf threatened or confronted, the Prince flees, hoping to escape back to Todden and hide there until the Black Ship returns for him.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-sea-prince-of-the-shore.arc", "form": "DEF", "guidance": [], "id": "#tPK7DygrPTOnOMdA5DzExRW", "key": "Intrigues of the Prince", "name": "Intrigues of the Prince", "parent": null, "props": [], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#tPT2xq9wIKGQ1dqfuebZbU6": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "adversaries/tor2e-0.5-hands-hill-troll.actor", "form": "DEF", "guidance": [], "id": "#tPT2xq9wIKGQ1dqfuebZbU6", "key": "Hill-Troll", "name": "Hill-Troll", "parent": null, "props": [{"name": "Name", "type": "STRING", "value": "Hill-Troll", "vk": "scalar"}, {"items": [{"value": "Fierce", "vk": "scalar"}, {"value": "Strong", "vk": "scalar"}], "name": "Distinctive Features", "of": "STRING", "vk": "list"}, {"name": "Attribute Level", "type": "INTEGER", "value": 8, "vk": "scalar"}, {"name": "Endurance", "type": "INTEGER", "value": 60, "vk": "scalar"}, {"name": "Might", "type": "INTEGER", "value": 2, "vk": "scalar"}, {"name": "Hate", "type": "INTEGER", "value": 8, "vk": "scalar"}, {"name": "Parry", "type": "STRING", "value": "+2", "vk": "scalar"}, {"name": "Armour", "type": "STRING", "value": "3", "vk": "scalar"}, {"items": [{"fields": [{"name": "Weapon", "type": "STRING", "value": "Hammer", "vk": "scalar"}, {"name": "Rating", "type": "INTEGER", "value": 3, "vk": "scalar"}, {"name": "Damage", "type": "INTEGER", "value": 8, "vk": "scalar"}, {"name": "Injury", "type": "INTEGER", "value": 16, "vk": "scalar"}, {"items": [{"value": "Break Shield", "vk": "scalar"}], "name": "Special Damage", "of": "STRING", "vk": "list"}, {"name": "Printed", "type": "STRING", "value": "Hammer 3 (8/16, Break Shield)", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Weapon", "type": "STRING", "value": "Bite", "vk": "scalar"}, {"name": "Rating", "type": "INTEGER", "value": 2, "vk": "scalar"}, {"name": "Damage", "type": "INTEGER", "value": 6, "vk": "scalar"}, {"name": "Injury", "type": "INTEGER", "value": 14, "vk": "scalar"}, {"items": [{"value": "Pierce", "vk": "scalar"}], "name": "Special Damage", "of": "STRING", "vk": "list"}, {"name": "Printed", "type": "STRING", "value": "Bite 2 (6/14, Pierce)", "vk": "scalar"}], "vk": "def"}], "name": "Combat Proficiencies", "of": "Adversary Combat Proficiency", "ofHash": "#tor5AdvCombat000001", "vk": "list"}, {"items": [{"fields": [{"name": "Name", "type": "STRING", "value": "Hideous Toughness", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "The creature is unaffected by unarmed attacks. Additionally, when an attack inflicts damage to the creature that would cause it to go to zero Endurance, it causes a Piercing Blow instead. Then, if the creature is still alive its Endurance score is set back at half its maximum rating.", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Name", "type": "STRING", "value": "Hate Sunlight", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "The creature loses 1 Hate at the start of each round if it is exposed to the full light of the sun (this Fell Ability replaces the Trolls’ usual sunlight curse).", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Name", "type": "STRING", "value": "Horrible Strength", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "If the creature scores a Piercing Blow, spend 1 Hate to make the target’s Protection roll Ill-favoured.", "vk": "scalar"}], "vk": "def"}], "name": "Fell Abilities", "of": "Fell Ability", "ofHash": "#tor5FellAbility0001", "vk": "list"}], "refs": [], "slot": null, "table": null, "type": "Adversary", "typeHash": "#TOR0020000000000"}, "#tPgYynmzGXkYj9oihownazy": {"book": "hands", "children": [], "choices": [], "desc": "Minas Tirith, the Tower of Guard, has seven of these rings; Isengard can boast only one, but it is mighty nonetheless. The ring-wall runs from the base of the cliffs of Methedras in a great circle, more than a mile wide at its fullest extent. On the outside of the ring is a deep and slippery ditch, which can be flooded to become an impassable moat. Then the sheer walls rise, like a frozen wave of stone. Atop the walls are battlements and walkways, punctuated by guard towers.\n\nThe outer portion of the ring-wall is stone and close-packed earth, but the inner part is a great circle of chambers and store-rooms linked by sheltered passageways. A soldier might travel from one side of the ring to the other without ever stepping foot outside. Abutting the inner ring are more buildings — forges and workshops, stables and animal pens, houses and living quarters for the officers and other officials. This place is a city in miniature, a cutting from the tree planted in the shadow of the Misty Mountains.\n\nFully occupied, the barracks and stores of Isengard could quarter and supply an army six thousand strong. The present garrison numbers less than a tenth of this, so much of the ring is unoccupied and unused. Player-heroes staying at Isengard have their choice of rooms.\n\nThere are no windows on the outer edge of the ring, save a few cleverly concealed spy holes for sentries, but the inner ring has hundreds of windows and archways; a traveller crossing the encircled basin is watched by many eyes.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-introduction.ttrpg", "form": "DEF", "guidance": [], "id": "#tPgYynmzGXkYj9oihownazy", "key": "8. The Ring of Isengard", "name": "8. The Ring of Isengard", "parent": "#tcMxywq75NOL2ves69gurzl", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#tPjVCvJEWzXrDMUsfr9AvNg": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "loremaster-characters/tor2e-0.5-hands-gildor-inglorion.actor", "form": "DEF", "guidance": [], "id": "#tPjVCvJEWzXrDMUsfr9AvNg", "key": "Gildor Inglorion", "name": "Gildor Inglorion", "parent": null, "props": [{"name": "Name", "type": "STRING", "value": "Gildor Inglorion", "vk": "scalar"}, {"name": "Location", "type": "STRING", "value": "Locations", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "*“We are Exiles, and most of our kindred have long ago departed and we too are now only tarrying here a while, ere we return over the Great Sea. But some of our kinsfolk dwell still in peace in Rivendell.”* — The Fellowship of the Ring™\n\nA High Elf of the House of Finrod, Gildor has long wandered the lands of the west. He came to this shore seeking the fabled Singer on the Shore (see *Ruins of the Lost Realm*, page 29). He never found this mythical figure, but rumour of the mysterious Prince drew him to Todden, and into the friendship of young Sellic.\n\nSellic betrayed him, and the Prince’s guards captured Gildor and dragged him here. He’s been mistreated and beaten to compel him to reveal the location of Rivendell, a secret he has kept despite the Prince’s demands.\n\nIn more pleasant circumstances, Gildor is a merry fellow, more likely to engage in wit than sword-play. But these are not pleasant circumstances…", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Loremaster Character", "typeHash": "#TOR0030000000000"}, "#tQokVmCLQSsM6Wiah5WgUsP": {"book": "hands", "children": [], "choices": [], "desc": "The hunt for the Black Númenóreans may give rise to many unforeseen difficulties and setbacks. Below is a list of problems and encounters the Player-heroes may meet on the way.\n\nIf the Player-heroes fail to assuage these concerns, the lord may bar them from entering their territory, engage in combat, or even try to ally with the Corsairs against the Player-heroes for self-preservation.\n\nSimilarly, while these are not especially dark or dangerous lands, accidents happen — hunters might slip and fall on the muddy banks, or be bitten by serpents, or suffer from exposure. If the Host’s strength is sapped by hunger or poison, and the Heroes do not take some action to relieve this situation, the next roll on the Battle Outcome table is *Ill-favoured*.\n\nThe Player-heroes have the skill and courage to slay these Undead, but their followers do not.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-there-let-them-lie-until-the-end.arc", "form": "DEF", "guidance": [], "id": "#tQokVmCLQSsM6Wiah5WgUsP", "key": "Encounters on the Hunt", "name": "Encounters on the Hunt", "parent": null, "props": [{"items": [{"value": "**Fear of the White Hand:** The arrival of a company of armed soldiers (or worse, Orcs!) in the lands along the Greyflood goes not without notice. The Player-heroes must deal with some local lord who fears that they are hostile invaders. The obvious candidate is **Gurnow**, the thuggish Master of Tharbad described in *Ruins of the Lost Realm* (page 15), but it might equally be the chieftain of some isolated steading along the riverbanks, or the lord of some minor Dwarf-hold or recent settlement not on the maps. How do the Player-heroes convince this lord that they mean no harm — bearing in mind that unless closely watched, some of the soldiers sent by Saruman may take the opportunity to do a little looting and pillaging, so the fears of the lord may not be wholly unjustified.", "vk": "scalar"}, {"value": "**Hunger and Other Perils:** A Ranger or experienced traveller will not starve in the wilds of southern Eriador; these lands are uncultivated but not barren or lifeless. There is game aplenty, and plants to eat. Indeed, in places there are old orchards and fields descended from the croplands of vanished Cardolan. However, it is a different matter for a company of warriors. Their presence may scare away most of the wildlife, and one cannot expect a hardened Dunlending raider to go grubbing for roots and berries. Where do the Player-heroes obtain supplies for their followers? Hunting or raiding? Barter? Or do they go hungry?", "vk": "scalar"}, {"value": "**Marsh-dwellers:** There are strange creatures everywhere in Middle-earth, if you go poking in the wrong places — and the Player-heroes are, effectively, Saruman’s designated pokers. The largest fens on the Greyflood are the haunted lands of Swanfleet at the confluence of the Hoarwell and the Glanduin, (see *Ruins of the Lost Realm*, page 18), but there are smaller marshes downstream, as the river meanders. In these, small groups of **Marsh-dwellers** (see *The One Ring*, page 155) creep through the mud, stalking their prey.", "vk": "scalar"}, {"value": "**Trolls and Wights and Sorcerers:** Trolls are rare this far from the Mountains and the Trollshaws, but not unheard of — and the presence of the sorcerer of Umbar on board the Black Ship stirs up all manner of evil. Alternatively, the explorers might stumble upon some haunted barrow or cursed tomb.", "vk": "scalar"}], "name": "Items", "of": "STRING", "vk": "list"}], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#tR9w2VTRDI6ymNXEqorWQ4G": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "tor2e-0.5-hands-there-let-them-lie-until-the-end.arc", "form": "DEF", "guidance": [], "id": "#tR9w2VTRDI6ymNXEqorWQ4G", "key": "The Tomb of the Admiral", "name": "The Tomb of the Admiral", "parent": null, "props": [], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#tRFySySTYybexfRSFWyg5bl": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [{"fields": [{"name": "Shadow", "type": "STRING", "value": "+1/2/3", "vk": "scalar"}], "name": "Fixed amount", "vk": "def"}, {"fields": [{"name": "Shadow", "type": "INTEGER", "value": 1, "vk": "scalar"}], "name": "The Player-heroes committed Misdeeds collectively worth 4 Shadow points or more", "vk": "def"}, {"fields": [{"name": "Shadow", "type": "INTEGER", "value": 1, "vk": "scalar"}], "name": "Arcinyas is left behind", "vk": "def"}, {"fields": [{"name": "Shadow", "type": "INTEGER", "value": 2, "vk": "scalar"}], "name": "The Company fails to recover the Elendilmir", "vk": "def"}, {"fields": [{"name": "Shadow", "type": "INTEGER", "value": 1, "vk": "scalar"}], "name": "The Player-heroes accept the House of Chimneys as a boon", "vk": "def"}, {"fields": [{"name": "Shadow", "type": "STRING", "value": "—", "vk": "scalar"}], "name": "The Company brings the bones back to Isengard. (If Saruman reaches Shadow 9 or more, this triggers the event *The Burning of the Bones* (page page 18).", "vk": "def"}], "enum": null, "file": "tor2e-0.5-hands-worksheet-saruman-s-shadow-score.ttrpg", "form": "DEF", "guidance": [], "id": "#tRFySySTYybexfRSFWyg5bl", "key": "The Disaster of the Gladden Fields Shadow Score", "name": "The Disaster of the Gladden Fields Shadow Score", "parent": "#t1FVKSXZ73A6ZfL42p4fxbk", "props": [], "refs": [], "slot": null, "table": {"columns": ["Trigger", "Shadow", "Tally"], "rows": [["Fixed amount", "+1/2/3", ""], ["The Player-heroes committed Misdeeds collectively worth 4 Shadow points or more", "+1", ""], ["Arcinyas is left behind", "+1", ""], ["The Company fails to recover the Elendilmir", "+2", ""], ["The Player-heroes accept the House of Chimneys as a boon", "+1", ""], ["The Company brings the bones back to Isengard. (If Saruman reaches Shadow 9 or more, this triggers the event *The Burning of the Bones* (page page 18).", "—", ""]]}, "type": "Table", "typeHash": "#tor5Table0000000001"}, "#tRicfRKMY7j9vj8ID6Yxmm1": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-ithil-stone.arc", "form": "DEF", "guidance": [], "id": "#tRicfRKMY7j9vj8ID6Yxmm1", "key": "Rumour", "name": "Rumour", "parent": null, "props": [], "refs": [], "slot": "PHASE", "table": null, "type": null, "typeHash": null}, "#tSD7VukaUa9CzpK6yhk3ouE": {"book": "hands", "children": [], "choices": [], "desc": "*Moria: Through the Doors of Durin* contains (in good Hobbit-sense fashion) a wealth of details on Moria, so the Loremaster should refer to it if possible. If the publication is unavailable, the Loremaster can use the Moria Hazards and Moria Location tables at the end of this adventure to evoke the impression of vast and labyrinthine halls.\n\nReaching the Ledge of Woe requires two rolls on the Moria Hazards table.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-disaster-of-the-gladden-fields.arc", "form": "DEF", "guidance": [], "id": "#tSD7VukaUa9CzpK6yhk3ouE", "key": "Exploring Moria", "name": "Exploring Moria", "parent": null, "props": [], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#tTazFYdrY5vSbAMB4SUfxjS": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [{"fields": [{"name": "Location", "type": "STRING", "value": "An unstable place — a narrow bridge spanning a chasm, a many-pillared hall on the verge of collapse, a hallway filled with choking smoke or foul air.", "vk": "scalar"}], "name": "[Eye of Sauron]", "vk": "def"}, {"fields": [{"name": "Location", "type": "STRING", "value": "The mischief of Orcs — all traces of the Dwarves have been erased, replaced by Orc-filth, carcasses of prisoners, and the smashed remnants of looted goods.", "vk": "scalar"}], "name": "1", "vk": "def"}, {"fields": [{"name": "Location", "type": "STRING", "value": "A passageway, so narrow that the travellers must move in single file, squeezing through the low-roofed crawl.", "vk": "scalar"}], "name": "2", "vk": "def"}, {"fields": [{"name": "Location", "type": "STRING", "value": "A natural and unworked cavern, a hollow in the heart of the mountain. Veins of metal ore gleam in the walls.", "vk": "scalar"}], "name": "3", "vk": "def"}, {"fields": [{"name": "Location", "type": "STRING", "value": "An old mine; shafts plunge deep into the earth, and mining tunnels worm off towards the roots of Redhorn.", "vk": "scalar"}], "name": "4", "vk": "def"}, {"fields": [{"name": "Location", "type": "STRING", "value": "A labyrinth of granaries, cellars and other storerooms, all long since emptied.", "vk": "scalar"}], "name": "5", "vk": "def"}, {"fields": [{"name": "Location", "type": "STRING", "value": "A once-great hall where some Dwarven lord ruled long ago; smaller chambers adjoin the main hall.", "vk": "scalar"}], "name": "6", "vk": "def"}], "enum": null, "file": "tor2e-0.5-hands-the-disaster-of-the-gladden-fields.arc", "form": "DEF", "guidance": [], "id": "#tTazFYdrY5vSbAMB4SUfxjS", "key": "Moria Locations", "name": "Moria Locations", "parent": null, "props": [], "refs": [], "slot": "SCENE", "table": {"columns": ["FEAT DIE", "LOCATION"], "rows": [["[Eye of Sauron]", "An unstable place — a narrow bridge spanning a chasm, a many-pillared hall on the verge of collapse, a hallway filled with choking smoke or foul air."], ["1", "The mischief of Orcs — all traces of the Dwarves have been erased, replaced by Orc-filth, carcasses of prisoners, and the smashed remnants of looted goods."], ["2", "A passageway, so narrow that the travellers must move in single file, squeezing through the low-roofed crawl."], ["3", "A natural and unworked cavern, a hollow in the heart of the mountain. Veins of metal ore gleam in the walls."], ["4", "An old mine; shafts plunge deep into the earth, and mining tunnels worm off towards the roots of Redhorn."], ["5", "A labyrinth of granaries, cellars and other storerooms, all long since emptied."], ["6", "A once-great hall where some Dwarven lord ruled long ago; smaller chambers adjoin the main hall."]]}, "type": "Table", "typeHash": "#tor5Table0000000001"}, "#tTcQWQzyiCvbzvBszrfqWZ3": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "adversaries/tor2e-0.5-hands-dunwalla.actor", "form": "DEF", "guidance": [], "id": "#tTcQWQzyiCvbzvBszrfqWZ3", "key": "Dunwalla", "name": "Dunwalla", "parent": null, "props": [{"name": "Name", "type": "STRING", "value": "Dunwalla", "vk": "scalar"}, {"items": [{"value": "Cruel", "vk": "scalar"}, {"value": "Uncanny", "vk": "scalar"}], "name": "Distinctive Features", "of": "STRING", "vk": "list"}, {"name": "Attribute Level", "type": "INTEGER", "value": 5, "vk": "scalar"}, {"name": "Endurance", "type": "INTEGER", "value": 20, "vk": "scalar"}, {"name": "Might", "type": "INTEGER", "value": 1, "vk": "scalar"}, {"name": "Hate", "type": "INTEGER", "value": 5, "vk": "scalar"}, {"name": "Parry", "type": "STRING", "value": "+1", "vk": "scalar"}, {"name": "Armour", "type": "STRING", "value": "2", "vk": "scalar"}, {"items": [{"fields": [{"name": "Weapon", "type": "STRING", "value": "Knife", "vk": "scalar"}, {"name": "Rating", "type": "INTEGER", "value": 3, "vk": "scalar"}, {"name": "Damage", "type": "INTEGER", "value": 2, "vk": "scalar"}, {"name": "Injury", "type": "INTEGER", "value": 14, "vk": "scalar"}, {"items": [{"value": "Pierce", "vk": "scalar"}], "name": "Special Damage", "of": "STRING", "vk": "list"}, {"name": "Printed", "type": "STRING", "value": "Knife 3 (2/14, Pierce)", "vk": "scalar"}], "vk": "def"}], "name": "Combat Proficiencies", "of": "Adversary Combat Proficiency", "ofHash": "#tor5AdvCombat000001", "vk": "list"}, {"items": [{"fields": [{"name": "Name", "type": "STRING", "value": "Combat Sorcerer", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "Dunwalla can cast her Dreadful Spells in place of her attack. If she does so, she can cast the spell without expending Hate.", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Name", "type": "STRING", "value": "Dreadful Spells: Murder of Crows", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "Spend 1 Hate to make each Player-hero in sight gain 2 Shadow points (Sorcery) and lose (1d) on any attack rolls they make during their next turn. Those who fail their Shadow test or who are Miserable also suffer a severe Endurance loss (consider it as if from falling).", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Name", "type": "STRING", "value": "Snake-like Speed", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "When targeted by an attack, spend 1 Hate to make the attack roll Ill-favoured.", "vk": "scalar"}], "vk": "def"}], "name": "Fell Abilities", "of": "Fell Ability", "ofHash": "#tor5FellAbility0001", "vk": "list"}, {"name": "Description", "type": "STRING", "value": "The Witch of Dunland, some call her. She is the twin sister of Dunrach. While he trained to fight, she ran wild, vanishing for days into the deep woods. There are stone idols there, squat and ugly, and it’s said they speak to her, and taught her the crow-speech. She has talent as a healer, and saved the life of her brother when he came home badly wounded from battle. Indeed, it’s commonly known that she would like to see her brother as ruler of Crow Hall, and it is a great frustration to her that he has not pressed his claim, but instead supports young Toirlas. She and Gorsad dislike each other, but they are also the two cleverest people in Crow Hall, and so they must work together to guide the clan. The other inhabitants of Crow Hall hate and fear Dunwalla, believing her to have unnatural powers. If it were not for the protection of Gorsad and her brother, she would long ago have been driven out of the Hall to perish in the wild. Dunwalla should be played as a spooky, mystical figure. If the Player-heroes ask about her crow familiar, or the shrine in her quarters, she darkly hints that there are powers in Middle-earth beyond the understanding of the Player-heroes.", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Adversary", "typeHash": "#TOR0020000000000"}, "#tUplRQbNcDtR95pJ9fRfKrs": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-disaster-of-the-gladden-fields.arc", "form": "DEF", "guidance": [], "id": "#tUplRQbNcDtR95pJ9fRfKrs", "key": "Interlude:", "name": "Interlude:", "parent": null, "props": [], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#tVODwScuM37eEnFXd38LzeD": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "loremaster-characters/tor2e-0.5-hands-tabarn-the-doorward.actor", "form": "DEF", "guidance": [], "id": "#tVODwScuM37eEnFXd38LzeD", "key": "Tabarn the Doorward", "name": "Tabarn the Doorward", "parent": null, "props": [{"name": "Name", "type": "STRING", "value": "Tabarn the Doorward", "vk": "scalar"}, {"name": "Occupation", "type": "STRING", "value": "Doorward of the Ring of Isengard", "vk": "scalar"}, {"items": [{"value": "Fierce", "vk": "scalar"}, {"value": "Wary", "vk": "scalar"}], "name": "Distinctive Features", "of": "STRING", "vk": "list"}, {"name": "Location", "type": "STRING", "value": "Locations", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "The keeper of the Gate of Isengard is a stern Dunlending, tall and taciturn, who bears a mighty axe. He will not allow any strangers to enter the Ring without permission, nor will he permit them to bear weapons into the presence of his master Saruman. And if anyone questions him, his axe is named Fragarach, which is ‘Answerer’ in the Dunnish tongue.", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Loremaster Character", "typeHash": "#TOR0030000000000"}, "#tViJJeOtzlDyniyYuKehSY1": {"book": "hands", "children": [], "choices": [], "desc": "If Redtooth doesn’t return from the raid, then tragedy repeats as farce. Again, a band of warriors perish near the Gladden Fields; again, a treasure is entrusted to some young squires (Isildur’s squire Ohtar, three thousand years ago; fleet-footed Orc messengers today). The Orc-messengers reached Moria ahead of the Player-heroes, and went to the Sixteenth Hall to wait for Redtooth. Only in this case, the subordinates start knifing each other over the treasure in Moria, as soon as it becomes clear Redtooth isn’t returning. The messengers are unsure if they should wait longer in the hope — or fear — that Redtooth survived, or if they should go to the Orc-chieftain Malech One-Eye for shelter, or if they should make off with the treasure for themselves.\n\nThe Player-heroes can easily deal with the messengers (they are just one Goblin Archer for each Player-hero), but unless they catch up with them with astounding swiftness, Baugrim and his Orcs of Mordor arrive just as they’re searching for the stolen goods.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-disaster-of-the-gladden-fields.arc", "form": "DEF", "guidance": [], "id": "#tViJJeOtzlDyniyYuKehSY1", "key": "Hot Potato", "name": "Hot Potato", "parent": null, "props": [], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#tVwtVGGrr6uY0BPWOCX0e38": {"book": "hands", "children": [], "choices": [], "desc": "If any of the Player-heroes are Wounded or poisoned, then the villagers advise them to go and see the Prince in his tower by the shore. Bring an offering, they say.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-sea-prince-of-the-shore.arc", "form": "DEF", "guidance": [], "id": "#tVwtVGGrr6uY0BPWOCX0e38", "key": "Offerings and Healing Arts", "name": "Offerings and Healing Arts", "parent": null, "props": [], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#tX8NeUsRzDKSA42P3jjTs6Z": {"book": "hands", "children": [], "choices": [], "desc": "Should any of the Company remain alive, they can flee the Morgul Vale in the confusion. If Saruman remains uncorrupted, then he can intervene to protect the survivors (see *The Choices of Saruman, Final Part*). If the Player-heroes lack the protection of Saruman, then they must fight or flee unaided; as this is likely the final scene of the campaign, it is an ideal time for heroic self-sacrifice.\n\nEither way, if the Player-heroes succeeded in their mission, describe the victory they have won, the injury they have inflicted on Sauron’s plans. The destruction of the Morgul-road delays his readiness for war by a crucial decade or more — giving time to rally defences, to prepare, to enjoy a few more precious years of peace. Whether they survived or perished, the Company have served the White Wizard well.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-ithil-stone.arc", "form": "DEF", "guidance": [], "id": "#tX8NeUsRzDKSA42P3jjTs6Z", "key": "Escaping the Morgul Vale", "name": "Escaping the Morgul Vale", "parent": null, "props": [], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#tXHRas17bN8vEkJceHoyxGm": {"book": "hands", "children": [], "choices": [], "desc": "The raid on Arcinyas’ House in the Gladden Fields did not go unnoticed. The Vales of Anduin are watched from both sides of the River. Through drum-beat and whisper, through powers seen and unseen, the word goes out, and soon it reaches Dol Guldur, the Fortress of the Necromancer. And though the Necromancer no longer resides there, three of his Nazgûl command Dol Guldur and the ongoing search for the missing One Ring.\n\nMessengers are sent to Moria the very same night that word of the raid reaches Dol Guldur. At the same time, other spies are sent to the Gladden Fields, and to watch the passes over the Misty Mountains.\n\nThe commander of these messengers is an Orc-captain named **Baugrim**. His mission — go to Moria, find this Redtooth, and recover whatever he discovered in Arcinyas’ house. One of the **Nazgûl**, unclad and invisible, goes with Baugrim, an unseen spirit of terror. Together with a strong company of Mordor Orcs, they cross the Great River with the aid of Men who secretly serve Sauron, sailing across the waters on wide rafts. The Great Eagles mark their crossing, but do not interfere.\n\nBaugrim’s company is formidable, counting three strong **Black Uruk Soldiers** for each Player-hero (see box). They carry with them gifts from Dol Guldur — a chest not of treasure, but of Mordor-forged weapons and armour, a mark of the Dark Lord’s favour for his *loyal servants* in Moria. These Orcs are plainly more disciplined and better equipped than the Moria-orcs under Redtooth, and they bear the symbol of the Lidless Eye on their shields.\n\nThe Orcs approach the Dimrill Gate, where they are met by Orcs in the service of Redtooth. Some of their company set up camp in the shadow of the Gate, while Baugrim and his best warriors enter Moria and are escorted directly to the Harper’s Hall. The Ringwraith does not enter yet — it can sense the distant, watchful presence of Durin’s Bane, and has been commanded not to show its power unless absolutely necessary.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-disaster-of-the-gladden-fields.arc", "form": "DEF", "guidance": [], "id": "#tXHRas17bN8vEkJceHoyxGm", "key": "Mordor-orcs!", "name": "Mordor-orcs!", "parent": null, "props": [], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#tXHr0LiNozdaC5JLFikzYXy": {"book": "hands", "children": [], "choices": [], "desc": "If the Player-heroes sleep in the main Hall, it is hot and crowded, and loud with snores and the worried talk of the Dunlendings. The one common thread in all the conversations is the hope that the chieftain’s son Toirlas will soon return to hunt down the beast.\n\nIf they’re exiled out to the barns, then their night is cold and lonely, their only company the crows that delight in pulling the Player-heroes’ belongings, stealing shiny things, and croaking loudly.\n\nHowever, Player-heroes outside the Hall get to make an **AWARENESS** roll — if successful, they spot a tall, pale figure lurking outside the fence. This figure turns and flees as soon as any of the Player-heroes move — it’s not the beast, it’s the herdsman Scepa from Rohan (see *Scepa’s Tale*, on page 34). If they chase after him, call for a **HUNTING** roll: Player-heroes *lose (2d)* for the darkness and Scepa’s head start.\n\nNote that the crows croak loudly in Scepa’s presence.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-beast-of-dunland.arc", "form": "DEF", "guidance": [], "id": "#tXHr0LiNozdaC5JLFikzYXy", "key": "During the Night", "name": "During the Night", "parent": null, "props": [], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#tXql7ACjtO8NZFHlDJrNvx4": {"book": "hands", "children": [], "choices": [], "desc": "As the Company sneak through the Vale, they hear the drums and thunderous clamour of a second, much larger host of Orcs, marching under the banner of the Lidless Eye. These are reinforcements for the faster host that the Company may have spotted — or fought — near the Crossroads (see *Swift Foes From Mordor*, on page 130); once this host passes through the Morgul Vale, they will head to Osgiliath and attack Boromir’s forces there.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-ithil-stone.arc", "form": "DEF", "guidance": [], "id": "#tXql7ACjtO8NZFHlDJrNvx4", "key": "The Second Host", "name": "The Second Host", "parent": null, "props": [{"items": [{"value": "Optionally, the arrival of these Orcs can draw the attention of Minas Morgul, reducing the Company’s Eye Awareness by 2.", "vk": "scalar"}, {"value": "Any Player-hero with at least one rank in **BATTLE** can instantly determine that this host is large enough to overwhelm Boromir’s forces and secure the Enemy’s hold on the east bank. However, if the Player-heroes can complete their task quickly, they could block the Road before the Orc army passes through — or, better yet, collapse the cliff *onto* the army marching far below.", "vk": "scalar"}, {"value": "The host consists of thousands of Orcs; far too many to fight.", "vk": "scalar"}], "name": "Items", "of": "STRING", "vk": "list"}], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#tYNIaSOxDBOlZanW1y9Sw3H": {"book": "hands", "children": [], "choices": [], "desc": "The massive stone door to the tomb was locked and barred when West Moria was abandoned — and molten lead poured into the lock mechanism to keep it sealed. The Dwarves never intended to return here. Finir has been hewing and hacking at the door to break it open, but it’s hard work and Finir’s half-starved. The Player-heroes can force the door open with a Simple (Resistance 3) Skill Endeavour using **ATHLETICS** or **CRAFT** rolls, but it takes time, and each Skill roll causes the Player-hero who makes it to gain 1 Fatigue.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-quest-of-moria.arc", "form": "DEF", "guidance": [], "id": "#tYNIaSOxDBOlZanW1y9Sw3H", "key": "3. The Door", "name": "3. The Door", "parent": null, "props": [], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#tYTRDNCyEPe4yv1Uy7AZqe8": {"book": "hands", "children": ["#tpZdL2Ln7uz3I1OM10GLdKk", "#tfttFbP3F4WmwRWvvezUHHi", "#tgrohATn15Wpi4QqwZl0eoL", "#tZ7cI1tQmaKNbkM6LFJUh9h"], "choices": [], "desc": "*— The Fellowship of the Ring™*\n\nIn the story as told in *The Lord of the Rings*, many things contributed to Saruman’s fall from grace. Ambition, jealousy, and arrogance all played their role. So too did despair, for like Denethor, Saruman was ensnared by Sauron and shown the invincible armies of Mordor. Unlike Denethor, who ultimately chose self-destruction rather than yielding to the Dark Lord, Saruman opted for appeasement, for accommodation, for the possibility of compromise with an eye to eventually replacing Sauron on the throne.\n\nIn *Hands of the White Wizard*, the players have a chance of slowing this fall. In each adventure, there’s a choice to commit misdeeds in the service of Saruman. Should the Player-heroes take the darker path (which often seems more ‘pragmatic’ or ‘far-sighted’ in context), then they may gain Shadow points — and so does Saruman!", "entries": [], "enum": null, "file": "tor2e-0.5-hands-introduction.ttrpg", "form": "DEF", "guidance": [], "id": "#tYTRDNCyEPe4yv1Uy7AZqe8", "key": "The Fall of Saruman", "name": "The Fall of Saruman", "parent": null, "props": [{"name": "Epigraph", "type": "STRING", "value": "“... I am Saruman the Wise, Saruman Ring-maker, Saruman of Many Colours!”", "vk": "scalar"}, {"items": [{"value": "The Loremaster must track the Shadow points accrued by Saruman in this manner across the campaign. Saruman starts at an effective Shadow score of 0. Then, before starting, the Loremaster should choose one of the following options (possibly in agreement with the players).", "vk": "scalar"}], "name": "Rules", "of": "STRING", "vk": "list"}], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#tYe3eia8e6g9kGt1bBBN3L6": {"book": "hands", "children": [], "choices": [], "desc": "If the Player-heroes don’t stop Usapthon and the Corsairs, then their final act is to defile the Admiral’s Tomb. The stone tomb is smashed with hammers, the Admiral’s Sword and Helm are taken as trophies back to Mordor, and — most important of all — any images that depict the Admiral’s victory over Sauron’s forces are taken down and destroyed. No record of Sauron’s defeat can survive!", "entries": [], "enum": null, "file": "tor2e-0.5-hands-there-let-them-lie-until-the-end.arc", "form": "DEF", "guidance": [], "id": "#tYe3eia8e6g9kGt1bBBN3L6", "key": "The Tomb is Defiled", "name": "The Tomb is Defiled", "parent": null, "props": [], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#tZ3eFhWXgfRvrNvXbQwUU74": {"book": "hands", "children": [], "choices": [], "desc": "If the Player-heroes are in the company of Dunlendings, or claim they have been welcomed as guests in Crow Hall by his father, then Toirlas invites them to sit by his campfire and share tales with his warriors. More than anything else, he wants a fresh audience for his boasts — he exaggerates the danger of his raid in the retelling, claiming that Sigulf’s stead was a veritable fortress, and that he was pursued by a host of Forgoil riders as he escaped over the Isen. He also claims to have seduced Gleodwyn, and that she begged him to carry her away to his castle in the hills.\n\nToirlas says that he’s on his way back to Crow Hall, but he’s not looking forward to doing so, since his tiresome father will start whining about wise rulership and his sore feet. He’s delaying his return as long as possible by visiting other Dunlending farmsteads and outposts.\n\nIf the Player-heroes mention the beast, Toirlas rolls his eyes. The crows protect Crow Hall — the fortress is invulnerable. Maybe it crept in once, but he chased it into the mountains, and he doubts it’ll ever return again. (If they tell him that the beast has returned since he left, he takes the matter more seriously, and returns to the Hall as soon as possible.)", "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-beast-of-dunland.arc", "form": "DEF", "guidance": [], "id": "#tZ3eFhWXgfRvrNvXbQwUU74", "key": "Meeting with Toirlas", "name": "Meeting with Toirlas", "parent": null, "props": [], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#tZ7cI1tQmaKNbkM6LFJUh9h": {"book": "hands", "children": ["#tZfzqgt8aJbs6shBsEKp5Ef"], "choices": [], "desc": "Isengard changes over the course of this campaign, as Saruman’s corruption grows. Whenever the Player-heroes return to Isengard after a period of absence, describe the external manifestation of Saruman’s descent.\n\n**(Shadow 1+) Expanding the Caves:** Saruman orders the Iron Caves to be expanded. New mine-shafts are dug out, and new, rich veins of iron are discovered. The older excavations are converted into storehouses; new foundries are built on the surface. The fires of Isengard burn hot and bright, and the ring resounds with the sound of hammers.\n\n**(Shadow 2+) Excavations Below:** Even though the new storehouses are done, the excavations continue. Some of this subterranean labour is ordinary iron-mining, delving into the roots of Methedras, but it seems as though Saruman is digging new cellars and dungeons within the ring of Isengard.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-introduction.ttrpg", "form": "DEF", "guidance": [], "id": "#tZ7cI1tQmaKNbkM6LFJUh9h", "key": "The Ruin of Isengard", "name": "The Ruin of Isengard", "parent": "#tYTRDNCyEPe4yv1Uy7AZqe8", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#tZNR6C8Nen0J2dHtxdE8AJt": {"book": "hands", "children": [], "choices": [], "desc": "Six Dwarves have been captured by the Huorns, and they are imprisoned in a hollow stump, capped with a heavy stone. Pushing the stone aside or smashing the stump open frees the Dwarves; the Player-heroes can do this as they fight (using a main action and with a successful **ATHLETICS** roll), or they can wait until they have defeated or driven away the Huorns. The Dwarves start hammering on the stump as soon as they hear the voices of the Player-heroes in the Black Glen.\n\n(If the Player-heroes are on the verge of being overwhelmed by Huorns, then have Lightroot or another Ent — maybe even Treebeard himself — appear on the top of the hill, and trumpet a command in Entish to send the Huorns back to sleep. The Ent does not interact with the Player-heroes — all Fangorn wants is for Saruman’s servants to collect these Dwarven trespassers.)", "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-quest-of-moria.arc", "form": "DEF", "guidance": [], "id": "#tZNR6C8Nen0J2dHtxdE8AJt", "key": "Prisoners of the Huorns", "name": "Prisoners of the Huorns", "parent": null, "props": [], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#tZPSXxN5cr7KPlcslau0pMo": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [{"fields": [{"name": "To the Twenty-first Hall", "type": "INTEGER", "value": 2, "vk": "scalar"}, {"name": "To Finir’s Hiding Place", "type": "INTEGER", "value": 4, "vk": "scalar"}], "name": "East-gate or Dimrill Door", "vk": "def"}, {"fields": [{"name": "To the Twenty-first Hall", "type": "INTEGER", "value": 3, "vk": "scalar"}, {"name": "To Finir’s Hiding Place", "type": "INTEGER", "value": 3, "vk": "scalar"}], "name": "Goblin-cave", "vk": "def"}, {"fields": [{"name": "To the Twenty-first Hall", "type": "INTEGER", "value": 4, "vk": "scalar"}, {"name": "To Finir’s Hiding Place", "type": "INTEGER", "value": 2, "vk": "scalar"}], "name": "West-gate", "vk": "def"}], "enum": null, "file": "tor2e-0.5-hands-the-quest-of-moria.arc", "form": "DEF", "guidance": [], "id": "#tZPSXxN5cr7KPlcslau0pMo", "key": "Part 4: In the Long Dark Table", "name": "Part 4: In the Long Dark Table", "parent": null, "props": [], "refs": [], "slot": "PHASE", "table": {"columns": ["ENTRY POINT", "TO THE TWENTY-FIRST HALL", "TO FINIR’S HIDING PLACE"], "rows": [["East-gate or Dimrill Door", "2", "4"], ["Goblin-cave", "3", "3"], ["West-gate", "4", "2"]]}, "type": "Table", "typeHash": "#tor5Table0000000001"}, "#tZfzqgt8aJbs6shBsEKp5Ef": {"book": "hands", "children": [], "choices": [], "desc": "Saruman is almost certainly doomed, but there is a small hope — a fool’s hope, one might say — that he might be saved, or at least that his fall has some virtue in it. Choose this option for a middle course; the story will likely end in Saruman’s fall, but the Player-heroes strive to master doom and by their actions change Saruman’s fate.\n\n**(Shadow 3+) Saruman the Tempter:** When speaking with the Player-heroes, Saruman begins to play on their ambitions, especially their Shadow Flaws. A Captain with the Lure of Power might be promised the command of a great army when the War with Mordor begins; a Scholar with the Lure of Secrets might be invited into Orthanc to study with the White Wizard; a Warden might be encouraged to put all their trust in Saruman to stave off despair.\n\n**(Shadow 4+) Wolves in the Stables:** The stables of Isengard are vast and mostly empty. There are a few horses stabled here — enough for the messengers and adventurers in Saruman’s service — but Isengard has space for six thousand soldiers, including stabling for a thousand horses. Now, some of the unused stables are converted to a new purpose: the keeping of wolves. These beasts prowl around the Wizard’s vale, and seem savage and hungry — but they never trouble those in the Wizard’s service, and lick Saruman’s hands as he passes by.\n\n**(Shadow 5+) Mead-hall Closed:** Saruman goes among the garrison, telling them that *“the days are too dark for song,”* and that they must harden their hearts and *“take pleasure only in grim defiance of the Enemy.”* He then orders the mead-hall to be shuttered. The songs of those who made merry there are silenced, and the hall is demolished the following year.\n\n**(Shadow 6+) The Lake Is Drained:** Overnight, the lake in the middle of the Ring vanishes, leaving behind a fetid brown marsh like a suppurating wound. The stream that fed the lake is diverted underground to power some mighty water-wheel in the depths.\n\n**(Shadow 7+) Saruman the Architect:** Saruman’s plans grow in scope and ambition; he begins to talk of how Middle-earth might be remade to better resist Sauron. He might talk to each Player-hero individually of their homelands, and how those lands might be better ordered and made more efficient, more productive, more useful to the war effort. He hints that as part of this improvement, the lands of the heroes will of course need better, wiser leaders… like the Player-heroes. Together, he promises, we will forge a better Age to come!\n\n**(Shadow 8+) Unfriendly Faces:** Isengard has previously been populated by a mix of Rohirrim, Dunlendings, and folk from afar. Now, the number of Dunlendings grows, and these newcomers are unfriendly and insular. There are other faces, too, strangers with an almost orcish look.\n\n**(Shadow 9+) The Burning of the Bones:** If the Player-heroes brought back the bones from the House of Chimneys (see *The Disaster of the Gladden Fields*, on page 59), then Saruman takes to burning these bones, one by one, in his furnaces. He stares as if looking for answers or conjured phantoms in the smoke.\n\nEdlenneth confides to the Player-heroes that the bones are kept in a store-house in the caverns, and asks if they might be willing to take the bones with them on their next adventure, and bury them in secret. She worries that Saruman is practising forbidden necromancy, and whispers to them that she cannot bury the bones herself, as she is being watched…\n\nIf the Player-heroes do not rescue the bones, Saruman gains 1 additional Shadow at the end of their next adventure.\n\n**(Shadow 10+) Heads on Spikes:** While the Player-heroes are absent, there is a purge in Isengard. Many who once served Saruman are executed as traitors; among their number is the former guard-captain Edlenneth, and the old serving-woman Neb. Their heads are impaled on spikes. If questioned, Saruman claims they were traitorous spies in the service of the Enemy; he says that Edlenneth was caught trying to steal the keys of Orthanc, and that Neb aided this betrayal.\n\nThe Dunlending Tabarn is promoted to Captain of Isengard.\n\n**(Shadow 11+) Saruman the Rancorous:** Saruman can no longer contain his venom or his paranoia. At times when talking to the Player-heroes, he grows sarcastic or cruel. If the Player-heroes are lucky, he directs these taunts at those who are not present (*“Radagast the Simple! Radagast the Bird-tamer! Radagast the Fool!”*), but if a Player-hero contradicts him, he savagely castigates them.\n\n**(Shadow 12+) Smoke and Fire:** Columns of pungent yellowish smoke rise from vents in the ground, and the whole ring shakes from time to time like a kettle coming to the boil. New shafts in the ground are hastily dug to release pressure; at times, flames burst from the ground, and the whole place stinks of sulphur.\n\n**(Shadow 13+) Further Excavations:** Despite these flames and smoke, Saruman orders new excavations. Thousands of wagon-loads of dirt and stone are dragged out of the pits, and dumped outside the ring to create a new line of defensive earthworks.\n\n**(Shadow 14+) Cutting the Elms:** The elm-trees that have lined the road to Orthanc for thousands of years are uprooted and hurled into the flames. The road is remade, lined with paving stones that conceal pits and other hidden traps.\n\n**(Shadow 15+) Saruman the Conspirator:** When dealing with the Player-heroes, Saruman seeks to divide them. He might speak to some Player-heroes in private, entrusting them alone with information or a special mission. He might reveal secrets held by the Player-heroes from one another, or recall old misdeeds and quarrels.\n\n**(Shadow 16+) Orcs in Isengard:** Orcs walk openly in Isengard — the fighting Uruk-hai! — and they bear the sigil of the White Hand.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-introduction.ttrpg", "form": "DEF", "guidance": [], "id": "#tZfzqgt8aJbs6shBsEKp5Ef", "key": "Upon the Edge of a Knife", "name": "Upon the Edge of a Knife", "parent": "#tZ7cI1tQmaKNbkM6LFJUh9h", "props": [{"items": [{"value": "*Raise Saruman’s Shadow by 2 after each adventure.*", "vk": "scalar"}], "name": "Items", "of": "STRING", "vk": "list"}], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#tacqhIkqLkxHyp4COBTNEbn": {"book": "hands", "children": ["#t6YiTOCzvfKGAY2EbunEWNO"], "choices": [], "desc": null, "entries": [], "enum": null, "file": "tor2e-0.5-hands-worksheet-saruman-s-shadow-score.ttrpg", "form": "DEF", "guidance": [], "id": "#tacqhIkqLkxHyp4COBTNEbn", "key": "The Sea-prince of the Shore", "name": "The Sea-prince of the Shore", "parent": "#t4tH0BF1gelfgVc1eyhWAuw", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#talyPNTJ9n9DL5d1je8Ofed": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "loremaster-characters/tor2e-0.5-hands-old-cradoc.actor", "form": "DEF", "guidance": [], "id": "#talyPNTJ9n9DL5d1je8Ofed", "key": "Old Cradoc", "name": "Old Cradoc", "parent": null, "props": [{"name": "Name", "type": "STRING", "value": "Old Cradoc", "vk": "scalar"}, {"name": "Occupation", "type": "STRING", "value": "Village Chief", "vk": "scalar"}, {"items": [{"value": "Patient", "vk": "scalar"}, {"value": "Subtle", "vk": "scalar"}], "name": "Distinctive Features", "of": "STRING", "vk": "list"}, {"name": "Location", "type": "STRING", "value": "Background", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "In his youth, Cradoc was renowned as a fighter and raider, but those days are long behind him. Now, he’s content to rule over his little domain. Cradoc is suspicious of outsiders, including the Sea-prince, but he knows that the newcomer could have easily overthrown him, taken his place, and dispossessed his sons, so Cradoc is content to serve for now — especially as the Sea-prince has declared that he is under a spell to dwell on land for only a year and a day, and that he must soon return to the ocean for a while.\n\nCradoc loves the riddle-game; a traveller who stumps him with a RIDDLE roll gets a warm welcome. While he’s interested in the affairs of the wider world, he has no desire to get involved.", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Loremaster Character", "typeHash": "#TOR0030000000000"}, "#tb6bfcB8cYBm1Rc2xJDHu6t": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "adversaries/tor2e-0.5-hands-zoril.actor", "form": "DEF", "guidance": [], "id": "#tb6bfcB8cYBm1Rc2xJDHu6t", "key": "Zoril", "name": "Zoril", "parent": null, "props": [{"name": "Name", "type": "STRING", "value": "Zoril", "vk": "scalar"}, {"items": [{"value": "Proud", "vk": "scalar"}, {"value": "Wilful", "vk": "scalar"}], "name": "Distinctive Features", "of": "STRING", "vk": "list"}, {"name": "Attribute Level", "type": "INTEGER", "value": 7, "vk": "scalar"}, {"name": "Endurance", "type": "INTEGER", "value": 28, "vk": "scalar"}, {"name": "Might", "type": "INTEGER", "value": 2, "vk": "scalar"}, {"name": "Hate", "type": "INTEGER", "value": 7, "vk": "scalar"}, {"name": "Parry", "type": "STRING", "value": "+4", "vk": "scalar"}, {"name": "Armour", "type": "STRING", "value": "4", "vk": "scalar"}, {"items": [{"fields": [{"name": "Weapon", "type": "STRING", "value": "The Blade Magolach", "vk": "scalar"}, {"name": "Rating", "type": "INTEGER", "value": 4, "vk": "scalar"}, {"name": "Damage", "type": "INTEGER", "value": 6, "vk": "scalar"}, {"name": "Injury", "type": "INTEGER", "value": 18, "vk": "scalar"}, {"items": [{"value": "Fiery Blow — see box", "vk": "scalar"}], "name": "Special Damage", "of": "STRING", "vk": "list"}, {"name": "Printed", "type": "STRING", "value": "The Blade Magolach 4 (6/18, Fiery Blow — see box)", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Weapon", "type": "STRING", "value": "Great Bow", "vk": "scalar"}, {"name": "Rating", "type": "INTEGER", "value": 3, "vk": "scalar"}, {"name": "Damage", "type": "INTEGER", "value": 4, "vk": "scalar"}, {"name": "Injury", "type": "INTEGER", "value": 16, "vk": "scalar"}, {"items": [{"value": "Pierce", "vk": "scalar"}], "name": "Special Damage", "of": "STRING", "vk": "list"}, {"name": "Printed", "type": "STRING", "value": "Great Bow 3 (4/16, Pierce)", "vk": "scalar"}], "vk": "def"}], "name": "Combat Proficiencies", "of": "Adversary Combat Proficiency", "ofHash": "#tor5AdvCombat000001", "vk": "list"}, {"items": [{"fields": [{"name": "Name", "type": "STRING", "value": "Fearless", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "Zoril’s Might is considered 1 higher for the purpose of resisting the Intimidate Foe combat task.", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Name", "type": "STRING", "value": "Snake-like Speed", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "When targeted by an attack, spend 1 Hate to make the attack roll Ill-favoured.", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Name", "type": "STRING", "value": "Yell of Triumph", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "Spend 1 Hate to restore 1 Hate or Resolve to all allies in the fight.", "vk": "scalar"}], "vk": "def"}], "name": "Fell Abilities", "of": "Fell Ability", "ofHash": "#tor5FellAbility0001", "vk": "list"}], "refs": [], "slot": null, "table": null, "type": "Adversary", "typeHash": "#TOR0020000000000"}, "#tbtMvvezu51HH1nGHwNu8Lo": {"book": "hands", "children": [], "choices": [], "desc": "The river is too deep to wade, so the Player-heroes will have to swim out or steal a boat. Swimming out is not especially difficult, but it requires an **ATHLETICS** roll to prevent Saruman’s blasting powder from getting wet, temporarily losing its effectiveness. There are always boats going back and forth, and one more might go unnoticed — if the Company can steal it undetected.\n\nSecond, Saruman’s blasting powder explodes when ignited. A **CRAFT** roll lets a Player-hero make a crude fuse, like a candle burning down — but where to plant the bomb? The Player-heroes could try setting the charge on a rowboat and sneaking away, but there are lots of ways that could go wrong — a breath of wind could snuff out the fuse, or it might be spotted by a sentry.\n\nA more reliable option is to get onboard and leave the explosive in some sheltered corner, but if they leave the explosives on the upper decks of the warship, they might succeed only in damaging the *Kathuphazgân*, not destroying it. The *Kathuphazgân* has weathered fires and storms before, and her crew are adept at repairing her if she’s merely wounded.\n\nThe best option (but most perilous for the Player-heroes) is to get onboard the ship, sneak down to the lower decks, and plant the charge below the waterline.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-there-let-them-lie-until-the-end.arc", "form": "DEF", "guidance": [], "id": "#tbtMvvezu51HH1nGHwNu8Lo", "key": "Blowing Up the Ship", "name": "Blowing Up the Ship", "parent": null, "props": [], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#tcErS7xso6tTr1GJih6CoDV": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "adversaries/tor2e-0.5-hands-sea-prince-guard.actor", "form": "DEF", "guidance": [], "id": "#tcErS7xso6tTr1GJih6CoDV", "key": "Sea-Prince Guard", "name": "Sea-Prince Guard", "parent": null, "props": [{"name": "Name", "type": "STRING", "value": "Sea-Prince Guard", "vk": "scalar"}, {"items": [{"value": "Disciplined", "vk": "scalar"}, {"value": "Wary", "vk": "scalar"}], "name": "Distinctive Features", "of": "STRING", "vk": "list"}, {"name": "Attribute Level", "type": "INTEGER", "value": 5, "vk": "scalar"}, {"name": "Endurance", "type": "INTEGER", "value": 20, "vk": "scalar"}, {"name": "Might", "type": "INTEGER", "value": 1, "vk": "scalar"}, {"name": "Resolve", "type": "INTEGER", "value": 5, "vk": "scalar"}, {"name": "Parry", "type": "STRING", "value": "+3", "vk": "scalar"}, {"name": "Armour", "type": "STRING", "value": "3", "vk": "scalar"}, {"items": [{"fields": [{"name": "Weapon", "type": "STRING", "value": "Spear", "vk": "scalar"}, {"name": "Rating", "type": "INTEGER", "value": 3, "vk": "scalar"}, {"name": "Damage", "type": "INTEGER", "value": 4, "vk": "scalar"}, {"name": "Injury", "type": "INTEGER", "value": 14, "vk": "scalar"}, {"items": [{"value": "Pierce", "vk": "scalar"}], "name": "Special Damage", "of": "STRING", "vk": "list"}, {"name": "Printed", "type": "STRING", "value": "Spear 3 (4/14, Pierce)", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Weapon", "type": "STRING", "value": "Short Sword", "vk": "scalar"}, {"name": "Rating", "type": "INTEGER", "value": 3, "vk": "scalar"}, {"name": "Damage", "type": "INTEGER", "value": 3, "vk": "scalar"}, {"name": "Injury", "type": "INTEGER", "value": 16, "vk": "scalar"}, {"items": [{"value": "Pierce", "vk": "scalar"}], "name": "Special Damage", "of": "STRING", "vk": "list"}, {"name": "Printed", "type": "STRING", "value": "Short Sword 3 (3/16, Pierce)", "vk": "scalar"}], "vk": "def"}], "name": "Combat Proficiencies", "of": "Adversary Combat Proficiency", "ofHash": "#tor5AdvCombat000001", "vk": "list"}, {"items": [{"fields": [{"name": "Name", "type": "STRING", "value": "Fearless", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "This creature’s Might is considered 1 higher for the purpose of resisting the Intimidate Foes combat task.", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Name", "type": "STRING", "value": "Thick Armour", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "Spend 1 Resolve point to gain (2d) on a Protection roll.", "vk": "scalar"}], "vk": "def"}], "name": "Fell Abilities", "of": "Fell Ability", "ofHash": "#tor5FellAbility0001", "vk": "list"}], "refs": [], "slot": null, "table": null, "type": "Adversary", "typeHash": "#TOR0020000000000"}, "#tcMxywq75NOL2ves69gurzl": {"book": "hands", "children": ["#tJqc068EbHQuvQTbmu3Hqbj", "#teXocuwF4vqG9Z4BO5jVH5a", "#tiKFB8DjGq8gMJ5SxizncBb", "#t6kos2scs41cWKv6Au7s6fQ", "#t4xGhgzU1PTvzRUZqrHDFaw", "#tu7E2UbJD7b2yAme56OywgB", "#tyerMPafdNxNVyLwW5uCofy", "#td5azUHunB6LcDb7ywnfOJK", "#tPgYynmzGXkYj9oihownazy", "#t74k6w0QD0NMcmYyVrOsNxa", "#tEtuAuHUkGiym4yINCBMxSe"], "choices": [], "desc": "*Nan Curunír*, the Valley of Saruman, is a great cleft at the southern end of the Misty Mountains. Many have heard of it, but few have visited: it lies away from the Road and many strange legends shroud it in mystery.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-introduction.ttrpg", "form": "DEF", "guidance": [], "id": "#tcMxywq75NOL2ves69gurzl", "key": "Locations", "name": "Locations", "parent": "#t5mXLkdNrxFIXVCfT0kUbiu", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#tce6CMMRcn2rordAlLVms1x": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-sea-prince-of-the-shore.arc", "form": "DEF", "guidance": [], "id": "#tce6CMMRcn2rordAlLVms1x", "key": "Old Lore", "name": "Old Lore", "parent": null, "props": [], "refs": [], "slot": "PHASE", "table": null, "type": null, "typeHash": null}, "#tckYh73mJP9eWgcBx17iVCC": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "tor2e-0.5-hands-there-let-them-lie-until-the-end.arc", "form": "DEF", "guidance": [], "id": "#tckYh73mJP9eWgcBx17iVCC", "key": "Old Lore", "name": "Old Lore", "parent": null, "props": [], "refs": [], "slot": "PHASE", "table": null, "type": null, "typeHash": null}, "#td5azUHunB6LcDb7ywnfOJK": {"book": "hands", "children": [], "choices": [], "desc": "Another legacy of the Dunlending occupation was the construction of this mead-hall, where warriors might drink their fill and tell tales of their exploits. Like the nearby huts, the mead-hall was built of stone salvaged from the fortifications of the Ring; the makers of the mead-hall stole from the tombs of long-forgotten Gondorian soldiers, so the faces of ancient dead heroes stare down at revellers.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-introduction.ttrpg", "form": "DEF", "guidance": [], "id": "#td5azUHunB6LcDb7ywnfOJK", "key": "7. Mead-hall", "name": "7. Mead-hall", "parent": "#tcMxywq75NOL2ves69gurzl", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#tdjfCMCvCSACYpLTAdEXypq": {"book": "hands", "children": ["#tu9RGNlZz11uT0zR4NvkM6e", "#t4NY9AKVE56II4EXWo5gCGI"], "choices": [], "desc": "A Company earning the patronage of the White Wizard gains a very powerful ally — Saruman is willing to generously support those who follow his counsel, especially if they don’t ask too many questions.\n\nHe is a formidable Wizard, well-versed in the art of crafting magical rings and inventing ingenious devices and machinery. One of his most potent tools is the power of his voice; its very sound acts as an enchantment, capable of influencing the thoughts and emotions of listeners. Whether speaking to allies or adversaries, he can choose to project an air of profound wisdom and reason, or sound both kind and authoritative when directing his followers. Regardless of his message, few can resist acquiescing to his requests or commands without a concerted effort to oppose his intentions.\n\nSaruman also possesses the ability to alter his appearance to resemble another Wizard, should it serve his purpose, or he might disguise himself as an innocuous old wanderer. He can move through his realm or while travelling without being noticed, as he can walk silently.\n\nA group of adventurers embarking on a mission with Saruman’s favour might find that others readily concede to their wishes and otherwise hesitant allies quickly comply with their directives (see *The Voice of Wisdom*, in the box below). They may discover their pace inexplicably quickens during travel, or that they can traverse terrain without leaving signs of their passage. The White Wizard might further equip such a group with cunning mechanical or alchemical inventions: a lamp that explodes into a fiery blast to breach a wall; a small wooden box containing a healing ointment for severe wounds; or a clockwork device able to unlock any mechanism.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-introduction.ttrpg", "form": "DEF", "guidance": [], "id": "#tdjfCMCvCSACYpLTAdEXypq", "key": "Saruman as a Patron", "name": "Saruman as a Patron", "parent": "#tt3qThmdMDDeiOEa4SfoqQ1", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#te0zhdAuZsdnIBrKRUrBhNV": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "adversaries/tor2e-0.5-hands-the-watcher-in-the-water.actor", "form": "DEF", "guidance": [], "id": "#te0zhdAuZsdnIBrKRUrBhNV", "key": "The Watcher In The Water", "name": "The Watcher In The Water", "parent": null, "props": [{"name": "Name", "type": "STRING", "value": "The Watcher In The Water", "vk": "scalar"}, {"items": [{"value": "Secretive", "vk": "scalar"}, {"value": "Watchful", "vk": "scalar"}], "name": "Distinctive Features", "of": "STRING", "vk": "list"}, {"name": "Attribute Level", "type": "INTEGER", "value": 10, "vk": "scalar"}, {"name": "Endurance", "type": "INTEGER", "value": 100, "vk": "scalar"}, {"name": "Might", "type": "INTEGER", "value": 3, "vk": "scalar"}, {"name": "Hate", "type": "INTEGER", "value": 10, "vk": "scalar"}, {"name": "Parry", "type": "STRING", "value": "—", "vk": "scalar"}, {"name": "Armour", "type": "STRING", "value": "4", "vk": "scalar"}, {"items": [{"fields": [{"name": "Weapon", "type": "STRING", "value": "Tentacle", "vk": "scalar"}, {"name": "Rating", "type": "INTEGER", "value": 3, "vk": "scalar"}, {"name": "Damage", "type": "INTEGER", "value": 8, "vk": "scalar"}, {"name": "Injury", "type": "INTEGER", "value": 16, "vk": "scalar"}, {"items": [{"value": "Seize", "vk": "scalar"}], "name": "Special Damage", "of": "STRING", "vk": "list"}, {"name": "Printed", "type": "STRING", "value": "Tentacle 3 (8/16, Seize)", "vk": "scalar"}], "vk": "def"}], "name": "Combat Proficiencies", "of": "Adversary Combat Proficiency", "ofHash": "#tor5AdvCombat000001", "vk": "list"}, {"items": [{"fields": [{"name": "Name", "type": "STRING", "value": "Denizen of the Dark", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "All attack rolls are Favoured while in darkness.", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Name", "type": "STRING", "value": "Foul Reek", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "Spend 1 Hate to cause all combatants engaged with the Watcher in the Water to lose (1d) on all attacks for the round.", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Name", "type": "STRING", "value": "Hate Sunlight", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "The Watcher in the Water loses 1 Hate at the start of each round it is exposed to the full light of the sun.", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Name", "type": "STRING", "value": "Hideous Toughness", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "The creature is unaffected by unarmed attacks. Additionally, when an attack inflicts damage to the creature that would cause it to go to zero Endurance, it causes a Piercing Blow instead. Then, if the creature is still alive its Endurance score is set back at half its maximum rating.", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Name", "type": "STRING", "value": "Horrible Strength", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "If the creature scores a Piercing Blow, spend 1 Hate to make the target’s Protection roll Ill-favoured.", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Name", "type": "STRING", "value": "Long Arms", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "Spend 1 Hate to attack any Player-hero, in any combat stance, including rearward (same as Great Leap).", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Name", "type": "STRING", "value": "Many Arms", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "The Watcher in the Water makes one additional attack each round. Each time it receives a Wound, however, for the rest of the fight the Watcher in the Water can make one less attack than those normally allowed (three attacks if Wounded once, two attacks if Wounded twice).", "vk": "scalar"}], "vk": "def"}], "name": "Fell Abilities", "of": "Fell Ability", "ofHash": "#tor5FellAbility0001", "vk": "list"}], "refs": [], "slot": null, "table": null, "type": "Adversary", "typeHash": "#TOR0020000000000"}, "#te7eGRQB0Ma1UglIWoOw4x8": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [{"fields": [{"name": "Shadow", "type": "STRING", "value": "+1/2/3", "vk": "scalar"}], "name": "Fixed amount", "vk": "def"}, {"fields": [{"name": "Shadow", "type": "INTEGER", "value": 1, "vk": "scalar"}], "name": "The Player-heroes committed Misdeeds collectively worth 4 Shadow points or more", "vk": "def"}, {"fields": [{"name": "Shadow", "type": "INTEGER", "value": 1, "vk": "scalar"}], "name": "One or both of Usapthon or Zoril survive", "vk": "def"}, {"fields": [{"name": "Shadow", "type": "INTEGER", "value": 2, "vk": "scalar"}], "name": "The *Kathuphazgân* survives", "vk": "def"}, {"fields": [{"name": "Shadow", "type": "INTEGER", "value": 1, "vk": "scalar"}], "name": "The Ents learn of Saruman’s blasting powder", "vk": "def"}], "enum": null, "file": "tor2e-0.5-hands-worksheet-saruman-s-shadow-score.ttrpg", "form": "DEF", "guidance": [], "id": "#te7eGRQB0Ma1UglIWoOw4x8", "key": "There Let Them Lie Until the End Shadow Score", "name": "There Let Them Lie Until the End Shadow Score", "parent": "#tpJlHhqZkg9A5XXth6GJn5l", "props": [], "refs": [], "slot": null, "table": {"columns": ["Trigger", "Shadow", "Tally"], "rows": [["Fixed amount", "+1/2/3", ""], ["The Player-heroes committed Misdeeds collectively worth 4 Shadow points or more", "+1", ""], ["One or both of Usapthon or Zoril survive", "+1", ""], ["The *Kathuphazgân* survives", "+2", ""], ["The Ents learn of Saruman’s blasting powder", "+1", ""]]}, "type": "Table", "typeHash": "#tor5Table0000000001"}, "#teXocuwF4vqG9Z4BO5jVH5a": {"book": "hands", "children": [], "choices": [], "desc": "The gardens of Isengard were neglected and left to run riot in the chaotic years before Saruman. The Wizard has put things right, although some might say his tastes are somewhat stark. Now the gardens are all perfectly manicured green lawns and uniform hedgerows, and many beds where rare plants and herbs are cultivated. Greenhouses protect rare plants gathered from the distant lands of the South and East. Every plant known to the herb-masters grows here, even ones that are perilous and poisonous. Everything here has a use; beauty is of little concern to the master of this garden. There will be time for pretty flowers when the Enemy is defeated.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-introduction.ttrpg", "form": "DEF", "guidance": [], "id": "#teXocuwF4vqG9Z4BO5jVH5a", "key": "2. The Gardens", "name": "2. The Gardens", "parent": "#tcMxywq75NOL2ves69gurzl", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#tf4zlNrO2T97gZGI5UB8Vml": {"book": "hands", "children": [], "choices": [], "desc": "Nidi’s map shows that they last saw the master-smith in West Moria. The western portion of Khazad-dûm was a stronghold in its own right, a Dwarf-hold equal to any of the halls in the Blue Mountains or Iron Hills. It was so far from the Dwarrowdelf and so prosperous for a time that its Lords grew haughty, and considered themselves princes, second only to the Kings.\n\nToday, West Moria is an eerie place. The Orcs have not made as much mischief here as they have in the east; the citadel has been stripped of many of its treasures, but overall is much more intact. Gilt and gemstones still glimmer in the dark, waiting to be discovered by keen-eyed treasure hunters.\n\nEventually, the Player-heroes find a few Dwarf-runes freshly chalked on one wall — an F-rune and an arrow.\n\nFollowing that passageway leads the Player-heroes to the Crypt of the Smiths (see next page).", "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-quest-of-moria.arc", "form": "DEF", "guidance": [], "id": "#tf4zlNrO2T97gZGI5UB8Vml", "key": "Searching for Finir", "name": "Searching for Finir", "parent": null, "props": [{"items": [{"value": "Searching for Finir is accomplished with a Laborious (Resistance 6) Skill Endeavour using **EXPLORE**, **HUNTING**, **SCAN** or **TRAVEL**. The time limit is 5 if the Player-heroes entered via the West-gate, and 4 otherwise. For every Skill roll, also roll on the Moria Hazards table (page 73). If the Player-heroes fail the Skill Endeavour, they still find Finir but will be penalised in Part 6 (the Loremaster should make a note of it).", "vk": "scalar"}], "name": "Rules", "of": "STRING", "vk": "list"}], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#tfttFbP3F4WmwRWvvezUHHi": {"book": "hands", "children": [], "choices": [], "desc": "Saruman’s doom is not fixed. His fate is almost wholly in the hands of the Player-heroes. It’s possible that they’ll be able to save him — and if he falls, it will be because of them.\n\nIn addition to the fixed increase above (regardless of the option chosen), Saruman’s Shadow may rise in response to the actions and choices of the Player-heroes. Each adventure lists potential Shadow gains for Saruman.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-introduction.ttrpg", "form": "DEF", "guidance": [], "id": "#tfttFbP3F4WmwRWvvezUHHi", "key": "Even the Very Wise Cannot See All Ends", "name": "Even the Very Wise Cannot See All Ends", "parent": "#tYTRDNCyEPe4yv1Uy7AZqe8", "props": [{"items": [{"value": "*Raise Saruman’s Shadow by 1 after each adventure.*", "vk": "scalar"}], "name": "Items", "of": "STRING", "vk": "list"}], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#tgCTe9mOuQoEkbXOvMJHjtD": {"book": "hands", "children": [], "choices": [], "desc": "Sellic is no warrior — if the Player-heroes can corner him where he cannot escape or call for aid, they can easily force him to confess. He’ll try to twist the truth — claiming, for example, that the Prince forced him to serve, or that Gildor gave him the flute as a birthday present — but any **AWE** or **INSIGHT** roll will get the truth from him.\n\nHe admits that he met the Elf Gildor Inglorion some weeks ago, and that the Elf came to him as a friend, seeking knowledge of certain ancient melodies that are sung among the folk of Enedwaith. He grew jealous of Gildor, and when the opportunity to curry favour with the Prince arose, he betrayed Gildor and had him taken captive. The Elf is imprisoned in the cellars of the Prince’s Tower.\n\nAs Sellic is a regular visitor to the Prince’s Tower, the Player-heroes might use **ENHEARTEN** to convince him to atone for his misdeeds by opening the doors for them.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-sea-prince-of-the-shore.arc", "form": "DEF", "guidance": [], "id": "#tgCTe9mOuQoEkbXOvMJHjtD", "key": "Confronting Sellic", "name": "Confronting Sellic", "parent": null, "props": [], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#tgrohATn15Wpi4QqwZl0eoL": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "tor2e-0.5-hands-introduction.ttrpg", "form": "DEF", "guidance": [], "id": "#tgrohATn15Wpi4QqwZl0eoL", "key": "Preamble", "name": "Preamble", "parent": "#tYTRDNCyEPe4yv1Uy7AZqe8", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#tgtf6GEUQP4RSsNyfoI65Le": {"book": "hands", "children": [], "choices": [], "desc": "The Loremaster must describe to the players the changes that have transpired in Crow Hall since *The Beast of Dunland*. How much time has passed since then? With Saruman’s aid and patronage, the Dunlendings have grown in strength and numbers, and that newfound might should be reflected in Crow Hall. The hall reflects the personality of the present Lord.\n\nHe bargains hard with the Player-heroes, demanding that they promise weapons and armour from the forges of Isengard.\n\nIn answer to Saruman’s summons, the Dunlendings of Crow Hall muster some three dozen warriors, every one of them skilled with spear and bow. They paint the image of the White Hand of Isengard onto their shields before departing the Hall — and a great flock of crows go with them, hungry for carrion.\n\nHaving the proud warriors of Crow Hall as the Player-heroes’ Host makes all rolls on the Battle Outcome table *Favoured*.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-there-let-them-lie-until-the-end.arc", "form": "DEF", "guidance": [], "id": "#tgtf6GEUQP4RSsNyfoI65Le", "key": "Allies from Crow Hall", "name": "Allies from Crow Hall", "parent": null, "props": [{"items": [{"value": "If **Gorsad** is still lord, then he’s an old man now, blind and on the verge of losing his wits. His hall is full of other old men, telling tales of days long past.", "vk": "scalar"}, {"value": "If **Toirlas** is chieftain, then he has grown into a canny warlord. Not for him the impetuous raids of his youth.", "vk": "scalar"}, {"value": "**Vila**, if she has become chieftain, is growing into a capable but cruel young woman, well able to rule Crow Hall with iron fist and barbed wit. She sees herself as Saruman’s daughter more than Gorsad’s.", "vk": "scalar"}], "name": "Items", "of": "STRING", "vk": "list"}], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#thKnwvX16tQ2jUO5d1K7AQV": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "loremaster-characters/tor2e-0.5-hands-toirlas.actor", "form": "DEF", "guidance": [], "id": "#thKnwvX16tQ2jUO5d1K7AQV", "key": "Toirlas", "name": "Toirlas", "parent": null, "props": [{"name": "Name", "type": "STRING", "value": "Toirlas", "vk": "scalar"}, {"name": "Occupation", "type": "STRING", "value": "Warrior Prince", "vk": "scalar"}, {"items": [{"value": "Generous", "vk": "scalar"}, {"value": "Impulsive", "vk": "scalar"}], "name": "Distinctive Features", "of": "STRING", "vk": "list"}, {"name": "Location", "type": "STRING", "value": "Toirlas", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "The heir to Crow Hall, Toirlas thinks of himself as a legend in waiting. He dreams of being worthy of song like Wulf, the Dunlending king who took the hall of Meduseld — and, in truth, he has a chance. He’s charismatic, generous, a good swordsman, a passable general — and most of all, he’s lucky. With a nudge, he could become a legend.\n\nShould the Player-heroes come to fight him, Toirlas has the same stats as a Southerner Champion, and his warriors are Southerner Raiders.", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Loremaster Character", "typeHash": "#TOR0030000000000"}, "#thfBe9RRvTDtaLewSh4cm7g": {"book": "hands", "children": [], "choices": [], "desc": "Finir refuses to leave the crypt until he’s searched it for Ring-lore. What do the Player-heroes do?", "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-quest-of-moria.arc", "form": "DEF", "guidance": [], "id": "#thfBe9RRvTDtaLewSh4cm7g", "key": "Searching for Ring-lore", "name": "Searching for Ring-lore", "parent": null, "props": [{"items": [{"value": "If they force him to give up his quest and accompany them to Isengard, then they must overpower him. Use the stats of a **Southerner Champion** holding a Mattock (7/18, Break Shield) instead of the normal weapons.", "vk": "scalar"}, {"value": "If they let Finir search the tombs by himself, then it takes him several hours to find the Ring-wight’s crypt. Run *The Siege of the Crypt* while this is going on. Once he finds Kinir’s tomb, Finir opens it and is slain by the Ring-wight unless the Player-heroes step in to protect him.", "vk": "scalar"}, {"value": "If the Player-heroes search the tombs, they can likely find the right tomb much more quickly.", "vk": "scalar"}], "name": "Items", "of": "STRING", "vk": "list"}], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#thoJJlmqKBxMEUNytRwQpFX": {"book": "hands", "children": [], "choices": [], "desc": "Later in the evening Dunwalla approaches the Player-hero with the highest **WISDOM**, and asks to speak with them privately. If they agree, she takes the hero off to her private chamber — a tower room, the stone floor stained with the droppings of birds. There’s a small shrine in one corner, a tangle of sticks and bones and bird skulls that is somehow unsettling. A pot of sticky, foul-smelling tree sap with a candle wick stuck in it smoulders in the shrine, and the smoke is heady and sickening. Dunwalla traffics with dark powers.\n\nDunwalla says that she knows (or guesses) that the Player-heroes are emissaries of Isengard, and wants them to understand the White Wizard has no business meddling in the affairs of Crow Hall. The Dunlendings will choose their own path, and deal with their own troubles. Soon, Toirlas will return, and he will lead the clan into better days. She has no quarrel with the Player-heroes — as long as they do not interfere. They will have no luck hunting the beast — she continues. If they try, they will perish.\n\nIf they have not yet handed over the silver box sent by Saruman, she demands to see it (even if the Player-heroes have not mentioned it to her). Should they hand it over, she takes the medicine from it and scornfully gives back the silver.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-beast-of-dunland.arc", "form": "DEF", "guidance": [], "id": "#thoJJlmqKBxMEUNytRwQpFX", "key": "The Counsel of Dunwalla", "name": "The Counsel of Dunwalla", "parent": null, "props": [], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#ti6nmbhULYrOf5xMstPN3gn": {"book": "hands", "children": [], "choices": [], "desc": "The Player-heroes find Finir at the entrance to the Crypt, a massive door of marble, sealed for a thousand years (see location #2 of the Crypt of the Smiths). Finir has been hewing away at it, and he has nearly broken through. He has established a small camp in a side room — a cache of supplies, a bedroll, and access to a clean-water well. (The waters of West Moria are cleaner than those of the eastern city).\n\nFinir initially (and not unreasonably) assumes the Player-heroes are Orcs, and lies in wait in the shadows with his mattock readied. Unless the Player-heroes announce themselves, or succeed at an **AWARENESS** roll to spot the lurking Dwarf, then Finir strikes at the lead traveller with all his might, inflicting a grievous Endurance loss (consider it as from falling).\n\nFinir has been alone in this section of Moria for weeks, although he is surprised that so much time has passed. He thought it only a few days, alone in the dark. He assumes that Balin sent the Company. Or Dáin, or Thorin, or Thráin. It doesn’t matter. Only the work matters.\n\nHe is clearly deranged, his eyes too bright, his gaze darting around like he’s watching an invisible insect, his hair and beard rank and matted. *“I’m nearly through,”* he hisses, *“the Tomb of the Smiths. The guild of smiths, all the way back to Durin’s day. To Narvi. Secrets buried with them. We must finish the work.”*\n\nHere are some questions that the Player-heroes may likely ask Finir:\n\nFinir also refuses to accompany the Player-heroes out of Moria, not until he’s had a chance to search the Tombs. The Player-heroes can force him to accompany them (a Misdeed), or they can indulge the Dwarf and fulfil Saruman’s commands by searching the Crypt for ring-lore.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-quest-of-moria.arc", "form": "DEF", "guidance": [], "id": "#ti6nmbhULYrOf5xMstPN3gn", "key": "Finir’s Camp", "name": "Finir’s Camp", "parent": null, "props": [{"items": [{"value": "Finir should be portrayed in a way that subtly reminds the Player-heroes of Saruman. If the Loremaster used any verbal tics or gestures when portraying the White Wizard, these should be replicated here — perhaps exaggerated — to highlight Finir’s arrogance and secretiveness. The overall aim is to convey that Finir is displaying the flaws associated with someone who is prideful and keeps his true intentions hidden.", "vk": "scalar"}], "name": "Rules", "of": "STRING", "vk": "list"}, {"items": [{"value": "**What happened to Óin and the other Dwarves?** Finir shrugs; they went away somewhere. Off into the dark. He doesn’t know where. It doesn’t matter. The work is all that’s important. The work will save the expedition.", "vk": "scalar"}, {"value": "**What work? **The making of Rings. The High Elves started the craft, but the High Elves are all gone now, and the Elves of Mirkwood know nothing of the work. The metal doesn’t call to them like it sings to Finir. No, the Dwarves must finish the work. The glories of the past must be preserved, restored, made imperishable, eternal, the passing years bent into a Ring. There are secrets in the tombs beyond the door, he knows it. The old smiths call to him.", "vk": "scalar"}, {"value": "**How do we get out of here?** Finir doesn’t know. Or care. Finding the Rings, that matters.", "vk": "scalar"}], "name": "Items", "of": "STRING", "vk": "list"}], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#tiKFB8DjGq8gMJ5SxizncBb": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "tor2e-0.5-hands-introduction.ttrpg", "form": "DEF", "guidance": [], "id": "#tiKFB8DjGq8gMJ5SxizncBb", "key": "Isengard", "name": "Isengard", "parent": "#tcMxywq75NOL2ves69gurzl", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#til3ET6BzIaUeghw0sf0XMZ": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "loremaster-characters/tor2e-0.5-hands-dunrach-captain-of-the-guard.actor", "form": "DEF", "guidance": [], "id": "#til3ET6BzIaUeghw0sf0XMZ", "key": "Dunrach, Captain of the Guard", "name": "Dunrach, Captain of the Guard", "parent": null, "props": [{"name": "Name", "type": "STRING", "value": "Dunrach, Captain of the Guard", "vk": "scalar"}, {"name": "Location", "type": "STRING", "value": "Poor Welcomes", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "Grey his beard, grey his hair. His shoulders are stooped, his back bent. But what are these if not the scars of time, and Dunrach already bears many scars. He lost his eye to a cast stone, three fingers to a knife-wound, and he walks with a limp ever since he was trampled by a horse in Rohan. But know this — even though blinded by pain and blood, Dunrach caught the stone-thrower and dashed his head against a wall. Even though he had only one finger and a thumb left, it was enough to draw his own knife and cut the thief’s throat. And even though he was trampled, his hip broken, he had enough strength to throw his own spear through the rider’s back. For Dunrach, all victories must be bought with pain.\n\nHe yearned to be chieftain in Crow’s Hall, but that ambition was thwarted when his young cousin Gorsad returned from the Wizard’s Vale.", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Loremaster Character", "typeHash": "#TOR0030000000000"}, "#tjB25fRS8YcLtFFhqULF80W": {"book": "hands", "children": [], "choices": [], "desc": "As the Company pass through the Morgul Vale, each of the Player-heroes is challenged. The topmost level of the great tower in the city rotates, swivelling back and forth like some watchful giant, and its gaze falls upon each Player-hero in turn. A Feat die roll is required to determine the sort of ordeal each Player-hero faces (or pick one that suits them best).\n\nThe Loremaster must keep in mind the following:\n\n**Ordeal of Valour:** Some dreadful sight tests the Player-hero’s courage. It might be the sheer oppression of the Vale, the sight of the climb ahead, or a specific circumstance — for example, as the Company creep along, the tested Player-hero is separated from the rest and has the opportunity to sneak away home. The Player-hero gains 3 Shadow (Dread). Those who fail their Shadow test or who are Miserable increase the Eye Awareness of the Company by 2.\n\n**Ordeal of Wisdom:** Malign spirits whisper dark words, and dreadful visions appear on the path; eldritch energies crawl through the air, hideous statues scan the landscape. The Player-hero might be seized with unnatural exhaustion, as Frodo was, or perceive the alien *awareness* behind the moonlit walls of Minas Morgul. The Player-hero gains 3 Shadow (Sorcery). Those who fail their Shadow test or who are Miserable gain 4 Fatigue.\n\n**Ordeals of Temptation:** The Player-hero has a chance to flee the Vale, or to indulge their Shadow Path. A Treasure Hunter might glimpse the glint of gold amid the rocks, and a Scholar might hear whispering voices from Minas Morgul, calling them to glory. Simpler temptations also work — the Player-hero might be seized by the sudden thought that they could throw this heavy and foul-smelling cask into the waters of the Morgulduin. The Player-hero may choose to either gain 3 Shadow points (Greed) or give into temptation, increasing the Eye Awareness of the Company by 2.\n\n**Ordeal of Obstacles:** The Player-hero must overcome a physical barrier — climb over treacherous rocks, fight through a thicket of thorns, find the way ahead through the darkness. Failing whatever roll the Loremaster chooses (**ATHLETICS**, **EXPLORE**, **SCAN**, or **STEALTH**) causes a severe Endurance loss and increases the Eye Awareness of the Company by 1.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-ithil-stone.arc", "form": "DEF", "guidance": [], "id": "#tjB25fRS8YcLtFFhqULF80W", "key": "The Sentinel Gaze of Minas Ithil", "name": "The Sentinel Gaze of Minas Ithil", "parent": null, "props": [{"items": [{"value": "Remember to track the Company’s Eye Awareness — the challenge here is to avoid notice.", "vk": "scalar"}, {"value": "This may be an excellent moment for Saruman to intercede — or betray the Company (see *The Choices of Saruman, Final Part* on page 138).", "vk": "scalar"}, {"value": "Intersperse these ordeals with the *Terrors of the Vale*.", "vk": "scalar"}], "name": "Items", "of": "STRING", "vk": "list"}], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#tjtCr5xGZ3h7RxPQi1CGCTY": {"book": "hands", "children": [], "choices": [], "desc": "If the Player-heroes complete their Skill Endeavour within the set time limit, then they find the resting place of the Corsair vessel with most of the warband of Isengard intact.\n\nIf they fail to complete the Skill Endeavour in time, then one of the following penalties must be applied based on the number of missing successes. (For example, it’s 2 missing\n\nsuccesses if the Resistance was 6 and the Player-heroes only accumulated 4 successes).", "entries": [], "enum": null, "file": "tor2e-0.5-hands-there-let-them-lie-until-the-end.arc", "form": "DEF", "guidance": [], "id": "#tjtCr5xGZ3h7RxPQi1CGCTY", "key": "The Cost of the Hunt", "name": "The Cost of the Hunt", "parent": null, "props": [{"items": [{"value": "**1 or more missing successes:** Scouts spot the advancing Player-heroes: the Corsairs are warned and on guard against intruders.", "vk": "scalar"}, {"value": "**2 or more missing successes:** The Host is severely diminished. All rolls on the Battle Outcome table are *Ill-favoured*.", "vk": "scalar"}, {"value": "**3 or more missing successes:** The search for the Black Ship has failed! By the time the Player-heroes reach the Girdle of Usapthon, the *Kathuphazgân* has already set sail, and the Corsair expedition is returning victorious to Umbar.", "vk": "scalar"}], "name": "Items", "of": "STRING", "vk": "list"}], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#tkADYJjO3zfnt8jT4bHAB3F": {"book": "hands", "children": [], "choices": [], "desc": "The actual trail of the beast is invisible, for it leaves no footprints in mud or snow. However, the Player-heroes find the remains of one of its kills, a deer caught and savaged in the woods. Crows peck at the carcass. A trail of dripping blood leads north-east towards the mountains and the Eordscrafa (see *Part 5: The Eordscrafa*, on page 36).", "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-beast-of-dunland.arc", "form": "DEF", "guidance": [], "id": "#tkADYJjO3zfnt8jT4bHAB3F", "key": "The Trail to the Eordscrafa", "name": "The Trail to the Eordscrafa", "parent": null, "props": [], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#tkqbWk8K0sfbQeWInCmW2LH": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "adversaries/tor2e-0.5-hands-ranger-of-ithilien.actor", "form": "DEF", "guidance": [], "id": "#tkqbWk8K0sfbQeWInCmW2LH", "key": "Ranger Of Ithilien", "name": "Ranger Of Ithilien", "parent": null, "props": [{"name": "Name", "type": "STRING", "value": "Ranger Of Ithilien", "vk": "scalar"}, {"items": [{"value": "Stealthy", "vk": "scalar"}, {"value": "Wary", "vk": "scalar"}], "name": "Distinctive Features", "of": "STRING", "vk": "list"}, {"name": "Attribute Level", "type": "INTEGER", "value": 6, "vk": "scalar"}, {"name": "Endurance", "type": "INTEGER", "value": 24, "vk": "scalar"}, {"name": "Might", "type": "INTEGER", "value": 1, "vk": "scalar"}, {"name": "Resolve", "type": "INTEGER", "value": 6, "vk": "scalar"}, {"name": "Parry", "type": "STRING", "value": "+1", "vk": "scalar"}, {"name": "Armour", "type": "STRING", "value": "3", "vk": "scalar"}, {"items": [{"fields": [{"name": "Weapon", "type": "STRING", "value": "Spear", "vk": "scalar"}, {"name": "Rating", "type": "INTEGER", "value": 3, "vk": "scalar"}, {"name": "Damage", "type": "INTEGER", "value": 4, "vk": "scalar"}, {"name": "Injury", "type": "INTEGER", "value": 16, "vk": "scalar"}, {"items": [{"value": "Pierce", "vk": "scalar"}], "name": "Special Damage", "of": "STRING", "vk": "list"}, {"name": "Printed", "type": "STRING", "value": "Spear 3 (4/16, Pierce)", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Weapon", "type": "STRING", "value": "Great Bow", "vk": "scalar"}, {"name": "Rating", "type": "INTEGER", "value": 3, "vk": "scalar"}, {"name": "Damage", "type": "INTEGER", "value": 4, "vk": "scalar"}, {"name": "Injury", "type": "INTEGER", "value": 16, "vk": "scalar"}, {"items": [{"value": "Pierce", "vk": "scalar"}], "name": "Special Damage", "of": "STRING", "vk": "list"}, {"name": "Printed", "type": "STRING", "value": "Great Bow 3 (4/16, Pierce)", "vk": "scalar"}], "vk": "def"}], "name": "Combat Proficiencies", "of": "Adversary Combat Proficiency", "ofHash": "#tor5AdvCombat000001", "vk": "list"}, {"items": [{"fields": [{"name": "Name", "type": "STRING", "value": "Fearless", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "A Ranger of Ithilien’s Might is considered 1 higher for the purpose of resisting the Intimidate Foes combat task.", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Name", "type": "STRING", "value": "Wind-like Speed", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "When targeted by an attack, spend 1 Resolve to make the attack roll Ill-favoured.", "vk": "scalar"}], "vk": "def"}], "name": "Fell Abilities", "of": "Fell Ability", "ofHash": "#tor5FellAbility0001", "vk": "list"}], "refs": [], "slot": null, "table": null, "type": "Adversary", "typeHash": "#TOR0020000000000"}, "#tkr3nZGlduWl0tDNrJhJVyH": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-disaster-of-the-gladden-fields.arc", "form": "DEF", "guidance": [], "id": "#tkr3nZGlduWl0tDNrJhJVyH", "key": "The Harper’s Hall", "name": "The Harper’s Hall", "parent": null, "props": [], "refs": [], "slot": "PHASE", "table": null, "type": null, "typeHash": null}, "#tkv1nozeFJzHaQs6xJxCsLr": {"book": "hands", "children": [], "choices": [], "desc": "The Player-heroes — or their scouts — see a curious thing in the distance just as they’re making camp: a tree, in the midst of the almost treeless plains of the Enedwaith. It’s not completely strange, for there are a few thickets and wooded regions outside the dark forests of the Eryn Vorn, but it’s still an oddity — especially as it’s a mountain ash, right in the middle of a plain. Even more curiously, the tree *moves* during the night. When the Player-heroes awaken, the tree has gone. They come across it again during their explorations the next day — the same tree, several miles further down the river.\n\nFor this is not a tree — it is an Ent, Lightroot, of Quickbeam’s folk. The Ent reveals himself only if challenged, or if there are Elves among the Company (certainly not if the Player-heroes are associating with Orcs, *burarum*), or if they mention the name of Saruman. After all, Saruman is a neighbour of the Ents of Fangorn, and has from time to time walked in their woods and conversed with Treebeard himself.\n\nLightroot explains that he has gone on a Quest (he is such a young, excitable and hasty Ent that you can hear the capital letters in his voice) because the Ents have tasted strange dreams in the rainwater coming over the mountains. Something has awoken a very old wood — and he’s not sure if it’s a good thing. He picks up a great handful of soil and lets it trickle through his twig-like fingers, explaining that this land is a vast grave of the forests of Enedwaith, and the dead trees slumber now, felled by the axes of Númenor. It troubles him that the ghosts of trees should be stirred up now. The world is changing, and unseen powers are moving.\n\nHowever — if the Player-heroes attack or offend the Ent, or if they have Orcs with them, or if Lightroot gets a sniff of Saruman’s blasting powder (*“Ash and death! Fire and malice! A foulness! A foulness!”*), then he assumes they are foes. He may attack them, terrify some of their followers into fleeing, or at the very least bring word back to Fangorn that the White Wizard cannot be trusted.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-there-let-them-lie-until-the-end.arc", "form": "DEF", "guidance": [], "id": "#tkv1nozeFJzHaQs6xJxCsLr", "key": "A Wandering Tree", "name": "A Wandering Tree", "parent": null, "props": [{"items": [{"value": "If the Player-heroes use sufficient **COURTESY** and seem trustworthy, then Lightroot agrees to help them. This counts as three bonus successes on their current Skill Endeavour.", "vk": "scalar"}], "name": "Rules", "of": "STRING", "vk": "list"}], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#tkzG1FdwMCe3MPe5QNOqLI9": {"book": "hands", "children": ["#tzVnWVBO3ZyemOC7PInDb7s"], "choices": [], "desc": null, "entries": [], "enum": null, "file": "tor2e-0.5-hands-worksheet-saruman-s-shadow-score.ttrpg", "form": "DEF", "guidance": [], "id": "#tkzG1FdwMCe3MPe5QNOqLI9", "key": "The Beast of Dunland", "name": "The Beast of Dunland", "parent": "#t4tH0BF1gelfgVc1eyhWAuw", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#tl2E6XWKwBvyi4XnZ320AEp": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "loremaster-characters/tor2e-0.5-hands-baugrims-black-uruks.actor", "form": "DEF", "guidance": [], "id": "#tl2E6XWKwBvyi4XnZ320AEp", "key": "Baugrim’s Black Uruks", "name": "Baugrim’s Black Uruks", "parent": null, "props": [{"name": "Name", "type": "STRING", "value": "Baugrim’s Black Uruks", "vk": "scalar"}, {"name": "Location", "type": "STRING", "value": "Arcinyas’ Tale", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "Large and evil Orcs of great strength, picked from among the fiercest to act as lieutenants, bodyguards or chosen warriors, sent to reinforce a colony of lesser Orcs.", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Loremaster Character", "typeHash": "#TOR0030000000000"}, "#tl3mvAePpF4pEYLURHpxeMH": {"book": "hands", "children": [], "choices": [], "desc": "It is clear to anyone with experience (at least a rank in **BATTLE**) that the *Kathuphazgân* must carry a host of heavily armed warriors, and that it is a threat beyond the present capabilities of the Player-heroes. Even if every warrior in Todden took up arms against that mighty sea-fortress, they would have no hope of victory.\n\nIf the Player-heroes (or anyone else) interferes, then marines from the ship are dispatched to deal with the danger. The Corsairs assume the Player-heroes are mere troublemakers from the local fisher-folk, and so do not pursue them for long. The ship’s primary purpose here is to pick up the ‘Sea-prince’ and any supplies he’s assembled, and it does not linger for long.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-sea-prince-of-the-shore.arc", "form": "DEF", "guidance": [], "id": "#tl3mvAePpF4pEYLURHpxeMH", "key": "Perils of Kathuphazgân", "name": "Perils of Kathuphazgân", "parent": null, "props": [], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#tlANy3rAKYzeWuGiMSr9s7r": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "loremaster-characters/tor2e-0.5-hands-edlenneth-the-guard-captain.actor", "form": "DEF", "guidance": [], "id": "#tlANy3rAKYzeWuGiMSr9s7r", "key": "Edlenneth the Guard-Captain", "name": "Edlenneth the Guard-Captain", "parent": null, "props": [{"name": "Name", "type": "STRING", "value": "Edlenneth the Guard-Captain", "vk": "scalar"}, {"name": "Occupation", "type": "STRING", "value": "Captain of the Guard", "vk": "scalar"}, {"items": [{"value": "Lordly", "vk": "scalar"}, {"value": "Proud", "vk": "scalar"}], "name": "Distinctive Features", "of": "STRING", "vk": "list"}, {"name": "Location", "type": "STRING", "value": "Locations", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "The captain of Isengard’s garrison is a woman of Gondor. She descends from the Gondorian chieftains who held Isengard of old, although her branch of the family returned south in the days of Wulf son of Freca. When Saruman was given the keys of Orthanc in 2756 by Steward Beren, Edlenneth’s great-grandfather rode west with the White Wizard. Edlenneth is deeply conscious and proud of her ancient lineage, and always wears the antique armour bearing the sigil of the White Tree surrounded by the Ring of Isengard. She even speaks in a manner that seems old-fashioned and overly formal.", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Loremaster Character", "typeHash": "#TOR0030000000000"}, "#tlOU3uJ94OmDayEpuL1HurS": {"book": "hands", "children": [], "choices": [], "desc": "If their Gondorian contact is arrested because of his illicit dealings (see above), then the Player-heroes have a choice. They can either slip into the host without Alagoson’s help with successful **STEALTH** rolls (Dwarves and Hobbits *lose [1d]*, since their shapes are less likely to go unnoticed; failure means getting arrested), try to find another way across, or go to Húrin Snowhair, the commander of Cair Andros (see below).", "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-ithil-stone.arc", "form": "DEF", "guidance": [], "id": "#tlOU3uJ94OmDayEpuL1HurS", "key": "Alagoson Arrested", "name": "Alagoson Arrested", "parent": null, "props": [], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#tlkh3h7Lw0AmuLDFODjEZTk": {"book": "hands", "children": [], "choices": [], "desc": "To enter the Landmark, the Corsairs must excavate and then break down the doors of the Admiral’s Tomb. If the Skill Endeavour to search for the Black Ship failed, then the Corsairs have already torn down the doors by the time the Player-heroes arrive. Saruman’s blasting powder is also efficacious at opening the doorway.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-there-let-them-lie-until-the-end.arc", "form": "DEF", "guidance": [], "id": "#tlkh3h7Lw0AmuLDFODjEZTk", "key": "Breaking Down the Doors", "name": "Breaking Down the Doors", "parent": null, "props": [], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#tllao9XzkP3SHHIChbuzbun": {"book": "hands", "children": [], "choices": [], "desc": "If Redtooth reached Moria before the Player-heroes caught up with him, then he and his Orcs (two Orc Soldiers and one Goblin Archer for each Player-hero) gather in the Sixteenth Hall to celebrate their victory. Orcs are by nature bitter and cruel — they may make merry for a little while, but only while they have prisoners to torment or some other distraction from their own unworthy souls. Left to their own devices, their merriment turns rancorous and fights soon break out.\n\nPlayer-heroes who sneak into the Sixteenth Hall and stay hidden can exploit these divisions by throwing stones or whispering insults in the dim firelight. For example, a successful **RIDDLE** roll can start a fist-fight among the Orcs; with a good enough success, they can even ensnare mighty Redtooth in the quarrels.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-disaster-of-the-gladden-fields.arc", "form": "DEF", "guidance": [], "id": "#tllao9XzkP3SHHIChbuzbun", "key": "Redtooth’s Celebration", "name": "Redtooth’s Celebration", "parent": null, "props": [], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#tlona8YOY48U8Xm0NFaScgP": {"book": "hands", "children": ["#t9ZI429ynJJHdK9A49rL5cx"], "choices": [], "desc": null, "entries": [], "enum": null, "file": "tor2e-0.5-hands-worksheet-saruman-s-shadow-score.ttrpg", "form": "DEF", "guidance": [], "id": "#tlona8YOY48U8Xm0NFaScgP", "key": "The Quest of Moria", "name": "The Quest of Moria", "parent": "#t4tH0BF1gelfgVc1eyhWAuw", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#tlwi0zkO65dW3gxAFBrdWfe": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "loremaster-characters/tor2e-0.5-hands-arcinyas-the-healer.actor", "form": "DEF", "guidance": [], "id": "#tlwi0zkO65dW3gxAFBrdWfe", "key": "Arcinyas the Healer", "name": "Arcinyas the Healer", "parent": null, "props": [{"name": "Name", "type": "STRING", "value": "Arcinyas the Healer", "vk": "scalar"}, {"name": "Occupation", "type": "STRING", "value": "Healer, Spy", "vk": "scalar"}, {"items": [{"value": "Faithful", "vk": "scalar"}, {"value": "Frail", "vk": "scalar"}], "name": "Distinctive Features", "of": "STRING", "vk": "list"}, {"name": "Description", "type": "STRING", "value": "Old Arcinyas was a scholar and a master in the Houses of Healing once, but he barely remembers that life; he has been in the service of Saruman for decades, doing whatever the Wizard requires of him, from searching in the fields of the Gladden and exploring ancient tombs to tending the wounds of injured Dunlendings. He has grown old in the shadow of Orthanc — he came to Saruman as a young apprentice, tall and dark-haired, and now he is bent under a snowy pate, and yet the Wizard has barely aged. In his secret heart, Arcinyas hungers for a ring that will prolong his life and stave off death so he can continue his studies for eternity. A fuller description of Arcinyas is contained in *Ruins of the Lost Realm* (page 41).", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Loremaster Character", "typeHash": "#TOR0030000000000"}, "#tmEPsmd9yzwujvUDreCjgyc": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "tor2e-0.5-hands-introduction.ttrpg", "form": "DEF", "guidance": [], "id": "#tmEPsmd9yzwujvUDreCjgyc", "key": "Old Lore", "name": "Old Lore", "parent": "#t5mXLkdNrxFIXVCfT0kUbiu", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#tnI5soOxfgM720Whui7LKs0": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "loremaster-characters/tor2e-0.5-hands-bar-and-neb.actor", "form": "DEF", "guidance": [], "id": "#tnI5soOxfgM720Whui7LKs0", "key": "Bar and Neb", "name": "Bar and Neb", "parent": null, "props": [{"name": "Name", "type": "STRING", "value": "Bar and Neb", "vk": "scalar"}, {"name": "Occupation", "type": "STRING", "value": "Stewards of Orthanc", "vk": "scalar"}, {"items": [{"value": "Faithful", "vk": "scalar"}, {"value": "Secretive", "vk": "scalar"}], "name": "Distinctive Features", "of": "STRING", "vk": "list"}, {"name": "Location", "type": "STRING", "value": "Locations", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "Saruman’s chief servants in Isengard are an old man and an old woman named Bar and Neb, respectively. The pair never speak, communicating in signs or written notes when they must. It is rumoured they have been in Saruman’s service since they were children. Bar wears a signet ring, and Neb a jewelled amulet, and some stories insist they are exiled royalty from some distant kingdom. They are utterly loyal to Saruman.", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Loremaster Character", "typeHash": "#TOR0030000000000"}, "#tnQAXMYVHrLsxfko0YdTQWk": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "adversaries/tor2e-0.5-hands-the-beast-of-dunland.actor", "form": "DEF", "guidance": [], "id": "#tnQAXMYVHrLsxfko0YdTQWk", "key": "The Beast of Dunland", "name": "The Beast of Dunland", "parent": null, "props": [{"name": "Name", "type": "STRING", "value": "The Beast of Dunland", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "Snow-trolls may be smaller than many of their kin, but their ferocity more than compensates for their size. Typically residing in caves, they usually lie dormant until a snowstorm hits. As the winds howl and snow limits visibility to mere inches, they emerge to hunt. Despite their stature, Snow-trolls are stealthy hunters, adept at sneaking up on their prey and catching them off guard.", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Adversary", "typeHash": "#TOR0020000000000"}, "#tngBRQWdTgH3j38QCeQzzVU": {"book": "hands", "children": [], "choices": [], "desc": "The lands of the Gore are a pleasant grassy plain, rich and warmed by the sun. There are ruins here, the remnants of small towns once inhabited by a folk hailing from Gondor, but they have been left to sink into the mud; the folk of the Gore of Adorn keep to their own camps and forts.\n\nAs they travel, the Player-heroes come across a Dunlendish wanderer by the name of **Dera**. She is a scout and a hunter, and the Player-heroes may bargain with her for supplies, news or even passage across the river.\n\nIn time, the Player-heroes come to the western edge of the Gore, and as Erkenspere warned, the river is dangerously fast-flowing. Crossing it requires an **ATHLETICS** roll; those who fail are swept away quickly and suffer a *severe* Endurance loss from suffocation.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-sea-prince-of-the-shore.arc", "form": "DEF", "guidance": [], "id": "#tngBRQWdTgH3j38QCeQzzVU", "key": "Through the Gore", "name": "Through the Gore", "parent": null, "props": [{"items": [{"value": "If they ask for news of a new power rising in the west, Dera says that she’s heard of the Lady of Tears; she’s said to be a sorceress of the sea, and can heal even the most grievous wounds.", "vk": "scalar"}], "name": "Items", "of": "STRING", "vk": "list"}], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#tnoSGlT3QUALY2Z6PmiAmU3": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "tor2e-0.5-hands-there-let-them-lie-until-the-end.arc", "form": "DEF", "guidance": [], "id": "#tnoSGlT3QUALY2Z6PmiAmU3", "key": "Rumour", "name": "Rumour", "parent": null, "props": [], "refs": [], "slot": "PHASE", "table": null, "type": null, "typeHash": null}, "#tnriMTXCMTAnFw8oKtS2l22": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-sea-prince-of-the-shore.arc", "form": "DEF", "guidance": [], "id": "#tnriMTXCMTAnFw8oKtS2l22", "key": "Old Lore", "name": "Old Lore", "parent": null, "props": [], "refs": [], "slot": "PHASE", "table": null, "type": null, "typeHash": null}, "#toCAdH2xJyAHYONlFiHyaOY": {"book": "hands", "children": [], "choices": [], "desc": "If for some reason Saruman cannot call on the Dunlendings of Crow Hall, he sends different servants with the Player-heroes. He has warriors and guards within the Ring of Isengard; he shall send some two dozen of these instead.\n\nWhat is the current state of Saruman’s Shadow?", "entries": [], "enum": null, "file": "tor2e-0.5-hands-there-let-them-lie-until-the-end.arc", "form": "DEF", "guidance": [], "id": "#toCAdH2xJyAHYONlFiHyaOY", "key": "Ill-favoured Companions", "name": "Ill-favoured Companions", "parent": null, "props": [{"items": [{"value": "**Less than 10:** The soldiers of Isengard are all Men; folk of Rohan for the most part, and a handful of recruits from the Vales of Anduin. There are a few Dunlendings too, but they are honourable folk.", "vk": "scalar"}, {"value": "**10 to 15:** Most of the soldiers of Isengard are Dunlendings of violent temperament. They grumble about the insults and injuries inflicted on them by the Kings of Rohan, and around the campfire they talk about how they shall one day have revenge. One or two of the soldiers even have an *Orcish* look to them.", "vk": "scalar"}, {"value": "**16 or more:** Saruman has taken Orcs into his service. These warriors do not yet make up a majority of his troops — it’s still mostly Dunlendings. However, the Orcs push to the front of the line and are clearly in charge. The **Orc-captain** is **Gurthaur**, a cruel and ambitious Uruk. He seeks to replace the Player-heroes as Saruman’s trusted servant, and looks for ways to undermine them. The ferocity of the Uruks makes all rolls on the Battle Outcome table *Favoured*.", "vk": "scalar"}], "name": "Items", "of": "STRING", "vk": "list"}], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#toM1gwRsNi0rQPe35hUeB60": {"book": "hands", "children": [], "choices": [], "desc": "Besides speaking with the steward, the Player-heroes can hear the Tale of the Sea-prince (see page 46) from the patrons of the local tavern. Collecting rumours provides them with the following pieces of information.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-sea-prince-of-the-shore.arc", "form": "DEF", "guidance": [], "id": "#toM1gwRsNi0rQPe35hUeB60", "key": "Rumours and Tales at the Tavern", "name": "Rumours and Tales at the Tavern", "parent": null, "props": [{"items": [{"value": "The Prince arrived nearly a year ago. He will leave soon, for he’s under a spell to only dwell in a place for a year and a day.", "vk": "scalar"}, {"value": "The Prince wears a blue ring on his finger, a symbol of his authority. And it’s said that the hands of a king are the hands of a healer, and that’s true — the prince’s touch heals!", "vk": "scalar"}, {"value": "The Prince will soon depart, so the people of Todden are gathering gifts for him.", "vk": "scalar"}, {"value": "The Prince warned that servants of the Enemy are searching for him, and he must be wary. Strangers, he says, are not to be trusted.", "vk": "scalar"}, {"value": "There are rumours of another stranger, according to Mad Magga, but no-one else has seen anyone other than the Player-heroes. Still, it’s good that the Prince has some guards to protect him from danger.", "vk": "scalar"}], "name": "Items", "of": "STRING", "vk": "list"}], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#toUv3AxQzEyn73YHWhXSacY": {"book": "hands", "children": [], "choices": [], "desc": "The northern bank is, indeed, safer and quicker at first. The Old North–South Road runs straight and level, although the Player-heroes can only use it for a few days before they must leave it to follow the course of the Isen. The northern valley is steeper and stonier, and rife with Dunlendish brigands.\n\nIn time, the Player-heroes come to a particularly dangerous spot — a place where a spur of stone nearly overhangs the fast-flowing river below. This place, the Gorge of Lamentation, is watched by **Dunlending thieves** who ambush travellers. The Dunlendings lurk in caves atop the stone spur, and creep down on ropes to grab intruders. They are so stealthy that they are like spiders, picking off the travellers at the rear of a party one by one (for these foes — one for each Player-hero — use the stats for **Highway Robbers**, on page 147 of *The One Ring*).", "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-sea-prince-of-the-shore.arc", "form": "DEF", "guidance": [], "id": "#toUv3AxQzEyn73YHWhXSacY", "key": "Following the Old Road", "name": "Following the Old Road", "parent": null, "props": [], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#toaZuep1a361JHq78g4BdMb": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-beast-of-dunland.arc", "form": "DEF", "guidance": [], "id": "#toaZuep1a361JHq78g4BdMb", "key": "Rumour", "name": "Rumour", "parent": null, "props": [], "refs": [], "slot": "PHASE", "table": null, "type": null, "typeHash": null}, "#toljJrD6tdxVyMSk35mEc3O": {"book": "hands", "children": [], "choices": [], "desc": "If the Player-heroes are captured (through the machinations of Sellic or overwhelmed by guards), then they’re thrown into the same cell as Gildor. The cell does not count as a sheltered place so the Player-heroes cannot heal Fatigue here. How can they escape?", "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-sea-prince-of-the-shore.arc", "form": "DEF", "guidance": [], "id": "#toljJrD6tdxVyMSk35mEc3O", "key": "Prisoners of the Prince", "name": "Prisoners of the Prince", "parent": null, "props": [{"items": [{"value": "If there are any Player-heroes still free, then it’s up to them to rescue their comrades.", "vk": "scalar"}, {"value": "If restored to health, then Gildor can sing the song of Finrod in the tower with his full voice — retelling the tale of how Lúthien conquered the master of that tower, and freed the prisoners from bondage. The magic of the song is so potent that the door of the cell flies open.", "vk": "scalar"}, {"value": "Another option — the players wait until the events of *On Wings of Storm*, and then escape as they’re being marched down to the dock at Todden.", "vk": "scalar"}], "name": "Items", "of": "STRING", "vk": "list"}], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#tpAWxJLQYndyN3V3JkBuled": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-quest-of-moria.arc", "form": "DEF", "guidance": [], "id": "#tpAWxJLQYndyN3V3JkBuled", "key": "Rumour", "name": "Rumour", "parent": null, "props": [], "refs": [], "slot": "PHASE", "table": null, "type": null, "typeHash": null}, "#tpJlHhqZkg9A5XXth6GJn5l": {"book": "hands", "children": ["#te7eGRQB0Ma1UglIWoOw4x8"], "choices": [], "desc": null, "entries": [], "enum": null, "file": "tor2e-0.5-hands-worksheet-saruman-s-shadow-score.ttrpg", "form": "DEF", "guidance": [], "id": "#tpJlHhqZkg9A5XXth6GJn5l", "key": "There Let Them Lie Until the End", "name": "There Let Them Lie Until the End", "parent": "#t4tH0BF1gelfgVc1eyhWAuw", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#tpZdL2Ln7uz3I1OM10GLdKk": {"book": "hands", "children": [], "choices": [], "desc": "Saruman’s fate is sealed; he is doomed to fall, and there is no saving him. The tale shall unfold as described in *The Lord of the Rings*, and what matters is the fates of the Player-heroes, not Saruman. Choose this option if you want to ensure fidelity to the story as written.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-introduction.ttrpg", "form": "DEF", "guidance": [], "id": "#tpZdL2Ln7uz3I1OM10GLdKk", "key": "Saruman, Your Staff is Broken", "name": "Saruman, Your Staff is Broken", "parent": "#tYTRDNCyEPe4yv1Uy7AZqe8", "props": [{"items": [{"value": "*Raise Saruman’s Shadow by 3 after each adventure.*", "vk": "scalar"}], "name": "Items", "of": "STRING", "vk": "list"}], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#tpeeSgB8iA4YvhpP3JRYdq7": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "loremaster-characters/tor2e-0.5-hands-nidi-the-treasure-hunter.actor", "form": "DEF", "guidance": [], "id": "#tpeeSgB8iA4YvhpP3JRYdq7", "key": "Nidi the Treasure-hunter", "name": "Nidi the Treasure-hunter", "parent": null, "props": [{"name": "Name", "type": "STRING", "value": "Nidi the Treasure-hunter", "vk": "scalar"}, {"name": "Occupation", "type": "STRING", "value": "Scavenger", "vk": "scalar"}, {"items": [{"value": "Bold", "vk": "scalar"}, {"value": "Impractical", "vk": "scalar"}], "name": "Distinctive Features", "of": "STRING", "vk": "list"}, {"name": "Location", "type": "STRING", "value": "To the Ledge of Woe", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "Nidi’s grandfather Nidur was never found after the Battle of Dimrill Dale. He was not found among the dead, and she cannot boast he was a burned Dwarf, but neither was he numbered among the survivors. Some whisper darkly that Nidur fled the battle as a coward, but Nidi believes he met some other fate — maybe he was dragged away into the deeps.\n\nNidi never actually knew Nidur — she’s a young Dwarf, born many years after the Battle — but she often dreamed of him, and those dreams brought her to the lands around Moria. She’s one of the scavengers and relic-hunters who snoop around the edges of the Dwarven city, collecting scraps of the glorious past. She hopes that one day she’ll find some sign of Nidur, like the family axe he wielded in battle.", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Loremaster Character", "typeHash": "#TOR0030000000000"}, "#tq1uHaJyhhSTWzx9E0r6H43": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [{"fields": [{"name": "Revelation Episode", "type": "STRING", "value": "Unstable Cask: One of the casks of blasting powder grows hot to the touch, and pungent yellow fumes gush from its mouth. The powder has undergone a chemical change and is now much more volatile and unstable. If jarred or dropped, it explodes spontaneously (see *The Blasting Powder*, on page 82).", "vk": "scalar"}], "name": "1", "vk": "def"}, {"fields": [{"name": "Revelation Episode", "type": "STRING", "value": "Guided by Sinister Purpose: Orcs or other foes abroad in Ithilien seem to be guided to the Company’s trail. All STEALTH rolls are *Ill-Favoured* in Ithilien.", "vk": "scalar"}], "name": "2", "vk": "def"}, {"fields": [{"name": "Revelation Episode", "type": "STRING", "value": "The Malice of the Enemy: The Company come across a place of horror or despair — butchered Gondorian soldiers or captured prisoners, or a once-prosperous village now abandoned and overgrown. That would be disturbing enough, but a malign presence seems to fill the air. Each Player-hero gains 2 Shadow points (Dread).", "vk": "scalar"}], "name": "3", "vk": "def"}, {"fields": [{"name": "Revelation Episode", "type": "STRING", "value": "Patrol from Minas Ithil: Orcs bearing the sigil of the swollen moon search the forest for intruders.", "vk": "scalar"}], "name": "4", "vk": "def"}, {"fields": [{"name": "Revelation Episode", "type": "STRING", "value": "Strife Among Friends: The Player-heroes find themselves growing irritated with one another. Each Player-hero must choose: either swallow their malice, gaining 2 Shadow points (Sorcery), lose the benefits (but not the costs) of their Fellowship Focus for the rest of the adventure, or blame Saruman for their sorrows (increasing his Shadow by 1).", "vk": "scalar"}], "name": "5", "vk": "def"}, {"fields": [{"name": "Revelation Episode", "type": "STRING", "value": "The Probing Eye: The gaze of the Lidless Eye sweeps across the sky. Each Player-hero gains 1 Shadow point (Dread), and the Company’s Hunt Threshold is reduced by 1 while in Ithilien or the Morgul Vale.", "vk": "scalar"}], "name": "6", "vk": "def"}], "enum": null, "file": "tor2e-0.5-hands-the-ithil-stone.arc", "form": "DEF", "guidance": [], "id": "#tq1uHaJyhhSTWzx9E0r6H43", "key": "Revelation Episodes East of the Anduin", "name": "Revelation Episodes East of the Anduin", "parent": null, "props": [{"name": "Note", "type": "STRING", "value": "Roll a Success die or pick one of the following revelations.", "vk": "scalar"}], "refs": [], "slot": "SCENE", "table": {"columns": ["SUCCESS DIE", "REVELATION EPISODE"], "rows": [["1", "Unstable Cask: One of the casks of blasting powder grows hot to the touch, and pungent yellow fumes gush from its mouth. The powder has undergone a chemical change and is now much more volatile and unstable. If jarred or dropped, it explodes spontaneously (see *The Blasting Powder*, on page 82)."], ["2", "Guided by Sinister Purpose: Orcs or other foes abroad in Ithilien seem to be guided to the Company’s trail. All STEALTH rolls are *Ill-Favoured* in Ithilien."], ["3", "The Malice of the Enemy: The Company come across a place of horror or despair — butchered Gondorian soldiers or captured prisoners, or a once-prosperous village now abandoned and overgrown. That would be disturbing enough, but a malign presence seems to fill the air. Each Player-hero gains 2 Shadow points (Dread)."], ["4", "Patrol from Minas Ithil: Orcs bearing the sigil of the swollen moon search the forest for intruders."], ["5", "Strife Among Friends: The Player-heroes find themselves growing irritated with one another. Each Player-hero must choose: either swallow their malice, gaining 2 Shadow points (Sorcery), lose the benefits (but not the costs) of their Fellowship Focus for the rest of the adventure, or blame Saruman for their sorrows (increasing his Shadow by 1)."], ["6", "The Probing Eye: The gaze of the Lidless Eye sweeps across the sky. Each Player-hero gains 1 Shadow point (Dread), and the Company’s Hunt Threshold is reduced by 1 while in Ithilien or the Morgul Vale."]]}, "type": "Table", "typeHash": "#tor5Table0000000001"}, "#tqO0FAkqApy3KngqlHi60TT": {"book": "hands", "children": [], "choices": [], "desc": "Cradoc wears a tunic of coarse, woven linen dyed in shades of muted green and grey, resembling the hues of stone and seaweed. Over his shoulders rests a simple cloak fastened with a carved wooden brooch, weathered by time and salt. He leans on a staff hewn from driftwood. He speaks in a whisper, but one of his sons echoes his words by speaking through a booming conch.\n\nThere’s no need to run this as a full Council; a simple **COURTESY** roll is enough for the Player-heroes to assure the chieftain that they’re not dangerous. If they fail the roll, he asks them to leave their weapons with his sons while they are in Todden. If asked about the mysterious Sea-prince, he can tell the Tale of the Prince, but admits he knows little else. An **INSIGHT** roll reveals that he’s worried about the Prince’s influence over his followers, and that Cradoc really hopes that he spoke truly when he said he would soon leave.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-sea-prince-of-the-shore.arc", "form": "DEF", "guidance": [], "id": "#tqO0FAkqApy3KngqlHi60TT", "key": "Meeting Old Cradoc", "name": "Meeting Old Cradoc", "parent": null, "props": [], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#tqP1syXyFNdmYbFFpP0XjH9": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "loremaster-characters/tor2e-0.5-hands-gorsad-crowlord.actor", "form": "DEF", "guidance": [], "id": "#tqP1syXyFNdmYbFFpP0XjH9", "key": "Gorsad Crowlord", "name": "Gorsad Crowlord", "parent": null, "props": [{"name": "Name", "type": "STRING", "value": "Gorsad Crowlord", "vk": "scalar"}, {"name": "Occupation", "type": "STRING", "value": "Gout-ridden Warlord", "vk": "scalar"}, {"items": [{"value": "Fair-spoken", "vk": "scalar"}, {"value": "Patient", "vk": "scalar"}], "name": "Distinctive Features", "of": "STRING", "vk": "list"}, {"name": "Location", "type": "STRING", "value": "A Council with the Crow Lord", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "The chieftain of Crow Hall is old before his time; he is a few years younger than Dunrach, but he shuffles around painfully, his back bent. He suffers from gout and other ailments that weigh heavily on both body and mind. While he is capable of great oratory when speaking in the hall from the high seat, in casual conversation he talks in a halting whisper.\n\nGorsad was fostered in Isengard, and has a deep and unassailable belief in the wisdom and power of the White Wizard. His one regret is that his son Toirlas does not share his faith in Saruman — but alas, Toirlas never lived in Isengard. He should have, but Gorsad fell ill that year, and was confined to bed while Dunrach and Dunwalla managed the clan’s affairs. By the time he regained his health, they had convinced Toirlas that he would be better served learning to fight and hunt in the old ways of Dunland.\n\nHis daughter Vila is much younger than her brother, and is only ten years old. She serves as his cupbearer in court. Toirlas has also considered sending Vila to Isengard, but Dunwalla argues against it.", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Loremaster Character", "typeHash": "#TOR0030000000000"}, "#tqW8LrOkXXj0HXKSAuETOe0": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-quest-of-moria.arc", "form": "DEF", "guidance": [], "id": "#tqW8LrOkXXj0HXKSAuETOe0", "key": "Old Lore", "name": "Old Lore", "parent": null, "props": [], "refs": [], "slot": "PHASE", "table": null, "type": null, "typeHash": null}, "#tqq6HrmKmJty6aTsTjegN9P": {"book": "hands", "children": [], "choices": [], "desc": "Nambar is used to easily over-awing the simple fisher-folk; when confronted by more formidable people like the Player-heroes, he tries to be as evasive as possible about his purpose and intention, couching everything in mystical riddles (*“I am here because here is where I am, and where I need to be”*). Still, if the heroes approach him with due deference, run the encounter as a Council.\n\nIt’s a Reasonable request for them to know where he comes from or ask for healing, a Bold request for him to free Gildor or another boon, and an Outrageous one to compel the Prince to confess the truth about his origins. The Prince is Friendly *(gain 1d)* if he thinks he can trick the Heroes into giving up their weapons, resting in the tower, or even switching sides to serve Umbar; he’s Open if he believes the Player-heroes are wandering adventurers who’ve happened upon him by chance, and Reluctant *(lose 1d)* if he suspects they are plotting against him, or if there are any Elves or Men of Gondor in the company.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-sea-prince-of-the-shore.arc", "form": "DEF", "guidance": [], "id": "#tqq6HrmKmJty6aTsTjegN9P", "key": "An Audience with the Prince", "name": "An Audience with the Prince", "parent": null, "props": [], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#tr3wed44cnOiLaJACBTJCjb": {"book": "hands", "children": [], "choices": [], "desc": "Depending on the success of the Player-heroes’ efforts, these can be likely outcomes from the meeting with Gorsad.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-beast-of-dunland.arc", "form": "DEF", "guidance": [], "id": "#tr3wed44cnOiLaJACBTJCjb", "key": "End of the Council", "name": "End of the Council", "parent": null, "props": [{"items": [{"value": "If the Council results in a Success, Gorsad welcomes the Player-heroes, and gives them room within the Hall to sleep in. The other warriors seem cheered — in their dour, Dunnish way — to have such renowned visitors, and even Dunrach is grudgingly impressed.", "vk": "scalar"}, {"value": "On a Success with Woe, the chieftain gives the Player-Heroes a place within the Hall to rest — but he is alone in welcoming them. Dunrach and the other warriors scoff at them.", "vk": "scalar"}, {"value": "If the Council ends in a Disaster, Gorsad, offended by their discourtesy, dismisses them, telling them there is no room for them in the Hall and that they must sleep outside in one of the settlement’s barns. The night is cold and no-one sleeps well — the barn doesn’t count as a safe and sheltered place, and the Company therefore cannot heal Fatigue points during a Prolonged Rest there.", "vk": "scalar"}], "name": "Items", "of": "STRING", "vk": "list"}], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#tr5Q1TIG3zKHYLuy8GnmcPE": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "loremaster-characters/tor2e-0.5-hands-midgewater-meg.actor", "form": "DEF", "guidance": [], "id": "#tr5Q1TIG3zKHYLuy8GnmcPE", "key": "Midgewater Meg", "name": "Midgewater Meg", "parent": null, "props": [{"name": "Name", "type": "STRING", "value": "Midgewater Meg", "vk": "scalar"}, {"name": "Occupation", "type": "STRING", "value": "Healer, Hunter", "vk": "scalar"}, {"items": [{"value": "Rustic", "vk": "scalar"}, {"value": "Secretive", "vk": "scalar"}], "name": "Distinctive Features", "of": "STRING", "vk": "list"}, {"name": "Description", "type": "STRING", "value": "Old Meg lives in a small house outside Bree. It stinks of the glue she uses to make traps for the marsh-birds she hunts. She also collects herbs and mushrooms from the marsh, and has a reputation as a wisewoman — or a madwoman. The local children fear her, although the Ferny boys from over the hill sometimes help out wringing the necks of trapped birds.", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Loremaster Character", "typeHash": "#TOR0030000000000"}, "#trcydXQGQxmHOIdyRTB7UUX": {"book": "hands", "children": [], "choices": [], "desc": "Before they depart Isengard, Saruman has servants equip them with food and drink for their journey; if they are in need of weapons, armour or travelling gear, these too can be supplied from the arsenal of Isengard. After all, the Player-heroes are going as representatives of the White Wizard and the power of Isengard — they must comport themselves in a fitting manner.\n\nTo this end, Saruman also entrusts them with a small silver box marked with a white star — a gift, he says, for Gorsad. It’s shut with a wax seal. They may do with it as they wish; hand it over freely, present it formally or hold it back if Gorsad is uncooperative.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-beast-of-dunland.arc", "form": "DEF", "guidance": [], "id": "#trcydXQGQxmHOIdyRTB7UUX", "key": "Needful Things", "name": "Needful Things", "parent": null, "props": [], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#trhzOwG5SR561o83VFZVUKV": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "tor2e-0.5-hands-introduction.ttrpg", "form": "DEF", "guidance": [], "id": "#trhzOwG5SR561o83VFZVUKV", "key": "Preamble", "name": "Preamble", "parent": null, "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#trrsIsdiZhun8EZ0hfQu1yy": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "tor2e-0.5-hands-introduction.ttrpg", "form": "DEF", "guidance": [], "id": "#trrsIsdiZhun8EZ0hfQu1yy", "key": "Rumour", "name": "Rumour", "parent": "#t5mXLkdNrxFIXVCfT0kUbiu", "props": [{"name": "Epigraph", "type": "STRING", "value": "There’s a haunted fortress north of the Gap of Rohan, a tower like a black spike, and a cunning Wizard lives there. He’s been there as long as anyone can remember, and he traffics in sorcery. Beware!", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#tsE0WAHAKeXNWe67l2YsRVL": {"book": "hands", "children": [], "choices": [], "desc": "If the Player-heroes slay the Beithir, and spend some days searching the marsh, then a successful **EXPLORE** roll finds the monster’s treasure hoard, amid a stratum of gelatinous whitish mud speckled with teeth and bone fragments. Most of this treasure is of little worth — a few coins, a rusted dagger with some bright glass in the hilt — but there is also a treasure chest, its sides stained and discoloured by long burial in the mud. It contains a Greater Hoard of strange coins that resemble money struck in Gondor, but bear the sigil of the Eye.\n\nA successful **LORE** roll can guess at the origin of these coins — in the year 2758 of the Third Age (about two hundred years ago), Corsairs from Umbar landed in Enedwaith and allied with the Dunlendings against Rohan and Gondor. Those were the days of Helm Hammerhand and false king Wulf. This treasure must be part of the Corsair war chest, money brought to hire Dunlendish mercenaries.\n\nAny magical treasure found here is the work of Sauron and his acolytes, and comes with a Shadow (Greed) gain of 2 points (in addition to any Shadow gained on an [Eye of Sauron] result on the Magical Treasure roll).", "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-sea-prince-of-the-shore.arc", "form": "DEF", "guidance": [], "id": "#tsE0WAHAKeXNWe67l2YsRVL", "key": "Gold in the Muck", "name": "Gold in the Muck", "parent": null, "props": [], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#tsvGAzKfV3hphmyBRynhXVI": {"book": "hands", "children": [], "choices": [], "desc": "the North-kingdom collapsed, that some Dwarves returned to the work of the Ring-smiths and tried again to forge new Rings of Power. They continued these efforts even as the heat from the Balrog’s flames eclipsed the heat of their forges.\n\nThe secret shame of the Ring-smiths was that those who made their rings became Ring-wights, undead creatures chained to the rotting husk of their bodies, hungry for the life of the living. Most of the Ring-wights were locked away in a secret prison in their hidden Citadel, but one lies here, in the Crypt of the Smiths.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-quest-of-moria.arc", "form": "DEF", "guidance": [], "id": "#tsvGAzKfV3hphmyBRynhXVI", "key": "The Crypt of the Smiths", "name": "The Crypt of the Smiths", "parent": null, "props": [], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#tt3qThmdMDDeiOEa4SfoqQ1": {"book": "hands", "children": ["#t5xZuLwtFQZcV29V8Xh7kkK", "#tdjfCMCvCSACYpLTAdEXypq", "#tu6xvtsz0RGddvPh1RmG6Ld"], "choices": [], "desc": "*— The Fellowship of the Ring™*\n\nSaruman’s purpose in this age of the world is to be the main foe of the Enemy, the general of the forces of good. While he might go out himself to gather those with the courage and strength of spirit to oppose Sauron, he generally prefers to employ agents — trusted helpers he sends across the land (Saruman considered Gandalf himself to be one such agent, albeit a somewhat wayward one).\n\nThe hands of the White Wizard are most often found in the halls of kings and chieftains, or watching over the ancient strongholds and places of power of the Enemy. Some among them are Rangers, though he has relied on them less of late, as their current chieftain, Aragorn, is too close a friend of the Elves and Gandalf to be fully trusted.\n\nIf the Player-heroes demonstrate their worth, they may be contacted and summoned to Isengard. Will they go of their own accord, or might they be sent there by some ally or Patron?", "entries": [], "enum": null, "file": "tor2e-0.5-hands-introduction.ttrpg", "form": "DEF", "guidance": [], "id": "#tt3qThmdMDDeiOEa4SfoqQ1", "key": "In the Service of Saruman", "name": "In the Service of Saruman", "parent": null, "props": [{"name": "Epigraph", "type": "STRING", "value": "“I have come for your aid, Saruman the White.”", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#ttPp9jJGrGHgLAAP3pXHagf": {"book": "hands", "children": [], "choices": [], "desc": "Dunwalla knows about the beast’s hiding place. She’s kept the creature here by giving it offerings of food. If the Player-heroes keep watch over the Eordscrafa, they may catch Dunwalla in the act, and be able to bring her for judgement before Gorsad (see page 39).", "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-beast-of-dunland.arc", "form": "DEF", "guidance": [], "id": "#ttPp9jJGrGHgLAAP3pXHagf", "key": "Dunwalla the Witch", "name": "Dunwalla the Witch", "parent": null, "props": [], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#ttc3Z7PTeSsGaOwuItLM9z3": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-sea-prince-of-the-shore.arc", "form": "DEF", "guidance": [], "id": "#ttc3Z7PTeSsGaOwuItLM9z3", "key": "Rumour", "name": "Rumour", "parent": null, "props": [], "refs": [], "slot": "PHASE", "table": null, "type": null, "typeHash": null}, "#tu6xvtsz0RGddvPh1RmG6Ld": {"book": "hands", "children": ["#t4ca0dPzLyI2Ao6bQdFa6ou"], "choices": [], "desc": "Saruman meets new arrivals out in the sunlight, in the green gardens of Isengard. His white robes blaze with light, and he is very grave and lordly, kind and wise. He listens more than he speaks, and shares his knowledge generously — servants fetch maps and scrolls at his command. He keeps a fine table, too, laden with meats and cheeses, grapes and good wine from afar, even though Saruman himself eats little.\n\nHis insight is astoundingly keen — the Player-heroes feel as though the Wizard can see into their souls, as if all their secrets are laid bare to him. However, he does not abuse this power. He might make an oblique reference to some aspect of a Player-hero’s backstory or secret calling, but always gently and in a good-hearted manner. For now, Saruman is in every respect a good and wise Wizard.\n\nAfter discussion of the affairs of their homelands, Saruman introduces the chief topic of this meeting.\n\n*“My new friends, you have doubtless heard rumours of the ancient Power — the Dark Lord Sauron. In ages past he was humbled by armies of Númenor, and conquered by an Alliance of Elves and Men. But after each defeat, he fled into the shadowed East and rebuilt his strength. Now, as I have long anticipated, he has returned to his stronghold in Mordor, and once again prepares to make war upon Middle-earth. In this Age, the task of defeating this Power falls to us. The Elder Days are gone. The Middle Days are passing. The Younger Days are coming, and it rests upon a knife-edge whether they shall be days bright or dark.*\n\n*Know this — doom is near, but we still have a little time before the Shadow falls upon us. The Enemy’s plans are not yet ripe. He is still gathering his forces, and I must do the same. I am in need of intelligent, trustworthy agents who can aid me in preparing the world of Men for this trial.”*\n\nSaruman explains that the Player-heroes are welcome in Isengard whenever they pass this way, and that chambers have been set aside for their use (though they may not yet enter Orthanc, see page 14). They do not immediately gain Saruman as a Patron but may use the Meet Patron undertaking while at Isengard.\n\nIn future adventures, Saruman might:", "entries": [], "enum": null, "file": "tor2e-0.5-hands-introduction.ttrpg", "form": "DEF", "guidance": [], "id": "#tu6xvtsz0RGddvPh1RmG6Ld", "key": "Meeting Saruman the Wise", "name": "Meeting Saruman the Wise", "parent": "#tt3qThmdMDDeiOEa4SfoqQ1", "props": [{"items": [{"value": "Leave a letter containing instructions for the Player-heroes at some crossroads like the Prancing Pony.", "vk": "scalar"}, {"value": "Contact the Player-heroes through a messenger.", "vk": "scalar"}, {"value": "Someone close to the Player-heroes, ideally someone overlooked — a cup-bearer at Queen Nimue’s hall, a stable boy in Bree, a smith’s apprentice in Tharbad — tells them that the White Wizard calls them.", "vk": "scalar"}, {"value": "Use the nearest Wizard (Gandalf west of the mountains, Radagast to the east) as a messenger.", "vk": "scalar"}, {"value": "Meet the Player-heroes himself, for he sometimes walks abroad in disguise.", "vk": "scalar"}], "name": "Items", "of": "STRING", "vk": "list"}], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#tu7E2UbJD7b2yAme56OywgB": {"book": "hands", "children": [], "choices": [], "desc": "This ornamental lake is fed with fresh water diverted from the Isen and from other springs and streams flowing down from the mountains; underground channels water the vegetation in the surrounding gardens.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-introduction.ttrpg", "form": "DEF", "guidance": [], "id": "#tu7E2UbJD7b2yAme56OywgB", "key": "5. Lake", "name": "5. Lake", "parent": "#tcMxywq75NOL2ves69gurzl", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#tu9RGNlZz11uT0zR4NvkM6e": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [{"fields": [], "name": "FAVOURED CALLINGS: Scholar, Treasure Hunter", "vk": "def"}], "enum": null, "file": "tor2e-0.5-hands-introduction.ttrpg", "form": "DEF", "guidance": [], "id": "#tu9RGNlZz11uT0zR4NvkM6e", "key": "Saruman as a Patron Table 1", "name": "Saruman as a Patron Table 1", "parent": "#tdjfCMCvCSACYpLTAdEXypq", "props": [], "refs": [], "slot": null, "table": {"columns": ["FELLOWSHIP BONUS: +0"], "rows": [["FAVOURED CALLINGS: Scholar, Treasure Hunter"]]}, "type": "Table", "typeHash": "#tor5Table0000000001"}, "#tuEEdjqq1iZgKu83DCIShsi": {"book": "hands", "children": [], "choices": [], "desc": "Saruman has agents in the garrison, and they have been watching for the approach of the Player-heroes. As soon as the Player-heroes arrive, they are met by a soldier of Gondor who introduces himself as **Alagoson**; he shows them a secret badge with the sign of the White Hand. He hands the Player-heroes a sealed letter, and tells them to present the document to the dock-master. It will get them onto Cair Andros.\n\nAs Alagoson promised, the papers permit the Player-heroes to transfer their cargo — including the precious casks — to a ferry that crosses to the island shore. The Player-heroes have reached the mid-point of their journey.\n\nTraffic across the river to Ithilien is strictly controlled. Partly, this is to ensure spies and saboteurs from Mordor cannot cross; the Enemy has many Men in his service. But it also ensures unwary travellers do not stray into Ithilien. The abandoned garden province was once lush, and still appears to be a fair and inviting land — but it is a battleground. The Rangers of Ithilien command the ferries that cross to the eastern bank.\n\nAlagoson explains that there are troops coming from Minas Tirith — an unusually large war party. He does not know why the Tower is sending reinforcements or mounting an expedition into Ithilien, but there will be lots of soldiers and supplies crossing the River. He is confident of being able to sneak the Player-heroes in with the expedition — but the Company must wait on Cair Andros until the expedition arrives.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-ithil-stone.arc", "form": "DEF", "guidance": [], "id": "#tuEEdjqq1iZgKu83DCIShsi", "key": "Agents of the White Wizard", "name": "Agents of the White Wizard", "parent": null, "props": [], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#tv6SJ9aoTwWOzFRiPUOW880": {"book": "hands", "children": [], "choices": [], "desc": "Three times in the Years of Sun and Moon, the great powers of the Undying Lands in the Uttermost West took up arms against the Shadow.\n\nThe first occasion was the dreadful battle that broke the dominion of Morgoth. Terrible was the wrath of the Valar. In that battle Beleriand was drowned, and mountains shattered, and there was great turmoil and terror, and much beauty was lost.\n\nAn Age of the world later, Sauron — Morgoth’s chief lieutenant and disciple — seduced Ar-Pharazôn of Númenor, and convinced him to invade the Undying Lands. When Ar-Pharazôn set foot on the shore of Valinor, the powers called upon the One, and the World was remade. Once again, there was terrible destruction. The great island of Númenor sank beneath the seas, and many lives were lost. Elendil and his faithful fled the wreck of their homeland — as did the Dark Lord. Even though Sauron was later defeated by the Last Alliance, a Shadow lingered in Middle-earth, nameless and hidden.\n\nOnce again, the powers of the West interceded. This time, they did not send a heavenly host, nor did they shatter the world. This time, they would act with subtlety. Around the year 1000 of the Third Age, they sent five messengers, the *Istari*, to advise and guide, to draw together all those who had the will to resist, and to contest the power of Sauron.\n\n*Wizards*, some called them.\n\nEach of these five Wizards had a purpose assigned to them. Two travelled far into the East, reaching lands long under the dominion of darkness. Of them, little is known, and no tales are told in the West.\n\nOf those who remain in the North-west of Middle-earth in the present year, Radagast the Brown delights in the living world, in trees and flowers, beasts and especially birds. The corruption of the Shadow may be seen in the land, as the Enemy despises all that grows under the sun. With his keen-eyed birds, it was Radagast who searched for signs of its resurgence. It is no coincidence that he made his home in Mirkwood, near the lair of the Necromancer.\n\nThe role of the Grey Pilgrim *Mithrandir* is to be messenger and counsellor, to seek out those who might fight against the Shadow and bring them together. He is great in power and wisdom, but he is only *second* in the order.\n\nFor the greatest of the Five, and the wisest, is the one called *Curunír*, the Man of Skill. To him falls the heaviest duty. His role is to be the Captain and the General, to rally the Free Peoples and to direct them; he is to discern the thought of Sauron and counter it, to forge armies and shape alliances. He is Saruman, head of the order of the Istari, leader of the White Council, the White Wizard — the chief adversary of the Enemy in this last battle. If he fails in his task, there will be no more intervention from the Valar. He is the last hope for freedom and light in Middle-earth.\n\nNearly two thousand years have passed since the Wizards first landed on the shores of Lindon. Nearly two thousand years have passed since the White Wizard began his struggle with the Shadow.\n\nHe has not yet fallen.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-introduction.ttrpg", "form": "DEF", "guidance": [], "id": "#tv6SJ9aoTwWOzFRiPUOW880", "key": "Introduction", "name": "Introduction", "parent": null, "props": [{"items": [{"value": "“He was great once, of a noble kind that we should not dare to raise our hands against. He is fallen, and his cure is beyond us;", "vk": "scalar"}, {"value": "but I would still spare him, in the hope that he may find it.”", "vk": "scalar"}, {"value": "— The Return of the King™", "vk": "scalar"}], "name": "Epigraphs", "of": "STRING", "vk": "list"}], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#tvLmZGB1VUASJJc456qellV": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-disaster-of-the-gladden-fields.arc", "form": "DEF", "guidance": [], "id": "#tvLmZGB1VUASJJc456qellV", "key": "Old Lore", "name": "Old Lore", "parent": null, "props": [], "refs": [], "slot": "PHASE", "table": null, "type": null, "typeHash": null}, "#twGuOhw91r2LJGKhzYRQXhS": {"book": "hands", "children": [], "choices": [], "desc": "Impatient or mistrustful Player-heroes may prefer not to wait for the distraction of the host from Minas Tirith, and seek another way across.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-ithil-stone.arc", "form": "DEF", "guidance": [], "id": "#twGuOhw91r2LJGKhzYRQXhS", "key": "Other Ways Across", "name": "Other Ways Across", "parent": null, "props": [{"items": [{"value": "**Stealing a Ferry-Boat:** There are lots of boats on the shore of Cair Andros, from huge rafts used to transport horses and supplies, to small paddle-boats used by the Rangers. Some are kept under guard, but a **STEALTH** roll could liberate a usable boat. The key question is: what do the Player-heroes do about the guards?", "vk": "scalar"}, {"value": "**Taking their own Boat:** If the Player-heroes sailed their own boat all the way from Rohan, they can use it to cross the Anduin. It is forbidden to cross the Anduin without permission, so archers from Cair Andros will challenge the travellers unless they manage to cross unseen (again, with a **STEALTH** roll).", "vk": "scalar"}, {"value": "**Persuasion:** Honeyed are the tongues of Saruman’s servants. The Captain of Cair Andros is an aged Gondorian commander named **Húrin Snowhair**; a successful Council can convince him to allow the Player-heroes to cross (see *Revealing the Quest*, on the previous page), but they somehow need to gain access to the commander.", "vk": "scalar"}, {"value": "**Travelling Elsewhere:** See *Bypassing Cair Andros*, on page 126.", "vk": "scalar"}], "name": "Items", "of": "STRING", "vk": "list"}], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#twXOU9PSboejoxiBaWbJ5Cr": {"book": "hands", "children": [], "choices": [], "desc": "In this time, the Gate-stream of the Sirannon has been dammed, creating an artificial lake whose waters lap at the very threshold of the Doors of Durin. The doors can still be opened — they can be forced open from the inside, or opened by one who knows the password (Saruman, of course, knows this secret word, and will entrust it to the Player-heroes if they intend to make for the West-gate). However, to reach the doors, the Player-heroes must wade along the edge of the lake. The slope gives way in places, forcing the Player-heroes to swim.\n\nWorse, lurking in the lake is **the Watcher in the Water**. This horror from the deep attacks anyone who comes near the doors. An **AWARENESS** roll lets Player-heroes spot ripples in the lake, or a foulness on the wind, that suggests there’s something lurking nearby. A **STEALTH** roll lets them reach the Doors of Durin safely — but the Watcher always attacks when the doors open.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-quest-of-moria.arc", "form": "DEF", "guidance": [], "id": "#twXOU9PSboejoxiBaWbJ5Cr", "key": "The West-gate", "name": "The West-gate", "parent": null, "props": [], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#twkcFKGNaNieEoKnz6lgq0t": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "adversaries/tor2e-0.5-hands-saruman-of-many-colours-revealed.actor", "form": "DEF", "guidance": [], "id": "#twkcFKGNaNieEoKnz6lgq0t", "key": "Saruman Of Many Colours, Revealed", "name": "Saruman Of Many Colours, Revealed", "parent": null, "props": [{"name": "Name", "type": "STRING", "value": "Saruman Of Many Colours, Revealed", "vk": "scalar"}, {"items": [{"value": "Cunning", "vk": "scalar"}, {"value": "Lordly", "vk": "scalar"}, {"value": "Traitorous", "vk": "scalar"}], "name": "Distinctive Features", "of": "STRING", "vk": "list"}, {"name": "Attribute Level", "type": "INTEGER", "value": 12, "vk": "scalar"}, {"name": "Endurance", "type": "INTEGER", "value": 100, "vk": "scalar"}, {"name": "Might", "type": "INTEGER", "value": 2, "vk": "scalar"}, {"name": "Hate", "type": "INTEGER", "value": 12, "vk": "scalar"}, {"name": "Parry", "type": "STRING", "value": "+1", "vk": "scalar"}, {"name": "Armour", "type": "STRING", "value": "1", "vk": "scalar"}, {"items": [{"fields": [{"name": "Weapon", "type": "STRING", "value": "Wizard’s Staff", "vk": "scalar"}, {"name": "Rating", "type": "INTEGER", "value": 4, "vk": "scalar"}, {"name": "Damage", "type": "INTEGER", "value": 4, "vk": "scalar"}, {"name": "Injury", "type": "INTEGER", "value": 14, "vk": "scalar"}, {"items": [{"value": "Knockback*", "vk": "scalar"}], "name": "Special Damage", "of": "STRING", "vk": "list"}, {"name": "Printed", "type": "STRING", "value": "Wizard’s Staff 4 (4/14, Knockback)", "vk": "scalar"}], "vk": "def"}], "name": "Combat Proficiencies", "of": "Adversary Combat Proficiency", "ofHash": "#tor5AdvCombat000001", "vk": "list"}, {"items": [{"fields": [{"name": "Name", "type": "STRING", "value": "A Mind of Metal and Wheels", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "Saruman is not affected by the Intimidate Foes combat task.", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Name", "type": "STRING", "value": "Combat Sorcerer", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "Once per round, Saruman can cast his Dreadful Spells in place of one of his attacks. If he does so, he can cast the spell without expending Hate.", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Name", "type": "STRING", "value": "Cunning Mind", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "While inside Orthanc, Saruman cannot be surprised and all his rolls are Favoured.", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Name", "type": "STRING", "value": "Devilry of Saruman", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "Once per round, spend 1 Hate to cause a grievous Endurance loss from fire to one Player-hero engaged with Saruman, and a severe Endurance loss from fire to all other Player-heroes either in a Close Combat stance or Rearward stance (Loremaster’s choice). Targets who lose at least 1 Endurance are also set on fire, suffering a moderate Endurance loss at the end of each combat round, unless they put out the fire as their main action for the round.", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Name", "type": "STRING", "value": "Dreadful Spells: The Voice of Saruman", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "Once per round, spend 1 Hate to make all Player-heroes who can hear Saruman gain 4 Shadow points (Sorcery). The WIS- DOM roll is Ill-favoured. Those who fail their Shadow test or who are Miserable are enthralled and cannot attack Saruman for the rest of the fight, or until they suffer any Endurance loss. Those who fail their Shadow test and are Miserable suffer the same effects, and must spend", "vk": "scalar"}], "vk": "def"}], "name": "Fell Abilities", "of": "Fell Ability", "ofHash": "#tor5FellAbility0001", "vk": "list"}, {"name": "Description", "type": "STRING", "value": "their next main action to attack another Player-hero of the Loremaster’s choice (in any combat stance, including Rearward). Use the higher of the attacker’s Strength TN and the target’s Parry as the TN for the attack, and ignore any stance modifiers for this attack; the Loremaster chooses the weapon used for the attack and how to spend any Success icons ( [Success] ). A successful AWE or PERSUADE roll from a Player-hero who is not enthralled (and who must spend their main action to do so) breaks the enchantment. *Dreadful Spells: The Will of Saruman.* Once per round, spend 1 Hate to restore 1 Hate to all Saruman’s allies and make all Player-heroes in the fight gain 3 Shadow points (Sorcery). The WISDOM roll is *Ill- favoured*. Those who fail their Shadow test or who are Miserable are Weary for the rest of the fight. Those who fail their Shadow test and are Miserable suffer the same effects, and cannot Harden Will for the rest of the fight. *Dwimmer-crafty.* If Saruman is not surprised, opening volleys against him are not possible, he acts first during each round of combat, and all attack rolls against him are *Ill-favoured*. *Istar.* Spend 1 Hate to cancel a Wound. When an attack inflicts damage to Saruman that would cause him to go to zero Endurance, it causes a Piercing Blow instead. Then, if Saruman is still alive, his Endurance score is set back at half its maximum rating.", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Adversary", "typeHash": "#TOR0020000000000"}, "#twoA3c3k6SEV0Vq7924SRtp": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "loremaster-characters/tor2e-0.5-hands-gambold.actor", "form": "DEF", "guidance": [], "id": "#twoA3c3k6SEV0Vq7924SRtp", "key": "Gambold", "name": "Gambold", "parent": null, "props": [{"name": "Name", "type": "STRING", "value": "Gambold", "vk": "scalar"}, {"name": "Occupation", "type": "STRING", "value": "Shepherd", "vk": "scalar"}, {"items": [{"value": "Rustic", "vk": "scalar"}], "name": "Distinctive Features", "of": "STRING", "vk": "list"}, {"name": "Location", "type": "STRING", "value": "An Encounter Underground", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "Gambold is a simple shepherd, scratching out a living in the foothills of the mountains. He only wants to get back to his family. Should the Player-heroes rescue him, he invites them to visit him at the hall of his chieftain, Tarloch (see *Moria: Through the Doors of Durin*, page 128).", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Loremaster Character", "typeHash": "#TOR0030000000000"}, "#txQcEnuguqivxhLy3zTqYOY": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "loremaster-characters/tor2e-0.5-hands-finir-the-mastersmith.actor", "form": "DEF", "guidance": [], "id": "#txQcEnuguqivxhLy3zTqYOY", "key": "Finir the Mastersmith", "name": "Finir the Mastersmith", "parent": null, "props": [{"name": "Name", "type": "STRING", "value": "Finir the Mastersmith", "vk": "scalar"}, {"name": "Occupation", "type": "STRING", "value": "Metallurgist, Smith", "vk": "scalar"}, {"items": [{"value": "Secretive", "vk": "scalar"}, {"value": "Wilful", "vk": "scalar"}], "name": "Distinctive Features", "of": "STRING", "vk": "list"}, {"name": "Location", "type": "STRING", "value": "Finir and the Ring-smiths", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Loremaster Character", "typeHash": "#TOR0030000000000"}, "#txS2G8xdSIIa8N6IokdR2X4": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "adversaries/tor2e-0.5-hands-baugrim.actor", "form": "DEF", "guidance": [], "id": "#txS2G8xdSIIa8N6IokdR2X4", "key": "Baugrim", "name": "Baugrim", "parent": null, "props": [{"name": "Name", "type": "STRING", "value": "Baugrim", "vk": "scalar"}, {"items": [{"value": "Cruel", "vk": "scalar"}, {"value": "Hardened", "vk": "scalar"}], "name": "Distinctive Features", "of": "STRING", "vk": "list"}, {"name": "Attribute Level", "type": "INTEGER", "value": 6, "vk": "scalar"}, {"name": "Endurance", "type": "INTEGER", "value": 24, "vk": "scalar"}, {"name": "Might", "type": "INTEGER", "value": 1, "vk": "scalar"}, {"name": "Hate", "type": "INTEGER", "value": 6, "vk": "scalar"}, {"name": "Parry", "type": "STRING", "value": "+3", "vk": "scalar"}, {"name": "Armour", "type": "STRING", "value": "4", "vk": "scalar"}, {"items": [{"fields": [{"name": "Weapon", "type": "STRING", "value": "Broad-bladed Sword", "vk": "scalar"}, {"name": "Rating", "type": "INTEGER", "value": 3, "vk": "scalar"}, {"name": "Damage", "type": "INTEGER", "value": 4, "vk": "scalar"}, {"name": "Injury", "type": "INTEGER", "value": 16, "vk": "scalar"}, {"items": [{"value": "Pierce", "vk": "scalar"}], "name": "Special Damage", "of": "STRING", "vk": "list"}, {"name": "Printed", "type": "STRING", "value": "Broad-bladed Sword 3 (4/16, Pierce)", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Weapon", "type": "STRING", "value": "Bow of Horn", "vk": "scalar"}, {"name": "Rating", "type": "INTEGER", "value": 3, "vk": "scalar"}, {"name": "Damage", "type": "INTEGER", "value": 3, "vk": "scalar"}, {"name": "Injury", "type": "INTEGER", "value": 14, "vk": "scalar"}, {"items": [{"value": "Pierce", "vk": "scalar"}], "name": "Special Damage", "of": "STRING", "vk": "list"}, {"name": "Printed", "type": "STRING", "value": "Bow of Horn 3 (3/14, Pierce)", "vk": "scalar"}], "vk": "def"}], "name": "Combat Proficiencies", "of": "Adversary Combat Proficiency", "ofHash": "#tor5AdvCombat000001", "vk": "list"}, {"items": [{"fields": [{"name": "Name", "type": "STRING", "value": "Horrible Strength", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "If Baugrim scores a Piercing Blow with a close combat attack, spend 1 Hate to make the target’s Protection roll Ill-favoured.", "vk": "scalar"}], "vk": "def"}, {"fields": [{"name": "Name", "type": "STRING", "value": "Yell of Triumph", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "Spend 1 Hate to restore 1 Hate to all allies in the fight.", "vk": "scalar"}], "vk": "def"}], "name": "Fell Abilities", "of": "Fell Ability", "ofHash": "#tor5FellAbility0001", "vk": "list"}, {"name": "Description", "type": "STRING", "value": "Baugrim is a dogged veteran commander in the garrison of Dol Guldur. For him, the big war started years ago; he’s been skirmishing with Mirkwood Elves and Woodmen and pesky heroes from Dale for a long time now. But he has never crossed the River, and knows how much peril he’s in. He’s eager to get this job done and leg it back across the Anduin. Baugrim is a barrel-chested monster with long arms that nearly touch the ground when he is standing. He despises the Orcs of Moria as undisciplined hooligans, and looks forward to the day when he can use them as cannon fodder against the horse-boys down Rohan way.", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Adversary", "typeHash": "#TOR0020000000000"}, "#tyerMPafdNxNVyLwW5uCofy": {"book": "hands", "children": [], "choices": [], "desc": "During the period of Isengard’s decline, some of the soldiers who dwelt here feared to live in the old barracks dug within the Ring-wall of Isengard, claiming it was haunted. They quarried the inner ring, taking the worked masonry and building their own crude huts in the shadow of ancient Gondorian architecture. These huts are pitifully crude and draughty compared to the work of the ancients — but at least those that live in them can be sure their homes were built by Men, not giants.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-introduction.ttrpg", "form": "DEF", "guidance": [], "id": "#tyerMPafdNxNVyLwW5uCofy", "key": "6. Stone Huts", "name": "6. Stone Huts", "parent": "#tcMxywq75NOL2ves69gurzl", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#tyjMZj17V5wm9x2cb0keqIw": {"book": "hands", "children": [], "choices": [], "desc": "The Prince is a talented healer, his skills enhanced by his magic ring. He can cure the poison of the Beithir (see page 45) or other wounds, but his patients must stay overnight in the tower: he uses this time to interrogate them. Patients may also hear the singing of Gildor from the cellar below.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-sea-prince-of-the-shore.arc", "form": "DEF", "guidance": [], "id": "#tyjMZj17V5wm9x2cb0keqIw", "key": "The Healing Arts of the Prince", "name": "The Healing Arts of the Prince", "parent": null, "props": [], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#tykyYOIjLQ8uC9haE6KYbFV": {"book": "hands", "children": [], "choices": [], "desc": "The fortress of Isengard was built in the Second Age of the world. It guards the Gap of Rohan and the main road between North-kingdom and South, and has for countless centuries been one of the great strongholds of Middle-earth. In its simplest terms, it is a fortified valley — the steep mountains guard the vale on the northern side, and a mighty ring-wall of stone encircles it from north-west to north-east. There are all manner of ancient barracks, workshops, granaries, storehouses and chambers built into that encircling wall; Isengard can hold thousands of soldiers. Provisions from its green gardens and orchards, and the constant supply of fresh water from the\n\nIsen, ensure that it can outlast virtually any siege. Only once has the fortress been taken by force as opposed to treachery.\n\nFor much of the Third Age, the fortress was garrisoned by soldiers from Gondor. At first it was a prestigious assignment, for they kept watch on the Kingdom’s westernmost border, and there was much traffic between north and south. But as the years went by, and the North-kingdom foundered and broke, the importance of Isengard diminished. It was no longer a place for ambitious captains to make their name, but veritable exile to the lonely edge of the realm. The fortress was still important, for it defended Gondor against the wild men beyond the Isen.\n\nBy the days of the Watchful Peace, some six hundred years ago, soldiers from Gondor no longer came to Isengard; instead, the fortress was manned by locals overseen by a hereditary Gondorian chieftain. The tower of Orthanc was locked and the keys given over to the Stewards. This arrangement persisted even after the province of Calenardhon was given over to the people of Eorl and became the Kingdom of Rohan.\n\nSome three hundred years ago, disaster struck. The line of hereditary lords of Isengard failed, and possession of the fortress passed to a family whose allegiance lay with the Dunlendings and their usurper-king Wulf. They held Isengard and greatly troubled Rohan for decades, until the terrible Long Winter of 2758 so reduced their numbers that they could be defeated. In the following year, Saruman went to Minas Tirith and persuaded the ruling Steward to give him the keys of Orthanc. The Wizard took possession of Isengard, and has restored it after years of neglect. Once again, the Tower stands watch over the west.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-introduction.ttrpg", "form": "DEF", "guidance": [], "id": "#tykyYOIjLQ8uC9haE6KYbFV", "key": "Background", "name": "Background", "parent": "#t5mXLkdNrxFIXVCfT0kUbiu", "props": [], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#tyri1I1C0YSc6a0lgaDMfba": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "adversaries/tor2e-0.5-hands-bugrag.actor", "form": "DEF", "guidance": [], "id": "#tyri1I1C0YSc6a0lgaDMfba", "key": "Bugrag", "name": "Bugrag", "parent": null, "props": [{"name": "Name", "type": "STRING", "value": "Bugrag", "vk": "scalar"}, {"name": "Description", "type": "STRING", "value": "Under normal conditions, Bugrag would never have risen to rule this part of the Misty Mountains; he’s a sickly creature, half blind and unambitious. However, all the bigger, nastier Orcs in his lair got killed in the Battle of Five Armies, making him chieftain by default. He’s survived since then by being obsequiously loyal to Gorgol, the Goblin-king of Mount Gundabad. Bugrag is equivalent to an Orc Guard with the *Snake-like Speed* Fell Ability.", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": "Adversary", "typeHash": "#TOR0020000000000"}, "#tyvTftqCa4y4SeCHmaUAT3A": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [], "enum": null, "file": "tor2e-0.5-hands-introduction.ttrpg", "form": "DEF", "guidance": [], "id": "#tyvTftqCa4y4SeCHmaUAT3A", "key": "Old Lore", "name": "Old Lore", "parent": "#t5mXLkdNrxFIXVCfT0kUbiu", "props": [{"name": "Epigraph", "type": "STRING", "value": "A fortress built by the Men of Gondor in the days of their might, Isengard stands sentry over the Fords of Isen and the western border of the kingdoms. For centuries, it has been in the possession of a line of hereditary lords, of whom many strange things are whispered. There are more secrets in the Ring of Isengard than any mortal man knows.", "vk": "scalar"}], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#tz8ibzN9UkMTUNLV7TVtSOX": {"book": "hands", "children": [], "choices": [], "desc": "*Hands of the White Wizard* presents a campaign outline in which the Player-heroes are agents of Saruman. It begins around 2965, and climaxes around the year 3000 of the Third Age — when Saruman finally dares look in the *palantír* of Orthanc, and falls under the influence of Sauron.\n\nNow, every player of *The One Ring* probably knows that Saruman is doomed to fall into corruption and evil, and to become a secondary villain of the tale. However, in this campaign, Saruman’s fate is not yet certain: while he has set foot on the ruinous path, there still exists the possibility of redemption. At the start of the campaign, he is still great and wise, still obedient to the command laid upon him in the Uttermost West. Over the course of the campaign, the choices of the Player-heroes affect Saruman’s hope and despair. His cynicism and ambition might grow with theirs — or their heroic deeds might remind him of his own better nature. It is the actions of the Players that will seal his doom — or help save him from himself.\n\nThe supplement is structured thusly:\n\nThe following six chapters are quests of grave import entrusted to the Player-heroes by Saruman. Some of these adventures are tied to a particular year or period of time; others can be run at any time.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-introduction.ttrpg", "form": "DEF", "guidance": [{"concerns": [{"hash": "#tz8ibzN9UkMTUNLV7TVtSOX", "name": "Overview"}], "id": "#t4NqJAEJAGYNEa3doveEwpO", "name": "On Chronology", "text": "Chapter 1, 2, and 3 can all be run at any time after 2965 and in any order, although all three should be run by the start of Chapter 5.\n\nChapter 4 can be run at any point before Chap-\n\nter 5, although it is better to run it after the first three, as it is significantly more challenging.\n\nChapter 5 takes place in the year 2994, in the year Balin’s attempt to retake Moria meets its final end. Finally, Chapter 6 takes place around the Year\n\n3000 of the Third Age, just before Saruman dares\n\nto look into the Orthanc-stone for the first time and becomes ensnared by the Enemy.\n\nDepending on the needs and nature of your campaign, you might let the years between adventures pass uneventfully, interweave your own tales and adventures, or condense the canonical timeline. Balin’s expedition might start and end sooner than history records, while Saruman’s first use of the stone is speculative even in the canonical Tale of Years.", "topics": []}, {"concerns": [{"hash": "#tz8ibzN9UkMTUNLV7TVtSOX", "name": "Overview"}], "id": "#tqulDuHK4rktaVVqWyxZnJa", "name": "Useful Books", "text": "While this campaign can be played using only *The One Ring* core rules, Loremasters may wish to consult *Ruins of the Lost Realm* for additional details on Eriador and Saruman’s schemes. The section starting on page 40 adds depth to the Black Númenórean expedition referenced in Chapter 2 of this volume — the adventure *There Let Them Lie Until the End* may serve as a fitting conclusion for the mission of the ship *Kathuphazgân*.\n\nFinally, *Moria: Through the Doors of Durin* would be a valuable resource for adding details about the Dwarven city in both *The Disaster of the Gladden Fields* and *The Quest of Moria*.", "topics": []}], "id": "#tz8ibzN9UkMTUNLV7TVtSOX", "key": "Overview", "name": "Overview", "parent": null, "props": [{"items": [{"value": "Following the overview, *In the Service of Saruman* describes ways the Player-heroes might become involved in the campaign, and discusses how the Loremaster can interweave adventures from this book with other plotlines.", "vk": "scalar"}, {"value": "*Isengard* describes the home of the White Wizard, Orthanc and the surrounding lands, and the supporting cast of the campaign.", "vk": "scalar"}, {"value": "*The Fall of Saruman* outlines the gradual transformation of Isengard and the growing darkness of Saruman.", "vk": "scalar"}, {"value": "*Chapter 1: The Beast of Dunland.* The Player-heroes are sent to Dunland to slay a monster that troubles the tribes there.", "vk": "scalar"}, {"value": "*Chapter 2: The Sea-prince of the Shore. *The rise of a charismatic healer near the mouths of the Isen troubles Saruman, and the Player-heroes are sent to investigate.", "vk": "scalar"}, {"value": "*Chapter 3: The Disaster of the Gladden Fields.* One of Saruman’s agents is waylaid by Orcs, and a treasure he bears is stolen from him. It must be recovered at all costs…", "vk": "scalar"}, {"value": "*Chapter 4: There Let Them Lie Until the End.* The threat of the Corsairs in Eriador must be ended. Saruman aids the heroes in destroying the great Black Ship that lurks off the coast.", "vk": "scalar"}, {"value": "*Chapter 5: The Quest of Moria.* The Player-heroes are sent into Moria to retrieve the lost ring-lore of Eregion.", "vk": "scalar"}, {"value": "*Chapter 6: The Ithil-stone.* To Minas Morgul, and a desperate strike against the Enemy!", "vk": "scalar"}], "name": "Items", "of": "STRING", "vk": "list"}], "refs": [], "slot": null, "table": null, "type": null, "typeHash": null}, "#tzVnWVBO3ZyemOC7PInDb7s": {"book": "hands", "children": [], "choices": [], "desc": null, "entries": [{"fields": [{"name": "Shadow", "type": "STRING", "value": "+1/2/3", "vk": "scalar"}], "name": "Fixed amount (see *The Fall of Saruman*, on page page 17)", "vk": "def"}, {"fields": [{"name": "Shadow", "type": "INTEGER", "value": 1, "vk": "scalar"}], "name": "The Player-heroes committed Misdeeds collectively worth 4 Shadow points or more", "vk": "def"}, {"fields": [{"name": "Shadow", "type": "INTEGER", "value": 1, "vk": "scalar"}], "name": "Vila is not sent to Isengard", "vk": "def"}, {"fields": [{"name": "Shadow", "type": "INTEGER", "value": 1, "vk": "scalar"}], "name": "Scepa is killed", "vk": "def"}, {"fields": [{"name": "Shadow", "type": "INTEGER", "value": 2, "vk": "scalar"}], "name": "Saruman loses influence over Crow Hall (Toirlas takes credit for slaying the beast, or remains under the influence of Dunrach and Dunwalla)", "vk": "def"}], "enum": null, "file": "tor2e-0.5-hands-worksheet-saruman-s-shadow-score.ttrpg", "form": "DEF", "guidance": [], "id": "#tzVnWVBO3ZyemOC7PInDb7s", "key": "The Beast of Dunland Shadow Score", "name": "The Beast of Dunland Shadow Score", "parent": "#tkzG1FdwMCe3MPe5QNOqLI9", "props": [], "refs": [], "slot": null, "table": {"columns": ["Trigger", "Shadow", "Tally"], "rows": [["Fixed amount (see *The Fall of Saruman*, on page page 17)", "+1/2/3", ""], ["The Player-heroes committed Misdeeds collectively worth 4 Shadow points or more", "+1", ""], ["Vila is not sent to Isengard", "+1", ""], ["Scepa is killed", "+1", ""], ["Saruman loses influence over Crow Hall (Toirlas takes credit for slaying the beast, or remains under the influence of Dunrach and Dunwalla)", "+2", ""]]}, "type": "Table", "typeHash": "#tor5Table0000000001"}, "#tzfm7VopZOXgUueJogjCfMP": {"book": "hands", "children": [], "choices": [], "desc": "That night, after a surprisingly good stew garnished generously with herbs, Caelur sings the tale of Helm Hammerhand, her fingers plucking a melody from her psaltery.\n\nThere is a purpose behind her choice of song: the minstrel has been instructed by Saruman to test the loyalty of the Player-heroes, and she will do so by observing their reactions.\n\nThe content of the song is summarised below:\n\n*When Hammerhand was king, Men came down from Dunland and crossed the Isen, and Corsairs from the South landed in both the west and east and came over the mountains. Edoras was captured, and the Dunlending Wulf claimed the great hall of Meduseld.*\n\n*Helm and his faithful retreated to the fortress of the Hornburg, but those were also the times of the Long Winter, and for five months the green grass was hidden by snow. Helm grew strange and fey, and it is said of him that he walked abroad by night, the frost shining in his hair and beard, and slew Dunlendings with his bare hands.*\n\n*One night, Helm went out from the Hornburg, and did not return. When morning came, he was found standing on the dike, dead yet unbowed. It was Helm’s sister-son who slew Wulf and retook Meduseld, and drove the Dunlendings and the Corsairs from the land. And he became king thereafter, first of the second line.*\n\n*And Helm? It is said that his wraith still guards Rohan, and that his horn sounds in the valley of Helm’s Deep whenever danger threatens.*\n\nAfter singing, Caelur leans back slightly, her expression thoughtful. *“They say,”* she begins softly, *“that the Dunlendings have their own songs of Helm Hammerhand — but in their tales, Helm is no mighty king of Rohan. No, they speak of him as a terrible beast, a monstrous figure as vast and ravenous as a Snow-troll, driven by hunger and rage. Their songs paint him as a creature of fear and fury, more monster than man.”*\n\nShe pauses, then continues, her tone shifting to a more subtle note. *“And there are tales that Wulf — yes, Wulf the Dunlending — had a rightful claim to the throne of Rohan. It is said he descends from Helm’s grandsire, Freawine, and that Wulf’s own son was married to Helm’s daughter. So, some claim that Wulf was not an invader, but a contender born of the bloodline, one who believed he had a right to rule.”* **Caelur**\n\nCaelur’s eyes flicker with a mix of curiosity and challenge. *“Even more, some hold that Helm himself struck the first blow in their long struggle. But who is to say which tales hold more truth? Are the stories of Helm as a mighty king to be trusted, or are myths spun to serve those in power?”*\n\nWith her words, Caelur seeks not merely to gauge the Player-heroes’ perceptions of Helm’s legend, but rather to assess how much trust they place in their patron, Saruman. Are they inclined to accept stories at face value, or do they question the motives behind such tales? How do they judge heroism and villainy, and what do they consider honourable?\n\nCaelur seeks to lay bare their loyalty, their capability to discern, and their perspective upon trusting power and authority versus the pursuit of truth.\n\nPossible prompts for the Player-heroes:", "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-beast-of-dunland.arc", "form": "DEF", "guidance": [], "id": "#tzfm7VopZOXgUueJogjCfMP", "key": "A Song", "name": "A Song", "parent": null, "props": [{"items": [{"value": "Do you believe Helm was a hero or a monster?", "vk": "scalar"}, {"value": "Are legends meant to paint the hero in a good light, or do they hide uncomfortable truths?", "vk": "scalar"}, {"value": "How much trust do you place in stories passed down through generations?", "vk": "scalar"}, {"value": "Is there honour in seeking the truth behind the tales, regardless of what you find?", "vk": "scalar"}], "name": "Items", "of": "STRING", "vk": "list"}], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}, "#tzpqhwBDGrOVvcSIMbm0Tdy": {"book": "hands", "children": [], "choices": [], "desc": "Should the Player-heroes not find the beast’s lair in the Eordscrafa before the fifth day, then the thing attacks Crow Hall once more. If everything goes as Dunwalla and Dunrach expect, the attack unfolds as follows: this time, the crows provide plenty of advance warning of its approach. Toirlas and the other young warriors go out to battle the beast. Several of the warriors perish, but Toirlas manages to slay the monster.\n\nIf the Player-heroes are present, then Dunrach tries to ensure that none of them take the glory away from Toirlas — which may involve stabbing a Player-hero in the back or pushing them into the arms of the hungry monster! Similarly, Dunwalla can have the crows assail a Player-hero who might threaten their plan to exalt Toirlas.", "entries": [], "enum": null, "file": "tor2e-0.5-hands-the-beast-of-dunland.arc", "form": "DEF", "guidance": [], "id": "#tzpqhwBDGrOVvcSIMbm0Tdy", "key": "The Beast Attacks", "name": "The Beast Attacks", "parent": null, "props": [], "refs": [], "slot": "SCENE", "table": null, "type": null, "typeHash": null}}, "src": "data/hands.js"};var T=window.TOR2E=window.TOR2E||{books:{},entities:{},loaded:{}};
T.loaded[d.src]=true;T.books[d.book.id]=d.book;
for(var h in d.entities){T.entities[h]=d.entities[h];}})();
